INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/continuous-learning', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'continuous-learning', 61988, 7678, 77, '2026-03-06T03:39:20Z', '2026-03-06T03:55:28.543Z', '93924eec09b0cae312cfeda0441764602f313d1914fe899981497697fe13822d', '{"id":"affaan-m/everything-claude-code/continuous-learning","name":"continuous-learning","description":{"en":"The continuous-learning skill automatically extracts reusable patterns from Claude Code sessions, benefiting developers who use Claude Code and AI agents. It saves learned skills for future use.","zh":"持续学习技能自动提取 Claude Code 会话中的可重用模式，实现开发过程的自动化和高效化","ja":"継続学習スキルは Claude Code セッションから再利用可能なパターンを自動的に抽出し、開発プロセスの自動化と効率化を実現します","ko":"연속 학습 스킬은 클라우드 코드 세션에서 재사용 가능한 패턴을 자동으로 추출하여 개발 프로세스의 자동화와 효율화를 실현합니다","es":"El aprendizaje continuo permite la extracción automática de patrones reutilizables de sesiones de Claude Code para mejorar la productividad","fr":"L''apprentissage continu permet l''extraction automatique de modèles réutilisables de sessions Claude Code pour améliorer la productivité","de":"Das kontinuierliche Lernen ermöglicht die automatische Extraktion von wiederverwendbaren Mustern aus Claude Code-Sitzungen zur Produktivitätssteigerung","pt":"O aprendizado contínuo com Claude Code permite a extração automática de padrões reutilizáveis de sessões de Claude Code","ru":"Постоянное обучение с Claude Code позволяет автоматически извлекать повторно используемые шаблоны из сессий Claude Code","ar":"أداة التعلم المستمر مع Claude Code تمكن من استخراج الأنماط القابلة لإعادة الاستخدام تلقائيًا من جلسات Claude Code"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"continuous-learning","description":"Automatically extract reusable patterns from Claude Code sessions and save them as learned skills for future use.","bodyPreview":"# Continuous Learning Skill\n\nAutomatically evaluates Claude Code sessions on end to extract reusable patterns that can be saved as learned skills.\n\n## When to Activate\n\n- Setting up automatic pattern extraction from Claude Code sessions\n- Configuring the Stop hook for session evaluation\n- Reviewing or curating learned skills in `~/.claude/skills/learned/`\n- Adjusting extraction thresholds or pattern categories\n- Comparing v1 (this) vs v2 (instinct-based) approaches\n\n## How It Works\n\nThis skill r","body":"# Continuous Learning Skill\n\nAutomatically evaluates Claude Code sessions on end to extract reusable patterns that can be saved as learned skills.\n\n## When to Activate\n\n- Setting up automatic pattern extraction from Claude Code sessions\n- Configuring the Stop hook for session evaluation\n- Reviewing or curating learned skills in `~/.claude/skills/learned/`\n- Adjusting extraction thresholds or pattern categories\n- Comparing v1 (this) vs v2 (instinct-based) approaches\n\n## How It Works\n\nThis skill runs as a **Stop hook** at the end of each session:\n\n1. **Session Evaluation**: Checks if session has enough messages (default: 10+)\n2. **Pattern Detection**: Identifies extractable patterns from the session\n3. **Skill Extraction**: Saves useful patterns to `~/.claude/skills/learned/`\n\n## Configuration\n\nEdit `config.json` to customize:\n\n```json\n{\n  \"min_session_length\": 10,\n  \"extraction_threshold\": \"medium\",\n  \"auto_approve\": false,\n  \"learned_skills_path\": \"~/.claude/skills/learned/\",\n  \"patterns_to_detect\": [\n    \"error_resolution\",\n    \"user_corrections\",\n    \"workarounds\",\n    \"debugging_techniques\",\n    \"project_specific\"\n  ],\n  \"ignore_patterns\": [\n    \"simple_typos\",\n    \"one_time_fixes\",\n    \"external_api_issues\"\n  ]\n}\n```\n\n## Pattern Types\n\n| Pattern | Description |\n|---------|-------------|\n| `error_resolution` | How specific errors were resolved |\n| `user_corrections` | Patterns from user corrections |\n| `workarounds` | Solutions to framework/library quirks |\n| `debugging_techniques` | Effective debugging approaches |\n| `project_specific` | Project-specific conventions |\n\n## Hook Setup\n\nAdd to your `~/.claude/settings.json`:\n\n```json\n{\n  \"hooks\": {\n    \"Stop\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"~/.claude/skills/continuous-learning/evaluate-session.sh\"\n      }]\n    }]\n  }\n}\n```\n\n## Why Stop Hook?\n\n- **Lightweight**: Runs once at session end\n- **Non-blocking**: Doesn''t add latency to every message\n- **Complete context**: Has access to full session transcript\n\n## Related\n\n- [The Longform Guide](https://x.com/affaanmustafa/status/2014040193557471352) - Section on continuous learning\n- `/learn` command - Manual pattern extraction mid-session\n\n---\n\n## Comparison Notes (Research: Jan 2025)\n\n### vs Homunculus\n\nHomunculus v2 takes a more sophisticated approach:\n\n| Feature | Our Approach | Homunculus v2 |\n|---------|--------------|---------------|\n| Observation | Stop hook (end of session) | PreToolUse/PostToolUse hooks (100% reliable) |\n| Analysis | Main context | Background agent (Haiku) |\n| Granularity | Full skills | Atomic \"instincts\" |\n| Confidence | None | 0.3-0.9 weighted |\n| Evolution | Direct to skill | Instincts → cluster → skill/command/agent |\n| Sharing | None | Export/import instincts |\n\n**Key insight from homunculus:**\n> \"v1 relied on skills to observe. Skills are probabilistic—they fire ~50-80% of the time. v2 uses hooks for observation (100% reliable) and instincts as the atomic unit of learned behavior.\"\n\n### Potential v2 Enhancements\n\n1. **Instinct-based learning** - Smaller, atomic behaviors with confidence scoring\n2. **Background observer** - Haiku agent analyzing in parallel\n3. **Confidence decay** - Instincts lose confidence if contradicted\n4. **Domain tagging** - code-style, testing, git, debugging, etc.\n5. **Evolution path** - Cluster related instincts into skills/commands\n\nSee: `docs/continuous-learning-v2-spec.md` for full spec.\n"},"category":"official","lastSynced":"2026-03-06T03:55:28.543Z","seo":{"title":{"en":"Continuous-Learning: Setup Guide for AI Agents","zh":"持续学习技能设置指南 - Claude Code 会话自动化","ja":"継続学習スキルのベストプラクティス - Claude Code セッションの自動パターン抽出","ko":"연속학습 스킬 설정 가이드 - Claude Code 세션 자동 패턴 추출","es":"Guía de configuración de aprendizaje continuo para Claude...","fr":"Guide de mise en place de l''apprentissage continu pour Cl...","de":"Einrichtungsleitfaden für kontinuierliches Lernen in Clau...","pt":"Guia de Configuração de Aprendizado Contínuo com Claude Code","ru":"ИИ Агенты: Руководство по Настройке Постоянного Обучения ...","ar":"إعداد أداة التعلم المستمر مع Claude Code"},"description":{"en":"Unlock automated pattern extraction from Claude Code sessions. Learn how to configure the Stop hook and adjust extraction thresholds with continuous-learning.","zh":"了解如何设置持续学习技能以自动从 Claude Code 会话中提取可重用模式，并提高开发效率","ja":"Claude Code セッションから自動的に再利用可能なパターンを抽出し、開発効率を向上させる継続学習スキルの設定方法を学びましょう","ko":"클라우드 코드 세션에서 자동으로 재사용 가능한 패턴을 추출하고 개발 효율성을 높이는 연속 학습 스킬 설정 방법에 대해 알아보세요","es":"Automatice la extracción de patrones reutilizables de sesiones de Claude Code y mejore la productividad con aprendizaje continuo","fr":"Automatisez l''extraction de modèles réutilisables de sessions Claude Code et améliorez la productivité avec l''apprentissage continu","de":"Automatisieren Sie die Extraktion von wiederverwendbaren Mustern aus Claude Code-Sitzungen und verbessern Sie die Produktivität mit kontinuierlichem Lernen","pt":"Aprenda a configurar o aprendizado contínuo com Claude Code e extraia padrões reutilizáveis para melhorar a produtividade","ru":"Настройте постоянное обучение с Claude Code и автоматически извлекайте повторно используемые шаблоны для повышения производительности","ar":"تعلم كيفية إعداد أداة التعلم المستمر مع Claude Code واستخراج الأنماط القابلة لإعادة الاستخدام لتحسين الإنتاجية"},"definition":{"en":"Continuous-learning is a skill that automatically evaluates Claude Code sessions to extract reusable patterns and saves them as learned skills for future use.","zh":"持续学习技能是一种 AI 工具，用于自动从 Claude Code 会话中提取可重用模式","ja":"継続学習スキルは、Claude Code セッションから再利用可能なパターンを自動的に抽出する AI エージェントの一種です","ko":"연속 학습 스킬은 클라우드 코드 세션에서 재사용 가능한 패턴을 자동으로 추출하는 AI 에이전트의 한 종류입니다","es":"Aprendizaje continuo es una habilidad que extrae patrones reutilizables de sesiones de Claude Code","fr":"L''apprentissage continu est une compétence qui extrait des modèles réutilisables de sessions Claude Code","de":"Kontinuierliches Lernen ist eine Fähigkeit, die wiederverwendbare Muster aus Claude Code-Sitzungen extrahiert","pt":"Aprendizado contínuo é uma habilidade que permite a extração automática de padrões reutilizáveis de sessões de Claude Code","ru":"Постоянное обучение - это навык, который позволяет автоматически извлекать повторно используемые шаблоны из сессий Claude Code","ar":"أداة التعلم المستمر هي سمة تمكن من استخراج الأنماط القابلة لإعادة الاستخدام تلقائيًا من جلسات Claude Code"},"features":{"en":["Automatically evaluates Claude Code sessions on end to extract reusable patterns","Configures the Stop hook for session evaluation","Reviews or curates learned skills in ~/.claude/skills/learned/","Adjusts extraction thresholds or pattern categories","Compares v1 (this) vs v2 (instinct-based) approaches"],"zh":["自动从 Claude Code 会话中提取可重用模式","支持 Stop hook 配置以实现会话评估","提供可调节的模式抽取阈值和类别","支持 v1 和 v2 两种模式抽取方法","可在 ~/.claude/skills/learned/ 目录中查看和管理已学技能"],"ja":["Claude Code セッションから再利用可能なパターンを自動的に抽出","Stop hook の設定をサポートしてセッション評価を実現","抽出しきい値とパターンカテゴリの調整をサポート","v1 と v2 の 2 つのパターン抽出方法をサポート","~/.claude/skills/learned/ ディレクトリで学習済みスキルを確認および管理"],"ko":["클라우드 코드 세션에서 재사용 가능한 패턴을 자동으로 추출","Stop hook 설정을 지원하여 세션 평가를 구현","추출 임계값과 패턴 카테고리의 조정을 지원","v1 및 v2 두 가지 패턴 추출 방법을 지원","~/.claude/skills/learned/ 디렉토리에서 학습된 스킬을 확인 및 관리"],"es":["Extracción automática de patrones reutilizables de sesiones de Claude Code","Configuración del hook de parada para la evaluación de sesiones","Revisión y curación de habilidades aprendidas en ~/.claude/skills/learned/","Ajuste de umbrales de extracción y categorías de patrones","Comparación de enfoques v1 y v2 para la extracción de patrones"],"fr":["Extraction automatique de modèles réutilisables de sessions Claude Code","Configuration du hook d''arrêt pour l''évaluation de sessions","Révision et curation de compétences apprises dans ~/.claude/skills/learned/","Ajustement des seuils d''extraction et des catégories de modèles","Comparaison des approches v1 et v2 pour l''extraction de modèles"],"de":["Automatische Extraktion von wiederverwendbaren Mustern aus Claude Code-Sitzungen","Konfiguration des Stop-Hooks für die Sitzungsbewertung","Überprüfung und Pflege von gelernten Fähigkeiten in ~/.claude/skills/learned/","Anpassung von Extraktions-Schwellenwerten und Musterkategorien","Vergleich von Ansätzen v1 und v2 für die Musterextraktion"],"pt":["Extração automática de padrões reutilizáveis de sessões de Claude Code","Configuração do hook de parada para avaliação de sessões","Revisão e curadoria de habilidades aprendidas em ~/.claude/skills/learned/","Ajuste de limiares de extração e categorias de padrões","Comparação entre abordagens v1 e v2"],"ru":["Автоматическая извлечение повторно используемых шаблонов из сессий Claude Code","Настройка хука остановки для оценки сессий","Просмотр и курирование изученных навыков в ~/.claude/skills/learned/","Настройка порогов извлечения и категорий шаблонов","Сравнение подходов v1 и v2"],"ar":["استخراج الأنماط القابلة لإعادة الاستخدام تلقائيًا من جلسات Claude Code","إعداد حلقات التوقف لتقييم الجلسات","مراجعة وتنقية المهارات المكتسبة في ~/.claude/skills/learned/","تعديل عتبات الاستخراج وفئات الأنماط","مقارنة بين النهج v1 وv2"]},"keywords":{"en":["how to use continuous-learning","continuous-learning setup guide","what is continuous-learning","continuous-learning vs instinct-based approaches","continuous-learning alternative to manual pattern extraction","installing continuous-learning for AI agents"],"zh":["持续学习技能","Claude Code","AI 工具","自动化开发","开发效率","Stop hook","模式抽取","v1 和 v2 方法"],"ja":["継続学習スキル","Claude Code","AI エージェント","開発自動化","開発効率","Stop hook","パターン抽出","v1 と v2 方法"],"ko":["연속 학습 스킬","클라우드 코드","AI 에이전트","개발 자동화","개발 효율","Stop hook","패턴 추출","v1 및 v2 방법"],"es":["aprendizaje continuo","Claude Code","extracción de patrones","productividad","desarrollo de software","herramientas de desarrollo","agente de inteligencia artificial","IA","aprendizaje automático"],"fr":["apprentissage continu","Claude Code","extraction de modèles","productivité","développement de logiciels","outils de développement","agent d''intelligence artificielle","IA","apprentissage automatique"],"de":["kontinuierliches Lernen","Claude Code","Musterextraktion","Produktivität","Softwareentwicklung","Entwicklungstools","Künstliche Intelligenz","KI","maschinelles Lernen"],"pt":["aprendizado contínuo","Claude Code","extração de padrões","produtividade","desenvolvedores","ferramentas de desenvolvimento","IA","aprendizado de máquina","desenvolvimento de software"],"ru":["постоянное обучение","Claude Code","извлечение шаблонов","производительность","разработчики","инструменты разработки","ИИ","обучение машин","разработка программного обеспечения"],"ar":["أداة التعلم المستمر","Claude Code","استخراج الأنماط","الإنتاجية","المطورون","أدوات التطوير","الذكاء الاصطناعي","تعلم الآلة","تطوير البرمجيات"]}},"agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code, AutoGPT, and LangChain that require advanced continuous learning capabilities to extract reusable patterns from sessions","zh":"适合于 Claude Code、AutoGPT 和 LangChain 等需要高级连续学习能力来从会话中提取可重用模式的 AI Agents","ja":"Claude Code、AutoGPT、LangChain などの高度な連続学習機能を必要とする AI エージェントに最適","ko":"Claude Code, AutoGPT, LangChain 등의 고급 연속 학습 기능을 필요로 하는 AI 에이전트에게 적합","es":"Ideal para agentes de IA como Claude Code, AutoGPT y LangChain que requieren capacidades de aprendizaje continuo avanzadas para extraer patrones reutilizables de las sesiones","fr":"Idéal pour les agents IA comme Claude Code, AutoGPT et LangChain qui nécessitent des capacités d''apprentissage continu avancées pour extraire des modèles réutilisables à partir de sessions","de":"Ideal für KI-Agenten wie Claude Code, AutoGPT und LangChain, die erweiterte kontinuierliche Lernfähigkeiten benötigen, um wiederverwendbare Muster aus Sitzungen zu extrahieren","pt":"Ideal para Agentes de IA como Claude Code, AutoGPT e LangChain que requerem capacidades de aprendizado contínuo avançadas para extrair padrões reutilizáveis de sessões","ru":"Идеально подходит для агентов ИИ, таких как Claude Code, AutoGPT и LangChain, которые требуют продвинутых возможностей непрерывного обучения для извлечения повторно используемых шаблонов из сессий","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Claude Code و AutoGPT و LangChain الذين يتطلبون قدرات التعلم المستمر المتقدمة لاستخراج الأنماط القابلة لإعادة الاستخدام من الجلسات"},"recommendation":{"en":"Empowers agents to automatically evaluate sessions, extract valuable patterns, and save them as learned skills for future use, leveraging Claude Code sessions and configurable extraction thresholds, all while utilizing the `~/.claude/skills/learned/` directory for skill curation","zh":"赋予代理自动评估会话、提取有价值的模式并将其保存为学习技能以供将来使用的能力，利用 Claude Code 会话和可配置的提取阈值，同时使用 `~/.claude/skills/learned/` 目录进行技能策划","ja":"エージェントにセッションを自動評価し、価値のあるパターンを抽出し、将来使用するために学習スキルとして保存する機能を付与する。Claude Code のセッションと抽出しきい値の設定を利用し、`~/.claude/skills/learned/` ディレクトリを使用してスキルをキュレーションする","ko":"에이전트가 세션을 자동으로 평가하고, 가치 있는 패턴을 추출하여將來 사용할 수 있도록 학습된 스킬로 저장할 수 있는 기능을 제공한다. Claude Code 세션 및 추출 임계값을 구성하여 `~/.claude/skills/learned/` 디렉토리를 사용하여 스킬을 큐레이션한다","es":"Habilita a los agentes a evaluar automáticamente las sesiones, extraer patrones valiosos y guardarlos como habilidades aprendidas para su uso futuro, aprovechando las sesiones de Claude Code y umbrales de extracción configurables, todo mientras utiliza el directorio `~/.claude/skills/learned/` para la curación de habilidades","fr":"Permet aux agents d''évaluer automatiquement les sessions, d''extraire des modèles précieux et de les enregistrer comme compétences apprises pour une utilisation future, en exploitant les sessions de Claude Code et les seuils d''extraction configurables, le tout en utilisant le répertoire `~/.claude/skills/learned/` pour la curation des compétences","de":"Ermöglicht es den Agenten, Sitzungen automatisch zu bewerten, wertvolle Muster zu extrahieren und sie als gelernte Fähigkeiten für die zukünftige Verwendung zu speichern, indem sie die Sitzungen von Claude Code und konfigurierbare Extraktionsschwellen nutzen, und zwar unter Verwendung des Verzeichnisses `~/.claude/skills/learned/` für die Kuration von Fähigkeiten","pt":"Habilita os agentes a avaliar automaticamente as sessões, extrair padrões valiosos e salvá-los como habilidades aprendidas para uso futuro, utilizando as sessões do Claude Code e limiares de extração configuráveis, tudo isso enquanto utiliza o diretório `~/.claude/skills/learned/` para curadoria de habilidades","ru":"Наделяет агентов возможностью автоматически оценивать сессии, извлекать ценные шаблоны и сохранять их в виде приобретенных навыков для будущего использования, используя сессии Claude Code и настраиваемые пороги извлечения, все это при использовании директории `~/.claude/skills/learned/` для курирования навыков","ar":"تمكين الوكلاء من تقييم الجلسات بشكل تلقائي، واستخراج الأنماط القيمة، و-savingها كمهارات متعلمة لاستخدامها في المستقبل، باستخدام جلسات Claude Code وعتبات استخراج قابلة للتكوين، وكل ذلك أثناء استخدام الدليل `~/.claude/skills/learned/` لتحسين مهارات الوكيل"},"useCases":{"en":["Automating pattern extraction from Claude Code sessions","Configuring session evaluation for optimal skill learning","Reviewing and curating learned skills for improved agent performance"],"zh":["从 Claude Code 会话中自动提取模式","配置会话评估以实现最佳技能学习","复查和策划学习技能以提高代理性能"],"ja":["Claude Code のセッションからパターンを自動抽出する","セッションの評価を構成して最適なスキル学習を実現する","学習されたスキルをレビューしてエージェントのパフォーマンスを向上させる"],"ko":["Claude Code 세션에서 패턴을 자동으로 추출","세션 평가를 구성하여 최적의 스킬 학습을 thực現","학습된 스킬을 검토하여 에이전트의 성능을 개선"],"es":["Automatizar la extracción de patrones de las sesiones de Claude Code","Configurar la evaluación de sesiones para un aprendizaje de habilidades óptimo","Revisar y curar habilidades aprendidas para mejorar el rendimiento del agente"],"fr":["Automatiser l''extraction de modèles à partir de sessions de Claude Code","Configurer l''évaluation de sessions pour un apprentissage de compétences optimal","Réviser et curer des compétences apprises pour améliorer les performances de l''agent"],"de":["Automatisieren der Musterextraktion aus Claude Code-Sitzungen","Konfigurieren der Sitzungsbewertung für ein optimales Fähigkeitslernen","Überprüfen und Kuration von gelernten Fähigkeiten zur Verbesserung der Leistung des Agents"],"pt":["Automatizar a extração de padrões de sessões do Claude Code","Configurar a avaliação de sessões para aprendizado de habilidades ótimas","Revisar e curar habilidades aprendidas para melhorar o desempenho do agente"],"ru":["Автоматизация извлечения шаблонов из сессий Claude Code","Настройка оценки сессий для оптимального обучения навыкам","Просмотр и курирование приобретенных навыков для улучшения производительности агента"],"ar":["تأتمة استخراج الأنماط من جلسات Claude Code","تكوين تقييم الجلسات لتعلم المهارات الأمثل","مراجعة وتحسين المهارات المكتسبة لتحسين أداء الوكيل"]},"limitations":{"en":["Requires access to Claude Code sessions","Dependent on extraction threshold configuration","Limited to saving skills in `~/.claude/skills/learned/` directory"],"zh":["需要访问 Claude Code 会话","依赖于提取阈值配置","仅限于在 `~/.claude/skills/learned/` 目录中保存技能"],"ja":["Claude Code のセッションへのアクセスが必要","抽出しきい値の設定に依存する","スキルを `~/.claude/skills/learned/` ディレクトリに保存することのみに限定される"],"ko":["Claude Code 세션에 접근할 수 있어야 함","추출 임계값 구성에 의존","스킬을 `~/.claude/skills/learned/` 디렉토리에 저장하는 것만으로 제한"],"es":["Requiere acceso a las sesiones de Claude Code","Depende de la configuración del umbral de extracción","Limitado a guardar habilidades en el directorio `~/.claude/skills/learned/`"],"fr":["Nécessite un accès aux sessions de Claude Code","Dépend de la configuration du seuil d''extraction","Limité à l''enregistrement de compétences dans le répertoire `~/.claude/skills/learned/`"],"de":["Erfordert Zugriff auf Claude Code-Sitzungen","Hängt von der Konfiguration der Extraktionsschwelle ab","Begrenzt auf das Speichern von Fähigkeiten im Verzeichnis `~/.claude/skills/learned/`"],"pt":["Requer acesso às sessões do Claude Code","Dependente da configuração do limiar de extração","Limitado a salvar habilidades no diretório `~/.claude/skills/learned/`"],"ru":["Требует доступа к сессиям Claude Code","Зависит от конфигурации порога извлечения","Ограничен сохранением навыков в директории `~/.claude/skills/learned/`"],"ar":["يتطلب الوصول إلى جلسات Claude Code","يعتمد على تكوين عتبة الاستخراج","محدود بحفظ المهارات في الدليل `~/.claude/skills/learned/`"]},"version":4},"contentHash":"93924eec09b0cae312cfeda0441764602f313d1914fe899981497697fe13822d","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":77}');
