INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/continuous-learning', 'continuous-learning', 'affaan-m', 'everything-claude-code', 'official', 'continuous-learning affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The continuous-learning skill automatically extracts reusable patterns from Claude Code sessions, benefiting developers who use Claude Code and AI agents. It saves learned skills for future use. 持续学习技能自动提取 Claude Code 会话中的可重用模式，实现开发过程的自动化和高效化 継続学習スキルは Claude Code セッションから再利用可能なパターンを自動的に抽出し、開発プロセスの自動化と効率化を実現します 연속 학습 스킬은 클라우드 코드 세션에서 재사용 가능한 패턴을 자동으로 추출하여 개발 프로세스의 자동화와 효율화를 실현합니다 El aprendizaje continuo permite la extracción automática de patrones reutilizables de sesiones de Claude Code para mejorar la productividad L''apprentissage continu permet l''extraction automatique de modèles réutilisables de sessions Claude Code pour améliorer la productivité Das kontinuierliche Lernen ermöglicht die automatische Extraktion von wiederverwendbaren Mustern aus Claude Code-Sitzungen zur Produktivitätssteigerung O aprendizado contínuo com Claude Code permite a extração automática de padrões reutilizáveis de sessões de Claude Code Постоянное обучение с Claude Code позволяет автоматически извлекать повторно используемые шаблоны из сессий Claude Code أداة التعلم المستمر مع Claude Code تمكن من استخراج الأنماط القابلة لإعادة الاستخدام تلقائيًا من جلسات Claude Code how to use continuous-learning continuous-learning setup guide what is continuous-learning continuous-learning vs instinct-based approaches continuous-learning alternative to manual pattern extraction installing continuous-learning for AI agents 持续学习技能 Claude Code AI 工具 自动化开发 开发效率 Stop hook 模式抽取 v1 和 v2 方法 Automatically evaluates Claude Code sessions on end to extract reusable patterns Configures the Stop hook for session evaluation Reviews or curates learned skills in ~/.claude/skills/learned/ Adjusts extraction thresholds or pattern categories Compares v1 (this) vs v2 (instinct-based) approaches Continuous-learning is a skill that automatically evaluates Claude Code sessions to extract reusable patterns and saves them as learned skills for future use.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/frontend-patterns', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'frontend-patterns', 61988, 7678, 77, '2026-03-06T03:39:20Z', '2026-03-06T04:11:26.623Z', 'd32a3f430d658a8a8adb3d05da56fa1b49ef39cf2d1a6be8f27e5164f2d510df', '{"id":"affaan-m/everything-claude-code/frontend-patterns","name":"frontend-patterns","description":{"en":"This AI agent skill provides modern frontend development patterns for React and Next.js. It assists developers with state management, performance optimization, data fetching strategies, and UI best practices.","es":"Patrones de frontend para React y Next.js que mejoran el rendimiento y la eficiencia. Incluye gestión de estado, optimización de rendimiento y mejores prácticas de interfaz de usuario","fr":"Modèles de frontend pour React et Next.js qui améliorent les performances et l''efficacité. Inclut la gestion d''état, l''optimisation des performances et les meilleures pratiques d''interface utilisateur","de":"Frontend-Muster für React und Next.js, die die Leistung und Effizienz verbessern. Enthält Zustandsverwaltung, Leistungsoptimierung und Best Practices für Benutzeroberflächen","pt":"Padrões de frontend para React, Next.js, gerenciamento de estado e otimização de desempenho","ru":"Шаблоны frontend для React, Next.js, управления состоянием и оптимизации производительности","ar":"أنماط الواجهة الأمامية ل React و Next.js وإدارة الحالة وتحسين الأداء"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"frontend-patterns","description":"Frontend development patterns for React, Next.js, state management, performance optimization, and UI best practices.","bodyPreview":"# Frontend Development Patterns\n\nModern frontend patterns for React, Next.js, and performant user interfaces.\n\n## When to Activate\n\n- Building React components (composition, props, rendering)\n- Managing state (useState, useReducer, Zustand, Context)\n- Implementing data fetching (SWR, React Query, server components)\n- Optimizing performance (memoization, virtualization, code splitting)\n- Working with forms (validation, controlled inputs, Zod schemas)\n- Handling client-side routing and navigation","body":"# Frontend Development Patterns\n\nModern frontend patterns for React, Next.js, and performant user interfaces.\n\n## When to Activate\n\n- Building React components (composition, props, rendering)\n- Managing state (useState, useReducer, Zustand, Context)\n- Implementing data fetching (SWR, React Query, server components)\n- Optimizing performance (memoization, virtualization, code splitting)\n- Working with forms (validation, controlled inputs, Zod schemas)\n- Handling client-side routing and navigation\n- Building accessible, responsive UI patterns\n\n## Component Patterns\n\n### Composition Over Inheritance\n\n```typescript\n// ✅ GOOD: Component composition\ninterface CardProps {\n  children: React.ReactNode\n  variant?: ''default'' | ''outlined''\n}\n\nexport function Card({ children, variant = ''default'' }: CardProps) {\n  return <div className={`card card-${variant}`}>{children}</div>\n}\n\nexport function CardHeader({ children }: { children: React.ReactNode }) {\n  return <div className=\"card-header\">{children}</div>\n}\n\nexport function CardBody({ children }: { children: React.ReactNode }) {\n  return <div className=\"card-body\">{children}</div>\n}\n\n// Usage\n<Card>\n  <CardHeader>Title</CardHeader>\n  <CardBody>Content</CardBody>\n</Card>\n```\n\n### Compound Components\n\n```typescript\ninterface TabsContextValue {\n  activeTab: string\n  setActiveTab: (tab: string) => void\n}\n\nconst TabsContext = createContext<TabsContextValue | undefined>(undefined)\n\nexport function Tabs({ children, defaultTab }: {\n  children: React.ReactNode\n  defaultTab: string\n}) {\n  const [activeTab, setActiveTab] = useState(defaultTab)\n\n  return (\n    <TabsContext.Provider value={{ activeTab, setActiveTab }}>\n      {children}\n    </TabsContext.Provider>\n  )\n}\n\nexport function TabList({ children }: { children: React.ReactNode }) {\n  return <div className=\"tab-list\">{children}</div>\n}\n\nexport function Tab({ id, children }: { id: string, children: React.ReactNode }) {\n  const context = useContext(TabsContext)\n  if (!context) throw new Error(''Tab must be used within Tabs'')\n\n  return (\n    <button\n      className={context.activeTab === id ? ''active'' : ''''}\n      onClick={() => context.setActiveTab(id)}\n    >\n      {children}\n    </button>\n  )\n}\n\n// Usage\n<Tabs defaultTab=\"overview\">\n  <TabList>\n    <Tab id=\"overview\">Overview</Tab>\n    <Tab id=\"details\">Details</Tab>\n  </TabList>\n</Tabs>\n```\n\n### Render Props Pattern\n\n```typescript\ninterface DataLoaderProps<T> {\n  url: string\n  children: (data: T | null, loading: boolean, error: Error | null) => React.ReactNode\n}\n\nexport function DataLoader<T>({ url, children }: DataLoaderProps<T>) {\n  const [data, setData] = useState<T | null>(null)\n  const [loading, setLoading] = useState(true)\n  const [error, setError] = useState<Error | null>(null)\n\n  useEffect(() => {\n    fetch(url)\n      .then(res => res.json())\n      .then(setData)\n      .catch(setError)\n      .finally(() => setLoading(false))\n  }, [url])\n\n  return <>{children(data, loading, error)}</>\n}\n\n// Usage\n<DataLoader<Market[]> url=\"/api/markets\">\n  {(markets, loading, error) => {\n    if (loading) return <Spinner />\n    if (error) return <Error error={error} />\n    return <MarketList markets={markets!} />\n  }}\n</DataLoader>\n```\n\n## Custom Hooks Patterns\n\n### State Management Hook\n\n```typescript\nexport function useToggle(initialValue = false): [boolean, () => void] {\n  const [value, setValue] = useState(initialValue)\n\n  const toggle = useCallback(() => {\n    setValue(v => !v)\n  }, [])\n\n  return [value, toggle]\n}\n\n// Usage\nconst [isOpen, toggleOpen] = useToggle()\n```\n\n### Async Data Fetching Hook\n\n```typescript\ninterface UseQueryOptions<T> {\n  onSuccess?: (data: T) => void\n  onError?: (error: Error) => void\n  enabled?: boolean\n}\n\nexport function useQuery<T>(\n  key: string,\n  fetcher: () => Promise<T>,\n  options?: UseQueryOptions<T>\n) {\n  const [data, setData] = useState<T | null>(null)\n  const [error, setError] = useState<Error | null>(null)\n  const [loading, setLoading] = useState(false)\n\n  const refetch = useCallback(async () => {\n    setLoading(true)\n    setError(null)\n\n    try {\n      const result = await fetcher()\n      setData(result)\n      options?.onSuccess?.(result)\n    } catch (err) {\n      const error = err as Error\n      setError(error)\n      options?.onError?.(error)\n    } finally {\n      setLoading(false)\n    }\n  }, [fetcher, options])\n\n  useEffect(() => {\n    if (options?.enabled !== false) {\n      refetch()\n    }\n  }, [key, refetch, options?.enabled])\n\n  return { data, error, loading, refetch }\n}\n\n// Usage\nconst { data: markets, loading, error, refetch } = useQuery(\n  ''markets'',\n  () => fetch(''/api/markets'').then(r => r.json()),\n  {\n    onSuccess: data => console.log(''Fetched'', data.length, ''markets''),\n    onError: err => console.error(''Failed:'', err)\n  }\n)\n```\n\n### Debounce Hook\n\n```typescript\nexport function useDebounce<T>(value: T, delay: number): T {\n  const [debouncedValue, setDebouncedValue] = useState<T>(value)\n\n  useEffect(() => {\n    const handler = setTimeout(() => {\n      setDebouncedValue(value)\n    }, delay)\n\n    return () => clearTimeout(handler)\n  }, [value, delay])\n\n  return debouncedValue\n}\n\n// Usage\nconst [searchQuery, setSearchQuery] = useState('''')\nconst debouncedQuery = useDebounce(searchQuery, 500)\n\nuseEffect(() => {\n  if (debouncedQuery) {\n    performSearch(debouncedQuery)\n  }\n}, [debouncedQuery])\n```\n\n## State Management Patterns\n\n### Context + Reducer Pattern\n\n```typescript\ninterface State {\n  markets: Market[]\n  selectedMarket: Market | null\n  loading: boolean\n}\n\ntype Action =\n  | { type: ''SET_MARKETS''; payload: Market[] }\n  | { type: ''SELECT_MARKET''; payload: Market }\n  | { type: ''SET_LOADING''; payload: boolean }\n\nfunction reducer(state: State, action: Action): State {\n  switch (action.type) {\n    case ''SET_MARKETS'':\n      return { ...state, markets: action.payload }\n    case ''SELECT_MARKET'':\n      return { ...state, selectedMarket: action.payload }\n    case ''SET_LOADING'':\n      return { ...state, loading: action.payload }\n    default:\n      return state\n  }\n}\n\nconst MarketContext = createContext<{\n  state: State\n  dispatch: Dispatch<Action>\n} | undefined>(undefined)\n\nexport function MarketProvider({ children }: { children: React.ReactNode }) {\n  const [state, dispatch] = useReducer(reducer, {\n    markets: [],\n    selectedMarket: null,\n    loading: false\n  })\n\n  return (\n    <MarketContext.Provider value={{ state, dispatch }}>\n      {children}\n    </MarketContext.Provider>\n  )\n}\n\nexport function useMarkets() {\n  const context = useContext(MarketContext)\n  if (!context) throw new Error(''useMarkets must be used within MarketProvider'')\n  return context\n}\n```\n\n## Performance Optimization\n\n### Memoization\n\n```typescript\n// ✅ useMemo for expensive computations\nconst sortedMarkets = useMemo(() => {\n  return markets.sort((a, b) => b.volume - a.volume)\n}, [markets])\n\n// ✅ useCallback for functions passed to children\nconst handleSearch = useCallback((query: string) => {\n  setSearchQuery(query)\n}, [])\n\n// ✅ React.memo for pure components\nexport const MarketCard = React.memo<MarketCardProps>(({ market }) => {\n  return (\n    <div className=\"market-card\">\n      <h3>{market.name}</h3>\n      <p>{market.description}</p>\n    </div>\n  )\n})\n```\n\n### Code Splitting & Lazy Loading\n\n```typescript\nimport { lazy, Suspense } from ''react''\n\n// ✅ Lazy load heavy components\nconst HeavyChart = lazy(() => import(''./HeavyChart''))\nconst ThreeJsBackground = lazy(() => import(''./ThreeJsBackground''))\n\nexport function Dashboard() {\n  return (\n    <div>\n      <Suspense fallback={<ChartSkeleton />}>\n        <HeavyChart data={data} />\n      </Suspense>\n\n      <Suspense fallback={null}>\n        <ThreeJsBackground />\n      </Suspense>\n    </div>\n  )\n}\n```\n\n### Virtualization for Long Lists\n\n```typescript\nimport { useVirtualizer } from ''@tanstack/react-virtual''\n\nexport function VirtualMarketList({ markets }: { markets: Market[] }) {\n  const parentRef = useRef<HTMLDivElement>(null)\n\n  const virtualizer = useVirtualizer({\n    count: markets.length,\n    getScrollElement: () => parentRef.current,\n    estimateSize: () => 100,  // Estimated row height\n    overscan: 5  // Extra items to render\n  })\n\n  return (\n    <div ref={parentRef} style={{ height: ''600px'', overflow: ''auto'' }}>\n      <div\n        style={{\n          height: `${virtualizer.getTotalSize()}px`,\n          position: ''relative''\n        }}\n      >\n        {virtualizer.getVirtualItems().map(virtualRow => (\n          <div\n            key={virtualRow.index}\n            style={{\n              position: ''absolute'',\n              top: 0,\n              left: 0,\n              width: ''100%'',\n              height: `${virtualRow.size}px`,\n              transform: `translateY(${virtualRow.start}px)`\n            }}\n          >\n            <MarketCard market={markets[virtualRow.index]} />\n          </div>\n        ))}\n      </div>\n    </div>\n  )\n}\n```\n\n## Form Handling Patterns\n\n### Controlled Form with Validation\n\n```typescript\ninterface FormData {\n  name: string\n  description: string\n  endDate: string\n}\n\ninterface FormErrors {\n  name?: string\n  description?: string\n  endDate?: string\n}\n\nexport function CreateMarketForm() {\n  const [formData, setFormData] = useState<FormData>({\n    name: '''',\n    description: '''',\n    endDate: ''''\n  })\n\n  const [errors, setErrors] = useState<FormErrors>({})\n\n  const validate = (): boolean => {\n    const newErrors: FormErrors = {}\n\n    if (!formData.name.trim()) {\n      newErrors.name = ''Name is required''\n    } else if (formData.name.length > 200) {\n      newErrors.name = ''Name must be under 200 characters''\n    }\n\n    if (!formData.description.trim()) {\n      newErrors.description = ''Description is required''\n    }\n\n    if (!formData.endDate) {\n      newErrors.endDate = ''End date is required''\n    }\n\n    setErrors(newErrors)\n    return Object.keys(newErrors).length === 0\n  }\n\n  const handleSubmit = async (e: React.FormEvent) => {\n    e.preventDefault()\n\n    if (!validate()) return\n\n    try {\n      await createMarket(formData)\n      // Success handling\n    } catch (error) {\n      // Error handling\n    }\n  }\n\n  return (\n    <form onSubmit={handleSubmit}>\n      <input\n        value={formData.name}\n        onChange={e => setFormData(prev => ({ ...prev, name: e.target.value }))}\n        placeholder=\"Market name\"\n      />\n      {errors.name && <span className=\"error\">{errors.name}</span>}\n\n      {/* Other fields */}\n\n      <button type=\"submit\">Create Market</button>\n    </form>\n  )\n}\n```\n\n## Error Boundary Pattern\n\n```typescript\ninterface ErrorBoundaryState {\n  hasError: boolean\n  error: Error | null\n}\n\nexport class ErrorBoundary extends React.Component<\n  { children: React.ReactNode },\n  ErrorBoundaryState\n> {\n  state: ErrorBoundaryState = {\n    hasError: false,\n    error: null\n  }\n\n  static getDerivedStateFromError(error: Error): ErrorBoundaryState {\n    return { hasError: true, error }\n  }\n\n  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    console.error(''Error boundary caught:'', error, errorInfo)\n  }\n\n  render() {\n    if (this.state.hasError) {\n      return (\n        <div className=\"error-fallback\">\n          <h2>Something went wrong</h2>\n          <p>{this.state.error?.message}</p>\n          <button onClick={() => this.setState({ hasError: false })}>\n            Try again\n          </button>\n        </div>\n      )\n    }\n\n    return this.props.children\n  }\n}\n\n// Usage\n<ErrorBoundary>\n  <App />\n</ErrorBoundary>\n```\n\n## Animation Patterns\n\n### Framer Motion Animations\n\n```typescript\nimport { motion, AnimatePresence } from ''framer-motion''\n\n// ✅ List animations\nexport function AnimatedMarketList({ markets }: { markets: Market[] }) {\n  return (\n    <AnimatePresence>\n      {markets.map(market => (\n        <motion.div\n          key={market.id}\n          initial={{ opacity: 0, y: 20 }}\n          animate={{ opacity: 1, y: 0 }}\n          exit={{ opacity: 0, y: -20 }}\n          transition={{ duration: 0.3 }}\n        >\n          <MarketCard market={market} />\n        </motion.div>\n      ))}\n    </AnimatePresence>\n  )\n}\n\n// ✅ Modal animations\nexport function Modal({ isOpen, onClose, children }: ModalProps) {\n  return (\n    <AnimatePresence>\n      {isOpen && (\n        <>\n          <motion.div\n            className=\"modal-overlay\"\n            initial={{ opacity: 0 }}\n            animate={{ opacity: 1 }}\n            exit={{ opacity: 0 }}\n            onClick={onClose}\n          />\n          <motion.div\n            className=\"modal-content\"\n            initial={{ opacity: 0, scale: 0.9, y: 20 }}\n            animate={{ opacity: 1, scale: 1, y: 0 }}\n            exit={{ opacity: 0, scale: 0.9, y: 20 }}\n          >\n            {children}\n          </motion.div>\n        </>\n      )}\n    </AnimatePresence>\n  )\n}\n```\n\n## Accessibility Patterns\n\n### Keyboard Navigation\n\n```typescript\nexport function Dropdown({ options, onSelect }: DropdownProps) {\n  const [isOpen, setIsOpen] = useState(false)\n  const [activeIndex, setActiveIndex] = useState(0)\n\n  const handleKeyDown = (e: React.KeyboardEvent) => {\n    switch (e.key) {\n      case ''ArrowDown'':\n        e.preventDefault()\n        setActiveIndex(i => Math.min(i + 1, options.length - 1))\n        break\n      case ''ArrowUp'':\n        e.preventDefault()\n        setActiveIndex(i => Math.max(i - 1, 0))\n        break\n      case ''Enter'':\n        e.preventDefault()\n        onSelect(options[activeIndex])\n        setIsOpen(false)\n        break\n      case ''Escape'':\n        setIsOpen(false)\n        break\n    }\n  }\n\n  return (\n    <div\n      role=\"combobox\"\n      aria-expanded={isOpen}\n      aria-haspopup=\"listbox\"\n      onKeyDown={handleKeyDown}\n    >\n      {/* Dropdown implementation */}\n    </div>\n  )\n}\n```\n\n### Focus Management\n\n```typescript\nexport function Modal({ isOpen, onClose, children }: ModalProps) {\n  const modalRef = useRef<HTMLDivElement>(null)\n  const previousFocusRef = useRef<HTMLElement | null>(null)\n\n  useEffect(() => {\n    if (isOpen) {\n      // Save currently focused element\n      previousFocusRef.current = document.activeElement as HTMLElement\n\n      // Focus modal\n      modalRef.current?.focus()\n    } else {\n      // Restore focus when closing\n      previousFocusRef.current?.focus()\n    }\n  }, [isOpen])\n\n  return isOpen ? (\n    <div\n      ref={modalRef}\n      role=\"dialog\"\n      aria-modal=\"true\"\n      tabIndex={-1}\n      onKeyDown={e => e.key === ''Escape'' && onClose()}\n    >\n      {children}\n    </div>\n  ) : null\n}\n```\n\n**Remember**: Modern frontend patterns enable maintainable, performant user interfaces. Choose patterns that fit your project complexity.\n"},"category":"official","lastSynced":"2026-03-06T04:11:26.623Z","seo":{"title":{"en":"frontend-patterns: React & Next.js Optimization Guide | A...","es":"Patrones de frontend para React y Next.js: Guía de config...","fr":"Modèles de frontend pour React et Next.js: Meilleures pra...","de":"Frontend-Muster für React und Next.js: Leitfaden für Entw...","pt":"Guia de Padrões de Frontend para React e Next.js","ru":"Настройка шаблонов frontend для React и Next.js с ИИ Аген...","ar":"دليل أنماط الواجهة الأمامية ل React و Next.js"},"description":{"en":"Level up your React and Next.js apps with AI-driven patterns for state management (Zustand, Context), performance optimization (memoization, code splitting),...","es":"Aprende patrones de frontend para mejorar el rendimiento y la eficiencia en React y Next.js. Descubre cómo optimizar la gestión de estado y la interfaz de us...","fr":"Découvrez les modèles de frontend pour améliorer les performances et l''efficacité dans React et Next.js. Apprenez à optimiser la gestion d''état et l''interfac...","de":"Erfahren Sie mehr über Frontend-Muster, um die Leistung und Effizienz in React und Next.js zu verbessern. Lernen Sie, wie Sie die Zustandsverwaltung und Benu...","pt":"Aprenda padrões de frontend modernos para React, Next.js e interfaces de usuário performáticas","ru":"Изучите современные шаблоны frontend для React, Next.js и производительных пользовательских интерфейсов с помощью ИИ Агентов","ar":"تعلم أنماط الواجهة الأمامية الحديثة ل React و Next.js وواجهات المستخدم عالية الأداء"},"definition":{"en":"frontend-patterns is an AI agent skill that delivers expert guidance on modern frontend development patterns. It specifically covers React, Next.js, state management solutions, performance optimization techniques, and UI implementation best practices for developers.","es":"Patrones de frontend son técnicas y estrategias para desarrollar interfaces de usuario eficientes y escalables en React y Next.js","fr":"Les modèles de frontend sont des techniques et des stratégies pour développer des interfaces utilisateur efficaces et évolutives dans React et Next.js","de":"Frontend-Muster sind Techniken und Strategien zur Entwicklung effizienter und skalierbarer Benutzeroberflächen in React und Next.js","pt":"Padrões de frontend são práticas recomendadas para desenvolver interfaces de usuário eficientes","ru":"Шаблоны frontend - это рекомендуемые практики для разработки эффективных пользовательских интерфейсов","ar":"أنماط الواجهة الأمامية هي ممارسات موصى بها لإنشاء واجهات مستخدم فعالة"},"features":{"en":["Provides patterns for building React components using composition and props","Guides on state management with useState, useReducer, Zustand, and Context API","Assists in implementing data fetching strategies with SWR and React Query","Offers performance optimization techniques including memoization and code splitting","Supports form handling with validation and controlled inputs","Provides guidance on client-side routing and navigation implementation"],"es":["Gestión de estado con useState, useReducer y Zustand","Optimización de rendimiento con memoización y virtualización","Implementación de fetching de datos con SWR y React Query","Mejores prácticas de interfaz de usuario con formularios y validación","Implementación de enrutamiento y navegación cliente-servidor"],"fr":["Gestion d''état avec useState, useReducer et Zustand","Optimisation des performances avec la mémoïsation et la virtualisation","Implémentation du fetching de données avec SWR et React Query","Meilleures pratiques d''interface utilisateur avec des formulaires et une validation","Implémentation du routage et de la navigation client-serveur"],"de":["Zustandsverwaltung mit useState, useReducer und Zustand","Leistungsoptimierung mit Memoisierung und Virtualisierung","Implementierung von Datenabfragen mit SWR und React Query","Best Practices für Benutzeroberflächen mit Formularen und Validierung","Implementierung von Client-Server-Routing und -Navigation"],"pt":["Implementação de componentes React com composição e gerenciamento de estado","Otimização de desempenho com memoização e virtualização","Gerenciamento de estado com useState, useReducer e Zustand","Implementação de roteamento cliente com Next.js","Otimização de formulários com validação e controle de entrada"],"ru":["Реализация компонентов React с составлением и управлением состоянием","Оптимизация производительности с помощью мемоизации и виртуализации","Управление состоянием с помощью useState, useReducer и Zustand","Реализация клиентского маршрутизации с Next.js","Оптимизация форм с помощью валидации и контроля ввода"],"ar":["تنفيذ مكونات React مع التركيب وإدارة الحالة","تحسين الأداء مع التخزين المؤقت والتفعيل","إدارة الحالة مع useState و useReducer و Zustand","تنفيذ التوجيه العميل مع Next.js","تحسين Forms مع التحقق والتحكم في المدخلات"]},"keywords":{"en":["how to use frontend-patterns with React","frontend-patterns vs other MCP skills","frontend-patterns install guide","what is frontend-patterns AI agent","frontend-patterns Zustand state management","frontend-patterns Next.js performance optimization","frontend-patterns setup for Claude","frontend-patterns React Query patterns","frontend-patterns alternative tools","frontend-patterns code splitting techniques"],"es":["patrones de frontend","react","next.js","gestión de estado","optimización de rendimiento","interfaz de usuario","formularios","validación","enrutamiento","navegación"],"fr":["modèles de frontend","react","next.js","gestion d''état","optimisation des performances","interface utilisateur","formulaires","validation","routage","navigation"],"de":["frontend-muster","react","next.js","zustandsverwaltung","leistungsoptimierung","benutzeroberfläche","formulare","validierung","routing","navigation"],"pt":["padrões de frontend","desenvolvimento frontend","React","Next.js","gerenciamento de estado","otimização de desempenho","interfaces de usuário performáticas"],"ru":["шаблоны frontend","разработка frontend","React","Next.js","управление состоянием","оптимизация производительности","производительные пользовательские интерфейсы","ИИ Агенты"],"ar":["أنماط الواجهة الأمامية","تطوير الواجهة الأمامية","React","Next.js","إدارة الحالة","تحسين الأداء","واجهات المستخدم عالية الأداء","أدوات ذكاء اصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Full Stack Agents seeking to master modern React and Next.js development with optimized state management and performance techniques.","zh":"适合于希望掌握现代 React 和 Next.js 开发的全栈代理，具有优化的状态管理和性能技术。","ja":"モダンな React と Next.js 開発をマスターしたいフルスタックエージェントに最適です。状態管理とパフォーマンス技術が最適化されています。","ko":"모던한 React와 Next.js 개발을 마스터하고 싶은 풀스택 에이전트에게 적합합니다. 상태 관리와 성능 기술이 최적화되어 있습니다.","es":"Ideal para Agentes Full Stack que buscan dominar el desarrollo moderno con React y Next.js con técnicas optimizadas de gestión de estado y rendimiento.","fr":"Idéal pour les Agents Full Stack cherchant à maîtriser le développement moderne avec React et Next.js avec des techniques optimisées de gestion d''état et de performance.","de":"Ideal für Full Stack Agents, die die moderne Entwicklung mit React und Next.js mit optimierten State-Management- und Performance-Techniken beherrschen möchten.","pt":"Ideal para Agentes Full Stack que buscam dominar o desenvolvimento moderno com React e Next.js com técnicas otimizadas de gerenciamento de estado e performance.","ru":"Идеально подходит для Full Stack агентов, стремящихся освоить современную разработку на React и Next.js с оптимизированным управлением состоянием и методами повышения производительности.","ar":"مثالي لوكلاء Full Stack الذين يسعون لإتقان التطوير الحديث باستخدام React و Next.js مع تقنيات مُحسّنة لإدارة الحالة والأداء."},"recommendation":{"en":"Empowers agents to craft performant user interfaces using React, Next.js, and state management libraries like Zustand and Context, while optimizing performance through memoization, virtualization, and code splitting with tools like SWR and React Query.","zh":"赋予代理创建高性能用户界面的能力，使用 React、Next.js 和状态管理库，如 Zustand 和 Context，同时通过 memoization、虚拟化和代码分割等工具优化性能，如 SWR 和 React Query。","ja":"React、Next.js、Zustand、Context などのステート管理ライブラリを使用して、高パフォーマンスのユーザーインターフェイスを作成するエージェントの能力を付与します。また、SWRやReact Queryなどのツールを使用して、メモ化、仮想化、コード分割などでパフォーマンスを最適化します。","ko":"리액트, 넥스트.js 및 Zustand, Context와 같은 상태 관리 라이브러리를 사용하여 고성능 사용자 인터페이스를 만들 수 있는 에이전트의 능력을 부여합니다. 또한, SWR 및 리액트 쿼리와 같은 도구를 사용하여 메모화, 가상화 및 코드 분할 등을 통해 성능을 최적화합니다.","es":"Permite a los agentes crear interfaces de usuario de alto rendimiento utilizando React, Next.js y librerías de gestión de estado como Zustand y Context, mientras optimizan el rendimiento mediante memoización, virtualización y división de código con herramientas como SWR y React Query.","fr":"Permet aux agents de créer des interfaces utilisateur performantes en utilisant React, Next.js et des bibliothèques de gestion d''état comme Zustand et Context, tout en optimisant les performances grâce à la mémorisation, la virtualisation et la division du code avec des outils comme SWR et React Query.","de":"Ermöglicht Agents die Erstellung leistungsstarker Benutzeroberflächen mit React, Next.js und State-Management-Bibliotheken wie Zustand und Context, während die Performance durch Memoization, Virtualisierung und Code-Splitting mit Tools wie SWR und React Query optimiert wird.","pt":"Capacita os agentes a criar interfaces de usuário performáticas usando React, Next.js e bibliotecas de gerenciamento de estado como Zustand e Context, enquanto otimiza o desempenho por meio de memoização, virtualização e divisão de código com ferramentas como SWR e React Query.","ru":"Позволяет агентам создавать производительные пользовательские интерфейсы с использованием React, Next.js и библиотек управления состоянием, таких как Zustand и Context, одновременно оптимизируя производительность с помощью мемоизации, виртуализации и разделения кода с такими инструментами, как SWR и React Query.","ar":"يمكّن الوكلاء من صياغة واجهات مستخدم عالية الأداء باستخدام React و Next.js ومكتبات إدارة الحالة مثل Zustand و Context، مع تحسين الأداء من خلال memoization virtualization وتقسيم التعليمات البرمجية باستخدام أدوات مثل SWR و React Query."},"useCases":{"en":["Building reusable React components with composition and props","Implementing efficient state management with useState, useReducer, and Context","Optimizing frontend performance through memoization, virtualization, and code splitting"],"zh":["使用组合和属性构建可重用的 React 组件","使用 useState、useReducer 和 Context 实现高效的状态管理","通过 memoization、虚拟化和代码分割优化前端性能"],"ja":["コンポジションとプロップを使用して再利用可能な React コンポーネントを構築する","useState、useReducer、Context を使用して効率的なステート管理を実装する","メモ化、仮想化、コード分割を使用してフロントエンドのパフォーマンスを最適化する"],"ko":["컴포지션과 속성을 사용하여 재사용 가능한 리액트 컴포넌트를 구축한다.","useState, useReducer, Context를 사용하여 효율적인 상태 관리를 구현한다.","메모화, 가상화, 코드 분할을 사용하여 프론트엔드 성능을 최적화한다."],"es":["Construcción de componentes React reutilizables con composición y props","Implementación de una gestión de estado eficiente con useState, useReducer y Context","Optimización del rendimiento del frontend mediante memoización, virtualización y división de código"],"fr":["Construction de composants React réutilisables avec composition et props","Mise en œuvre d''une gestion d''état efficace avec useState, useReducer et Context","Optimisation des performances frontend grâce à la mémorisation, la virtualisation et la division du code"],"de":["Erstellung wiederverwendbarer React-Komponenten mit Composition und Props","Implementierung eines effizienten State-Managements mit useState, useReducer und Context","Optimierung der Frontend-Performance durch Memoization, Virtualisierung und Code-Splitting"],"pt":["Construindo componentes React reutilizáveis com composição e props","Implementando gerenciamento de estado eficiente com useState, useReducer e Context","Otimizando o desempenho do frontend por meio de memoização, virtualização e divisão de código"],"ru":["Создание переиспользуемых React компонентов с помощью композиции и props","Реализация эффективного управления состоянием с помощью useState, useReducer и Context","Оптимизация производительности фронтенда с помощью мемоизации, виртуализации и разделения кода"],"ar":["بناء مكونات React قابلة لإعادة الاستخدام باستخدام composition و props","تنفيذ إدارة حالة فعالة باستخدام useState و useReducer و Context","تحسين أداء الواجهة الأمامية من خلال memoization و virtualization وتقسيم التعليمات البرمجية"]},"limitations":{"en":["Requires familiarity with React and Next.js ecosystems","Limited to frontend development patterns and optimizations"],"zh":["需要熟悉 React 和 Next.js 生态系统","仅限于前端开发模式和优化"],"ja":["React と Next.js のエコシステムに精通している必要がある","フロントエンド開発パターンと最適化に限定される"],"ko":["리액트와 넥스트.js의 생태계에 익숙해야 한다.","프론트엔드 개발 패턴 및 최적화에만 제한된다."],"es":["Requiere familiaridad con los ecosistemas de React y Next.js","Limitado a patrones de desarrollo frontend y optimizaciones"],"fr":["Nécessite une familiarité avec les écosystèmes React et Next.js","Limité aux modèles de développement frontend et aux optimisations"],"de":["Erfordert Vertrautheit mit den React- und Next.js-Ökosystemen","Beschränkt auf Frontend-Entwicklungsmuster und -Optimierungen"],"pt":["Requer familiaridade com os ecossistemas React e Next.js","Limitado a padrões e otimizações de desenvolvimento frontend"],"ru":["Требует familiarity с экосистемами React и Next.js","Ограничено шаблонами разработки фронтенда и оптимизациями"],"ar":["يتطلب الإلمام بـ ecosystems الخاصة بـ React و Next.js","يقتصر على أنماط تحسينات تطوير الواجهة الأمامية"]},"version":4},"contentHash":"d32a3f430d658a8a8adb3d05da56fa1b49ef39cf2d1a6be8f27e5164f2d510df","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":77}');
