INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/frontend-patterns', 'frontend-patterns', 'affaan-m', 'everything-claude-code', 'official', 'frontend-patterns affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity This AI agent skill provides modern frontend development patterns for React and Next.js. It assists developers with state management, performance optimization, data fetching strategies, and UI best practices. Patrones de frontend para React y Next.js que mejoran el rendimiento y la eficiencia. Incluye gestión de estado, optimización de rendimiento y mejores prácticas de interfaz de usuario Modèles de frontend pour React et Next.js qui améliorent les performances et l''efficacité. Inclut la gestion d''état, l''optimisation des performances et les meilleures pratiques d''interface utilisateur Frontend-Muster für React und Next.js, die die Leistung und Effizienz verbessern. Enthält Zustandsverwaltung, Leistungsoptimierung und Best Practices für Benutzeroberflächen Padrões de frontend para React, Next.js, gerenciamento de estado e otimização de desempenho Шаблоны frontend для React, Next.js, управления состоянием и оптимизации производительности أنماط الواجهة الأمامية ل React و Next.js وإدارة الحالة وتحسين الأداء how to use frontend-patterns with React frontend-patterns vs other MCP skills frontend-patterns install guide what is frontend-patterns AI agent frontend-patterns Zustand state management frontend-patterns Next.js performance optimization frontend-patterns setup for Claude frontend-patterns React Query patterns frontend-patterns alternative tools frontend-patterns code splitting techniques Provides patterns for building React components using composition and props Guides on state management with useState, useReducer, Zustand, and Context API Assists in implementing data fetching strategies with SWR and React Query Offers performance optimization techniques including memoization and code splitting Supports form handling with validation and controlled inputs Provides guidance on client-side routing and navigation implementation frontend-patterns is an AI agent skill that delivers expert guidance on modern frontend development patterns. It specifically covers React, Next.js, state management solutions, performance optimization techniques, and UI implementation best practices for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/code-review', 'official', 'getsentry', 'skills', 'getsentry/skills', 'code-review', 360, 11, 77, '2026-03-06T00:20:36Z', '2026-03-06T04:59:18.541Z', 'ec5fc8855cb4648b4f2c79b608f8c8824a2da6a683330524c4d6283e4a3954c4', '{"id":"getsentry/skills/code-review","name":"code-review","description":{"en":"The code-review skill performs thorough code reviews following Sentry engineering practices, benefiting developers by ensuring high-quality code. It covers security, performance, testing, and design review.","zh":"代码审查AI工具按照Sentry工程实践进行代码审查，确保代码质量和安全","ja":"コードレビューAIエージェントはSentryエンジニアリングプラクティスに従ってコードをレビュー","ko":"코드 리뷰 AI 에이전트는 Sentry 엔지니어링 실践을 따라 코드를 리뷰","es":"Nuestra guía de revisión de código para herramientas de AI ayuda a los desarrolladores a mejorar la calidad del código, cubriendo aspectos como seguridad, rendimiento y diseño","fr":"Notre guide de revue de code pour outils d''IA aide les développeurs à améliorer la qualité du code, en couvrant des aspects tels que la sécurité, les performances et la conception","de":"Unser Code-Review-Leitfaden für KI-Tools hilft Entwicklern, die Codequalität zu verbessern, indem er Aspekte wie Sicherheit, Leistung und Design abdeckt","pt":"A revisão de código com Sentry ajuda a identificar problemas de segurança, desempenho e design. Siga nossas práticas de engenharia para melhorar a qualidade do seu código","ru":"Проверка кода с помощью Sentry помогает выявить проблемы безопасности, производительности и дизайна. Следуйте нашим инженерным практикам, чтобы улучшить качество вашего кода","ar":"أداة مراجعة الكود مع سينتري تساعد في تحديد مشاكل الأمان والأداء والتصميم. اتبع ممارسات الهندسة لدينا لتحسين جودة الكود الخاص بك"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"code-review","description":"Perform code reviews following Sentry engineering practices. Use when reviewing pull requests, examining code changes, or providing feedback on code quality. Covers security, performance, testing, and design review.","bodyPreview":"# Sentry Code Review\n\nFollow these guidelines when reviewing code for Sentry projects.\n\n## Review Checklist\n\n### Identifying Problems\n\nLook for these issues in code changes:\n\n- **Runtime errors**: Potential exceptions, null pointer issues, out-of-bounds access\n- **Performance**: Unbounded O(n²) operations, N+1 queries, unnecessary allocations\n- **Side effects**: Unintended behavioral changes affecting other components\n- **Backwards compatibility**: Breaking API changes without migration path\n- *","body":"# Sentry Code Review\n\nFollow these guidelines when reviewing code for Sentry projects.\n\n## Review Checklist\n\n### Identifying Problems\n\nLook for these issues in code changes:\n\n- **Runtime errors**: Potential exceptions, null pointer issues, out-of-bounds access\n- **Performance**: Unbounded O(n²) operations, N+1 queries, unnecessary allocations\n- **Side effects**: Unintended behavioral changes affecting other components\n- **Backwards compatibility**: Breaking API changes without migration path\n- **ORM queries**: Complex Django ORM with unexpected query performance\n- **Security vulnerabilities**: Injection, XSS, access control gaps, secrets exposure\n\n### Design Assessment\n\n- Do component interactions make logical sense?\n- Does the change align with existing project architecture?\n- Are there conflicts with current requirements or goals?\n\n### Test Coverage\n\nEvery PR should have appropriate test coverage:\n\n- Functional tests for business logic\n- Integration tests for component interactions\n- End-to-end tests for critical user paths\n\nVerify tests cover actual requirements and edge cases. Avoid excessive branching or looping in test code.\n\n### Long-Term Impact\n\nFlag for senior engineer review when changes involve:\n\n- Database schema modifications\n- API contract changes\n- New framework or library adoption\n- Performance-critical code paths\n- Security-sensitive functionality\n\n## Feedback Guidelines\n\n### Tone\n\n- Be polite and empathetic\n- Provide actionable suggestions, not vague criticism\n- Phrase as questions when uncertain: \"Have you considered...?\"\n\n### Approval\n\n- Approve when only minor issues remain\n- Don''t block PRs for stylistic preferences\n- Remember: the goal is risk reduction, not perfect code\n\n## Common Patterns to Flag\n\n### Python/Django\n\n```python\n# Bad: N+1 query\nfor user in users:\n    print(user.profile.name)  # Separate query per user\n\n# Good: Prefetch related\nusers = User.objects.prefetch_related(''profile'')\n```\n\n### TypeScript/React\n\n```typescript\n// Bad: Missing dependency in useEffect\nuseEffect(() => {\n  fetchData(userId);\n}, []);  // userId not in deps\n\n// Good: Include all dependencies\nuseEffect(() => {\n  fetchData(userId);\n}, [userId]);\n```\n\n### Security\n\n```python\n# Bad: SQL injection risk\ncursor.execute(f\"SELECT * FROM users WHERE id = {user_id}\")\n\n# Good: Parameterized query\ncursor.execute(\"SELECT * FROM users WHERE id = %s\", [user_id])\n```\n\n## References\n\n- [Sentry Code Review Guidelines](https://develop.sentry.dev/engineering-practices/code-review/)\n"},"category":"official","lastSynced":"2026-03-06T04:59:18.541Z","seo":{"title":{"en":"Code-Review: Best Practices for AI Agents | Sentry Code Q...","zh":"代码审查最佳实践 - AI工具","ja":"コードレビュー設定ガイド - AIエージェント","ko":"코드 리뷰 가이드 - AI 에이전트","es":"Guía de Configuración de Revisión de Código para Herramie...","fr":"Guide de Configuration de la Revue de Code pour Outils d''IA","de":"Einrichtungsleitfaden für Code-Review mit KI-Tools","pt":"Guia de Configuração de Revisão de Código com Sentry","ru":"ИИ Агент для Проверки Код: Руководство по Настройке","ar":"دليل إعداد أداة مراجعة الكود مع سينتري"},"description":{"en":"Unlock expert code review techniques for Sentry projects. Learn how to identify runtime errors, optimize performance, and ensure backwards compatibility. Get...","zh":"使用代码审查AI工具遵循Sentry工程实践，确保代码质量和安全","ja":"Sentryエンジニアリングプラクティスに従ったコードレビューを実行するAIエージェント","ko":"Sentry 엔지니어링 실践을 따르는 코드 리뷰를 수행하는 AI 에이전트","es":"Optimice su flujo de trabajo de desarrollo con nuestra guía de revisión de código para herramientas de AI, que cubre prácticas de seguridad, rendimiento y di...","fr":"Optimisez votre flux de travail de développement avec notre guide de revue de code pour outils d''IA, qui couvre les pratiques de sécurité, de performances et...","de":"Optimieren Sie Ihren Entwicklungsworkflow mit unserem Code-Review-Leitfaden für KI-Tools, der Sicherheits-, Leistungs- und Designpraktiken abdeckt","pt":"Aprenda a configurar a revisão de código com Sentry e melhore a qualidade do seu código com nossas práticas de engenharia","ru":"Узнайте, как настроить проверку кода с помощью Sentry и улучшить качество вашего кода с нашими инженерными практиками","ar":"تعرف على كيفية تهيئة أداة مراجعة الكود مع سينتري وتحسين جودة الكود الخاص بك باستخدام ممارسات الهندسة لدينا"},"definition":{"en":"Code-review is a systematic evaluation of code changes to identify issues such as runtime errors, performance problems, and side effects, ensuring adherence to Sentry engineering practices.","zh":"代码审查是指按照Sentry工程实践对代码进行检查和评估","ja":"コードレビューとはSentryエンジニアリングプラクティスに従ったコードの検査と評価","ko":"코드 리뷰는 Sentry 엔지니어링 실践에 따라 코드를 검사하고 평가하는 것","es":"La revisión de código es el proceso de examinar y evaluar el código fuente para detectar errores, mejorar el rendimiento y asegurar la calidad","fr":"La revue de code est le processus d''examen et d''évaluation du code source pour détecter les erreurs, améliorer les performances et assurer la qualité","de":"Die Code-Review ist der Prozess des Überprüfens und Bewerten des Quellcodes, um Fehler zu erkennen, die Leistung zu verbessern und die Qualität zu gewährleisten","pt":"Revisão de código é o processo de examinar o código para identificar problemas de segurança, desempenho e design","ru":"Проверка кода - это процесс проверки кода для выявления проблем безопасности, производительности и дизайна","ar":"أداة مراجعة الكود هي عملية فحص الكود لتحديد مشاكل الأمان والأداء والتصميم"},"features":{"en":["Identifies potential runtime errors, including null pointer issues and out-of-bounds access","Analyzes performance issues, such as unbounded O(n²) operations and N+1 queries","Detects unintended side effects affecting other components","Ensures backwards compatibility by checking for breaking API changes without migration paths","Examines code changes for security vulnerabilities and testing coverage"],"zh":["运行时错误检测","性能优化","安全性检查","设计评审"],"ja":["ランタイムエラーの検出","パフォーマンスの最適化","セキュリティチェック","設計レビュー"],"ko":["런타임 오류 탐지","성능 최적화","보안 점검","디자인 평가"],"es":["Análisis de errores en tiempo de ejecución","Optimización del rendimiento con detección de operaciones O(n²) y consultas N+1","Detección de efectos secundarios y cambios de comportamiento no intencionados","Verificación de la compatibilidad hacia atrás y cambios de API","Revisión de la seguridad y el diseño del código"],"fr":["Analyse des erreurs en temps d''exécution","Optimisation des performances avec détection d''opérations O(n²) et requêtes N+1","Détectection d''effets secondaires et de changements de comportement non intentionnels","Vérification de la compatibilité ascendante et de changements d''API","Revue de la sécurité et de la conception du code"],"de":["Analyse von Laufzeitfehlern","Leistungsoptimierung mit Erkennung von O(n²)-Operationen und N+1-Abfragen","Erkennung von Nebenwirkungen und unbeabsichtigten Verhaltensänderungen","Überprüfung der Abwärtskompatibilität und API-Änderungen","Überprüfung der Sicherheit und des Code-Designs"],"pt":["Identificação de erros de tempo de execução","Análise de desempenho para operações não limitadas","Verificação de efeitos colaterais","Análise de compatibilidade com versões anteriores"],"ru":["Определение ошибок времени выполнения","Анализ производительности для неограниченных операций","Проверка побочных эффектов","Анализ обратной совместимости"],"ar":["تحديد أخطاء وقت التشغيل","تحليل الأداء لعمليات غير مقيدة","فحص الآثار الجانبية","تحليل التوافق مع الإصدارات السابقة"]},"keywords":{"en":["how to use code-review","code-review best practices","Sentry code quality","code-review alternative","code-review vs manual review","code-review install guide","code-review setup for AI agents","what is code-review","code-review for developers","code-review tutorial"],"zh":["代码审查AI工具","Sentry工程实践","代码质量检查","安全性评估","性能优化","设计评审"],"ja":["コードレビューAIエージェント","Sentryエンジニアリングプラクティス","コード品質チェック","セキュリティ評価","パフォーマンス最適化","設計レビュー"],"ko":["코드 리뷰 AI 에이전트","Sentry 엔지니어링 실践","코드 품질 점검","보안 평가","성능 최적화","디자인 평가"],"es":["revisión de código","herramientas de AI","desarrollo de software","prácticas de seguridad","optimización del rendimiento","diseño de código","compatibilidad hacia atrás","cambio de API","errores en tiempo de ejecución"],"fr":["revue de code","outils d''IA","développement de logiciels","pratiques de sécurité","optimisation des performances","conception de code","compatibilité ascendante","changement d''API","erreurs en temps d''exécution"],"de":["Code-Review","KI-Tools","Software-Entwicklung","Sicherheitspraktiken","Leistungsoptimierung","Code-Design","Abwärtskompatibilität","API-Änderung","Laufzeitfehler"],"pt":["revisão de código","Sentry","segurança do código","desempenho do código","design de código","práticas de engenharia","erros de tempo de execução","análise de desempenho"],"ru":["проверка кода","Sentry","безопасность кода","производительность кода","дизайн кода","инженерные практики","ошибки времени выполнения","анализ производительности"],"ar":["مراجعة الكود","سينتري","أمان الكود","أداء الكود","تصميم الكود","ممارسات الهندسة","أخطاء وقت التشغيل","تحليل الأداء"]}},"agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing advanced code analysis capabilities for security, performance, and design review","zh":"适用于像Cursor、Windsurf和Claude Code这样的AI代理，需要高级代码分析功能以进行安全、性能和设计审查","ja":"Cursor、Windsurf、Claude CodeなどのAIエージェントに適しています。これらはセキュリティ、パフォーマンス、設計レビューのための高度なコード分析機能を必要とします","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 보안, 성능 및 디자인 검토를 위한 고급 코드 분석 기능이 필요합니다","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan capacidades de análisis de código avanzadas para seguridad, rendimiento y revisión de diseño","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant des capacités d''analyse de code avancées pour la sécurité, les performances et la revue de conception","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die erweiterte Codeanalysefunktionen für Sicherheit, Leistung und Designüberprüfung benötigen","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de capacidades avançadas de análise de código para segurança, desempenho e revisão de design","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которым необходимы расширенные возможности анализа кода для безопасности, производительности и обзора дизайна","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذي يحتاج إلى قدرات تحليل متقدمة للأمان والأداء والمراجعة التصميمية"},"recommendation":{"en":"Empowers agents to perform comprehensive code reviews following Sentry engineering practices, examining runtime errors, performance issues, and security vulnerabilities using protocols like pull requests and API changes","zh":"使代理能够按照Sentry工程实践执行全面代码审查，检查运行时错误、性能问题和安全漏洞，使用诸如拉取请求和API更改的协议","ja":"エージェントがSentryエンジニアリングの実践に従って包括的なコードレビューを実行できるようにし、プルリクエストやAPIの変更などのプロトコルを使用してランタイムエラー、パフォーマンスの問題、セキュリティの脆弱性を調べます","ko":"에이전트가 Sentry 엔지니어링 실무를 따라 전체 코드 리뷰를 수행할 수 있도록 해주며, 풀 리퀘스트 및 API 변경과 같은 프로토콜을 사용하여 런타임 오류, 성능 문제 및 보안 취약성을 조사합니다","es":"Habilita a los agentes a realizar revisiones de código exhaustivas siguiendo las prácticas de ingeniería de Sentry, examinando errores de tiempo de ejecución, problemas de rendimiento y vulnerabilidades de seguridad utilizando protocolos como solicitudes de extracción y cambios de API","fr":"Permet aux agents d''effectuer des examens de code exhaustifs en suivant les pratiques d''ingénierie de Sentry, en examinant les erreurs d''exécution, les problèmes de performance et les vulnérabilités de sécurité en utilisant des protocoles tels que les demandes d''extraction et les modifications d''API","de":"Ermöglicht es Agents, umfassende Code-Reviews durchzuführen, indem sie den Ingenieurnormen von Sentry folgen, Laufzeitfehler, Leistungsprobleme und Sicherheitslücken unter Verwendung von Protokollen wie Pull-Requests und API-Änderungen untersuchen","pt":"Habilita os agentes a realizar revisões de código abrangentes seguindo as práticas de engenharia do Sentry, examinando erros de tempo de execução, problemas de desempenho e vulnerabilidades de segurança usando protocolos como solicitações de pull e alterações de API","ru":"Наделяет агентов возможностью проводить комплексные обзоры кода в соответствии с инженерными практиками Sentry, изучая ошибки времени выполнения, проблемы производительности и уязвимости безопасности с помощью протоколов, таких как запросы на включение и изменения API","ar":"تمكين الوكلاء من أداء مراجعات شاملة للكود متابعة لممارسات هندسة Sentry، وفحص أخطاء وقت التشغيل ومشاكل الأداء والثغرات الأمنية باستخدام بروتوكولات مثل طلبات السحب وتغييرات API"},"useCases":{"en":["Debugging potential exceptions and null pointer issues","Optimizing code performance by identifying unbounded O(n²) operations","Ensuring backwards compatibility by reviewing API changes"],"zh":["调试潜在的异常和空指针问题","通过识别无界O(n²)操作来优化代码性能","通过审查API更改来确保向后兼容性"],"ja":["潜在の例外とヌルポインタの問題をデバッグする","無限のO(n²)操作を特定することでコードのパフォーマンスを最適化する","APIの変更をレビューすることで下位互換性を確保する"],"ko":["潜在的な 예외 및 Null 포인터 문제를 디버깅합니다","무제한 O(n²) 연산을 식별하여 코드 성능을 최적화합니다","API 변경 사항을 검토하여 하위 호환성을 보장합니다"],"es":["Depuración de posibles excepciones y problemas de punteros nulos","Optimización del rendimiento del código al identificar operaciones no acotadas O(n²)","Garantía de compatibilidad hacia atrás al revisar los cambios de API"],"fr":["Débogage des exceptions et des problèmes de pointeurs nuls potentiels","Optimisation des performances du code en identifiant les opérations non bornées O(n²)","Assurance de la compatibilité ascendante en examinant les modifications d''API"],"de":["Behandlung potenzieller Ausnahmen und Nullzeigerprobleme","Optimierung der Codeleistung durch Identifizierung unbeschränkter O(n²)-Operationen","Sicherstellung der Abwärtskompatibilität durch Überprüfung von API-Änderungen"],"pt":["Depuração de exceções e problemas de ponteiro nulo potenciais","Otimização do desempenho do código identificando operações não limitadas O(n²)","Garantia de compatibilidade com versões anteriores revisando alterações de API"],"ru":["Отладка потенциальных исключений и проблем с нулевыми указателями","Оптимизация производительности кода, выявляя неограниченные операции O(n²)","Обеспечение обратной совместимости, пересматривая изменения API"],"ar":["تصحيح أخطاء الاستثناءات والمشاكل المحتملة للاشارة الى بؤل NULL","تحسين أداء الكود عن طريق تحديد العمليات غير المقيدة O(n²)","ضمان التوافق العكسي من خلال مراجعة تغييرات API"]},"limitations":{"en":["Requires knowledge of Sentry engineering practices","Limited to code review of Sentry projects"],"zh":["需要了解Sentry工程实践","仅限Sentry项目的代码审查"],"ja":["Sentryエンジニアリングの実践の知識が必要","Sentryプロジェクトのコードレビューのみ"],"ko":["Sentry 엔지니어링 실무에 대한 지식이 필요합니다","Sentry 프로젝트의 코드 리뷰만 해당"],"es":["Requiere conocimiento de las prácticas de ingeniería de Sentry","Limitado a la revisión de código de proyectos de Sentry"],"fr":["Nécessite une connaissance des pratiques d''ingénierie de Sentry","Limité à la revue de code des projets Sentry"],"de":["Benötigt Kenntnisse der Ingenieurnormen von Sentry","Begrenzt auf Code-Review von Sentry-Projekten"],"pt":["Requer conhecimento das práticas de engenharia do Sentry","Limitado à revisão de código de projetos do Sentry"],"ru":["Требует знания инженерных практик Sentry","Ограничен обзором кода проектов Sentry"],"ar":["يتطلب معرفة بممارسات هندسة Sentry","محدود بمراجعة الكود لمشاريع Sentry"]},"version":4},"contentHash":"ec5fc8855cb4648b4f2c79b608f8c8824a2da6a683330524c4d6283e4a3954c4","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":77}');
