INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/django-access-review', 'django-access-review', 'getsentry', 'skills', 'official', 'django-access-review getsentry skills official tag-production The django-access-review skill helps developers review Django views, DRF viewsets, and ORM queries for IDOR security vulnerabilities. It benefits developers working with Django and Python. Django访问控制和IDOR安全审查，用于审查Django视图、DRF视图集、ORM查询等 Djangoアクセスレビューは、IDOR脆弱性とアクセス制御をチェックするために使用されます 장고 접근 검토는 IDOR 취약점과 접근 제어를 검토하는 데 사용됩니다 django-access-review es una herramienta para revisar el control de acceso y la seguridad IDOR en Django. Ayuda a identificar vulnerabilidades en la autorización de usuarios django-access-review est un outil pour réviser le contrôle d''accès et la sécurité IDOR dans Django. Il aide à identifier les vulnérabilités dans l''autorisation des utilisateurs django-access-review ist ein Tool zur Überprüfung der Zugriffskontrolle und der IDOR-Sicherheit in Django. Es hilft bei der Identifizierung von Schwachstellen in der Benutzerautorisierung O django-access-review é uma ferramenta para revisar o controle de acesso e a segurança IDOR em aplicações Django, ajudando a identificar vulnerabilidades django-access-review - это инструмент для проверки контроля доступа и безопасности IDOR в приложениях Django, помогающий выявить уязвимости django-access-review هي أداة لمراقبة التحكم في الوصول وأمان IDOR في تطبيقات Django، تساعد في تحديد الثغرات how to use django-access-review django-access-review setup guide idor security review in django django access control best practices django-access-review alternative django-access-review vs owasp django-access-review install what is django-access-review django idor vulnerability prevention Django访问控制 IDOR安全审查 Django权限 对象权限 租户隔离 Django安全 AI Agent 代码审查 Investigates access control vulnerabilities in Django views and DRF viewsets Reviews ORM queries for IDOR security risks Analyzes Python/Django code for proper authorization and permission handling Checks for tenant isolation and broken access control Provides a philosophical approach to investigation over pattern matching django-access-review is a skill that reviews Django access control and IDOR security by investigating how the codebase handles user authorization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/skills/iterate-pr', 'official', 'getsentry', 'skills', 'getsentry/skills', 'iterate-pr', 360, 11, 77, '2026-03-06T00:20:36Z', '2026-03-06T05:11:28.650Z', '07322339d5e6b78167025c3bb6a6e2aebbb8d5095d9d7b4f6db2fc56b7f26560', '{"id":"getsentry/skills/iterate-pr","name":"iterate-pr","description":{"en":"iterate-pr automates the process of iterating on a PR until CI checks pass and review feedback is addressed, benefiting developers working with GitHub CLI and Python scripts.","zh":"iterate-pr 是一个自动化 CI 检查和代码审查的工具，使用 GitHub CLI 和 Python 脚本","ja":"iterate-pr は CI チェックとコードレビューを自動化するツールで、GitHub CLI と Python スクリプトを使用","ko":"iterate-pr는 CI 체크 및 코드 리뷰를 자동화하는 도구로 GitHub CLI 및 Python 스크립트를 사용","es":"Iterate-pr es una herramienta de AI que automatiza el ciclo de feedback y reparación en tus pruebas CI/CD. Requiere GitHub CLI autenticado","fr":"Iterate-pr est un outil d''IA qui automatise le cycle de feedback et de correction dans vos tests CI/CD. Nécessite GitHub CLI authentifié","de":"Iterate-pr ist ein AI-Tool, das den Feedback- und Reparaturzyklus in Ihren CI/CD-Tests automatisiert. Benötigt authentifizierten GitHub CLI","pt":"O Iterate-PR é uma ferramenta que automatiza o ciclo de feedback e correção de falhas de CI, permitindo que os desenvolvedores trabalhem de forma mais eficiente","ru":"Iterate-PR - это инструмент, который автоматизирует цикл обратной связи и исправления ошибок CI, позволяя разработчикам работать более эффективно","ar":"Iterate-PR هو أداة تلقائية لتعزيز دورة ملاحظات الإصلاح والاختبار التلقائي، مما يتيح للمطورين العمل بشكل أكثر كفاءة"},"owner":"getsentry","repo":"skills","repoPath":"getsentry/skills","stars":360,"forks":11,"updatedAt":"2026-03-06T00:20:36Z","topics":["tag-production"],"skillMd":{"name":"iterate-pr","description":"Iterate on a PR until CI passes. Use when you need to fix CI failures, address review feedback, or continuously push fixes until all checks are green. Automates the feedback-fix-push-wait cycle.","bodyPreview":"# Iterate on PR Until CI Passes\n\nContinuously iterate on the current branch until all CI checks pass and review feedback is addressed.\n\n**Requires**: GitHub CLI (`gh`) authenticated.\n\n**Important**: All scripts must be run from the repository root directory (where `.git` is located), not from the skill directory. Use the full path to the script via `${CLAUDE_SKILL_ROOT}`.\n\n## Bundled Scripts\n\n### `scripts/fetch_pr_checks.py`\n\nFetches CI check status and extracts failure snippets from logs.\n\n```b","body":"# Iterate on PR Until CI Passes\n\nContinuously iterate on the current branch until all CI checks pass and review feedback is addressed.\n\n**Requires**: GitHub CLI (`gh`) authenticated.\n\n**Important**: All scripts must be run from the repository root directory (where `.git` is located), not from the skill directory. Use the full path to the script via `${CLAUDE_SKILL_ROOT}`.\n\n## Bundled Scripts\n\n### `scripts/fetch_pr_checks.py`\n\nFetches CI check status and extracts failure snippets from logs.\n\n```bash\nuv run ${CLAUDE_SKILL_ROOT}/scripts/fetch_pr_checks.py [--pr NUMBER]\n```\n\nReturns JSON:\n```json\n{\n  \"pr\": {\"number\": 123, \"branch\": \"feat/foo\"},\n  \"summary\": {\"total\": 5, \"passed\": 3, \"failed\": 2, \"pending\": 0},\n  \"checks\": [\n    {\"name\": \"tests\", \"status\": \"fail\", \"log_snippet\": \"...\", \"run_id\": 123},\n    {\"name\": \"lint\", \"status\": \"pass\"}\n  ]\n}\n```\n\n### `scripts/fetch_pr_feedback.py`\n\nFetches and categorizes PR review feedback using the [LOGAF scale](https://develop.sentry.dev/engineering-practices/code-review/#logaf-scale).\n\n```bash\nuv run ${CLAUDE_SKILL_ROOT}/scripts/fetch_pr_feedback.py [--pr NUMBER]\n```\n\nReturns JSON with feedback categorized as:\n- `high` - Must address before merge (`h:`, blocker, changes requested)\n- `medium` - Should address (`m:`, standard feedback)\n- `low` - Optional (`l:`, nit, style, suggestion)\n- `bot` - Informational automated comments (Codecov, Dependabot, etc.)\n- `resolved` - Already resolved threads\n\nReview bot feedback (from Sentry, Warden, Cursor, Bugbot, CodeQL, etc.) appears in `high`/`medium`/`low` with `review_bot: true` — it is NOT placed in the `bot` bucket.\n\nEach feedback item may also include:\n- `thread_id` - GraphQL node ID for inline review comments (used for replies)\n\n## Workflow\n\n### 1. Identify PR\n\n```bash\ngh pr view --json number,url,headRefName\n```\n\nStop if no PR exists for the current branch.\n\n### 2. Gather Review Feedback\n\nRun `${CLAUDE_SKILL_ROOT}/scripts/fetch_pr_feedback.py` to get categorized feedback already posted on the PR.\n\n### 3. Handle Feedback by LOGAF Priority\n\n**Auto-fix (no prompt):**\n- `high` - must address (blockers, security, changes requested)\n- `medium` - should address (standard feedback)\n\nWhen fixing feedback:\n- Understand the root cause, not just the surface symptom\n- Check for similar issues in nearby code or related files\n- Fix all instances, not just the one mentioned\n\nThis includes review bot feedback (items with `review_bot: true`). Treat it the same as human feedback:\n- Real issue found → fix it\n- False positive → skip, but explain why in a brief comment\n- Never silently ignore review bot feedback — always verify the finding\n\n**Prompt user for selection:**\n- `low` - present numbered list and ask which to address:\n\n```\nFound 3 low-priority suggestions:\n1. [l] \"Consider renaming this variable\" - @reviewer in api.py:42\n2. [nit] \"Could use a list comprehension\" - @reviewer in utils.py:18\n3. [style] \"Add a docstring\" - @reviewer in models.py:55\n\nWhich would you like to address? (e.g., \"1,3\" or \"all\" or \"none\")\n```\n\n**Skip silently:**\n- `resolved` threads\n- `bot` comments (informational only — Codecov, Dependabot, etc.)\n\n#### Replying to Comments\n\nAfter processing each inline review comment, reply on the PR thread to acknowledge the action taken. Only reply to items with a `thread_id` (inline review comments).\n\n**When to reply:**\n- `high` and `medium` items — whether fixed or determined to be false positives\n- `low` items — whether fixed or declined by the user\n\n**How to reply:** Use the `addPullRequestReviewThreadReply` GraphQL mutation with `pullRequestReviewThreadId` and `body` inputs.\n\n**Reply format:**\n- 1-2 sentences: what was changed, why it''s not an issue, or acknowledgment of declined items\n- End every reply with `\\n\\n*— Claude Code*`\n- Before replying, check if the thread already has a reply ending with `*- Claude Code*` or `*— Claude Code*` to avoid duplicates on re-loops\n- If the `gh api` call fails, log and continue — do not block the workflow\n\n### 4. Check CI Status\n\nRun `${CLAUDE_SKILL_ROOT}/scripts/fetch_pr_checks.py` to get structured failure data.\n\n**Wait if pending:** If review bot checks (sentry, warden, cursor, bugbot, seer, codeql) are still running, wait before proceeding—they post actionable feedback that must be evaluated. Informational bots (codecov) are not worth waiting for.\n\n### 5. Fix CI Failures\n\nFor each failure in the script output:\n1. Read the `log_snippet` and trace backwards from the error to understand WHY it failed — not just what failed\n2. Read the relevant code and check for related issues (e.g., if a type error in one call site, check other call sites)\n3. Fix the root cause with minimal, targeted changes\n4. Find existing tests for the affected code and run them. If the fix introduces behavior not covered by existing tests, extend them to cover it (add a test case, not a whole new test file)\n\nDo NOT assume what failed based on check name alone—always read the logs. Do NOT \"quick fix and hope\" — understand the failure thoroughly before changing code.\n\n### 6. Verify Locally, Then Commit and Push\n\nBefore committing, verify your fixes locally:\n- If you fixed a test failure: re-run that specific test locally\n- If you fixed a lint/type error: re-run the linter or type checker on affected files\n- For any code fix: run existing tests covering the changed code\n\nIf local verification fails, fix before proceeding — do not push known-broken code.\n\n```bash\ngit add <files>\ngit commit -m \"fix: <descriptive message>\"\ngit push\n```\n\n### 7. Monitor CI and Address Feedback\n\nPoll CI status and review feedback in a loop instead of blocking:\n\n1. Run `uv run ${CLAUDE_SKILL_ROOT}/scripts/fetch_pr_checks.py` to get current CI status\n2. If all checks passed → proceed to exit conditions\n3. If any checks failed (none pending) → return to step 5\n4. If checks are still pending:\n   a. Run `uv run ${CLAUDE_SKILL_ROOT}/scripts/fetch_pr_feedback.py` for new review feedback\n   b. Address any new high/medium feedback immediately (same as step 3)\n   c. If changes were needed, commit and push (this restarts CI), then continue polling\n   d. Sleep 30 seconds, then repeat from sub-step 1\n5. After all checks pass, do a final feedback check: `sleep 10`, then run `uv run ${CLAUDE_SKILL_ROOT}/scripts/fetch_pr_feedback.py`. Address any new high/medium feedback — if changes are needed, return to step 6.\n\n### 8. Repeat\n\nIf step 7 required code changes (from new feedback after CI passed), return to step 2 for a fresh cycle. CI failures during monitoring are already handled within step 7''s polling loop.\n\n## Exit Conditions\n\n**Success:** All checks pass, post-CI feedback re-check is clean (no new unaddressed high/medium feedback including review bot findings), user has decided on low-priority items.\n\n**Ask for help:** Same failure after 2 attempts, feedback needs clarification, infrastructure issues.\n\n**Stop:** No PR exists, branch needs rebase.\n\n## Fallback\n\nIf scripts fail, use `gh` CLI directly:\n- `gh pr checks name,state,bucket,link`\n- `gh run view <run-id> --log-failed`\n- `gh api repos/{owner}/{repo}/pulls/{number}/comments`\n"},"category":"official","lastSynced":"2026-03-06T05:11:28.650Z","seo":{"title":{"en":"iterate-pr: Automate CI Feedback Loop for AI Agents | AI ...","zh":"iterate-pr 设置指南：自动化 CI 检查和代码审查","ja":"iterate-pr のベストプラクティス：CI チェックとコードレビューの自動化","ko":"iterate-pr 설정 가이드: CI 체크 및 코드 리뷰 자동화","es":"Guía de configuración de iterate-pr para CI/CD","fr":"Configurer iterate-pr pour des tests CI/CD réussis","de":"Einrichtungsleitfaden für iterate-pr zur Automatisierung ...","pt":"Guia de Configuração do Iterate-PR para Automatizar Teste...","ru":"Настройка Iterate-PR для автоматизации тестирования CI","ar":"دليل إعداد Iterate-PR لتحسين الاختبارات التلقائية"},"description":{"en":"Streamline your development workflow with iterate-pr, a skill that automates the feedback-fix-push-wait cycle for CI checks and review feedback - learn how t...","zh":"使用 iterate-pr 自动化 CI 检查和代码审查，提高开发效率和代码质量","ja":"iterate-pr を使用して CI チェックとコードレビューを自動化し、開発効率とコード品質を向上させる","ko":"iterate-pr를 사용하여 CI 체크 및 코드 리뷰를 자동화하고 개발 효율성 및 코드 품질 향상","es":"Automatice el ciclo de feedback y reparación con iterate-pr. Obtenga más información sobre cómo configurar esta herramienta de AI para CI/CD","fr":"Découvrez comment configurer iterate-pr pour automatiser le cycle de feedback et de correction dans vos tests CI/CD","de":"Erfahren Sie, wie Sie iterate-pr einrichten, um den Feedback- und Reparaturzyklus in Ihren CI/CD-Tests zu automatisieren","pt":"Aprenda a configurar o Iterate-PR para automatizar o ciclo de feedback e correção de falhas de CI em seus projetos de desenvolvimento","ru":"Узнайте, как настроить Iterate-PR для автоматизации цикла обратной связи и исправления ошибок CI в ваших проектах разработки","ar":"تعرف على كيفية تهيئة Iterate-PR لتحسين دورة ملاحظات الإصلاح والاختبار التلقائي في مشاريع التطوير الخاصة بك"},"definition":{"en":"iterate-pr is a skill that continuously iterates on the current branch until all CI checks pass and review feedback is addressed, using GitHub CLI and Python scripts.","zh":"iterate-pr 是一个自动化工具，用于持续迭代代码直到所有 CI 检查通过和代码审查完成","ja":"iterate-pr は、すべての CI チェックが通過し、コードレビューが完了するまでコードを継続的に反復する自動化ツール","ko":"iterate-pr는 모든 CI 체크가 통과되고 코드 리뷰가 완료될 때까지 코드를 지속적으로 반복하는 자동화 도구","es":"Iterate-pr es una herramienta de AI que automatiza la iteración en una rama hasta que todas las comprobaciones de CI pasen","fr":"Iterate-pr est un outil d''IA qui automatise l''itération sur une branche jusqu''à ce que toutes les vérifications de CI soient réussies","de":"Iterate-pr ist ein AI-Tool, das die Iteration in einem Branch automatisiert, bis alle CI-Prüfungen bestanden sind","pt":"O que é Iterate-PR? É uma ferramenta de automação de testes de CI que utiliza o GitHub CLI para iterar em um PR até que todos os testes sejam aprovados","ru":"Что такое Iterate-PR? Это инструмент автоматизации тестирования CI, который использует GitHub CLI для итерации по PR до тех пор, пока все тесты не пройдут","ar":"ما هو Iterate-PR؟ هو أداة لتحسين الاختبارات التلقائية التي تستخدم واجهة سطر الأوامر GitHub لإعادة التشغيل في طلبات السحب حتى موافقة جميع الاختبارات"},"features":{"en":["Uses GitHub CLI (`gh`) for authentication and automation","Runs `scripts/fetch_pr_checks.py` to fetch CI check status and extract failure snippets from logs","Requires scripts to be run from the repository root directory (where `.git` is located)","Utilizes the `${CLAUDE_SKILL_ROOT}` path to execute scripts","Automates the feedback-fix-push-wait cycle for CI checks and review feedback"],"zh":["使用 GitHub CLI 进行身份验证","支持 Python 脚本","自动化 CI 检查和代码审查","持续迭代代码直到所有检查通过","支持多种 CI 工具"],"ja":["GitHub CLI を使用した認証","Python スクリプトのサポート","CI チェックとコードレビューの自動化","すべてのチェックが通過するまでコードを継続的に反復","複数の CI ツールのサポート"],"ko":["GitHub CLI를 사용한 인증","Python 스크립트 지원","CI 체크 및 코드 리뷰 자동화","모든 체크가 통과할 때까지 코드를 지속적으로 반복","다중 CI 도구 지원"],"es":["Automatización del ciclo de feedback y reparación","Integración con GitHub CLI","Ejecución de scripts desde el directorio raíz del repositorio","Uso de scripts Python para la extracción de fragmentos de errores de los registros","Soporte para la autenticación con GitHub CLI"],"fr":["Automatisation du cycle de feedback et de correction","Intégration avec GitHub CLI","Exécution de scripts depuis le répertoire racine du référentiel","Utilisation de scripts Python pour l''extraction de fragments d''erreurs des journaux","Prise en charge de l''authentification avec GitHub CLI"],"de":["Automatisierung des Feedback- und Reparaturzyklus","Integration mit GitHub CLI","Ausführung von Skripten vom Repository-Root-Verzeichnis","Verwendung von Python-Skripten zur Extraktion von Fehlerfragmenten aus den Log-Dateien","Unterstützung für die Authentifizierung mit GitHub CLI"],"pt":["Automação do ciclo de feedback e correção de falhas de CI","Utilização do GitHub CLI para iterar em um PR","Execução de scripts em Python para fetch de status de testes","Extração de trechos de falha de logs","Compatibilidade com tag-production"],"ru":["Автоматизация цикла обратной связи и исправления ошибок CI","Использование GitHub CLI для итерации по PR","Выполнение скриптов на Python для получения статуса тестов","Извлечение фрагментов ошибок из логов","Совместимость с tag-production"],"ar":["تحسين دورة ملاحظات الإصلاح والاختبار التلقائي","استخدام واجهة سطر الأوامر GitHub لإعادة التشغيل في طلبات السحب","تشغيل البرامج النصية بالبايثون لاسترداد حالة الاختبارات","استخراج مقتطفات الأخطاء من السجلات","التوافق مع العلامة الإنتاجية"]},"keywords":{"en":["how to use iterate-pr","iterate-pr setup guide","what is iterate-pr","iterate-pr alternative","iterate-pr vs github actions","iterate-pr install","github cli automation","ci check automation","python script automation"],"zh":["iterate-pr","GitHub CLI","Python 脚本","CI 检查","代码审查","自动化工具","代码质量","开发效率"],"ja":["iterate-pr","GitHub CLI","Python スクリプト","CI チェック","コードレビュー","自動化ツール","コード品質","開発効率"],"ko":["iterate-pr","GitHub CLI","Python 스크립트","CI 체크","코드 리뷰","자동화 도구","코드 품질","개발 효율성"],"es":["iterate-pr","herramientas de AI para CI/CD","automatización de pruebas","GitHub CLI","scripts Python","integración continua","entrega continua","desarrollo de software","pruebas de software"],"fr":["iterate-pr","outils d''IA pour CI/CD","automatisation des tests","GitHub CLI","scripts Python","intégration continue","livraison continue","développement de logiciels","tests de logiciels"],"de":["iterate-pr","AI-Tools für CI/CD","Automatisierung von Tests","GitHub CLI","Python-Skripte","kontinuierliche Integration","kontinuierliche Lieferung","Software-Entwicklung","Software-Tests"],"pt":["Iterate-PR","Automação de testes de CI","GitHub CLI","Python","Tag-production","Desenvolvimento de software","Testes automatizados","Ferramentas de desenvolvimento"],"ru":["Iterate-PR","Автоматизация тестирования CI","GitHub CLI","Python","Tag-production","Разработка программного обеспечения","Автоматизированное тестирование","Инструменты разработки"],"ar":["Iterate-PR","تحسين الاختبارات التلقائية","واجهة سطر الأوامر GitHub","بايثون","العلامة الإنتاجية","تطوير البرمجيات","الاختبارات التلقائية","أدوات التطوير"]}},"agentAnalysis":{"suitability":{"en":"Perfect for GitHub-integrated Agents needing automated CI/CD pipeline management and PR iteration.","zh":"适合需要自动化CI/CD管道管理和PR迭代的GitHub集成Agent。","ja":"GitHubと統合されたエージェントが自動化されたCI/CDパイプライン管理とPRのイテレーションを必要とする場合に最適。","ko":"GitHub 통합 에이전트가 자동화된 CI/CD 파이프라인 관리 및 PR 반복을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes integrados con GitHub que necesitan una gestión automatizada de pipelines de CI/CD y iteración de PR.","fr":"Parfait pour les Agents intégrés à GitHub nécessitant une gestion automatisée de pipeline de CI/CD et d''itération de PR.","de":"Perfekt für GitHub-integrierte Agenten, die eine automatisierte Verwaltung von CI/CD-Pipelines und PR-Iteration benötigen.","pt":"Perfeito para Agentes integrados ao GitHub que necessitam de gerenciamento de pipeline de CI/CD automatizado e iteração de PR.","ru":"Идеально подходит для агентов, интегрированных с GitHub, которым требуется автоматизированное управление конвейером CI/CD и итерация PR.","ar":"مثالي لعميل GitHub المتكامل الذي يحتاج إلى إدارة трубة CI/CD آليّة و تكرار PR."},"recommendation":{"en":"Empowers agents to automate the feedback-fix-push-wait cycle using GitHub CLI, streamlining CI failure fixes, review feedback addressing, and continuous integration until all checks pass, utilizing scripts like `scripts/fetch_pr_checks.py` for CI check status and failure snippet extraction.","zh":"赋予代理人使用GitHub CLI自动化反馈-修复-推送-等待循环的能力，简化CI失败修复、审查反馈处理和持续集成，直到所有检查都通过，使用诸如`scripts/fetch_pr_checks.py`的脚本来获取CI检查状态和失败片段。","ja":"GitHub CLIを使用して、エージェントがフィードバック-修正-プッシュ-待機サイクルを自動化できるようにします。CIの失敗を修正するのを簡素化し、レビューのフィードバックに対応し、すべてのチェックが通過するまで継続的に統合します。CIチェックのステータスと失敗スニペットの抽出に`scripts/fetch_pr_checks.py`のようなスクリプトを使用します。","ko":"에이전트가 GitHub CLI를 사용하여 피드백-수정-푸시-대기 주기를 자동화할 수 있도록 합니다. CI 실패를 수정하고審查 피드백에 대응하며 모든 체크가 통과할 때까지 지속적으로 통합합니다. CI 체크 상태 및 실패 스니펫 추출에 `scripts/fetch_pr_checks.py`와 같은 스크립트를 사용합니다.","es":"Habilita a los agentes a automatizar el ciclo de retroalimentación-corrección-envío-espera utilizando GitHub CLI, simplificando la corrección de fallos de CI, la dirección de comentarios de revisión y la integración continua hasta que pasen todas las comprobaciones, utilizando scripts como `scripts/fetch_pr_checks.py` para el estado de comprobación de CI y la extracción de fragmentos de fallo.","fr":"Permet aux agents d''automatiser le cycle de rétroaction-correction-envoi-attente en utilisant GitHub CLI, simplifiant la correction des échecs de CI, l''adressage des commentaires de révision et l''intégration continue jusqu''à ce que toutes les vérifications passent, en utilisant des scripts comme `scripts/fetch_pr_checks.py` pour le statut de vérification de CI et l''extraction de fragments d''échec.","de":"Ermächtigt Agenten, den Feedback-Fix-Push-Warte-Zyklus mithilfe von GitHub CLI zu automatisieren, wodurch CI-Fehlerkorrekturen, die Bearbeitung von Review-Feedback und die kontinuierliche Integration vereinfacht werden, bis alle Prüfungen bestanden sind, unter Verwendung von Skripten wie `scripts/fetch_pr_checks.py` für den CI-Prüfungsstatus und die Extraktion von Fehlertexten.","pt":"Habilita os agentes a automatizar o ciclo de feedback-correção-empurrar-esperar usando o GitHub CLI, simplificando a correção de falhas de CI, o endereçamento de feedback de revisão e a integração contínua até que todas as verificações passem, utilizando scripts como `scripts/fetch_pr_checks.py` para o status da verificação de CI e extração de trechos de falha.","ru":"Позволяет агентам автоматизировать цикл обратной связи-исправления-пushed-ожидания с помощью GitHub CLI, упрощая исправление сбоев CI, устранение замечаний по рецензии и непрерывную интеграцию до тех пор, пока все проверки не пройдут, используя скрипты, такие как `scripts/fetch_pr_checks.py`, для состояния проверки CI и извлечения фрагментов ошибок.","ar":"يُفعّل العملاء لتحسين دورة ملاحظات-تصحيح-دفع-انتظار باستخدام واجهة سطر الأوامر GitHub، مبسطاً إصلاحات فشل CI ومعالجة ملاحظات المراجعة والتكامل المستمر حتى كل الفحوصات تقطع، مستخدماً نصوصاً مثل `scripts/fetch_pr_checks.py` لحالة فحص CI واستخراج شذرات الفشل."},"useCases":{"en":["Automating CI failure fixes","Addressing review feedback iteratively","Continuously pushing fixes until all CI checks pass"],"zh":["自动化CI失败修复","迭代性地处理审查反馈","持续推送修复直到所有CI检查通过"],"ja":["CIの失敗を自動化して修正する","レビューのフィードバックをイテレーションして対応する","すべてのCIチェックが通過するまで修正を継続的にプッシュする"],"ko":["CI 실패를 자동화하여 수정","審查 피드백을 반복적으로 처리","모든 CI 체크가 통과할 때까지 修复을 지속적으로 푸시"],"es":["Automatización de correcciones de fallos de CI","Dirección iterativa de comentarios de revisión","Envío continuo de correcciones hasta que pasen todas las comprobaciones de CI"],"fr":["Automatisation des corrections d''échecs de CI","Adresse iterative des commentaires de révision","Envoi continu de corrections jusqu''à ce que toutes les vérifications de CI passent"],"de":["Automatisierung von CI-Fehlerkorrekturen","Iteratives Bearbeiten von Review-Feedback","Kontinuierliches Einreichen von Korrekturen, bis alle CI-Prüfungen bestanden sind"],"pt":["Automatizar a correção de falhas de CI","Endereçar feedback de revisão de forma iterativa","Empurrar continuamente correções até que todas as verificações de CI passem"],"ru":["Автоматизировать исправление сбоев CI","Итеративно устранять замечания по рецензии","Продолжительно передавать исправления до тех пор, пока все проверки CI не пройдут"],"ar":["تحسين إصلاحات فشل CI","معالجة ملاحظات المراجعة بالتكرار","دفع التصحيحات المستمرة حتى تتجاوز جميع فحوصات CI"]},"limitations":{"en":["Requires GitHub CLI (`gh`) authenticated","Must be run from the repository root directory"],"zh":["需要认证的GitHub CLI (`gh`)","必须从仓库根目录运行"],"ja":["認証されたGitHub CLI (`gh`)が必要","リポジトリのルートディレクトリから実行する必要がある"],"ko":["인증된 GitHub CLI (`gh`)가 필요","仓库 根 디렉토리에서 실행해야 함"],"es":["Requiere GitHub CLI (`gh`) autenticado","Debe ejecutarse desde el directorio raíz del repositorio"],"fr":["Nécessite GitHub CLI (`gh`) authentifié","Doit être exécuté à partir du répertoire racine du référentiel"],"de":["Benötigt GitHub CLI (`gh`) authentifiziert","Muss vom Repository-Stammdirectory aus ausgeführt werden"],"pt":["Requer autenticação do GitHub CLI (`gh`)","Deve ser executado a partir do diretório raiz do repositório"],"ru":["Требуется аутентификация GitHub CLI (`gh`)","Должно быть запущено из корневого каталога репозитория"],"ar":["يتطلب مصادقة واجهة سطر الأوامر GitHub (`gh`)","يجب تشغيله من目录 الجذر للمستودع"]},"version":4},"contentHash":"07322339d5e6b78167025c3bb6a6e2aebbb8d5095d9d7b4f6db2fc56b7f26560","repoEtag":"W/\"36a09bba6a611068f31a3df860388e78cbe9407beaecc6e6da77ba4b47f9eb59\"","qualityScore":77}');
