INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/skills/iterate-pr', 'iterate-pr', 'getsentry', 'skills', 'official', 'iterate-pr getsentry skills official tag-production iterate-pr automates the process of iterating on a PR until CI checks pass and review feedback is addressed, benefiting developers working with GitHub CLI and Python scripts. iterate-pr 是一个自动化 CI 检查和代码审查的工具，使用 GitHub CLI 和 Python 脚本 iterate-pr は CI チェックとコードレビューを自動化するツールで、GitHub CLI と Python スクリプトを使用 iterate-pr는 CI 체크 및 코드 리뷰를 자동화하는 도구로 GitHub CLI 및 Python 스크립트를 사용 Iterate-pr es una herramienta de AI que automatiza el ciclo de feedback y reparación en tus pruebas CI/CD. Requiere GitHub CLI autenticado Iterate-pr est un outil d''IA qui automatise le cycle de feedback et de correction dans vos tests CI/CD. Nécessite GitHub CLI authentifié Iterate-pr ist ein AI-Tool, das den Feedback- und Reparaturzyklus in Ihren CI/CD-Tests automatisiert. Benötigt authentifizierten GitHub CLI O Iterate-PR é uma ferramenta que automatiza o ciclo de feedback e correção de falhas de CI, permitindo que os desenvolvedores trabalhem de forma mais eficiente Iterate-PR - это инструмент, который автоматизирует цикл обратной связи и исправления ошибок CI, позволяя разработчикам работать более эффективно Iterate-PR هو أداة تلقائية لتعزيز دورة ملاحظات الإصلاح والاختبار التلقائي، مما يتيح للمطورين العمل بشكل أكثر كفاءة how to use iterate-pr iterate-pr setup guide what is iterate-pr iterate-pr alternative iterate-pr vs github actions iterate-pr install github cli automation ci check automation python script automation iterate-pr GitHub CLI Python 脚本 CI 检查 代码审查 自动化工具 代码质量 开发效率 Uses GitHub CLI (`gh`) for authentication and automation Runs `scripts/fetch_pr_checks.py` to fetch CI check status and extract failure snippets from logs Requires scripts to be run from the repository root directory (where `.git` is located) Utilizes the `${CLAUDE_SKILL_ROOT}` path to execute scripts Automates the feedback-fix-push-wait cycle for CI checks and review feedback iterate-pr is a skill that continuously iterates on the current branch until all CI checks pass and review feedback is addressed, using GitHub CLI and Python scripts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('huggingface/skills/huggingface-gradio', 'official', 'huggingface', 'skills', 'huggingface/skills', 'gradio', 8290, 490, 77, '2026-03-06T05:28:53Z', '2026-03-06T05:42:21.384Z', '4efdbe6670297c26456043af8568733a36c12e5bb6df15b38967f19555075a99', '{"id":"huggingface/skills/huggingface-gradio","name":"gradio","description":{"en":"Gradio is a Python library for building interactive web UIs and ML demos, ideal for developers and data scientists. It provides a simple and intuitive API for creating custom interfaces and chatbots.","zh":"Gradio Python","ja":"Gradio AI","ko":"Gradio ","es":"Gradio es una biblioteca Python para construir interfaces web interactivas y demos de ML. Esta habilidad cubre la API principal, patrones y ejemplos.","fr":"Gradio est une bibliothèque Python pour créer des interfaces web interactives et des démos de ML. Cette compétence couvre l''API principale, les modèles et les exemples.","de":"Gradio ist eine Python-Bibliothek zum Erstellen interaktiver Web-Oberflächen und ML-Demos. Diese Fähigkeit deckt die Haupt-API, Muster und Beispiele ab.","pt":"O Gradio é uma biblioteca Python para construir interfaces web interativas e demos de ML. Aprenda a usar a API, padrões e exemplos para criar aplicativos Gradio personalizados.","ru":"Gradio - это библиотека Python для создания интерактивных веб-интерфейсов и демонстраций ML. Узнайте, как использовать API, шаблоны и примеры для построения настраиваемых приложений Gradio с помощью ИИ Агентов.","ar":"Gradio هو مكتبة Python لبناء واجهات ويب تفاعلية ودemos للتعلم الآلي. تعلم كيفية استخدام API و الأنماط و الأمثلة لإنشاء تطبيقات Gradio المخصصة."},"owner":"huggingface","repo":"skills","repoPath":"huggingface/skills","stars":8290,"forks":490,"updatedAt":"2026-03-06T05:28:53Z","topics":[],"skillMd":{"name":"gradio","description":"Build Gradio web UIs and demos in Python. Use when creating or editing Gradio apps, components, event listeners, layouts, or chatbots.","bodyPreview":"# Gradio\n\nGradio is a Python library for building interactive web UIs and ML demos. This skill covers the core API, patterns, and examples.\n\n## Guides\n\nDetailed guides on specific topics (read these when relevant):\n\n- [Quickstart](https://www.gradio.app/guides/quickstart)\n- [The Interface Class](https://www.gradio.app/guides/the-interface-class)\n- [Blocks and Event Listeners](https://www.gradio.app/guides/blocks-and-event-listeners)\n- [Controlling Layout](https://www.gradio.app/guides/controllin","body":"# Gradio\n\nGradio is a Python library for building interactive web UIs and ML demos. This skill covers the core API, patterns, and examples.\n\n## Guides\n\nDetailed guides on specific topics (read these when relevant):\n\n- [Quickstart](https://www.gradio.app/guides/quickstart)\n- [The Interface Class](https://www.gradio.app/guides/the-interface-class)\n- [Blocks and Event Listeners](https://www.gradio.app/guides/blocks-and-event-listeners)\n- [Controlling Layout](https://www.gradio.app/guides/controlling-layout)\n- [More Blocks Features](https://www.gradio.app/guides/more-blocks-features)\n- [Custom CSS and JS](https://www.gradio.app/guides/custom-CSS-and-JS)\n- [Streaming Outputs](https://www.gradio.app/guides/streaming-outputs)\n- [Streaming Inputs](https://www.gradio.app/guides/streaming-inputs)\n- [Sharing Your App](https://www.gradio.app/guides/sharing-your-app)\n- [Custom HTML Components](https://www.gradio.app/guides/custom-HTML-components)\n- [Getting Started with the Python Client](https://www.gradio.app/guides/getting-started-with-the-python-client)\n- [Getting Started with the JS Client](https://www.gradio.app/guides/getting-started-with-the-js-client)\n\n## Core Patterns\n\n**Interface** (high-level): wraps a function with input/output components.\n\n```python\nimport gradio as gr\n\ndef greet(name):\n    return f\"Hello {name}!\"\n\ngr.Interface(fn=greet, inputs=\"text\", outputs=\"text\").launch()\n```\n\n**Blocks** (low-level): flexible layout with explicit event wiring.\n\n```python\nimport gradio as gr\n\nwith gr.Blocks() as demo:\n    name = gr.Textbox(label=\"Name\")\n    output = gr.Textbox(label=\"Greeting\")\n    btn = gr.Button(\"Greet\")\n    btn.click(fn=lambda n: f\"Hello {n}!\", inputs=name, outputs=output)\n\ndemo.launch()\n```\n\n**ChatInterface**: high-level wrapper for chatbot UIs.\n\n```python\nimport gradio as gr\n\ndef respond(message, history):\n    return f\"You said: {message}\"\n\ngr.ChatInterface(fn=respond).launch()\n```\n\n## Key Component Signatures\n\n### `Textbox(value: str | I18nData | Callable | None = None, type: Literal[''text'', ''password'', ''email''] = \"text\", lines: int = 1, max_lines: int | None = None, placeholder: str | I18nData | None = None, label: str | I18nData | None = None, info: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, autofocus: bool = False, autoscroll: bool = True, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", text_align: Literal[''left'', ''right''] | None = None, rtl: bool = False, buttons: list[Literal[''copy''] | Button] | None = None, max_length: int | None = None, submit_btn: str | bool | None = False, stop_btn: str | bool | None = False, html_attributes: InputHTMLAttributes | None = None)`\nCreates a textarea for user to enter string input or display string output..\n\n### `Number(value: float | Callable | None = None, label: str | I18nData | None = None, placeholder: str | I18nData | None = None, info: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", buttons: list[Button] | None = None, precision: int | None = None, minimum: float | None = None, maximum: float | None = None, step: float = 1)`\nCreates a numeric field for user to enter numbers as input or display numeric output..\n\n### `Slider(minimum: float = 0, maximum: float = 100, value: float | Callable | None = None, step: float | None = None, precision: int | None = None, label: str | I18nData | None = None, info: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", randomize: bool = False, buttons: list[Literal[''reset'']] | None = None)`\nCreates a slider that ranges from {minimum} to {maximum} with a step size of {step}..\n\n### `Checkbox(value: bool | Callable = False, label: str | I18nData | None = None, info: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", buttons: list[Button] | None = None)`\nCreates a checkbox that can be set to `True` or `False`.\n\n### `Dropdown(choices: Sequence[str | int | float | tuple[str, str | int | float]] | None = None, value: str | int | float | Sequence[str | int | float] | Callable | DefaultValue | None = DefaultValue(), type: Literal[''value'', ''index''] = \"value\", multiselect: bool | None = None, allow_custom_value: bool = False, max_choices: int | None = None, filterable: bool = True, label: str | I18nData | None = None, info: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", buttons: list[Button] | None = None)`\nCreates a dropdown of choices from which a single entry or multiple entries can be selected (as an input component) or displayed (as an output component)..\n\n### `Radio(choices: Sequence[str | int | float | tuple[str, str | int | float]] | None = None, value: str | int | float | Callable | None = None, type: Literal[''value'', ''index''] = \"value\", label: str | I18nData | None = None, info: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", rtl: bool = False, buttons: list[Button] | None = None)`\nCreates a set of (string or numeric type) radio buttons of which only one can be selected..\n\n### `Image(value: str | PIL.Image.Image | np.ndarray | Callable | None = None, format: str = \"webp\", height: int | str | None = None, width: int | str | None = None, image_mode: Literal[''1'', ''L'', ''P'', ''RGB'', ''RGBA'', ''CMYK'', ''YCbCr'', ''LAB'', ''HSV'', ''I'', ''F''] | None = \"RGB\", sources: list[Literal[''upload'', ''webcam'', ''clipboard'']] | Literal[''upload'', ''webcam'', ''clipboard''] | None = None, type: Literal[''numpy'', ''pil'', ''filepath''] = \"numpy\", label: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, buttons: list[Literal[''download'', ''share'', ''fullscreen''] | Button] | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, streaming: bool = False, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", webcam_options: WebcamOptions | None = None, placeholder: str | None = None, watermark: WatermarkOptions | None = None)`\nCreates an image component that can be used to upload images (as an input) or display images (as an output)..\n\n### `Audio(value: str | Path | tuple[int, np.ndarray] | Callable | None = None, sources: list[Literal[''upload'', ''microphone'']] | Literal[''upload'', ''microphone''] | None = None, type: Literal[''numpy'', ''filepath''] = \"numpy\", label: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, streaming: bool = False, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", format: Literal[''wav'', ''mp3''] | None = None, autoplay: bool = False, editable: bool = True, buttons: list[Literal[''download'', ''share''] | Button] | None = None, waveform_options: WaveformOptions | dict | None = None, loop: bool = False, recording: bool = False, subtitles: str | Path | list[dict[str, Any]] | None = None, playback_position: float = 0)`\nCreates an audio component that can be used to upload/record audio (as an input) or display audio (as an output)..\n\n### `Video(value: str | Path | Callable | None = None, format: str | None = None, sources: list[Literal[''upload'', ''webcam'']] | Literal[''upload'', ''webcam''] | None = None, height: int | str | None = None, width: int | str | None = None, label: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", webcam_options: WebcamOptions | None = None, include_audio: bool | None = None, autoplay: bool = False, buttons: list[Literal[''download'', ''share''] | Button] | None = None, loop: bool = False, streaming: bool = False, watermark: WatermarkOptions | None = None, subtitles: str | Path | list[dict[str, Any]] | None = None, playback_position: float = 0)`\nCreates a video component that can be used to upload/record videos (as an input) or display videos (as an output).\n\n### `File(value: str | list[str] | Callable | None = None, file_count: Literal[''single'', ''multiple'', ''directory''] = \"single\", file_types: list[str] | None = None, type: Literal[''filepath'', ''binary''] = \"filepath\", label: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, height: int | str | float | None = None, interactive: bool | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", allow_reordering: bool = False, buttons: list[Button] | None = None)`\nCreates a file component that allows uploading one or more generic files (when used as an input) or displaying generic files or URLs for download (as output).\n\n### `Chatbot(value: list[MessageDict | Message] | Callable | None = None, label: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, container: bool = True, scale: int | None = None, min_width: int = 160, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, autoscroll: bool = True, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", height: int | str | None = 400, resizable: bool = False, max_height: int | str | None = None, min_height: int | str | None = None, editable: Literal[''user'', ''all''] | None = None, latex_delimiters: list[dict[str, str | bool]] | None = None, rtl: bool = False, buttons: list[Literal[''share'', ''copy'', ''copy_all''] | Button] | None = None, watermark: str | None = None, avatar_images: tuple[str | Path | None, str | Path | None] | None = None, sanitize_html: bool = True, render_markdown: bool = True, feedback_options: list[str] | tuple[str, ...] | None = (''Like'', ''Dislike''), feedback_value: Sequence[str | None] | None = None, line_breaks: bool = True, layout: Literal[''panel'', ''bubble''] | None = None, placeholder: str | None = None, examples: list[ExampleMessage] | None = None, allow_file_downloads: <class ''inspect._empty''> = True, group_consecutive_messages: bool = True, allow_tags: list[str] | bool = True, reasoning_tags: list[tuple[str, str]] | None = None, like_user_message: bool = False)`\nCreates a chatbot that displays user-submitted messages and responses.\n\n### `Button(value: str | I18nData | Callable = \"Run\", every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, variant: Literal[''primary'', ''secondary'', ''stop'', ''huggingface''] = \"secondary\", size: Literal[''sm'', ''md'', ''lg''] = \"lg\", icon: str | Path | None = None, link: str | None = None, link_target: Literal[''_self'', ''_blank'', ''_parent'', ''_top''] = \"_self\", visible: bool | Literal[''hidden''] = True, interactive: bool = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", scale: int | None = None, min_width: int | None = None)`\nCreates a button that can be assigned arbitrary .click() events.\n\n### `Markdown(value: str | I18nData | Callable | None = None, label: str | I18nData | None = None, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool | None = None, rtl: bool = False, latex_delimiters: list[dict[str, str | bool]] | None = None, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", sanitize_html: bool = True, line_breaks: bool = False, header_links: bool = False, height: int | str | None = None, max_height: int | str | None = None, min_height: int | str | None = None, buttons: list[Literal[''copy'']] | None = None, container: bool = False, padding: bool = False)`\nUsed to render arbitrary Markdown output.\n\n### `HTML(value: Any | Callable | None = None, label: str | I18nData | None = None, html_template: str = \"${value}\", css_template: str = \"\", js_on_load: str | None = \"element.addEventListener(''click'', function() { trigger(''click'') });\", apply_default_css: bool = True, every: Timer | float | None = None, inputs: Component | Sequence[Component] | set[Component] | None = None, show_label: bool = False, visible: bool | Literal[''hidden''] = True, elem_id: str | None = None, elem_classes: list[str] | str | None = None, render: bool = True, key: int | str | tuple[int | str, ...] | None = None, preserved_by_key: list[str] | str | None = \"value\", min_height: int | None = None, max_height: int | None = None, container: bool = False, padding: bool = False, autoscroll: bool = False, buttons: list[Button] | None = None, props: Any)`\nCreates a component with arbitrary HTML.\n\n\n## Custom HTML Components\n\nIf a task requires significant customization of an existing component or a component that doesn''t exist in Gradio, you can create one with `gr.HTML`. It supports `html_template` (with `${}` JS expressions and `{{}}` Handlebars syntax), `css_template` for scoped styles, and `js_on_load` for interactivity — where `props.value` updates the component value and `trigger(''event_name'')` fires Gradio events. For reuse, subclass `gr.HTML` and define `api_info()` for API/MCP support. See the [full guide](https://www.gradio.app/guides/custom-HTML-components).\n\nHere''s an example that shows how to create and use these kinds of components:\n\n```python\nimport gradio as gr\n\nclass StarRating(gr.HTML):\n    def __init__(self, label, value=0, **kwargs):\n        html_template = \"\"\"\n        <h2>${label} rating:</h2>\n        ${Array.from({length: 5}, (_, i) => `<img class=''${i < value ? '''' : ''faded''}'' src=''https://upload.wikimedia.org/wikipedia/commons/d/df/Award-star-gold-3d.svg''>`).join('''')}\n        \"\"\"\n        css_template = \"\"\"\n            img { height: 50px; display: inline-block; cursor: pointer; }\n            .faded { filter: grayscale(100%); opacity: 0.3; }\n        \"\"\"\n        js_on_load = \"\"\"\n            const imgs = element.querySelectorAll(''img'');\n            imgs.forEach((img, index) => {\n                img.addEventListener(''click'', () => {\n                    props.value = index + 1;\n                });\n            });\n        \"\"\"\n        super().__init__(value=value, label=label, html_template=html_template, css_template=css_template, js_on_load=js_on_load, **kwargs)\n\n    def api_info(self):\n        return {\"type\": \"integer\", \"minimum\": 0, \"maximum\": 5}\n\n\nwith gr.Blocks() as demo:\n    gr.Markdown(\"# Restaurant Review\")\n    food_rating = StarRating(label=\"Food\", value=3)\n    service_rating = StarRating(label=\"Service\", value=3)\n    ambience_rating = StarRating(label=\"Ambience\", value=3)\n    average_btn = gr.Button(\"Calculate Average Rating\")\n    rating_output = StarRating(label=\"Average\", value=3)\n    def calculate_average(food, service, ambience):\n        return round((food + service + ambience) / 3)\n    average_btn.click(\n        fn=calculate_average,\n        inputs=[food_rating, service_rating, ambience_rating],\n        outputs=rating_output\n    )\n\ndemo.launch()\n```\n\n## Event Listeners\n\nAll event listeners share the same signature:\n\n```python\ncomponent.event_name(\n    fn: Callable | None | Literal[\"decorator\"] = \"decorator\",\n    inputs: Component | Sequence[Component] | set[Component] | None = None,\n    outputs: Component | Sequence[Component] | set[Component] | None = None,\n    api_name: str | None = None,\n    api_description: str | None | Literal[False] = None,\n    scroll_to_output: bool = False,\n    show_progress: Literal[\"full\", \"minimal\", \"hidden\"] = \"full\",\n    show_progress_on: Component | Sequence[Component] | None = None,\n    queue: bool = True,\n    batch: bool = False,\n    max_batch_size: int = 4,\n    preprocess: bool = True,\n    postprocess: bool = True,\n    cancels: dict[str, Any] | list[dict[str, Any]] | None = None,\n    trigger_mode: Literal[\"once\", \"multiple\", \"always_last\"] | None = None,\n    js: str | Literal[True] | None = None,\n    concurrency_limit: int | None | Literal[\"default\"] = \"default\",\n    concurrency_id: str | None = None,\n    api_visibility: Literal[\"public\", \"private\", \"undocumented\"] = \"public\",\n    time_limit: int | None = None,\n    stream_every: float = 0.5,\n    key: int | str | tuple[int | str, ...] | None = None,\n    validator: Callable | None = None,\n) -> Dependency\n```\n\nSupported events per component:\n\n- **AnnotatedImage**: select\n- **Audio**: stream, change, clear, play, pause, stop, pause, start_recording, pause_recording, stop_recording, upload, input\n- **BarPlot**: select, double_click\n- **BrowserState**: change\n- **Button**: click\n- **Chatbot**: change, select, like, retry, undo, example_select, option_select, clear, copy, edit\n- **Checkbox**: change, input, select\n- **CheckboxGroup**: change, input, select\n- **ClearButton**: click\n- **Code**: change, input, focus, blur\n- **ColorPicker**: change, input, submit, focus, blur\n- **Dataframe**: change, input, select, edit\n- **Dataset**: click, select\n- **DateTime**: change, submit\n- **DeepLinkButton**: click\n- **Dialogue**: change, input, submit\n- **DownloadButton**: click\n- **Dropdown**: change, input, select, focus, blur, key_up\n- **DuplicateButton**: click\n- **File**: change, select, clear, upload, delete, download\n- **FileExplorer**: change, input, select\n- **Gallery**: select, upload, change, delete, preview_close, preview_open\n- **HTML**: change, input, click, double_click, submit, stop, edit, clear, play, pause, end, start_recording, pause_recording, stop_recording, focus, blur, upload, release, select, stream, like, example_select, option_select, load, key_up, apply, delete, tick, undo, retry, expand, collapse, download, copy\n- **HighlightedText**: change, select\n- **Image**: clear, change, stream, select, upload, input\n- **ImageEditor**: clear, change, input, select, upload, apply\n- **ImageSlider**: clear, change, stream, select, upload, input\n- **JSON**: change\n- **Label**: change, select\n- **LinePlot**: select, double_click\n- **LoginButton**: click\n- **Markdown**: change, copy\n- **Model3D**: change, upload, edit, clear\n- **MultimodalTextbox**: change, input, select, submit, focus, blur, stop\n- **Navbar**: change\n- **Number**: change, input, submit, focus, blur\n- **ParamViewer**: change, upload\n- **Plot**: change\n- **Radio**: select, change, input\n- **ScatterPlot**: select, double_click\n- **SimpleImage**: clear, change, upload\n- **Slider**: change, input, release\n- **State**: change\n- **Textbox**: change, input, select, submit, focus, blur, stop, copy\n- **Timer**: tick\n- **UploadButton**: click, upload\n- **Video**: change, clear, start_recording, stop_recording, stop, play, pause, end, upload, input\n\n## Additional Reference\n\n- [End-to-End Examples](examples.md) — complete working apps\n"},"category":"official","lastSynced":"2026-03-06T05:42:21.384Z","seo":{"title":{"en":"Gradio: Build Interactive Web UIs and ML Demos | AI Agent...","zh":"Gradio Setup Guide: Python ","ja":"Gradio AI","ko":"Gradio ","es":"Guía de configuración de Gradio para interfaces web inter...","fr":"Guide de démarrage rapide pour les interfaces web interac...","de":"Gradio-Setup-Anleitung für interaktive Web-Oberflächen","pt":"Guia de Configuração do Gradio: Construindo Interfaces We...","ru":"Настройка Gradio: Создание интерактивных веб-интерфейсов ...","ar":"دليل إعداد Gradio: بناء واجهات ويب تفاعلية باستخدام Python"},"description":{"en":"Unlock the power of Gradio and create stunning web UIs and ML demos with ease. Learn how to get started with our expert guides and tutorials.","zh":"Gradio Python ","ja":"Gradio AI ","ko":"Gradio ","es":"Aprende a construir interfaces web interactivas y demos de ML con Gradio. Descubre los patrones y ejemplos para crear aplicaciones personalizadas.","fr":"Découvrez comment créer des interfaces web interactives et des démos de ML avec Gradio. Explorez les modèles et exemples pour des applications sur mesure.","de":"Erfahren Sie, wie Sie interaktive Web-Oberflächen und ML-Demos mit Gradio erstellen. Entdecken Sie Muster und Beispiele für maßgeschneiderte Anwendungen.","pt":"Aprenda a criar interfaces web interativas e demos de ML com o Gradio. Descubra como usar a biblioteca Python para construir aplicativos Gradio personalizados.","ru":"Узнайте, как создать интерактивные веб-интерфейсы и демонстрации ML с помощью Gradio. Откройте для себя, как использовать библиотеку Python для построения на...","ar":"تعرف على كيفية إنشاء واجهات ويب تفاعلية ودemos للتعلم الآلي مع Gradio. اكتشف كيفية استخدام مكتبة Python لبناء تطبيقات Gradio المخصصة."},"definition":{"en":"Gradio is a Python library for building interactive web UIs and ML demos, allowing developers to create custom interfaces, components, and event listeners.","zh":"Gradio Python ","ja":"Gradio AI","ko":"Gradio ","es":"Gradio es una biblioteca Python para interfaces web interactivas y demos de ML","fr":"Gradio est une bibliothèque Python pour les interfaces web interactives et les démos de ML","de":"Gradio ist eine Python-Bibliothek für interaktive Web-Oberflächen und ML-Demos","pt":"O que é Gradio? É uma biblioteca Python para construir interfaces web interativas e demos de ML.","ru":"Что такое Gradio? Это библиотека Python для создания интерактивных веб-интерфейсов и демонстраций ML с помощью ИИ Агентов.","ar":"ما هو Gradio؟ هو مكتبة Python لبناء واجهات ويب تفاعلية ودemos للتعلم الآلي."},"features":{"en":["Builds interactive web UIs using the Interface Class","Supports Blocks and Event Listeners for custom functionality","Allows controlling layout with intuitive API","Enables creation of chatbots and custom components","Provides detailed guides, including Quickstart and API documentation","Offers a simple and intuitive API for ML demo creation"],"zh":["Gradio ","Interface ","Blocks ","Event Listeners ","Layout "],"ja":["Gradio ","Interface ","Blocks "," ","Layout "],"ko":["Gradio ","Interface ","Blocks "," ","Layout "],"es":["Construcción de interfaces web interactivas con Gradio","Creación de demos de ML personalizadas","Uso de la clase Interface para crear aplicaciones","Implementación de bloques y oyentes de eventos","Control de diseño con Gradio"],"fr":["Création d''interfaces web interactives avec Gradio","Conception de démos de ML sur mesure","Utilisation de la classe Interface pour créer des applications","Mise en œuvre de blocs et d''écouteurs d''événements","Contrôle du design avec Gradio"],"de":["Erstellung interaktiver Web-Oberflächen mit Gradio","Erstellung von ML-Demos nach Maß","Verwendung der Interface-Klasse zum Erstellen von Anwendungen","Implementierung von Blöcken und Ereignis-Listenern","Layout-Kontrolle mit Gradio"],"pt":["Crie interfaces web interativas com a classe Interface","Use blocos e ouvintes de eventos para personalizar aplicativos","Controle o layout com a biblioteca Gradio","Crie chatbots personalizados com a biblioteca Gradio","Use a API do Gradio para criar aplicativos personalizados"],"ru":["Создайте интерактивные веб-интерфейсы с помощью класса Interface","Используйте блоки и слушатели событий для настройки приложений","Контролируйте макет с помощью библиотеки Gradio","Создайте настраиваемые чат-боты с помощью библиотеки Gradio","Используйте API Gradio для создания настраиваемых приложений с помощью ИИ Агентов"],"ar":["انشئ واجهات ويب تفاعلية باستخدام فئة Interface","استخدم الكتلة وسماع Events لتحديد تطبيقات مخصصة","تحكم في التصميم باستخدام مكتبة Gradio","انشئ chatbots مخصصة باستخدام مكتبة Gradio","استخدم API Gradio لإنشاء تطبيقات مخصصة"]},"keywords":{"en":["how to use gradio","what is gradio","gradio alternative","gradio vs dash","gradio install","gradio setup guide","gradio tutorial","gradio python library","gradio ml demos","gradio web ui"],"zh":["Gradio","Python Gradio","Gradio ","Gradio Interface","Gradio Blocks","Gradio Event Listeners","Gradio Layout"],"ja":["Gradio","Gradio AI","Python Gradio","Gradio ","Gradio Interface","Gradio Blocks","Gradio "],"ko":["Gradio","Gradio ","Python Gradio","Gradio ","Gradio Interface","Gradio Blocks","Gradio "],"es":["Gradio","interfaces web interactivas","demos de ML","Python","biblioteca Gradio","desarrollo de aplicaciones","creación de interfaces","Herramientas de AI"],"fr":["Gradio","interfaces web interactives","démos de ML","Python","bibliothèque Gradio","développement d''applications","création d''interfaces","Outils d''IA"],"de":["Gradio","interaktive Web-Oberflächen","ML-Demos","Python","Gradio-Bibliothek","Anwendungsentwicklung","Erstellung von Oberflächen","KI-Tools"],"pt":["Gradio","interfaces web interativas","demos de ML","biblioteca Python","API Gradio","chatbots personalizados","ouvintes de eventos","blocos Gradio"],"ru":["Gradio","интерактивные веб-интерфейсы","демонстрации ML","библиотека Python","API Gradio","настраиваемые чат-боты","слушатели событий","блоки Gradio","ИИ Агенты"],"ar":["Gradio","واجهات ويب تفاعلية","دemos للتعلم الآلي","مكتبة Python","API Gradio","чат-ботات مخصصة","سماع Events","كتلة Gradio"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Python Analysis Agents needing advanced interactive web UIs and ML demo capabilities.","zh":"非常适合需要高级交互式Web UI和ML演示功能的Python分析代理。","ja":"Python分析エージェントが高度なインタラクティブWeb UIとMLデモ機能を必要とする場合に最適です。","ko":"고급 인터랙티브 웹 UI와 머신 러닝 데모 기능이 필요한 Python 분석 에이전트에게 적합합니다.","es":"Perfecto para agentes de análisis de Python que necesitan interfaces web interactivas avanzadas y capacidades de demostración de ML.","fr":"Parfait pour les agents d''analyse Python nécessitant des interfaces web interactives avancées et des capacités de démonstration de ML.","de":"Perfekt für Python-Analyse-Agenten, die erweiterte interaktive Web-Benutzeroberflächen und ML-Demo-Funktionen benötigen.","pt":"Perfeito para Agentes de Análise Python que precisam de interfaces web interativas avançadas e capacidades de demonstração de ML.","ru":"Идеально подходит для агентов анализа Python, которым требуются продвинутые интерактивные веб-интерфейсы и возможности демонстрации ML.","ar":"مثالي لعميل تحليل Python الذي يحتاج إلى واجهات ويب تفاعلية متقدمة وقدرات عرض ML."},"recommendation":{"en":"Empowers agents to build interactive Gradio web UIs and demos using Python, leveraging the Interface Class, Blocks, and event listeners to create custom layouts and chatbots, while utilizing protocols like HTTP for seamless deployment.","zh":"赋予代理构建使用Python的交互式Gradio Web UI和演示的能力，利用接口类、块和事件监听器创建自定义布局和聊天机器人，同时利用HTTP等协议实现无缝部署。","ja":"エージェントがPythonを使用してインタラクティブなGradio Web UIとデモを構築する能力を提供します。インターフェイスクラス、ブロック、およびイベントリスナーを使用してカスタムレイアウトとチャットボットを作成し、HTTPなどのプロトコルを使用してシームレスにデプロイします。","ko":"에이전트가 Python을 사용하여 인터랙티브한 Gradio 웹 UI와 데모를 구축할 수 있는 능력을 제공합니다. 인터페이스 클래스, 블록 및 이벤트 리스너를 사용하여 사용자 지정 레이아웃과 챗봇을 생성하며 HTTP와 같은 프로토콜을 사용하여 무중단 배포를 구현합니다.","es":"Habilita a los agentes a crear demos y interfaces web interactivas de Gradio utilizando Python, aprovechando la Clase de Interfaz, Bloques y listeners de eventos para crear diseños personalizados y chatbots, mientras utiliza protocolos como HTTP para una implementación sin problemas.","fr":"Permet aux agents de créer des démos et des interfaces web interactives Gradio en utilisant Python, en exploitant la Classe d''Interface, les Blocs et les listeners d''événements pour créer des dispositions personnalisées et des chatbots, tout en utilisant des protocoles comme HTTP pour un déploiement sans problème.","de":"Ermächtigt die Agenten, interaktive Gradio-Webbenutzeroberflächen und Demos mit Python zu erstellen, indem sie die Schnittstellenklasse, Blöcke und Ereignislistener nutzen, um benutzerdefinierte Layouts und Chatbots zu erstellen, während sie Protokolle wie HTTP für eine nahtlose Bereitstellung verwenden.","pt":"Habilita os agentes a construir interfaces web interativas Gradio e demonstrações usando Python, aproveitando a Interface Class, Blocks e ouvintes de eventos para criar layouts personalizados e chatbots, enquanto utiliza protocolos como HTTP para implantação sem problemas.","ru":"Наделяет агентов возможностью создавать интерактивные веб-интерфейсы Gradio и демонстрации, используя Python, используя Interface Class, Blocks и обработчики событий для создания пользовательских макетов и чат-ботов, а также используя протоколы, такие как HTTP, для бесшовного развертывания.","ar":"تمكّن الوكيل من بناء واجهات ويب تفاعلية Gradio وعروض تقديمية باستخدام Python، وتحقيق الفائدة القصوى من Interface Class و Blocks ومستمعي الأحداث لإنشاء تخطيطات مخصصة وبرامج محادثة، بينما تستخدم بروتوكولات مثل HTTP لنشر سلس."},"useCases":{"en":["Building interactive ML model demos","Creating custom web UIs for data analysis","Developing chatbots with Gradio''s Blocks and event listeners"],"zh":["构建交互式机器学习模型演示","创建数据分析的自定义Web UI","使用Gradio的块和事件监听器开发聊天机器人"],"ja":["インタラクティブな機械学習モデルデモの構築","データ分析のためのカスタムWeb UIの作成","Gradioのブロックとイベントリスナーを使用したチャットボットの開発"],"ko":["인터랙티브 머신 러닝 모델 데모 구축","데이터 분석을 위한 사용자 지정 웹 UI 생성","Gradio의 블록 및 이벤트 리스너를 사용한 챗봇 개발"],"es":["Creación de demos de modelos de ML interactivos","Creación de interfaces web personalizadas para análisis de datos","Desarrollo de chatbots con Bloques y listeners de eventos de Gradio"],"fr":["Création de démos de modèles de ML interactifs","Création d''interfaces web personnalisées pour l''analyse de données","Développement de chatbots avec les Blocs et les listeners d''événements de Gradio"],"de":["Erstellung interaktiver ML-Modell-Demos","Erstellung benutzerdefinierter Webbenutzeroberflächen für Datenanalyse","Entwicklung von Chatbots mit Gradios Blöcken und Ereignislistenern"],"pt":["Construção de demonstrações interativas de modelos de ML","Criação de interfaces web personalizadas para análise de dados","Desenvolvimento de chatbots com Blocks e ouvintes de eventos do Gradio"],"ru":["Создание интерактивных демонстраций моделей ML","Создание пользовательских веб-интерфейсов для анализа данных","Разработка чат-ботов с помощью Blocks и обработчиков событий Gradio"],"ar":["بناء عروض تقديمية تفاعلية لأنماط ML","إنشاء واجهات ويب مخصصة لتحليل البيانات","تطوير برامج محادثة باستخدام Blocks ومستمعي الأحداث من Gradio"]},"limitations":{"en":["Requires Python environment","Gradio library dependency","Limited to building web UIs and demos"],"zh":["需要Python环境","依赖Gradio库","仅限于构建Web UI和演示"],"ja":["Python環境が必要","Gradioライブラリへの依存","Web UIとデモの構築のみ"],"ko":["Python 환경 필요","Gradio 라이브러리 의존","웹 UI 및 데모 구축만 가능"],"es":["Requiere entorno de Python","Dependencia de la biblioteca Gradio","Limitado a la creación de interfaces web y demos"],"fr":["Nécessite un environnement Python","Dépendance de la bibliothèque Gradio","Limité à la création d''interfaces web et de démos"],"de":["Benötigt Python-Umgebung","Abhängigkeit von der Gradio-Bibliothek","Begrenzt auf die Erstellung von Webbenutzeroberflächen und Demos"],"pt":["Requer ambiente Python","Dependência da biblioteca Gradio","Limitado à construção de interfaces web e demonstrações"],"ru":["Требуется среда Python","Зависимость от библиотеки Gradio","Ограничен созданием веб-интерфейсов и демонстраций"],"ar":["يتطلب بيئة Python","اعتماد مكتبة Gradio","محدود ببناء واجهات ويب وعروض تقديمية"]},"version":4},"contentHash":"4efdbe6670297c26456043af8568733a36c12e5bb6df15b38967f19555075a99","repoEtag":"W/\"3e8364a04a12bbf72e64808b1a78e3c2a1041cb67eca8016da4b98e27a299f18\"","qualityScore":77}');
