INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('huggingface/skills/huggingface-gradio', 'gradio', 'huggingface', 'skills', 'official', 'gradio huggingface skills official Gradio is a Python library for building interactive web UIs and ML demos, ideal for developers and data scientists. It provides a simple and intuitive API for creating custom interfaces and chatbots. Gradio Python Gradio AI Gradio Gradio es una biblioteca Python para construir interfaces web interactivas y demos de ML. Esta habilidad cubre la API principal, patrones y ejemplos. Gradio est une bibliothèque Python pour créer des interfaces web interactives et des démos de ML. Cette compétence couvre l''API principale, les modèles et les exemples. Gradio ist eine Python-Bibliothek zum Erstellen interaktiver Web-Oberflächen und ML-Demos. Diese Fähigkeit deckt die Haupt-API, Muster und Beispiele ab. O Gradio é uma biblioteca Python para construir interfaces web interativas e demos de ML. Aprenda a usar a API, padrões e exemplos para criar aplicativos Gradio personalizados. Gradio - это библиотека Python для создания интерактивных веб-интерфейсов и демонстраций ML. Узнайте, как использовать API, шаблоны и примеры для построения настраиваемых приложений Gradio с помощью ИИ Агентов. Gradio هو مكتبة Python لبناء واجهات ويب تفاعلية ودemos للتعلم الآلي. تعلم كيفية استخدام API و الأنماط و الأمثلة لإنشاء تطبيقات Gradio المخصصة. how to use gradio what is gradio gradio alternative gradio vs dash gradio install gradio setup guide gradio tutorial gradio python library gradio ml demos gradio web ui Gradio Python Gradio Gradio Gradio Interface Gradio Blocks Gradio Event Listeners Gradio Layout Builds interactive web UIs using the Interface Class Supports Blocks and Event Listeners for custom functionality Allows controlling layout with intuitive API Enables creation of chatbots and custom components Provides detailed guides, including Quickstart and API documentation Offers a simple and intuitive API for ML demo creation Gradio is a Python library for building interactive web UIs and ML demos, allowing developers to create custom interfaces, components, and event listeners.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/skills/cloudflare', 'official', 'cloudflare', 'skills', 'cloudflare/skills', 'cloudflare', 535, 66, 77, '2026-03-06T05:33:24Z', '2026-03-06T05:54:52.425Z', 'a8a8198011650bfc8005bcef0a4e315808468e4180e6d9169c78d3b200261e2a', '{"id":"cloudflare/skills/cloudflare","name":"cloudflare","description":{"en":"The Cloudflare skill provides a comprehensive platform for development tasks, including Workers, Pages, storage, AI, and security. It benefits developers working with Cloudflare APIs and infrastructure-as-code tools like Terraform and Pulumi.","zh":"Cloudflare是一种综合的平台技能，涵盖Workers、Pages、存储、AI和安全等功能。通过本技能，开发者可以更高效地开发和部署应用程序","ja":"Cloudflareは、Workers、Pages、ストレージ、AI、セキュリティなどを包含した総合的なプラットフォームスキルです。このスキルを使用すると、開発者はより効率的にアプリケーションを開発およびデプロイできます","ko":"Cloudflare은 Workers, Pages, 저장소, AI 및 보안 등을 포함한 종합 플랫폼 스킬입니다. 이 스킬을 통해 개발자는 보다 효율적으로 애플리케이션을 개발하고 배포할 수 있습니다","es":"La plataforma Cloudflare ofrece una amplia gama de herramientas y tecnologías para desarrolladores, incluyendo Workers, Pages, almacenamiento y seguridad","fr":"La plateforme Cloudflare propose une large gamme d''outils et de technologies pour les développeurs, notamment Workers, Pages, stockage et sécurité","de":"Die Cloudflare-Plattform bietet eine breite Palette von Tools und Technologien für Entwickler, darunter Workers, Pages, Speicher und Sicherheit","pt":"A plataforma Cloudflare oferece uma gama de ferramentas de desenvolvimento avançadas, incluindo Workers, Pages e armazenamento em nuvem.","ru":"Платформа Cloudflare предлагает ряд продвинутых инструментов для разработки, включая Workers, Pages и облачное хранилище для ИИ Агентов.","ar":"توفر منصة كلاودفلير مجموعة من أدوات التطوير المتقدمة، بما في ذلك Workers و Pages وتخزين السحابة."},"owner":"cloudflare","repo":"skills","repoPath":"cloudflare/skills","stars":535,"forks":66,"updatedAt":"2026-03-06T05:33:24Z","topics":["agents","cloudflare","skills","workers"],"skillMd":{"name":"cloudflare","description":"Comprehensive Cloudflare platform skill covering Workers, Pages, storage (KV, D1, R2), AI (Workers AI, Vectorize, Agents SDK), networking (Tunnel, Spectrum), security (WAF, DDoS), and infrastructure-as-code (Terraform, Pulumi). Use for any Cloudflare development task. Biases towards retrieval from Cloudflare docs over pre-trained knowledge.","bodyPreview":"# Cloudflare Platform Skill\n\nConsolidated skill for building on the Cloudflare platform. Use decision trees below to find the right product, then load detailed references.\n\nYour knowledge of Cloudflare APIs, types, limits, and pricing may be outdated. **Prefer retrieval over pre-training** — the references in this skill are starting points, not source of truth.\n\n## Retrieval Sources\n\nFetch the **latest** information before citing specific numbers, API signatures, or configuration options. Do not","body":"# Cloudflare Platform Skill\n\nConsolidated skill for building on the Cloudflare platform. Use decision trees below to find the right product, then load detailed references.\n\nYour knowledge of Cloudflare APIs, types, limits, and pricing may be outdated. **Prefer retrieval over pre-training** — the references in this skill are starting points, not source of truth.\n\n## Retrieval Sources\n\nFetch the **latest** information before citing specific numbers, API signatures, or configuration options. Do not rely on baked-in knowledge or these reference files alone.\n\n| Source | How to retrieve | Use for |\n|--------|----------------|---------|\n| Cloudflare docs | `cloudflare-docs` search tool or `https://developers.cloudflare.com/` | Limits, pricing, API reference, compatibility dates/flags |\n| Workers types | `npm pack @cloudflare/workers-types` or check `node_modules` | Type signatures, binding shapes, handler types |\n| Wrangler config schema | `node_modules/wrangler/config-schema.json` | Config fields, binding shapes, allowed values |\n| Product changelogs | `https://developers.cloudflare.com/changelog/` | Recent changes to limits, features, deprecations |\n\nWhen a reference file and the docs disagree, **trust the docs**. This is especially important for: numeric limits, pricing tiers, type signatures, and configuration options.\n\n## Quick Decision Trees\n\n### \"I need to run code\"\n\n```\nNeed to run code?\n├─ Serverless functions at the edge → workers/\n├─ Full-stack web app with Git deploys → pages/\n├─ Stateful coordination/real-time → durable-objects/\n├─ Long-running multi-step jobs → workflows/\n├─ Run containers → containers/\n├─ Multi-tenant (customers deploy code) → workers-for-platforms/\n├─ Scheduled tasks (cron) → cron-triggers/\n├─ Lightweight edge logic (modify HTTP) → snippets/\n├─ Process Worker execution events (logs/observability) → tail-workers/\n└─ Optimize latency to backend infrastructure → smart-placement/\n```\n\n### \"I need to store data\"\n\n```\nNeed storage?\n├─ Key-value (config, sessions, cache) → kv/\n├─ Relational SQL → d1/ (SQLite) or hyperdrive/ (existing Postgres/MySQL)\n├─ Object/file storage (S3-compatible) → r2/\n├─ Message queue (async processing) → queues/\n├─ Vector embeddings (AI/semantic search) → vectorize/\n├─ Strongly-consistent per-entity state → durable-objects/ (DO storage)\n├─ Secrets management → secrets-store/\n├─ Streaming ETL to R2 → pipelines/\n└─ Persistent cache (long-term retention) → cache-reserve/\n```\n\n### \"I need AI/ML\"\n\n```\nNeed AI?\n├─ Run inference (LLMs, embeddings, images) → workers-ai/\n├─ Vector database for RAG/search → vectorize/\n├─ Build stateful AI agents → agents-sdk/\n├─ Gateway for any AI provider (caching, routing) → ai-gateway/\n└─ AI-powered search widget → ai-search/\n```\n\n### \"I need networking/connectivity\"\n\n```\nNeed networking?\n├─ Expose local service to internet → tunnel/\n├─ TCP/UDP proxy (non-HTTP) → spectrum/\n├─ WebRTC TURN server → turn/\n├─ Private network connectivity → network-interconnect/\n├─ Optimize routing → argo-smart-routing/\n├─ Optimize latency to backend (not user) → smart-placement/\n└─ Real-time video/audio → realtimekit/ or realtime-sfu/\n```\n\n### \"I need security\"\n\n```\nNeed security?\n├─ Web Application Firewall → waf/\n├─ DDoS protection → ddos/\n├─ Bot detection/management → bot-management/\n├─ API protection → api-shield/\n├─ CAPTCHA alternative → turnstile/\n└─ Credential leak detection → waf/ (managed ruleset)\n```\n\n### \"I need media/content\"\n\n```\nNeed media?\n├─ Image optimization/transformation → images/\n├─ Video streaming/encoding → stream/\n├─ Browser automation/screenshots → browser-rendering/\n└─ Third-party script management → zaraz/\n```\n\n### \"I need analytics/metrics data\"\n\n```\nNeed analytics?\n├─ Query across all Cloudflare products (HTTP, Workers, DNS, etc.) → graphql-api/\n├─ Custom high-cardinality metrics from Workers → analytics-engine/\n├─ Client-side (RUM) performance data → web-analytics/\n├─ Workers Logs and real-time debugging → observability/\n└─ Raw logs (Logpush to external tools) → Cloudflare docs\n```\n\n### \"I need infrastructure-as-code\"\n\n```\nNeed IaC? → pulumi/ (Pulumi), terraform/ (Terraform), or api/ (REST API)\n```\n\n## Product Index\n\n### Compute & Runtime\n| Product | Reference |\n|---------|-----------|\n| Workers | `references/workers/` |\n| Pages | `references/pages/` |\n| Pages Functions | `references/pages-functions/` |\n| Durable Objects | `references/durable-objects/` |\n| Workflows | `references/workflows/` |\n| Containers | `references/containers/` |\n| Workers for Platforms | `references/workers-for-platforms/` |\n| Cron Triggers | `references/cron-triggers/` |\n| Tail Workers | `references/tail-workers/` |\n| Snippets | `references/snippets/` |\n| Smart Placement | `references/smart-placement/` |\n\n### Storage & Data\n| Product | Reference |\n|---------|-----------|\n| KV | `references/kv/` |\n| D1 | `references/d1/` |\n| R2 | `references/r2/` |\n| Queues | `references/queues/` |\n| Hyperdrive | `references/hyperdrive/` |\n| DO Storage | `references/do-storage/` |\n| Secrets Store | `references/secrets-store/` |\n| Pipelines | `references/pipelines/` |\n| R2 Data Catalog | `references/r2-data-catalog/` |\n| R2 SQL | `references/r2-sql/` |\n\n### AI & Machine Learning\n| Product | Reference |\n|---------|-----------|\n| Workers AI | `references/workers-ai/` |\n| Vectorize | `references/vectorize/` |\n| Agents SDK | `references/agents-sdk/` |\n| AI Gateway | `references/ai-gateway/` |\n| AI Search | `references/ai-search/` |\n\n### Networking & Connectivity\n| Product | Reference |\n|---------|-----------|\n| Tunnel | `references/tunnel/` |\n| Spectrum | `references/spectrum/` |\n| TURN | `references/turn/` |\n| Network Interconnect | `references/network-interconnect/` |\n| Argo Smart Routing | `references/argo-smart-routing/` |\n| Workers VPC | `references/workers-vpc/` |\n\n### Security\n| Product | Reference |\n|---------|-----------|\n| WAF | `references/waf/` |\n| DDoS Protection | `references/ddos/` |\n| Bot Management | `references/bot-management/` |\n| API Shield | `references/api-shield/` |\n| Turnstile | `references/turnstile/` |\n\n### Media & Content\n| Product | Reference |\n|---------|-----------|\n| Images | `references/images/` |\n| Stream | `references/stream/` |\n| Browser Rendering | `references/browser-rendering/` |\n| Zaraz | `references/zaraz/` |\n\n### Real-Time Communication\n| Product | Reference |\n|---------|-----------|\n| RealtimeKit | `references/realtimekit/` |\n| Realtime SFU | `references/realtime-sfu/` |\n\n### Developer Tools\n| Product | Reference |\n|---------|-----------|\n| Wrangler | `references/wrangler/` |\n| Miniflare | `references/miniflare/` |\n| C3 | `references/c3/` |\n| Observability | `references/observability/` |\n| GraphQL Analytics API | `references/graphql-api/` |\n| Analytics Engine | `references/analytics-engine/` |\n| Web Analytics | `references/web-analytics/` |\n| Sandbox | `references/sandbox/` |\n| Workerd | `references/workerd/` |\n| Workers Playground | `references/workers-playground/` |\n\n### Infrastructure as Code\n| Product | Reference |\n|---------|-----------|\n| Pulumi | `references/pulumi/` |\n| Terraform | `references/terraform/` |\n| API | `references/api/` |\n\n### Other Services\n| Product | Reference |\n|---------|-----------|\n| Email Routing | `references/email-routing/` |\n| Email Workers | `references/email-workers/` |\n| Static Assets | `references/static-assets/` |\n| Bindings | `references/bindings/` |\n| Cache Reserve | `references/cache-reserve/` |\n"},"category":"official","lastSynced":"2026-03-06T05:54:52.425Z","seo":{"title":{"en":"Cloudflare: Comprehensive Development Setup Guide | AI Ag...","zh":"Cloudflare开发指南：Workers、Pages和安全设置","ja":"Cloudflareの設定ガイド：Workers、Pages、セキュリティ","ko":"Cloudflare 개발 환경 설정: Workers, Pages, 보안","es":"Guía de configuración de Cloudflare para desarrolladores","fr":"Guide de mise en route de Cloudflare pour les développeurs","de":"Cloudflare-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração Cloudflare: Ferramentas de Desenvolv...","ru":"Руководство по настройке Cloudflare: Продвинутые инструме...","ar":"دليل إعداد كلاودفلير: أدوات تطوير متقدمة لمنصة Cloudflare"},"description":{"en":"Unlock Cloudflare''s full potential with our AI agent skill, covering Workers, Pages, and more. Get started with setup guides and best practices today!","zh":"了解Cloudflare的综合平台技能，包括Workers、Pages、存储、AI和安全功能，通过本开发指南提高您的开发效率","ja":"Cloudflareの総合プラットフォームスキルについて学び、Workers、Pages、ストレージ、AI、セキュリティ機能をマスターして開発効率を上げる","ko":"Cloudflare의 종합 플랫폼 스킬을 익히고 Workers, Pages, 저장소, AI 및 보안 기능을 통해 개발 효율성을 높여보세요","es":"Aprende a aprovechar al máximo la plataforma Cloudflare con nuestra guía de configuración y mejores prácticas para desarrolladores","fr":"Découvrez comment exploiter pleinement la plateforme Cloudflare avec notre guide de configuration et 