INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cloudflare/skills/cloudflare', 'cloudflare', 'cloudflare', 'skills', 'official', 'cloudflare cloudflare skills official agents cloudflare skills workers The Cloudflare skill provides a comprehensive platform for development tasks, including Workers, Pages, storage, AI, and security. It benefits developers working with Cloudflare APIs and infrastructure-as-code tools like Terraform and Pulumi. Cloudflare是一种综合的平台技能，涵盖Workers、Pages、存储、AI和安全等功能。通过本技能，开发者可以更高效地开发和部署应用程序 Cloudflareは、Workers、Pages、ストレージ、AI、セキュリティなどを包含した総合的なプラットフォームスキルです。このスキルを使用すると、開発者はより効率的にアプリケーションを開発およびデプロイできます Cloudflare은 Workers, Pages, 저장소, AI 및 보안 등을 포함한 종합 플랫폼 스킬입니다. 이 스킬을 통해 개발자는 보다 효율적으로 애플리케이션을 개발하고 배포할 수 있습니다 La plataforma Cloudflare ofrece una amplia gama de herramientas y tecnologías para desarrolladores, incluyendo Workers, Pages, almacenamiento y seguridad La plateforme Cloudflare propose une large gamme d''outils et de technologies pour les développeurs, notamment Workers, Pages, stockage et sécurité Die Cloudflare-Plattform bietet eine breite Palette von Tools und Technologien für Entwickler, darunter Workers, Pages, Speicher und Sicherheit A plataforma Cloudflare oferece uma gama de ferramentas de desenvolvimento avançadas, incluindo Workers, Pages e armazenamento em nuvem. Платформа Cloudflare предлагает ряд продвинутых инструментов для разработки, включая Workers, Pages и облачное хранилище для ИИ Агентов. توفر منصة كلاودفلير مجموعة من أدوات التطوير المتقدمة، بما في ذلك Workers و Pages وتخزين السحابة. how to use cloudflare workers cloudflare pages tutorial cloudflare vs aws cloudflare setup guide what is cloudflare kv cloudflare alternative cloudflare install cloudflare ai agents cloudflare security features cloudflare terraform setup Cloudflare开发 Cloudflare Workers Cloudflare Pages Cloudflare存储 Cloudflare AI Cloudflare安全 云计算平台 边缘计算 无服务器网页托管 Supports Cloudflare Workers for serverless computing Utilizes Cloudflare Pages for fast and secure web hosting Integrates with Cloudflare storage solutions like KV, D1, and R2 Leverages Cloudflare AI features including Workers AI and Vectorize Provides security through WAF and DDoS protection Enables infrastructure-as-code management with Terraform and Pulumi Cloudflare is a platform providing a range of services including Workers, Pages, storage solutions like KV, D1, and R2, and security features such as WAF and DDoS protection.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tadata-org/fastapi_mcp/README.md', 'official', 'tadata-org', 'fastapi_mcp', 'tadata-org/fastapi_mcp', 'README.md', 11622, 921, 77, '2026-03-06T04:33:50Z', '2026-03-06T06:02:39.034Z', 'd573958d974385f87b444cef01309245a98f4752eae4a7b32e9d31dc54895630', '{"id":"tadata-org/fastapi_mcp/README.md","name":"README.md","description":{"en":"README.md is a technical skill for integrating FastAPI with Model Context Protocol (MCP) for AI agents, built by Tadata. It provides a setup guide for developers to implement MCP servers with FastAPI.","zh":"FastAPI-MCP是一个基于FastAPI的MCP服务器，提供OpenAPI和Model Context Protocol支持","ja":"FastAPI-MCPはFastAPIベースのMCPサーバーであり、OpenAPIとModel Context Protocolをサポートしています","ko":"FastAPI-MCP는 FastAPI 기반의 MCP 서버로 OpenAPI 및 Model Context Protocol을 지원합니다","es":"README.md es una herramienta para configurar FastAPI-MCP, que permite a los desarrolladores crear aplicaciones web con autenticación y autorización","fr":"README.md est un outil pour configurer FastAPI-MCP, qui permet aux développeurs de créer des applications web avec authentification et autorisation","de":"README.md ist ein Tool zum Konfigurieren von FastAPI-MCP, mit dem Entwickler Webanwendungen mit Authentifizierung und Autorisierung erstellen können","pt":"O README.md é um arquivo de documentação essencial para o FastAPI-MCP, fornecendo informações sobre a configuração e o uso da plataforma.","ru":"Файл README.md является важнейшим документом для FastAPI-MCP, содержащим информацию о настройке и использовании платформы.","ar":"ملف README.md هو ملف توثيق أساسي ل FastAPI-MCP، يوفر معلومات حول إعداد واستخدام المنصة."},"owner":"tadata-org","repo":"fastapi_mcp","repoPath":"tadata-org/fastapi_mcp","stars":11622,"forks":921,"updatedAt":"2026-03-06T04:33:50Z","topics":["ai","authentication","authorization","claude","cursor","fastapi","llm","mcp","mcp-server","mcp-servers","modelcontextprotocol","openapi","windsurf"],"skillMd":{"name":"","description":"<p align=\"center\"><a href=\"https://github.com/tadata-org/fastapi_mcp\"><img src=\"https://github.com/user-attachments/assets/7e44e98b-a0ba-4aff-a68a-4ffee3a6189c\" alt=\"fastapi-to-mcp\" height=100/></a></p> <div align=\"center\">   <span style=\"font-size: 0.85em; font-weight: normal;\">Built by <a href=\"https://tadata.com\">Tadata</a></span> </div> <h1 align=\"center\">   FastAPI-MCP </h1> <div align=\"center\"> <a href=\"https://trendshift.io/repositories/14064\" target=\"_blank\"><img src=\"https://trendshi","bodyPreview":"<p align=\"center\"><a href=\"https://github.com/tadata-org/fastapi_mcp\"><img src=\"https://github.com/user-attachments/assets/7e44e98b-a0ba-4aff-a68a-4ffee3a6189c\" alt=\"fastapi-to-mcp\" height=100/></a></p>\n\n<div align=\"center\">\n  <span style=\"font-size: 0.85em; font-weight: normal;\">Built by <a href=\"https://tadata.com\">Tadata</a></span>\n</div>\n\n<h1 align=\"center\">\n  FastAPI-MCP\n</h1>\n\n<div align=\"center\">\n<a href=\"https://trendshift.io/repositories/14064\" target=\"_blank\"><img src=\"https://trendshi","body":"<p align=\"center\"><a href=\"https://github.com/tadata-org/fastapi_mcp\"><img src=\"https://github.com/user-attachments/assets/7e44e98b-a0ba-4aff-a68a-4ffee3a6189c\" alt=\"fastapi-to-mcp\" height=100/></a></p>\n\n<div align=\"center\">\n  <span style=\"font-size: 0.85em; font-weight: normal;\">Built by <a href=\"https://tadata.com\">Tadata</a></span>\n</div>\n\n<h1 align=\"center\">\n  FastAPI-MCP\n</h1>\n\n<div align=\"center\">\n<a href=\"https://trendshift.io/repositories/14064\" target=\"_blank\"><img src=\"https://trendshift.io/api/badge/repositories/14064\" alt=\"tadata-org%2Ffastapi_mcp | Trendshift\" style=\"width: 250px; height: 55px;\" width=\"250\" height=\"55\"/></a>\n</div>\n\n<p align=\"center\">Expose your FastAPI endpoints as Model Context Protocol (MCP) tools, with Auth!</p>\n<div align=\"center\">\n\n[![PyPI version](https://img.shields.io/pypi/v/fastapi-mcp?color=%2334D058&label=pypi%20package)](https://pypi.org/project/fastapi-mcp/)\n[![Python Versions](https://img.shields.io/pypi/pyversions/fastapi-mcp.svg)](https://pypi.org/project/fastapi-mcp/)\n[![FastAPI](https://img.shields.io/badge/FastAPI-009485.svg?logo=fastapi&logoColor=white)](#)\n[![CI](https://github.com/tadata-org/fastapi_mcp/actions/workflows/ci.yml/badge.svg)](https://github.com/tadata-org/fastapi_mcp/actions/workflows/ci.yml)\n[![Coverage](https://codecov.io/gh/tadata-org/fastapi_mcp/branch/main/graph/badge.svg)](https://codecov.io/gh/tadata-org/fastapi_mcp)\n\n</div>\n\n\n<p align=\"center\"><a href=\"https://github.com/tadata-org/fastapi_mcp\"><img src=\"https://github.com/user-attachments/assets/b205adc6-28c0-4e3c-a68b-9c1a80eb7d0c\" alt=\"fastapi-mcp-usage\" height=\"400\"/></a></p>\n\n\n## Features\n\n- **Authentication** built in, using your existing FastAPI dependencies!\n\n- **FastAPI-native:** Not just another OpenAPI -> MCP converter\n\n- **Zero/Minimal configuration** required - just point it at your FastAPI app and it works\n\n- **Preserving schemas** of your request models and response models\n\n- **Preserve documentation** of all your endpoints, just as it is in Swagger\n\n- **Flexible deployment** - Mount your MCP server to the same app, or deploy separately\n\n- **ASGI transport** - Uses FastAPI''s ASGI interface directly for efficient communication\n\n\n## Hosted Solution\n\nIf you prefer a managed hosted solution check out [tadata.com](https://tadata.com).\n\n## Installation\n\nWe recommend using [uv](https://docs.astral.sh/uv/), a fast Python package installer:\n\n```bash\nuv add fastapi-mcp\n```\n\nAlternatively, you can install with pip:\n\n```bash\npip install fastapi-mcp\n```\n\n## Basic Usage\n\nThe simplest way to use FastAPI-MCP is to add an MCP server directly to your FastAPI application:\n\n```python\nfrom fastapi import FastAPI\nfrom fastapi_mcp import FastApiMCP\n\napp = FastAPI()\n\nmcp = FastApiMCP(app)\n\n# Mount the MCP server directly to your FastAPI app\nmcp.mount()\n```\n\nThat''s it! Your auto-generated MCP server is now available at `https://app.base.url/mcp`.\n\n## Documentation, Examples and Advanced Usage\n\nFastAPI-MCP provides [comprehensive documentation](https://fastapi-mcp.tadata.com/). Additionaly, check out the [examples directory](examples) for code samples demonstrating these features in action.\n\n## FastAPI-first Approach\n\nFastAPI-MCP is designed as a native extension of FastAPI, not just a converter that generates MCP tools from your API. This approach offers several key advantages:\n\n- **Native dependencies**: Secure your MCP endpoints using familiar FastAPI `Depends()` for authentication and authorization\n\n- **ASGI transport**: Communicates directly with your FastAPI app using its ASGI interface, eliminating the need for HTTP calls from the MCP to your API\n\n- **Unified infrastructure**: Your FastAPI app doesn''t need to run separately from the MCP server (though [separate deployment](https://fastapi-mcp.tadata.com/advanced/deploy#deploying-separately-from-original-fastapi-app) is also supported)\n\nThis design philosophy ensures minimum friction when adding MCP capabilities to your existing FastAPI services.\n\n\n## Development and Contributing\n\nThank you for considering contributing to FastAPI-MCP! We encourage the community to post Issues and create Pull Requests.\n\nBefore you get started, please see our [Contribution Guide](CONTRIBUTING.md).\n\n## Community\n\nJoin [MCParty Slack community](https://join.slack.com/t/themcparty/shared_invite/zt-30yxr1zdi-2FG~XjBA0xIgYSYuKe7~Xg) to connect with other MCP enthusiasts, ask questions, and share your experiences with FastAPI-MCP.\n\n## Requirements\n\n- Python 3.10+ (Recommended 3.12)\n- uv\n\n## License\n\nMIT License. Copyright (c) 2025 Tadata Inc.\n"},"category":"official","lastSynced":"2026-03-06T06:02:39.034Z","seo":{"title":{"en":"README.md: FastAPI-MCP Setup Guide | AI Agent Skill","zh":"README.md FastAPI-MCP集成指南","ja":"README.md FastAPI-MCPのセットアップガイド","ko":"README.md FastAPI-MCP 설정 가이드","es":"Guía de Configuración de README.md para FastAPI-MCP","fr":"Guide d''Installation de README.md pour FastAPI-MCP","de":"Einrichtungsleitfaden für README.md mit FastAPI-MCP","pt":"Guia de Configuração do README.md para FastAPI-MCP","ru":"Настройка README.md для FastAPI-MCP: Лучшие Практики","ar":"دليل إعداد README.md ل FastAPI-MCP"},"description":{"en":"Unlock the power of FastAPI-MCP with this expert README.md guide. Learn how to integrate Model Context Protocol with FastAPI for AI agents.","zh":"了解如何集成FastAPI-MCP，并探索其强大的功能，包括OpenAPI和Model Context Protocol","ja":"FastAPI-MCPの統合方法を学び、OpenAPIやModel Context Protocolなどの強力な機能を発見しましょう","ko":"FastAPI-MCP를 통합하는 방법에 대해 알아보고 OpenAPI 및 Model Context Protocol 등의 강력한 기능을 탐색하세요","es":"Aprende a configurar README.md para FastAPI-MCP y mejora tu experiencia de desarrollo con esta guía paso a paso","fr":"Découvrez comment configurer README.md pour FastAPI-MCP et améliorez votre expérience de développement avec ce guide étape par étape","de":"Erfahren Sie, wie Sie README.md für FastAPI-MCP konfigurieren und verbessern Sie Ihre Entwicklungserfahrung mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o README.md para FastAPI-MCP e descubra as melhores práticas para otimizar seu projeto","ru":"Узнайте, как настроить README.md для FastAPI-MCP и оптимизировать свой проект с помощью лучших практик","ar":"تعرف على كيفية إعداد README.md ل FastAPI-MCP واكتشف أفضل الممارسات لتحسين مشروعك"},"definition":{"en":"README.md is a skill that integrates FastAPI with Model Context Protocol (MCP) for AI agents, enabling authentication and authorization capabilities.","zh":"FastAPI-MCP是一种AI工具，用于构建基于Model Context Protocol的API","ja":"FastAPI-MCPは、Model Context ProtocolベースのAPIを構築するためのAIエージェントです","ko":"FastAPI-MCP는 Model Context Protocol 기반의 API를 구축하는 데 사용되는 AI 도구입니다","es":"README.md es un archivo de configuración para FastAPI-MCP, que proporciona información sobre la autenticación y autorización","fr":"README.md est un fichier de configuration pour FastAPI-MCP, qui fournit des informations sur l''authentification et l''autorisation","de":"README.md ist eine Konfigurationsdatei für FastAPI-MCP, die Informationen über die Authentifizierung und Autorisierung bereitstellt","pt":"O que é README.md? É um arquivo de documentação que fornece informações sobre a configuração e o uso do FastAPI-MCP.","ru":"Что такое README.md? Это файл документации, содержащий информацию о настройке и использовании FastAPI-MCP.","ar":"ما هو ملف README.md؟ هو ملف توثيق يوفر معلومات حول إعداد واستخدام FastAPI-MCP."},"features":{"en":["Supports FastAPI framework for building web applications","Integrates with Model Context Protocol (MCP) for AI agent communication","Provides authentication and authorization capabilities using MCP","Includes OpenAPI support for API documentation and discovery","Built by Tadata, utilizing GitHub repositories for version control"],"zh":["支持OpenAPI","支持Model Context Protocol","基于FastAPI","提供强大的API构建能力","支持GitHub集成","支持Trendshift.io集成"],"ja":["OpenAPIをサポート","Model Context Protocolをサポート","FastAPIベース","強力なAPI構築能力を提供","GitHub統合をサポート","Trendshift.io統合をサポート"],"ko":["OpenAPI 지원","Model Context Protocol 지원","FastAPI 기반","강력한 API 구축 능력 제공","GitHub 통합 지원","Trendshift.io 통합 지원"],"es":["Soporte para autenticación y autorización","Integración con FastAPI","Compatibilidad con Model Context Protocol (MCP)","Generación de documentos de API con OpenAPI","Soporte para desarrolladores con CLI"],"fr":["Prise en charge de l''authentification et de l''autorisation","Intégration avec FastAPI","Compatibilité avec le protocole de contexte de modèle (MCP)","Génération de documents d''API avec OpenAPI","Prise en charge des développeurs avec CLI"],"de":["Unterstützung für Authentifizierung und Autorisierung","Integration mit FastAPI","Kompatibilität mit dem Model Context Protocol (MCP)","Generierung von API-Dokumenten mit OpenAPI","Unterstützung für Entwickler mit CLI"],"pt":["Integração com o FastAPI","Suporte à autenticação e autorização","Compatibilidade com o Model Context Protocol (MCP)","Documentação de API com OpenAPI","Suporte à cursor e windsurf"],"ru":["Интеграция с FastAPI","Поддержка аутентификации и авторизации","Совместимость с Model Context Protocol (MCP)","Документация API с OpenAPI","Поддержка cursor и windsurf"],"ar":["دمج مع FastAPI","دعم التأشير والتصريح","توافق مع بروتوكول سياق النموذج (MCP)","وثائق API مع OpenAPI","دعم cursor و windsurf"]},"keywords":{"en":["how to use README.md","FastAPI-MCP setup guide","README.md alternative to OpenAPI","Model Context Protocol tutorial","FastAPI authentication and authorization","README.md install for AI agents","Tadata GitHub repository","FastAPI vs Flask for AI applications","README.md setup for MCP servers"],"zh":["FastAPI-MCP","OpenAPI","Model Context Protocol","AI工具","API构建","FastAPI","MCP服务器","GitHub集成","Trendshift.io集成"],"ja":["FastAPI-MCP","OpenAPI","Model Context Protocol","AIエージェント","API構築","FastAPI","MCPサーバー","GitHub統合","Trendshift.io統合"],"ko":["FastAPI-MCP","OpenAPI","Model Context Protocol","AI 도구","API 구축","FastAPI","MCP 서버","GitHub 통합","Trendshift.io 통합"],"es":["FastAPI-MCP","autenticación y autorización","desarrollo web","Model Context Protocol","OpenAPI","CLI","herramientas de desarrollo","README.md","guía de configuración"],"fr":["FastAPI-MCP","authentification et autorisation","développement web","protocole de contexte de modèle","OpenAPI","CLI","outils de développement","README.md","guide de configuration"],"de":["FastAPI-MCP","Authentifizierung und Autorisierung","Webentwicklung","Model Context Protocol","OpenAPI","CLI","Entwicklungstools","README.md","Konfigurationsleitfaden"],"pt":["FastAPI-MCP","README.md","autenticação","autorização","Model Context Protocol","OpenAPI","cursor","windsurf","desenvolvimento de software","ferramentas de AI"],"ru":["FastAPI-MCP","README.md","аутентификация","авторизация","Model Context Protocol","OpenAPI","cursor","windsurf","разработка программного обеспечения","ИИ инструменты"],"ar":["FastAPI-MCP","README.md","التأشير","التصريح","بروتوكول سياق النموذج","OpenAPI","cursor","windsurf","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing to transform FastAPI applications into Model Context Protocol servers.","zh":"非常适合需要将 FastAPI 应用程序转换为 Model Context Protocol 服务器的 AI Agent。","ja":"FastAPI アプリケーションを Model Context Protocol サーバーに変換する必要がある AI Agent に最適です。","ko":"FastAPI 애플리케이션을 Model Context Protocol 서버로 변환해야 하는 AI Agent에 매우 적합합니다.","es":"Ideal para AI Agents que necesitan transformar aplicaciones FastAPI en servidores del Model Context Protocol.","fr":"Parfait pour les AI Agents ayant besoin de transformer des applications FastAPI en serveurs Model Context Protocol.","de":"Perfekt für AI Agents, die FastAPI-Anwendungen in Model Context Protocol-Server umwandeln müssen.","pt":"Perfeito para Agentes de IA que precisam transformar aplicações FastAPI em servidores de Protocolo de Contexto de Modelo.","ru":"Идеально для ИИ-агентов, которым необходимо преобразовывать приложения FastAPI в серверы протокола контекста модели.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى تحويل تطبيقات FastAPI إلى خادم بروتوكول سياق النموذج."},"recommendation":{"en":"Enables agents to automatically convert FastAPI endpoints into MCP-compatible tools and resources through seamless integration with the MCP SDK. Provides immediate compatibility with modern AI agent ecosystems by generating standardized MCP servers from existing API codebases.","zh":"通过与 MCP SDK 的无缝集成，使 Agent 能够自动将 FastAPI 端点转换为 MCP 兼容的工具和资源。通过从现有的 API 代码库生成标准化的 MCP 服务器，提供与现代 AI Agent 生态系统的即时兼容性。","ja":"MCP SDK とのシームレスな統合により、Agent が FastAPI エンドポイントを MCP 互換のツールやリソースに自動変換できるようにします。既存の API コードベースから標準化された MCP サーバーを生成することで、現代の AI Agent エコシステムとの即時互換性を提供します。","ko":"MCP SDK와의 원활한 통합을 통해 Agent가 FastAPI 엔드포인트를 MCP 호환 도구 및 리소스로 자동 변환할 수 있도록 합니다. 기존 API 코드베이스에서 표준화된 MCP 서버를 생성하여 현대 AI Agent 생태계와의 즉시 호환성을 제공합니다.","es":"Permite a los agentes convertir automáticamente los endpoints de FastAPI en herramientas y recursos compatibles con MCP mediante una integración perfecta con el MCP SDK. Proporciona compatibilidad inmediata con los ecosistemas modernos de agentes de IA al generar servidores MCP estandarizados a partir de codebases de API existentes.","fr":"Permet aux agents de convertir automatiquement les endpoints FastAPI en outils et ressources compatibles MCP grâce à une intégration transparente avec le MCP SDK. Fournit une compatibilité immédiate avec les écosystèmes modernes d''agents IA en générant des serveurs MCP standardisés à partir de codebases d''API existantes.","de":"Ermöglicht es Agents, FastAPI-Endpunkte automatisch in MCP-kompatible Tools und Ressourcen umzuwandeln, durch nahtlose Integration mit dem MCP SDK. Bietet sofortige Kompatibilität mit modernen AI Agent-Ökosystemen, indem standardisierte MCP-Server aus bestehenden API-Codebasen generiert werden.","pt":"Permite que os agentes convertam automaticamente os pontos de extremidade do FastAPI em ferramentas e recursos compatíveis com o MCP por meio de uma integração sem problemas com o SDK do MCP. Fornece compatibilidade imediata com ecossistemas modernos de agentes de IA, gerando servidores MCP padrão a partir de código de API existente.","ru":"Позволяет агентам автоматически преобразовывать конечные точки FastAPI в инструменты и ресурсы, совместимые с MCP, посредством бесшовной интеграции с SDK MCP. Обеспечивает мгновенную совместимость с современными экосистемами ИИ-агентов, генерируя стандартные серверы MCP из существующего кода API.","ar":"يسمح للعميل بتحويل نهاية النقاط السريعة إلى أدوات وموارد متوافقة مع بروتوكول سياق النموذج من خلال التكامل السلس مع SDK بروتوكول سياق النموذج. يوفر التوافق الفوري مع بيئات عميل الذكاء الاصطناعي الحديثة من خلال توليد خوادم بروتوكول سياق النموذج المعيارية من كود API الحالي."},"useCases":{"en":["Converting existing FastAPI endpoints to MCP tools","Integrating custom APIs with AI agent workflows","Rapid prototyping of MCP servers from Python backends","Extending agent capabilities with custom API integrations"],"zh":["将现有的 FastAPI 端点转换为 MCP 工具","将自定义 API 与 AI Agent 工作流集成","从 Python 后端快速原型化 MCP 服务器","通过自定义 API 集成扩展 Agent 能力"],"ja":["既存の FastAPI エンドポイントを MCP ツールに変換","カスタム API と AI Agent ワークフローの統合","Python バックエンドからの MCP サーバーの迅速なプロトタイピング","カスタム API 統合による Agent 機能の拡張"],"ko":["기존 FastAPI 엔드포인트를 MCP 도구로 변환","사용자 정의 API를 AI Agent 워크플로우와 통합","Python 백엔드에서 MCP 서버의 신속한 프로토타이핑","사용자 정의 API 통합으로 Agent 기능 확장"],"es":["Convertir endpoints existentes de FastAPI en herramientas MCP","Integrar APIs personalizadas con flujos de trabajo de agentes de IA","Prototipado rápido de servidores MCP a partir de backends Python","Ampliar las capacidades de los agentes con integraciones de API personalizadas"],"fr":["Conversion des endpoints FastAPI existants en outils MCP","Intégration d''API personnalisées dans les workflows d''agents IA","Prototypage rapide de serveurs MCP à partir de backends Python","Extension des capacités des agents avec des intégrations d''API personnalisées"],"de":["Umwandeln bestehender FastAPI-Endpunkte in MCP-Tools","Integration benutzerdefinierter APIs in AI Agent-Workflows","Schnelles Prototyping von MCP-Servern aus Python-Backends","Erweiterung der Agenten-Fähigkeiten mit benutzerdefinierten API-Integrationen"],"pt":["Conversão de pontos de extremidade do FastAPI existentes em ferramentas MCP","Integração de APIs personalizadas com fluxos de trabalho de agentes de IA","Prototipagem rápida de servidores MCP a partir de back-ends Python","Extensão das capacidades dos agentes com integrações de API personalizadas"],"ru":["Преобразование существующих конечных точек FastAPI в инструменты MCP","Интеграция пользовательских API с рабочими процессами ИИ-агентов","Быстрая прототипизация серверов MCP из бэкендов Python","Расширение возможностей агентов с помощью пользовательских интеграций API"],"ar":["تحويل نقاط النهاية السريعة الحالية إلى أدوات بروتوكول سياق النموذج","تكامل واجهات برمجة التطبيقات المخصصة مع تدفقات عمل عميل الذكاء الاصطناعي","النمذجة السريعة للخادم بروتوكول سياق النموذج من الخوادم الخلفية لغة بايثون","توسيع قدرات العميل مع التكاملات المخصصة لبروتوكول واجهة التطبيقات"]},"limitations":{"en":["Requires existing FastAPI application structure","Dependent on MCP SDK compatibility","Python-specific implementation"],"zh":["需要现有的 FastAPI 应用程序结构","依赖于 MCP SDK 的兼容性","特定于 Python 的实现"],"ja":["既存の FastAPI アプリケーション構造が必要","MCP SDK の互換性に依存","Python 固有の実装"],"ko":["기존 FastAPI 애플리케이션 구조 필요","MCP SDK 호환성에 의존","Python 전용 구현"],"es":["Requiere una estructura de aplicación FastAPI existente","Depende de la compatibilidad del MCP SDK","Implementación específica para Python"],"fr":["Nécessite une structure d''application FastAPI existante","Dépend de la compatibilité du MCP SDK","Implémentation spécifique à Python"],"de":["Erfordert eine bestehende FastAPI-Anwendungsstruktur","Abhängig von der Kompatibilität des MCP SDK","Python-spezifische Implementierung"],"pt":["Requer estrutura de aplicação FastAPI existente","Dependente da compatibilidade do SDK do MCP","Implementação específica do Python"],"ru":["Требуется существующая структура приложения FastAPI","Зависит от совместимости SDK MCP","Реализация, специфичная для Python"],"ar":["يتطلب هيكل تطبيق سريع موجود","يعتمد على توافق SDK بروتوكول سياق النموذج","تنفيذ محدد بلغة بايثون"]},"version":4},"contentHash":"d573958d974385f87b444cef01309245a98f4752eae4a7b32e9d31dc54895630","repoEtag":"W/\"a3eb15a16a78ed158c1d3588ced9d4ce30b3470f06b99f6ac293588f30947dab\"","qualityScore":77}');
