INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tadata-org/fastapi_mcp/README.md', 'README.md', 'tadata-org', 'fastapi_mcp', 'official', 'README.md tadata-org fastapi_mcp official ai authentication authorization claude cursor fastapi llm mcp mcp-server mcp-servers modelcontextprotocol openapi windsurf README.md is a technical skill for integrating FastAPI with Model Context Protocol (MCP) for AI agents, built by Tadata. It provides a setup guide for developers to implement MCP servers with FastAPI. FastAPI-MCP是一个基于FastAPI的MCP服务器，提供OpenAPI和Model Context Protocol支持 FastAPI-MCPはFastAPIベースのMCPサーバーであり、OpenAPIとModel Context Protocolをサポートしています FastAPI-MCP는 FastAPI 기반의 MCP 서버로 OpenAPI 및 Model Context Protocol을 지원합니다 README.md es una herramienta para configurar FastAPI-MCP, que permite a los desarrolladores crear aplicaciones web con autenticación y autorización README.md est un outil pour configurer FastAPI-MCP, qui permet aux développeurs de créer des applications web avec authentification et autorisation README.md ist ein Tool zum Konfigurieren von FastAPI-MCP, mit dem Entwickler Webanwendungen mit Authentifizierung und Autorisierung erstellen können O README.md é um arquivo de documentação essencial para o FastAPI-MCP, fornecendo informações sobre a configuração e o uso da plataforma. Файл README.md является важнейшим документом для FastAPI-MCP, содержащим информацию о настройке и использовании платформы. ملف README.md هو ملف توثيق أساسي ل FastAPI-MCP، يوفر معلومات حول إعداد واستخدام المنصة. how to use README.md FastAPI-MCP setup guide README.md alternative to OpenAPI Model Context Protocol tutorial FastAPI authentication and authorization README.md install for AI agents Tadata GitHub repository FastAPI vs Flask for AI applications README.md setup for MCP servers FastAPI-MCP OpenAPI Model Context Protocol AI工具 API构建 FastAPI MCP服务器 GitHub集成 Trendshift.io集成 Supports FastAPI framework for building web applications Integrates with Model Context Protocol (MCP) for AI agent communication Provides authentication and authorization capabilities using MCP Includes OpenAPI support for API documentation and discovery Built by Tadata, utilizing GitHub repositories for version control README.md is a skill that integrates FastAPI with Model Context Protocol (MCP) for AI agents, enabling authentication and authorization capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/internal-comms', 'official', 'anthropics', 'skills', 'anthropics/skills', 'internal-comms', 85097, 8974, 76, '2026-03-06T03:11:21Z', '2026-03-06T03:18:24.465Z', '067b7587a344a928fc6534ef66b1bcd591fc7c26d207ea7ca3334aeb678d6475', '{"id":"anthropics/skills/internal-comms","name":"internal-comms","description":{"en":"The internal-comms AI agent skill provides structured templates for generating internal communications like status reports, 3P updates, and incident reports. Development teams and technical writers benefit from standardized documentation formats.","zh":"Internal Comms AI代理技能专门用于自动化生成各种内部通信文档，包括状态报告、领导更新、3P更新和事件报告。该技能通过加载预定义的示例文件格式来确保符合公司通信标准。","ja":"Internal Comms AIエージェントスキルは、ステータスレポート、リーダーシップアップデート、3Pアップデート、インシデントレポートなどの社内通信文書を自動生成するために設計されています。あらかじめ定義されたexamplesファイル形式をロードして会社の通信標準に準拠します。","ko":"Internal Comms AI 에이전트 스킬은 상태 보고서, 리더십 업데이트, 3P 업데이트, 인시던트 리포트 등 다양한 내부 커뮤니케이션 문서 자동 생성을 위해 설계되었습니다. 미리 정의된 examples 파일 형식을 로드하여 회사 통신 표준을 준수합니다.","es":"Skill técnica para Claude AI que automatiza la redacción de comunicaciones internas mediante el uso de archivos de guía en formato Markdown. Incluye plantillas para actualizaciones 3P, reportes de incidentes y newsletters corporativas.","fr":"Compétence technique pour Claude IA automatisant la rédaction de communications internes via des fichiers guides Markdown. Inclut modèles pour mises à jour 3P, rapports d''incident et newsletters d''entreprise.","de":"Technische Skill für Claude KI zur Automatisierung interner Kommunikation mittels Markdown-Leitfäden. Enthält Vorlagen für 3P-Updates, Incident Reports und Unternehmens-Newsletters.","pt":"A skill internal-comms permite automatizar a criação de documentos internos como relatórios de status, atualizações de liderança e relatórios de incidentes. Ela carrega diretrizes específicas do diretório `examples/` para garantir conformidade com os formatos da empresa.","ru":"Навык internal-comms автоматизирует создание внутренних документов, таких как отчеты о статусе, обновления для руководства и отчеты об инцидентах. Он загружает конкретные руководства из каталога `examples/` для соответствия форматам компании.","ar":"تمكّن مهارة internal-comms من أتمتة إنشاء المستندات الداخلية مثل تقارير الحالة، وتحديثات القيادة، وتقارير الحوادث. تقوم بتحميل إرشادات محددة من مجلد `examples/` لضمان الامتثال لمعايير الشركة."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"internal-comms","description":"A set of resources to help me write all kinds of internal communications, using the formats that my company likes to use. Claude should use this skill whenever asked to write some sort of internal communications (status reports, leadership updates, 3P updates, company newsletters, FAQs, incident reports, project updates, etc.).","bodyPreview":"## When to use this skill\nTo write internal communications, use this skill for:\n- 3P updates (Progress, Plans, Problems)\n- Company newsletters\n- FAQ responses\n- Status reports\n- Leadership updates\n- Project updates\n- Incident reports\n\n## How to use this skill\n\nTo write any internal communication:\n\n1. **Identify the communication type** from the request\n2. **Load the appropriate guideline file** from the `examples/` directory:\n    - `examples/3p-updates.md` - For Progress/Plans/Problems team upda","body":"## When to use this skill\nTo write internal communications, use this skill for:\n- 3P updates (Progress, Plans, Problems)\n- Company newsletters\n- FAQ responses\n- Status reports\n- Leadership updates\n- Project updates\n- Incident reports\n\n## How to use this skill\n\nTo write any internal communication:\n\n1. **Identify the communication type** from the request\n2. **Load the appropriate guideline file** from the `examples/` directory:\n    - `examples/3p-updates.md` - For Progress/Plans/Problems team updates\n    - `examples/company-newsletter.md` - For company-wide newsletters\n    - `examples/faq-answers.md` - For answering frequently asked questions\n    - `examples/general-comms.md` - For anything else that doesn''t explicitly match one of the above\n3. **Follow the specific instructions** in that file for formatting, tone, and content gathering\n\nIf the communication type doesn''t match any existing guideline, ask for clarification or more context about the desired format.\n\n## Keywords\n3P updates, company newsletter, company comms, weekly update, faqs, common questions, updates, internal comms\n"},"category":"official","lastSynced":"2026-03-06T03:18:24.465Z","seo":{"title":{"en":"internal-comms: AI-Powered Internal Communication Templat...","zh":"Internal Comms AI代理技能设置指南 - 自动化内部通信","ja":"Internal Comms AIエージェントスキル活用ガイド - 社内コミュニケーション自動化","ko":"Internal Comms AI 에이전트 스킬 설정 가이드 - 내부 커뮤니케이션 자동화","es":"Guía de Configuración: internal-comms para Comunicaciones...","fr":"Guide de Configuration: internal-comms pour Communication...","de":"Setup Guide: internal-comms für Interne Kommunikation mit...","pt":"Skill internal-comms: Guia de Configuração para Comunicaç...","ru":"ИИ Агент internal-comms: Руководство по настройке для вну...","ar":"مهارة internal-comms: دليل الإعداد للتواصل الداخلي باستخد..."},"description":{"en":"Learn how the internal-comms AI skill automates status reports, 3P updates, and incident reports using structured templates. Streamline your team''s communica...","zh":"学习如何配置Internal Comms AI代理技能来自动生成状态报告、领导更新、3P更新、公司通讯和事件报告。包含具体技术实现指南和示例文件使用方法。","ja":"Internal Comms AIエージェントスキルを使用して、ステータスレポート、リーダーシップアップデート、3Pアップデート、社内ニュースレター、インシデントレポートを自動生成する方法。技術的な実装ガイドとexamplesファイルの使用方法を解説。","ko":"Internal Comms AI 에이전트 스킬을 사용하여 상태 보고서, 리더십 업데이트, 3P 업데이트, 회사 뉴스레터, 인시던트 리포트를 자동 생성하는 방법. 기술 구현 가이드와 examples 파일 사용법 포함.","es":"Aprende a configurar la skill internal-comms de Claude AI para automatizar informes de estado, actualizaciones 3P, newsletters y reportes de incidentes usand...","fr":"Configurez la compétence internal-comms de Claude IA pour automatiser les rapports d''état, mises à jour 3P, newsletters et rapports d''incident avec des modèl...","de":"Richte die internal-comms Skill für Claude KI ein, um Statusberichte, 3P-Updates, Newsletter und Incident Reports mit firmenspezifischen Vorlagen zu automati...","pt":"Aprenda a configurar a skill internal-comms do Claude AI para gerar relatórios de status, atualizações 3P, newsletters e relatórios de incidentes automaticam...","ru":"Настройте ИИ Агент internal-comms для Claude для автоматического создания отчетов о статусе, обновлений 3P, новостных рассылок и отчетов об инцидентах. Испол...","ar":"تعرف على كيفية إعداد مهارة internal-comms لـ Claude AI لتوليد تقارير الحالة، وتحديثات 3P، والنشرات الإخبارية، وتقارير الحوادث تلقائيًا. استخدم قوالب محددة لم..."},"definition":{"en":"internal-comms is an AI agent skill that provides template-based generation for internal corporate communications. It uses predefined guideline files from an examples/ directory to create standardized documents including status reports, leadership updates, and incident reports.","zh":"Internal Comms是一种AI代理技能，专门用于自动化生成企业内部通信文档。它通过识别通信类型并加载相应的示例文件格式，帮助开发者快速创建符合公司标准的各种内部通信内容。","ja":"Internal Commsは、企業内通信文書の自動生成に特化したAIエージェントスキルです。通信タイプを識別し、対応するexamplesファイル形式をロードすることで、開発者が会社標準に準拠した社内通信コンテンツを迅速に作成できます。","ko":"Internal Comms는 기업 내부 커뮤니케이션 문서 자동 생성에 특화된 AI 에이전트 스킬입니다. 커뮤니케이션 유형을 식별하고 해당 examples 파일 형식을 로드하여 개발자가 회사 표준에 맞는 내부 통신 콘텐츠를 빠르게 생성할 수 있도록 합니다.","es":"internal-comms es una skill de agente AI que proporciona plantillas y directrices estandarizadas para comunicaciones corporativas internas. Utiliza archivos Markdown en el directorio examples/ para generar documentos como informes 3P, actualizaciones de liderazgo y reportes de incidentes.","fr":"internal-comms est une compétence d''agent IA fournissant des modèles et directives standardisées pour les communications internes. Elle utilise des fichiers Markdown dans le répertoire examples/ pour générer des documents comme rapports 3P, mises à jour leadership et rapports d''incident.","de":"internal-comms ist eine KI-Agenten-Fähigkeit, die standardisierte Vorlagen für interne Kommunikation bereitstellt. Sie verwendet Markdown-Dateien im examples/-Verzeichnis zur Generierung von 3P-Berichten, Leadership-Updates und Incident Reports.","pt":"A internal-comms é uma skill de AI Agent projetada para gerar comunicações internas automatizadas, como relatórios de status, atualizações 3P e newsletters. Ela utiliza arquivos de guideline predefinidos para manter a consistência nos formatos corporativos.","ru":"Internal-comms — это навык ИИ Агента для автоматического создания внутренних коммуникаций, таких как отчеты о статусе, обновления 3P и рассылки. Он использует предопределенные файлы руководств для соблюдения корпоративных форматов.","ar":"internal-comms هي مهارة لعوامل الذكاء الاصطناعي مصممة لتوليد اتصالات داخلية مؤتمتة مثل تقارير الحالة، وتحديثات 3P، والنشرات الإخبارية. تستخدم ملفات إرشادية محددة مسبقًا للحفاظ على اتساق تنسيقات الشركة."},"features":{"en":["Generates 3P updates (Progress, Plans, Problems) using examples/3p-updates.md templates","Creates company newsletters with standardized formatting guidelines","Produces FAQ responses for internal knowledge bases","Automates status report generation with consistent structure","Formats leadership updates using predefined corporate templates","Generates incident reports with proper documentation protocols"],"zh":["支持多种内部通信类型：3P更新、公司通讯、FAQ回复、状态报告","自动识别通信类型并加载对应的示例文件格式","提供examples/3p-updates.md等预定义模板文件","专为公司内部通信标准格式设计","支持领导更新和项目更新文档生成","包含事件报告自动化生成功能"],"ja":["複数の社内通信タイプをサポート：3Pアップデート、社内ニュースレター、FAQ回答、ステータスレポート","通信タイプを自動識別し、対応するexamplesファイル形式をロード","examples/3p-updates.mdなどの事前定義されたテンプレートファイルを提供","社内通信標準フォーマットに特化して設計","リーダーシップアップデートとプロジェクトアップデート文書生成をサポート","インシデントレポート自動作成機能を含む"],"ko":["다양한 내부 커뮤니케이션 유형 지원: 3P 업데이트, 회사 뉴스레터, FAQ 응답, 상태 보고서","커뮤니케이션 유형 자동 식별 및 해당 examples 파일 형식 로드","examples/3p-updates.md 등 미리 정의된 템플릿 파일 제공","회사 내부 통신 표준 형식에 특화되어 설계","리더십 업데이트 및 프로젝트 업데이트 문서 생성 지원","인시던트 리포트 자동 생성 기능 포함"],"es":["Plantillas predefinidas para 7 tipos de comunicaciones (3P updates, newsletters, FAQs)","Sistema de carga automática de archivos guidelines desde directorio examples/","Soporte para formatos Markdown en todas las plantillas","Integración nativa con Claude AI para generación contextual","Estructura estandarizada para incident reports y project updates","Framework para leadership updates y status reports corporativos"],"fr":["Modèles prédéfinis pour 7 types de communications (mises à jour 3P, newsletters, FAQs)","Chargement automatique des fichiers directives depuis le répertoire examples/","Support des formats Markdown pour tous les modèles","Intégration native avec Claude IA pour génération contextuelle","Structure standardisée pour rapports d''incident et mises à jour projet","Cadre pour mises à jour leadership et rapports d''état d''entreprise"],"de":["Vordefinierte Vorlagen für 7 Kommunikationstypen (3P-Updates, Newsletter, FAQs)","Automatisches Laden von Leitfadendateien aus dem examples/-Verzeichnis","Markdown-Unterstützung für alle Vorlagen","Native Integration mit Claude KI für kontextuelle Generierung","Standardisierte Struktur für Incident Reports und Projekt-Updates","Framework für Leadership Updates und Unternehmensstatusberichte"],"pt":["Geração automática de atualizações 3P (Progresso, Planos, Problemas)","Carregamento de diretrizes do diretório `examples/`","Modelos para relatórios de status e incidentes","Suporte para newsletters corporativas e FAQs","Identificação automática do tipo de comunicação"],"ru":["Автоматическое создание обновлений 3P (Прогресс, Планы, Проблемы)","Загрузка руководств из каталога `examples/`","Шаблоны для отчетов о статусе и инцидентах","Поддержка корпоративных рассылок и FAQ","Автоматическое определение типа коммуникации"],"ar":["التوليد التلقائي لتحديثات 3P (التقدم، الخطط، المشاكل)","تحميل الإرشادات من مجلد `examples/`","قوالب لتقارير الحالة والحوادث","دعم النشرات الإخبارية للشركات والأسئلة الشائعة","التعرف التلقائي على نوع التواصل"]},"keywords":{"en":["internal-comms AI agent skill","how to use internal-comms for status reports","internal-comms setup guide","3P updates template automation","internal-comms vs manual documentation","AI-powered internal communication templates","incident report generation with internal-comms","corporate newsletter automation tool"],"zh":["Internal Comms AI代理技能","内部通信自动化工具","3P更新生成器","公司通讯AI工具","状态报告自动化","领导更新模板","事件报告AI生成","企业内部通信解决方案","AI代理通信技能配置","Claude内部通信技能"],"ja":["Internal Comms AIエージェントスキル","社内通信自動化ツール","3Pアップデートジェネレーター","社内ニュースレターAIツール","ステータスレポート自動化","リーダーシップアップデートテンプレート","インシデントレポートAI生成","企業内通信ソリューション","AIエージェント通信スキル設定","Claude社内通信スキル"],"ko":["Internal Comms AI 에이전트 스킬","내부 커뮤니케이션 자동화 도구","3P 업데이트 생성기","회사 뉴스레터 AI 도구","상태 보고서 자동화","리더십 업데이트 템플릿","인시던트 리포트 AI 생성","기업 내부 통신 솔루션","AI 에이전트 통신 스킬 설정","Claude 내부 통신 스킬"],"es":["claude ai agent skills","automatizar comunicaciones internas","plantillas 3p updates markdown","internal-comms skill configuración","generar company newsletters ai","incident reports automatizados","leadership updates claude ai","faq responses agent skills"],"fr":["compétences agent claude ia","automatiser communications internes","modèles mises à jour 3p markdown","internal-comms compétence configuration","générer newsletters entreprise ia","rapports incident automatisés","mises à jour leadership claude ia","réponses faq compétences agent"],"de":["claude ki agenten skills","interne kommunikation automatisieren","vorlagen 3p updates markdown","internal-comms skill einrichtung","unternehmens-newsletters ki generieren","incident reports automatisiert","leadership updates claude ki","faq antworten agenten skills"],"pt":["skill internal-comms Claude AI","automatizar relatórios de status","atualizações 3P AI Agent","modelos comunicação interna","exemplos diretrizes internal-comms","relatórios de incidentes automatizados"],"ru":["навык internal-comms ИИ Агент","автоматизация отчетов о статусе","обновления 3P ИИ Агенты","шаблоны внутренних коммуникаций","примеры руководств internal-comms","автоматические отчеты об инцидентах"],"ar":["مهارة internal-comms لعوامل الذكاء الاصطناعي","أتمتة تقارير الحالة","تحديثات 3P أدوات الذكاء الاصطناعي","قوالب التواصل الداخلي","أمثلة إرشادات internal-comms","تقارير الحوادث المؤتمتة"]}},"agentAnalysis":{"suitability":{"en":"Essential for Enterprise Communication Agents drafting structured internal documents.","zh":"对于企业通信代理起草结构化内部文档至关重要。","ja":"構造化された内部文書を作成するエンタープライズコミュニケーションエージェントに不可欠です。","ko":"구조화된 내부 문서를 기초하는 엔터프라이즈 커뮤니케이션 에이전트에 필수적입니다.","es":"Esencial para agentes de comunicación empresarial que redactan documentos internos estructurados.","fr":"Essentiel pour les agents de communication d''entreprise rédigeant des documents internes structurés.","de":"Essenziell für Enterprise Communication Agents, die strukturierte interne Dokumente entwerfen.","pt":"Essencial para Agentes de Comunicação Empresarial que redigem documentos internos estruturados.","ru":"Необходим для корпоративных коммуникационных агентов, составляющих структурированные внутренние документы.","ar":"أساسي لوكلاء الاتصال المؤسسي الذين يقومون بصياغة الوثائق الداخلية المنظمة."},"recommendation":{"en":"Enables AI agents to generate standardized internal communications by leveraging predefined templates from an examples/ directory. Provides immediate access to company-specific formats for 3P updates, status reports, and incident documentation.","zh":"使AI代理能够通过利用examples/目录中的预定义模板来生成标准化的内部通信。提供对公司特定格式（如3P更新、状态报告和事件文档）的即时访问。","ja":"examples/ディレクトリ内の事前定義されたテンプレートを活用することで、AIエージェントが標準化された内部コミュニケーションを生成できるようにします。3P更新、ステータスレポート、インシデント文書といった会社固有のフォーマットへの即時アクセスを提供します。","ko":"examples/ 디렉토리의 미리 정의된 템플릿을 활용하여 AI 에이전트가 표준화된 내부 커뮤니케이션을 생성할 수 있게 합니다. 3P 업데이트, 상태 보고서 및 사고 문서와 같은 회사별 형식에 대한 즉각적인 액세스를 제공합니다.","es":"Permite a los agentes de IA generar comunicaciones internas estandarizadas aprovechando plantillas predefinidas de un directorio examples/. Proporciona acceso inmediato a formatos específicos de la empresa para actualizaciones 3P, informes de estado y documentación de incidentes.","fr":"Permet aux agents IA de générer des communications internes standardisées en exploitant des modèles prédéfinis d''un répertoire examples/. Fournit un accès immédiat à des formats spécifiques à l''entreprise pour les mises à jour 3P, les rapports d''état et la documentation d''incident.","de":"Ermöglicht es KI-Agenten, standardisierte interne Kommunikation zu generieren, indem vordefinierte Vorlagen aus einem examples/-Verzeichnis genutzt werden. Bietet sofortigen Zugriff auf unternehmensspezifische Formate für 3P-Updates, Statusberichte und Incident-Dokumentation.","pt":"Permite que agentes de IA gerem comunicações internas padronizadas aproveitando modelos predefinidos de um diretório examples/. Oferece acesso imediato a formatos específicos da empresa para atualizações 3P, relatórios de status e documentação de incidentes.","ru":"Позволяет ИИ-агентам генерировать стандартизированные внутренние коммуникации, используя предопределенные шаблоны из каталога examples/. Обеспечивает немедленный доступ к специфичным для компании форматам для 3P-обновлений, отчетов о статусе и документации по инцидентам.","ar":"يمكن وكلاء الذكاء الاصطناعي من إنشاء اتصالات داخلية موحدة من خلال الاستفادة من القوالب المحددة مسبقًا من دليل examples/. يوفر وصولاً فوريًا إلى الصيغ المخصصة للشركة لتحديثات 3P، وتقارير الحالة، وتوثيق الحوادث."},"useCases":{"en":["Generating Progress/Plans/Problems (3P) team updates","Drafting standardized incident reports","Creating company newsletter content","Producing leadership status updates","Compiling FAQ responses"],"zh":["生成进度/计划/问题（3P）团队更新","起草标准化事件报告","创建公司新闻通讯内容","制作领导状态更新","汇编FAQ响应"],"ja":["進捗/計画/問題（3P）チーム更新の生成","標準化されたインシデントレポートの作成","会社ニュースレターコンテンツの作成","リーダーシップステータス更新の作成","FAQ応答のコンパイル"],"ko":["진행/계획/문제(3P) 팀 업데이트 생성","표준화된 사고 보고서 초안 작성","회사 뉴스레터 콘텐츠 생성","리더십 상태 업데이트 생성","FAQ 응답 컴파일"],"es":["Generación de actualizaciones de equipo Progress/Plans/Problems (3P)","Redacción de informes de incidentes estandarizados","Creación de contenido para boletines internos de la empresa","Producción de actualizaciones de estado para el liderazgo","Compilación de respuestas a preguntas frecuentes (FAQ)"],"fr":["Génération de mises à jour d''équipe Progress/Plans/Problems (3P)","Rédaction de rapports d''incident standardisés","Création de contenu pour les bulletins d''information internes de l''entreprise","Production de mises à jour d''état pour la direction","Compilation de réponses aux questions fréquentes (FAQ)"],"de":["Generieren von Progress/Plans/Problems (3P) Team-Updates","Entwurf von standardisierten Incident Reports","Erstellen von Inhalten für firmeninterne Newsletter","Erstellen von Statusupdates für die Führungsebene","Zusammenstellen von FAQ-Antworten"],"pt":["Geração de atualizações de equipe Progresso/Planos/Problemas (3P)","Redação de relatórios de incidentes padronizados","Criação de conteúdo para boletins informativos da empresa","Produção de atualizações de status para a liderança","Compilação de respostas para Perguntas Frequentes (FAQ)"],"ru":["Генерация командных обновлений Progress/Plans/Problems (3P)","Составление стандартизированных отчетов об инцидентах","Создание содержимого для корпоративных новостных рассылок","Подготовка отчетов о статусе для руководства","Составление ответов на Часто Задаваемые Вопросы (FAQ)"],"ar":["إنشاء تحديثات فريق التقدم/الخطط/المشاكل (3P)","صياغة تقارير الحوادث الموحدة","إنشاء محتوى النشرات الإخبارية للشركة","إنتاج تحديثات الحالة للقيادة","تجميع ردود الأسئلة الشائعة (FAQ)"]},"limitations":{"en":["Requires pre-configured guideline files in examples/ directory","Limited to predefined communication types (3P updates, newsletters, reports)"],"zh":["需要examples/目录中存在预配置的指南文件","仅限于预定义的通信类型（3P更新、新闻通讯、报告）"],"ja":["examples/ディレクトリ内に事前設定されたガイドラインファイルが必要","事前定義されたコミュニケーションタイプ（3P更新、ニュースレター、レポート）に限定される"],"ko":["examples/ 디렉토리에 미리 구성된 가이드라인 파일 필요","미리 정의된 커뮤니케이션 유형(3P 업데이트, 뉴스레터, 보고서)으로 제한됨"],"es":["Requiere archivos de directrices preconfigurados en el directorio examples/","Limitado a tipos de comunicación predefinidos (actualizaciones 3P, boletines, informes)"],"fr":["Nécessite des fichiers de directives préconfigurés dans le répertoire examples/","Limité à des types de communication prédéfinis (mises à jour 3P, bulletins d''information, rapports)"],"de":["Erfordert vorab konfigurierte Richtliniendateien im examples/-Verzeichnis","Beschränkt auf vordefinierte Kommunikationstypen (3P-Updates, Newsletter, Berichte)"],"pt":["Requer arquivos de diretrizes pré-configurados no diretório examples/","Limitado aos tipos de comunicação predefinidos (atualizações 3P, boletins informativos, relatórios)"],"ru":["Требует предварительно настроенных файлов руководств в каталоге examples/","Ограничено предопределенными типами коммуникаций (3P-обновления, рассылки, отчеты)"],"ar":["يتطلب ملفات إرشادية مهيأة مسبقًا في دليل examples/","مقتصر على أنواع الاتصال المحددة مسبقًا (تحديثات 3P، النشرات الإخبارية، التقارير)"]},"version":4},"contentHash":"067b7587a344a928fc6534ef66b1bcd591fc7c26d207ea7ca3334aeb678d6475","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":76}');
