INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/internal-comms', 'internal-comms', 'anthropics', 'skills', 'official', 'internal-comms anthropics skills official agent-skills The internal-comms AI agent skill provides structured templates for generating internal communications like status reports, 3P updates, and incident reports. Development teams and technical writers benefit from standardized documentation formats. Internal Comms AI代理技能专门用于自动化生成各种内部通信文档，包括状态报告、领导更新、3P更新和事件报告。该技能通过加载预定义的示例文件格式来确保符合公司通信标准。 Internal Comms AIエージェントスキルは、ステータスレポート、リーダーシップアップデート、3Pアップデート、インシデントレポートなどの社内通信文書を自動生成するために設計されています。あらかじめ定義されたexamplesファイル形式をロードして会社の通信標準に準拠します。 Internal Comms AI 에이전트 스킬은 상태 보고서, 리더십 업데이트, 3P 업데이트, 인시던트 리포트 등 다양한 내부 커뮤니케이션 문서 자동 생성을 위해 설계되었습니다. 미리 정의된 examples 파일 형식을 로드하여 회사 통신 표준을 준수합니다. Skill técnica para Claude AI que automatiza la redacción de comunicaciones internas mediante el uso de archivos de guía en formato Markdown. Incluye plantillas para actualizaciones 3P, reportes de incidentes y newsletters corporativas. Compétence technique pour Claude IA automatisant la rédaction de communications internes via des fichiers guides Markdown. Inclut modèles pour mises à jour 3P, rapports d''incident et newsletters d''entreprise. Technische Skill für Claude KI zur Automatisierung interner Kommunikation mittels Markdown-Leitfäden. Enthält Vorlagen für 3P-Updates, Incident Reports und Unternehmens-Newsletters. A skill internal-comms permite automatizar a criação de documentos internos como relatórios de status, atualizações de liderança e relatórios de incidentes. Ela carrega diretrizes específicas do diretório `examples/` para garantir conformidade com os formatos da empresa. Навык internal-comms автоматизирует создание внутренних документов, таких как отчеты о статусе, обновления для руководства и отчеты об инцидентах. Он загружает конкретные руководства из каталога `examples/` для соответствия форматам компании. تمكّن مهارة internal-comms من أتمتة إنشاء المستندات الداخلية مثل تقارير الحالة، وتحديثات القيادة، وتقارير الحوادث. تقوم بتحميل إرشادات محددة من مجلد `examples/` لضمان الامتثال لمعايير الشركة. internal-comms AI agent skill how to use internal-comms for status reports internal-comms setup guide 3P updates template automation internal-comms vs manual documentation AI-powered internal communication templates incident report generation with internal-comms corporate newsletter automation tool Internal Comms AI代理技能 内部通信自动化工具 3P更新生成器 公司通讯AI工具 状态报告自动化 领导更新模板 事件报告AI生成 企业内部通信解决方案 AI代理通信技能配置 Claude内部通信技能 Generates 3P updates (Progress, Plans, Problems) using examples/3p-updates.md templates Creates company newsletters with standardized formatting guidelines Produces FAQ responses for internal knowledge bases Automates status report generation with consistent structure Formats leadership updates using predefined corporate templates Generates incident reports with proper documentation protocols internal-comms is an AI agent skill that provides template-based generation for internal corporate communications. It uses predefined guideline files from an examples/ directory to create standardized documents including status reports, leadership updates, and incident reports.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/theme-factory', 'official', 'anthropics', 'skills', 'anthropics/skills', 'theme-factory', 85097, 8974, 76, '2026-03-06T03:11:21Z', '2026-03-06T03:23:56.825Z', 'c35893e221e28895c52143cc11bf30e41a44817796b39d4b15727dadc9796552', '{"id":"anthropics/skills/theme-factory","name":"theme-factory","description":{"en":"The theme-factory skill applies consistent, professional styling to artifacts like slides, docs, and HTML landing pages. Developers and AI agents use it to instantly style content with pre-set or dynamically generated themes.","zh":"Theme-Factory是一个AI代理技能工具包，用于为幻灯片、文档和HTML落地页等工件应用专业样式主题。它提供10种预设主题，包含协调的调色板和互补字体配对，也可动态生成新主题。","ja":"Theme-Factoryは、スライドやドキュメントなどのアーティファクトにプロフェッショナルなスタイリングを適用するAIエージェントスキルです。10のプリセットテーマと動的なテーマ生成を提供します。","ko":"Theme-Factory는 슬라이드나 문서 등의 아티팩트에 전문적인 스타일링을 적용하는 AI 에이전트 스킬입니다. 10개의 프리셋 테마와 동적 테마 생성을 제공합니다.","es":"Theme-factory es una herramienta para estilizar artefactos con temas profesionales, incluyendo presentaciones y documentos","fr":"Theme-factory est un outil pour personnaliser les artefacts avec des thèmes professionnels, y compris des présentations et des documents","de":"Theme-factory ist ein Werkzeug zur Stilisierung von Artefakten mit professionellen Themen, einschließlich Präsentationen und Dokumenten","pt":"O Theme Factory é um skill para Agentes IA que fornece 10 temas pré-definidos com paletas de cores hex e combinações de fontes. Permite aplicar estilos consistentes a slides, documentos e páginas HTML, ou gerar um novo tema sob demanda.","ru":"Theme Factory — это навык для ИИ Агентов, предоставляющий 10 предустановленных тем с hex-палитрами и парными шрифтами. Позволяет применять единообразные стили к слайдам, документам и HTML-страницам или генерировать новую тему на лету.","ar":"Theme Factory هو مهارة لأدوات الذكاء الاصطناعي تقدم 10 سمات محددة مسبقًا تحتوي على لوحات ألوان hex وتركيبات خطوط. تتيح تطبيق أنماط متسقة على الشرائح والمستندات وصفحات HTML، أو إنشاء سمة جديدة ديناميكيًا."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"theme-factory","description":"Toolkit for styling artifacts with a theme. These artifacts can be slides, docs, reportings, HTML landing pages, etc. There are 10 pre-set themes with colors/fonts that you can apply to any artifact that has been creating, or can generate a new theme on-the-fly.","bodyPreview":"# Theme Factory Skill\n\nThis skill provides a curated collection of professional font and color themes themes, each with carefully selected color palettes and font pairings. Once a theme is chosen, it can be applied to any artifact.\n\n## Purpose\n\nTo apply consistent, professional styling to presentation slide decks, use this skill. Each theme includes:\n- A cohesive color palette with hex codes\n- Complementary font pairings for headers and body text\n- A distinct visual identity suitable for differe","body":"# Theme Factory Skill\n\nThis skill provides a curated collection of professional font and color themes themes, each with carefully selected color palettes and font pairings. Once a theme is chosen, it can be applied to any artifact.\n\n## Purpose\n\nTo apply consistent, professional styling to presentation slide decks, use this skill. Each theme includes:\n- A cohesive color palette with hex codes\n- Complementary font pairings for headers and body text\n- A distinct visual identity suitable for different contexts and audiences\n\n## Usage Instructions\n\nTo apply styling to a slide deck or other artifact:\n\n1. **Show the theme showcase**: Display the `theme-showcase.pdf` file to allow users to see all available themes visually. Do not make any modifications to it; simply show the file for viewing.\n2. **Ask for their choice**: Ask which theme to apply to the deck\n3. **Wait for selection**: Get explicit confirmation about the chosen theme\n4. **Apply the theme**: Once a theme has been chosen, apply the selected theme''s colors and fonts to the deck/artifact\n\n## Themes Available\n\nThe following 10 themes are available, each showcased in `theme-showcase.pdf`:\n\n1. **Ocean Depths** - Professional and calming maritime theme\n2. **Sunset Boulevard** - Warm and vibrant sunset colors\n3. **Forest Canopy** - Natural and grounded earth tones\n4. **Modern Minimalist** - Clean and contemporary grayscale\n5. **Golden Hour** - Rich and warm autumnal palette\n6. **Arctic Frost** - Cool and crisp winter-inspired theme\n7. **Desert Rose** - Soft and sophisticated dusty tones\n8. **Tech Innovation** - Bold and modern tech aesthetic\n9. **Botanical Garden** - Fresh and organic garden colors\n10. **Midnight Galaxy** - Dramatic and cosmic deep tones\n\n## Theme Details\n\nEach theme is defined in the `themes/` directory with complete specifications including:\n- Cohesive color palette with hex codes\n- Complementary font pairings for headers and body text\n- Distinct visual identity suitable for different contexts and audiences\n\n## Application Process\n\nAfter a preferred theme is selected:\n1. Read the corresponding theme file from the `themes/` directory\n2. Apply the specified colors and fonts consistently throughout the deck\n3. Ensure proper contrast and readability\n4. Maintain the theme''s visual identity across all slides\n\n## Create your Own Theme\nTo handle cases where none of the existing themes work for an artifact, create a custom theme. Based on provided inputs, generate a new theme similar to the ones above. Give the theme a similar name describing what the font/color combinations represent. Use any basic description provided to choose appropriate colors/fonts. After generating the theme, show it for review and verification. Following that, apply the theme as described above.\n"},"category":"official","lastSynced":"2026-03-06T03:23:56.825Z","seo":{"title":{"en":"theme-factory: Apply Pre-Set Themes to Artifacts | AI Age...","zh":"Theme-Factory AI代理技能：主题样式工具包设置指南","ja":"Theme-Factory AIエージェントスキル：テーマ適用ガイド","ko":"Theme-Factory AI 에이전트 스킬: 테마 스타일링 툴킷 사용법","es":"Guía de configuración de theme-factory para estilizar art...","fr":"Guide de mise en place de theme-factory pour personnalise...","de":"Einrichtungsanleitung für theme-factory zur Stilisierung ...","pt":"Theme Factory: Guia de Configuração para Agentes IA","ru":"Theme Factory: Руководство по настройке для ИИ Агентов","ar":"Theme Factory: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Apply one of 10 pre-set themes with curated fonts & color palettes to slides, docs, or HTML. Generate new themes on-the-fly for consistent, professional styl...","zh":"Theme-Factory AI代理技能提供10种预设主题，包含协调的调色板（含十六进制代码）和互补字体配对，可快速应用于幻灯片、文档和HTML落地页等工件。","ja":"Theme-Factory AIエージェントスキルは、10のプリセットテーマ（カラーパレットとフォントペアリング）を提供し、スライドやHTMLランディングページに適用できます。","ko":"Theme-Factory AI 에이전트 스킬은 10개의 프리셋 테마(색상 팔레트 및 폰트 페어링)를 제공하며, 슬라이드나 HTML 랜딩 페이지에 적용할 수 있습니다.","es":"Aprende a aplicar temas profesionales a tus artefactos con theme-factory, incluyendo presentaciones, documentos y páginas de destino","fr":"Découvrez comment appliquer des thèmes professionnels à vos artefacts avec theme-factory, y compris des présentations, des documents et des pages de destination","de":"Erfahren Sie, wie Sie professionelle Themen auf Ihre Artefakte mit theme-factory anwenden können, einschließlich Präsentationen, Dokumente und Zielseiten","pt":"Aplique temas profissionais com paletas de cores e fontes pré-definidas em slides, docs e landing pages HTML. Gere temas dinamicamente para seus Agentes IA.","ru":"Применяйте профессиональные темы с предустановленными палитрами цветов и шрифтами к слайдам, документам и HTML-лендингам. Генерируйте темы на лету для ваших ...","ar":"طبق سمات احترافية تحتوي على لوحات ألوان وخطوط محددة مسبقًا على الشرائح والمستندات وصفحات الهبوط HTML. أنشئ سمات ديناميكيًا لأدوات الذكاء الاصطناعي الخاصة بك."},"definition":{"en":"theme-factory is an AI agent skill that provides a toolkit for styling artifacts with a theme. It offers 10 pre-set themes with curated color palettes (hex codes) and complementary font pairings, or can generate a new theme on-the-fly for slides, docs, and reports.","zh":"Theme-Factory是一个AI代理技能，提供精心策划的专业字体和颜色主题集合。每个主题包含协调的调色板（含十六进制代码）和互补的标题/正文字体配对，可为各种工件创建一致的视觉标识。","ja":"Theme-Factoryは、厳選されたプロフェッショナルなフォントとカラーテーマを提供するAIエージェントスキルです。各テーマには調和の取れたカラーパレットとフォントペアリングが含まれ、一貫したビジュアルアイデンティティを実現します。","ko":"Theme-Factory는 선별된 전문 폰트와 컬러 테마를 제공하는 AI 에이전트 스킬입니다. 각 테마에는 조화로운 색상 팔레트와 폰트 페어링이 포함되어 일관된 비주얼 아이덴티티를 생성합니다.","es":"¿Qué es theme-factory? Un conjunto de herramientas para aplicar temas profesionales a artefactos","fr":"Qu''est-ce que theme-factory? Un ensemble d''outils pour appliquer des thèmes professionnels aux artefacts","de":"Was ist theme-factory? Ein Satz von Werkzeugen zur Anwendung von professionellen Themen auf Artefakte","pt":"Theme Factory é um skill técnico para Agentes IA que automatiza a aplicação de temas de design em artefatos como slides, documentos e landing pages. Oferece 10 temas pré-configurados com paletas de cores hex e combinações de fontes, além de geração dinâmica de novos temas.","ru":"Theme Factory — это технический навык для ИИ Агентов, автоматизирующий применение дизайн-тем к артефактам, таким как слайды, документы и лендинги. Предоставляет 10 предустановленных тем с hex-палитрами и парными шрифтами, а также динамическую генерацию новых тем.","ar":"Theme Factory هي مهارة تقنية لأدوات الذكاء الاصطناعي تقوم بأتمتة تطبيق سمات التصميم على القطع الأثرية مثل الشرائح والمستندات وصفحات الهبوط. تقدم 10 سمات محددة مسبقًا تحتوي على لوحات ألوان hex وتركيبات خطوط، بالإضافة إلى إنشاء سمات جديدة ديناميكيًا."},"features":{"en":["Provides 10 pre-set themes with curated color palettes (hex codes)","Includes complementary font pairings for headers and body text","Applies themes to artifacts like slides, docs, reports, and HTML landing pages","Generates new color and font themes dynamically on-the-fly","Creates a distinct visual identity for different types of content"],"zh":["10种精心策划的预设主题，包含协调的调色板与十六进制代码","专业的标题和正文字体互补配对系统","支持幻灯片、文档、报告和HTML落地页等多种工件类型","动态即时主题生成功能","为不同视觉身份提供独特的样式方案","确保跨工件样式应用的一致性"],"ja":["10の厳選されたプリセットテーマ（カラーパレットとHEXコード付き）","ヘッダーと本文のための補完的なフォントペアリングシステム","スライド、ドキュメント、レポート、HTMLランディングページ対応","オンデマンドでの動的テーマ生成機能","異なるビジュアルアイデンティティに対応したスタイリング","アーティファクト間での一貫したスタイリング適用"],"ko":["10개의 선별된 프리셋 테마(색상 팔레트 및 HEX 코드 포함)","헤더와 본문을 위한 상호보완적인 폰트 페어링 시스템","슬라이드, 문서, 리포트, HTML 랜딩 페이지 지원","온더플라이 동적 테마 생성 기능","다양한 비주얼 아이덴티티에 적합한 스타일링","아티팩트 간 일관된 스타일링 적용 보장"],"es":["10 temas preestablecidos con paletas de colores y fuentes","Generación de temas personalizados","Aplicación de temas a presentaciones y documentos","Coherencia en la estilización de artefactos","Compatibilidad con HTML y landing pages"],"fr":["10 thèmes prédéfinis avec des palettes de couleurs et des polices","Génération de thèmes personnalisés","Application de thèmes à des présentations et des documents","Cohérence dans la personnalisation des artefacts","Compatibilité avec HTML et les pages de destination"],"de":["10 vorgefertigte Themen mit Farbpaletten und Schriftarten","Erstellung von benutzerdefinierten Themen","Anwendung von Themen auf Präsentationen und Dokumente","Konsistenz in der Stilisierung von Artefakten","Kompatibilität mit HTML und Zielseiten"],"pt":["10 temas pré-definidos com paletas de cores hex","Combinações de fontes complementares para headers e body","Aplicação de temas em slides, documentos e landing pages HTML","Geração de novos temas dinamicamente (on-the-fly)","Criação de identidade visual distinta para diferentes artefatos","Estilo consistente e profissional para apresentações e relatórios"],"ru":["10 предустановленных тем с hex-палитрами цветов","Комплементарные парные шрифты для заголовков и основного текста","Применение тем к слайдам, документам и HTML-лендингам","Динамическая генерация новых тем (on-the-fly)","Создание distinct визуальной идентичности для различных артефактов","Единообразный профессиональный стиль для презентаций и отчетов"],"ar":["10 سمات محددة مسبقًا تحتوي على لوحات ألوان hex","تركيبات خطوط مكملة للعناوين والنص الأساسي","تطبيق السمات على الشرائح والمستندات وصفحات الهبوط HTML","إنشاء سمات جديدة ديناميكيًا (on-the-fly)","إنشاء هوية بصرية مميزة للقطع الأثرية المختلفة","نمط احترافي متسق للعروض التقديمية والتقارير"]},"keywords":{"en":["how to use theme-factory","what is theme-factory","theme-factory vs manual styling","theme-factory alternative","theme-factory install guide","theme-factory setup for AI agents","apply themes to slides and docs","AI agent color palette generator"],"zh":["theme-factory AI代理","幻灯片主题应用","HTML落地页样式","调色板十六进制代码","字体配对最佳实践","动态主题生成","AI工具样式一致性","文档主题设置"],"ja":["theme-factory AIエージェント","スライドテーマ適用","HTMLランディングページスタイリング","カラーパレットHEXコード","フォントペアリングベストプラクティス","動的テーマ生成","AIツールスタイリング一貫性","ドキュメントテーマ設定"],"ko":["theme-factory AI 에이전트","슬라이드 테마 적용","HTML 랜딩페이지 스타일링","색상 팔레트 HEX 코드","폰트 페어링 베스트 프랙티스","동적 테마 생성","AI 도구 스타일링 일관성","문서 테마 설정"],"es":["theme-factory","estilizar artefactos","temas profesionales","presentaciones","documentos","Herramientas de AI","Agente de AI para estilizar","Desarrollo de temas personalizados"],"fr":["theme-factory","personnaliser les artefacts","thèmes professionnels","présentations","documents","Outils d''IA","Agent d''IA pour personnaliser","Développement de thèmes personnalisés"],"de":["theme-factory","Artefakte stilisieren","professionelle Themen","Präsentationen","Dokumente","AI-Tools","AI-Agent für Stilisierung","Entwicklung von benutzerdefinierten Themen"],"pt":["theme factory agent skill","aplicar temas slides AI","gerador temas dinâmico Agentes IA","paleta cores hex documentos","font pairing headers body","landing page HTML themes","skill temas pré-definidos","automação design artefatos"],"ru":["theme factory навык ИИ Агентов","применять темы слайды ИИ","генератор тем динамический ИИ Агенты","палитра цветов hex документы","парные шрифты заголовки body","лендинг HTML темы","навык предустановленные темы","автоматизация дизайн артефакты"],"ar":["theme factory مهارة أدوات الذكاء الاصطناعي","تطبيق السمات شرائح الذكاء الاصطناعي","منشئ سمات ديناميكي أدوات الذكاء الاصطناعي","لوحة ألوان hex مستندات","تركيبات خطوط عناوين نص أساسي","صفحة هبوط HTML سمات","مهارة سمات محددة مسبقًا","أتمتة تصميم قطع أثرية"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Content Creation Agents needing instant professional styling for diverse digital artifacts.","zh":"非常适合需要为各种数字文物提供即时专业样式的内容创作代理。","ja":"様々なデジタルアーティファクトにインスタントのプロフェッショナルスタイリングを必要とするコンテンツ作成エージェントに最適です。","ko":"다양한 디지털 아티팩트에 즉시 전문가 수준의 스타일링이 필요한 콘텐츠 생성 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Creación de Contenido que necesitan estilización profesional instantánea para diversos artefactos digitales.","fr":"Idéal pour les Agents de Création de Contenu nécessitant une stylisation professionnelle instantanée pour divers artefacts numériques.","de":"Perfekt für Content-Erstellungs-Agenten, die sofortige professionelle Gestaltung für diverse digitale Artefakte benötigen.","pt":"Perfeito para Agentes de Criação de Conteúdo que necessitam de estilização profissional instantânea para diversos artefactos digitais.","ru":"Идеально подходит для Агентов по Созданию Контента, которым требуется мгновенное профессиональное оформление для различных цифровых артефактов.","ar":"مثالي لوكلاء إنشاء المحتوى الذين يحتاجون إلى تصميم فوري محترف لمختلف القطع الرقمية."},"recommendation":{"en":"Applies cohesive color palettes with hex codes and complementary font pairings to slides, docs, HTML landing pages, and reports. Enables on-the-fly theme generation or selection from 10 pre-set professional themes for consistent visual identity across artifacts.","zh":"将协调的颜色调色板、十六进制代码和互补字体配对应用于幻灯片、文档、HTML 登陆页面和报告。启用即时主题生成或从 10 个预设的专业主题中选择，以保持文物的一致的视觉身份。","ja":"スライド、ドキュメント、HTML ランディングページ、レポートに一貫したカラーパレット、ヘックスコード、補足フォントのペアを適用します。10 の事前設定されたプロフェッショナルテーマから選択またはオンザフライのテーマ生成を可能にし、文物全体で一貫した視覚的なアイデンティティを実現します。","ko":"슬라이드, 문서, HTML 랜딩 페이지, 보고서에 일관된 색상 팔레트, 16진수 코드 및 보완 폰트 쌍을 적용합니다. 즉시 테마 생성 또는 10개의 사전 설정된 전문가 테마 중에서 선택하여 아티팩트 전반에 걸친 일관된 시각적 정체성을 허용합니다.","es":"Aplica paletas de colores cohesivas con códigos hexadecimales y combinaciones de fuentes complementarias a diapositivas, documentos, páginas de destino HTML e informes. Permite la generación de temas sobre la marcha o la selección de entre 10 temas preestablecidos para una identidad visual consistente en todos los artefactos.","fr":"Applique des palettes de couleurs cohérentes avec des codes hexadécimaux et des associations de polices complémentaires aux diapositives, documents, pages de destination HTML et rapports. Permet la génération de thèmes à la volée ou la sélection parmi 10 thèmes prédéfinis pour une identité visuelle cohérente sur tous les artefacts.","de":"Wendet zusammenhängende Farbpaletten mit Hex-Codes und komplementären Schriftkombinationen auf Folien, Dokumente, HTML-Landingpages und Berichte an. Ermöglicht die spontane Erstellung von Themen oder die Auswahl aus 10 voreingestellten professionellen Themen für eine konsistente visuelle Identität über alle Artefakte hinweg.","pt":"Aplica paletas de cores coesas com códigos hexadecimais e pares de fontes complementares a slides, documentos, páginas de destino HTML e relatórios. Permite a geração de temas em tempo real ou a seleção de 10 temas profissionais predefinidos para uma identidade visual consistente em todos os artefactos.","ru":"Применяет согласованные цветовые палитры с шестнадцатеричными кодами и дополнительные пары шрифтов к слайдам, документам, HTML-лендингам и отчетам. Позволяет мгновенно генерировать темы или выбирать из 10 предустановленных профессиональных тем для обеспечения единообразного визуального стиля всех артефактов.","ar":"يطبق لوحات ألوان متماسكة مع رموز ست عشرية وأزواج خطوط مكملة للشرائح والمستندات وصفحات الهبوط HTML والتقارير. يتيح إنشاء سيمات على الفور أو الاختيار من بين 10 سيمات مهنية محددة مسبقًا للحفاظ على هوية بصرية متسقة عبر جميع القطع."},"useCases":{"en":["Applying pre-set color/font themes to presentation slide decks","Generating new thematic identities for HTML landing pages","Styling documentation with consistent visual branding","Formatting reports with professional font pairings"],"zh":["将预设的颜色/字体主题应用于演示文稿幻灯片","为 HTML 登陆页面生成新的主题身份","使用一致的视觉品牌来样式化文档","使用专业的字体配对来格式化报告"],"ja":["プレゼンテーションスライドデッキに事前設定されたカラー/フォントテーマを適用する","HTML ランディングページに新しいテーマアイデンティティを生成する","文書に一貫した視覚的なブランディングを使用してスタイリングする","プロフェッショナルなフォントペアを使用してレポートをフォーマットする"],"ko":["프레젠테이션 슬라이드 데크에 사전 설정된 색상/폰트 테마를 적용한다","HTML 랜딩 페이지에 새로운 테마 아이덴티티를 생성한다","문서에 일관된 시각적 브랜딩을 사용하여 스타일링한다","전문가 수준의 폰트 쌍을 사용하여 보고서를 형식화한다"],"es":["Aplicar temas preestablecidos de color/fuente a decks de diapositivas de presentación","Generar nuevas identidades temáticas para páginas de destino HTML","Estilizar documentación con marca visual consistente","Formatear informes con combinaciones de fuentes profesionales"],"fr":["Appliquer des thèmes prédéfinis de couleur/police aux decks de diapositives de présentation","Générer de nouvelles identités thématiques pour les pages de destination HTML","Styliser la documentation avec une identité visuelle cohérente","Formater des rapports avec des associations de polices professionnelles"],"de":["Anwenden voreingestellter Farb-/Schriftthemen auf Präsentationsfoliendecks","Erzeugen neuer thematischer Identitäten für HTML-Landingpages","Gestalten von Dokumentation mit konsistentem visuellem Branding","Formatieren von Berichten mit professionellen Schriftkombinationen"],"pt":["Aplicar temas de cores/fontes predefinidos a decks de slides de apresentação","Gerar novas identidades temáticas para páginas de destino HTML","Estilizar documentação com marca visual consistente","Formatar relatórios com pares de fontes profissionais"],"ru":["Применение предустановленных цветовых/шрифтовых тем к презентационным слайдам","Создание новых тематических идентичностей для HTML-лендингов","Оформление документации с последовательным визуальным брендингом","Форматирование отчетов с профессиональными парами шрифтов"],"ar":["تطبيق سيمات الألوان/الخطوط المحددة مسبقًا على مجموعات شرائح العروض التقديمية","إنشاء هويات موضوعية جديدة لصفحات الهبوط HTML","تنسيق الوثائق بهوية بصرية موحدة","تنسيق التقارير بأزواج خطوط محترفة"]},"limitations":{"en":["Requires artifact creation capability first","Limited to 10 pre-set theme options without customization","Needs structured artifact formats for proper application"],"zh":["首先需要创建文物的能力","仅限 10 个预设主题选项，无自定义","需要结构化的文物格式以适当应用"],"ja":["事前にアーティファクトの作成能力を必要とする","カスタマイズなしで 10 の事前設定されたテーマオプションに限定される","適切な適用のために構造化されたアーティファクト形式を必要とする"],"ko":["まず 아티팩트 생성 기능이 필요하다","사전 설정된 테마 옵션 10개로 제한되며 사용자 지정이 불가능하다","적절한 적용을 위해 구조화된 아티팩트 형식을 필요로 한다"],"es":["Requiere capacidad de creación de artefactos primero","Limitado a 10 opciones de temas preestablecidos sin personalización","Necesita formatos de artefactos estructurados para una aplicación adecuada"],"fr":["Nécessite d''abord une capacité de création d''artefacts","Limité à 10 options de thèmes prédéfinis sans personnalisation","Nécessite des formats d''artefacts structurés pour une application correcte"],"de":["Erfordert zuerst Artefakterstellungskapazität","Beschränkt auf 10 voreingestellte Themenoptionen ohne Anpassung","Benötigt strukturierte Artefaktformate für ordnungsgemäße Anwendung"],"pt":["Requer capacidade de criação de artefactos primeiro","Limitado a 10 opções de temas predefinidos sem personalização","Necessita de formatos de artefactos estruturados para uma aplicação adequada"],"ru":["Требует сначала возможности создания артефактов","Ограничено 10 предустановленными вариантами тем без возможности настройки","Требует структурированных форматов артефактов для правильного применения"],"ar":["يتطلب أولاً قدرة على إنشاء القطع الرقمية","محدود بـ 10 خيارات سيمات محددة مسبقًا دون تخصيص","يحتاج إلى تنسيقات هيكلية للقطع لتطبيق سليم"]},"version":4},"contentHash":"c35893e221e28895c52143cc11bf30e41a44817796b39d4b15727dadc9796552","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":76}');
DELETE FROM skills_fts WHERE id = 'anthropics/skills/theme-factory';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/theme-factory', 'theme-factory', 'anthropics', 'skills', 'official', 'theme-factory anthropics skills official agent-skills The theme-factory skill applies consistent, professional styling to artifacts like slides, docs, and HTML landing pages. Developers and AI agents use it to instantly style content with pre-set or dynamically generated themes. Theme-Factory是一个AI代理技能工具包，用于为幻灯片、文档和HTML落地页等工件应用专业样式主题。它提供10种预设主题，包含协调的调色板和互补字体配对，也可动态生成新主题。 Theme-Factoryは、スライドやドキュメントなどのアーティファクトにプロフェッショナルなスタイリングを適用するAIエージェントスキルです。10のプリセットテーマと動的なテーマ生成を提供します。 Theme-Factory는 슬라이드나 문서 등의 아티팩트에 전문적인 스타일링을 적용하는 AI 에이전트 스킬입니다. 10개의 프리셋 테마와 동적 테마 생성을 제공합니다. Theme-factory es una herramienta para estilizar artefactos con temas profesionales, incluyendo presentaciones y documentos Theme-factory est un outil pour personnaliser les artefacts avec des thèmes professionnels, y compris des présentations et des documents Theme-factory ist ein Werkzeug zur Stilisierung von Artefakten mit professionellen Themen, einschließlich Präsentationen und Dokumenten O Theme Factory é um skill para Agentes IA que fornece 10 temas pré-definidos com paletas de cores hex e combinações de fontes. Permite aplicar estilos consistentes a slides, documentos e páginas HTML, ou gerar um novo tema sob demanda. Theme Factory — это навык для ИИ Агентов, предоставляющий 10 предустановленных тем с hex-палитрами и парными шрифтами. Позволяет применять единообразные стили к слайдам, документам и HTML-страницам или генерировать новую тему на лету. Theme Factory هو مهارة لأدوات الذكاء الاصطناعي تقدم 10 سمات محددة مسبقًا تحتوي على لوحات ألوان hex وتركيبات خطوط. تتيح تطبيق أنماط متسقة على الشرائح والمستندات وصفحات HTML، أو إنشاء سمة جديدة ديناميكيًا. how to use theme-factory what is theme-factory theme-factory vs manual styling theme-factory alternative theme-factory install guide theme-factory setup for AI agents apply themes to slides and docs AI agent color palette generator theme-factory AI代理 幻灯片主题应用 HTML落地页样式 调色板十六进制代码 字体配对最佳实践 动态主题生成 AI工具样式一致性 文档主题设置 Provides 10 pre-set themes with curated color palettes (hex codes) Includes complementary font pairings for headers and body text Applies themes to artifacts like slides, docs, reports, and HTML landing pages Generates new color and font themes dynamically on-the-fly Creates a distinct visual identity for different types of content theme-factory is an AI agent skill that provides a toolkit for styling artifacts with a theme. It offers 10 pre-set themes with curated color palettes (hex codes) and complementary font pairings, or can generate a new theme on-the-fly for slides, docs, and reports.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/market-research', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'market-research', 61988, 7678, 76, '2026-03-06T03:39:20Z', '2026-03-06T04:21:39.633Z', '7ef3fa13d6272fd295eeb2aca9f6a2f09f6a8270cf33b0675fc5a0018cf6e406', '{"id":"affaan-m/everything-claude-code/market-research","name":"market-research","description":{"en":"The market-research skill enables AI agents like Claude to perform rigorous market analysis, competitive intelligence, and investor due diligence. It provides developers and product teams with source-attributed research to inform critical business and technical decisions.","zh":"market-research是一款基于Anthropic Claude的AI代理技能，专为技术决策提供市场研究支持。通过MCP协议集成到开发环境，能够执行技术扫描、竞争对手分析和市场规模估算，所有结论均附带来源标注。","ja":"market-researchはAnthropic ClaudeベースのAIエージェントスキルで、技術的意思決定のための市場調査をサポート。MCPプロトコルで開発環境に統合され、技術スキャン、競合分析、市場規模推定を実行。","ko":"market-research는 Anthropic Claude 기반 AI 에이전트 스킬로, 기술 의사 결정을 위한 시장 조사를 지원. MCP 프로토콜로 개발 환경에 통합되어 기술 스캔, 경쟁사 분석, 시장 규모 추정을 실행.","es":"La skill market-research para AI Agents como Claude automatiza la inteligencia de mercado técnica. Proporciona análisis competitivo, sizing de mercado y due diligence de inversores con atribución de fuentes y datos recientes para decisiones de negocio informadas.","fr":"La skill market-research pour outils IA comme Claude automatise la veille technologique et marché. Fournit des analyses concurrentielles, sizing de marché et due diligence d''investisseurs avec attribution des sources et données récentes pour décisions business éclairées.","de":"Die market-research Skill für KI-Agenten wie Claude automatisiert die technische Markt- und Wettbewerbsanalyse. Liefert Wettbewerbsvergleiche, Marktgrößen-Schätzung und Investor Due Diligence mit Quellenangabe und aktuellen Daten für fundierte Geschäftsentscheidungen.","pt":"Uma skill de MCP para desenvolvedores que integram o Claude Code em aplicações. Executa pesquisa de mercado decisória com fontes atribuídas, comparações de concorrentes e estimativas TAM/SAM/SOM, focando em dados para decisões de negócio.","ru":"Навык MCP для разработчиков, интегрирующих Claude Code в приложения. Выполняет decisório исследование рынка с указанием источников, сравнением конкурентов и расчетами TAM/SAM/SOM, ориентируясь на данные для бизнес-решений.","ar":"مهارة MCP للمطورين الذين يدمجون Claude Code في التطبيقات. تنفذ أبحاث سوق قائمة على القرار مع الإسناد إلى المصادر ومقارنات المنافسين وتقديرات TAM/SAM/SOM، مع التركيز على البيانات لاتخاذ القرارات التجارية."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"market-research","description":"Conduct market research, competitive analysis, investor due diligence, and industry intelligence with source attribution and decision-oriented summaries. Use when the user wants market sizing, competitor comparisons, fund research, technology scans, or research that informs business decisions.","bodyPreview":"# Market Research\n\nProduce research that supports decisions, not research theater.\n\n## When to Activate\n\n- researching a market, category, company, investor, or technology trend\n- building TAM/SAM/SOM estimates\n- comparing competitors or adjacent products\n- preparing investor dossiers before outreach\n- pressure-testing a thesis before building, funding, or entering a market\n\n## Research Standards\n\n1. Every important claim needs a source.\n2. Prefer recent data and call out stale data.\n3. Include","body":"# Market Research\n\nProduce research that supports decisions, not research theater.\n\n## When to Activate\n\n- researching a market, category, company, investor, or technology trend\n- building TAM/SAM/SOM estimates\n- comparing competitors or adjacent products\n- preparing investor dossiers before outreach\n- pressure-testing a thesis before building, funding, or entering a market\n\n## Research Standards\n\n1. Every important claim needs a source.\n2. Prefer recent data and call out stale data.\n3. Include contrarian evidence and downside cases.\n4. Translate findings into a decision, not just a summary.\n5. Separate fact, inference, and recommendation clearly.\n\n## Common Research Modes\n\n### Investor / Fund Diligence\nCollect:\n- fund size, stage, and typical check size\n- relevant portfolio companies\n- public thesis and recent activity\n- reasons the fund is or is not a fit\n- any obvious red flags or mismatches\n\n### Competitive Analysis\nCollect:\n- product reality, not marketing copy\n- funding and investor history if public\n- traction metrics if public\n- distribution and pricing clues\n- strengths, weaknesses, and positioning gaps\n\n### Market Sizing\nUse:\n- top-down estimates from reports or public datasets\n- bottom-up sanity checks from realistic customer acquisition assumptions\n- explicit assumptions for every leap in logic\n\n### Technology / Vendor Research\nCollect:\n- how it works\n- trade-offs and adoption signals\n- integration complexity\n- lock-in, security, compliance, and operational risk\n\n## Output Format\n\nDefault structure:\n1. executive summary\n2. key findings\n3. implications\n4. risks and caveats\n5. recommendation\n6. sources\n\n## Quality Gate\n\nBefore delivering:\n- all numbers are sourced or labeled as estimates\n- old data is flagged\n- the recommendation follows from the evidence\n- risks and counterarguments are included\n- the output makes a decision easier\n"},"category":"official","lastSynced":"2026-03-06T04:21:39.633Z","seo":{"title":{"en":"market-research: AI-Powered Due Diligence & TAM Analysis ...","zh":"market-research AI代理设置指南：技术市场分析与竞争情报","ja":"market-research AIエージェント実践ガイド：技術調査と競合分析","ko":"market-research AI 에이전트 설정 가이드: 기술 시장 분석 및 경쟁 정보","es":"Market-Research Skill: Guía de Análisis Competitivo para ...","fr":"Market-Research Skill: Guide de Veille Technologique pour...","de":"Market-Research Skill: Leitfaden für Wettbewerbsanalyse m...","pt":"Market-Research Skill: Guia de Configuração para Análise ...","ru":"Market-Research Skill: Руководство по настройке для анали...","ar":"Market-Research Skill: دليل الإعداد لتحليل السوق"},"description":{"en":"Stop research theater. Use this MCP skill for Claude to conduct market research with source attribution, competitor comparisons, and TAM/SAM/SOM estimates. I...","zh":"专为开发者设计的market-research AI代理技能，通过Claude Code和MCP协议实现技术市场扫描、竞争对手比较和TAM/SAM/SOM估算。提供来源标注的决策支持报告，避免研究浪费。","ja":"開発者向けmarket-research AIエージェントスキル。Claude CodeとMCPプロトコルで技術トレンド調査、競合比較、TAM/SAM/SOM推定を実現。ソース付きの意思決定支援レポートを生成。","ko":"개발자를 위한 market-research AI 에이전트 스킬. Claude Code와 MCP 프로토콜로 기술 트렌드 스캔, 경쟁사 비교, TAM/SAM/SOM 추정 구현. 출처가 명시된 의사 결정 지원 보고서 생성.","es":"Automatiza la investigación de mercado con la skill MCP market-research para Claude. Genera análisis de competidores, TAM/SAM/SOM con atribución de fuentes y...","fr":"Automatisez l''étude de marché avec la skill MCP market-research pour Claude. Générez des analyses concurrentielles, TAM/SAM/SOM avec attribution des sources ...","de":"Automatisieren Sie Marktforschung mit der MCP-Skill market-research für Claude. Generieren Sie Wettbewerbsanalysen, TAM/SAM/SOM mit Quellenangabe und entsche...","pt":"Configure a skill market-research para MCP com Claude. Automatize pesquisa de mercado, análise competitiva com atribuição de fontes, TAM/SAM/SOM e due dilige...","ru":"Настройте навык market-research для MCP с Claude. Автоматизируйте исследование рынка, конкурентный анализ с указанием источников, TAM/SAM/SOM и Due Diligence...","ar":"قم بإعداد مهارة market-research لـ MCP مع Claude. أتمتة أبحاث السوق والتحليل التنافسي مع الإسناد للمصادر وحسابات TAM/SAM/SOM و Due Diligence للمستثمرين. تجنب..."},"definition":{"en":"market-research is an AI Agent skill for MCP servers that conducts market sizing, competitor comparisons, and investor due diligence. It produces decision-oriented summaries with source attribution, adhering to standards that prioritize recent data and call out stale information.","zh":"market-research是基于Claude Code和MCP协议的AI代理技能，专门为开发者提供技术市场研究功能。它能够执行竞争对手比较、技术趋势扫描、市场规模估算（TAM/SAM/SOM），并生成带有来源标注的决策导向报告，避免无意义的研究展示。","ja":"market-researchはClaude CodeとMCPプロトコルに基づくAIエージェントスキルで、開発者向けに技術市場調査機能を提供。競合比較、技術トレンドスキャン、市場規模推定（TAM/SAM/SOM）を実行し、ソース付きの意思決定指向レポートを生成。","ko":"market-research는 Claude Code와 MCP 프로토콜 기반 AI 에이전트 스킬로, 개발자를 위한 기술 시장 조사 기능을 제공. 경쟁사 비교, 기술 트렌드 스캔, 시장 규모 추정(TAM/SAM/SOM)을 실행하고 출처가 명시된 의사 결정 지향 보고서를 생성.","es":"Market-research es una skill MCP para AI Agents que realiza investigación de mercado automatizada con atribución de fuentes. Genera análisis competitivo, estimaciones TAM/SAM/SOM y resúmenes para due diligence, priorizando datos recientes sobre research theater.","fr":"Market-research est une skill MCP pour outils IA qui effectue de la recherche de marché automatisée avec attribution des sources. Génère des analyses concurrentielles, estimations TAM/SAM/SOM et synthèses pour due diligence, privilégiant les données récentes au research theater.","de":"Market-research ist eine MCP-Skill für KI-Agenten, die automatisierte Marktforschung mit Quellenangabe durchführt. Erstellt Wettbewerbsanalysen, TAM/SAM/SOM-Schätzungen und Due-Diligence-Zusammenfassungen, wobei aktuelle Daten vor Research Theater priorisiert werden.","pt":"A skill ''market-research'' é um componente técnico para Model Context Protocol (MCP) que permite ao Claude acessar ferramentas e realizar pesquisas de mercado automatizadas com atribuição de fontes, análise competitiva e due diligence para investidores.","ru":"Навык ''market-research'' — это технический компонент для Model Context Protocol (MCP), который позволяет Claude получать доступ к инструментам и выполнять автоматизированные исследования рынка с указанием источников, конкурентным анализом и Due Diligence для инвесторов.","ar":"مهارة ''market-research'' هي مكون تقني لـ Model Context Protocol (MCP) تتيح لـ Claude الوصول إلى الأدوات وإجراء أبحاث السوق الآلية مع الإسناد إلى المصادر والتحليل التنافسي و Due Diligence للمستثمرين."},"features":{"en":["Generates TAM/SAM/SOM market sizing estimates for business planning","Performs competitive analysis and adjacent product comparisons","Builds investor dossiers for outreach preparation","Pressure-tests business theses before market entry","Attributes every important claim to a verifiable source","Flags stale data and prioritizes recent information in reports"],"zh":["基于MCP协议与开发工具链集成","执行TAM/SAM/SOM市场规模估算","竞争对手产品对比分析功能","技术趋势扫描与行业情报收集","所有重要声明均提供来源标注","生成决策导向型研究报告而非研究展示"],"ja":["MCPプロトコルによる開発ツールチェーン統合","TAM/SAM/SOM市場規模推定の実行","競合製品比較分析機能","技術トレンドスキャンと業界情報収集","重要な主張すべてにソース明記","研究展示ではなく意思決定指向のレポート生成"],"ko":["MCP 프로토콜 기반 개발 도구 체인 통합","TAM/SAM/SOM 시장 규모 추정 실행","경쟁사 제품 비교 분석 기능","기술 트렌드 스캔 및 업계 정보 수집","모든 중요한 주장에 출처 명시","연구 전시가 아닌 의사 결정 지향 보고서 생성"],"es":["Atribución de fuentes para cada afirmación importante en los informes","Generación de estimaciones TAM/SAM/SOM para análisis de mercado","Análisis comparativo de competidores y productos adyacentes","Preparación automatizada de dossiers para outreach de inversores","Detección y marcado de datos obsoletos en la investigación","Pressure-testing de tesis antes de lanzar productos o mercados"],"fr":["Attribution des sources pour chaque affirmation importante dans les rapports","Génération d''estimations TAM/SAM/SOM pour l''analyse de marché","Analyse comparative des concurrents et produits adjacents","Préparation automatisée de dossiers pour démarchage d''investisseurs","Détection et signalement des données obsolètes dans la recherche","Pressure-testing des thèses avant le lancement de produits ou marchés"],"de":["Quellenangabe für jede wichtige Behauptung in Berichten","Generierung von TAM/SAM/SOM-Schätzungen für Marktanalysen","Vergleichende Analyse von Wettbewerbern und adjacent products","Automatisierte Vorbereitung von Investor Dossiers für Outreach","Erkennung und Kennzeichnung veralteter Daten in der Forschung","Pressure-Testing von Thesen vor Produkt- oder Markteintritt"],"pt":["Atribuição de fontes para todas as afirmações importantes","Geração de estimativas TAM/SAM/SOM para tamanho de mercado","Análise comparativa de concorrentes e produtos adjacentes","Preparação de dossiês para due diligence de investidores","Pressão-testada de teses antes de construir ou entrar em um mercado","Preferência por dados recentes com alertas para informações desatualizadas"],"ru":["Указание источников для всех важных утверждений","Генерация оценок TAM/SAM/SOM для размера рынка","Сравнительный анализ конкурентов и смежных продуктов","Подготовка досье для Due Diligence инвесторов","Проверка тезисов перед созданием продукта или выходом на рынок","Предпочтение актуальным данным с указанием на устаревшую информацию"],"ar":["الإسناد إلى المصادر لجميع الادعاءات المهمة","إنشاء تقديرات TAM/SAM/SOM لحجم السوق","تحليل مقارن للمنافسين والمنتجات المجاورة","إعداد ملفات لـ Due Diligence للمستثمرين","اختبار الفرضيات قبل البناء أو الدخول إلى السوق","تفضيل البيانات الحديثة مع الإشارة إلى المعلومات القديمة"]},"keywords":{"en":["market-research MCP skill","how to use market-research for TAM analysis","market-research vs traditional research","install market-research for Claude","market-research competitive analysis","what is market-research AI agent","market-research setup guide","investor due diligence AI skill","Anthropic Claude market research"],"zh":["market-research AI代理","Claude Code市场分析","MCP协议技术研究","TAM SAM SOM估算","竞争对手分析工具","开发者市场情报","AI代理设置教程","技术决策支持"],"ja":["market-research AIエージェント","Claude Code市場分析","MCPプロトコル技術調査","TAM SAM SOM推定","競合分析ツール","開発者向け市場情報","AIエージェント設定チュートリアル","技術的意思決定支援"],"ko":["market-research AI 에이전트","Claude Code 시장 분석","MCP 프로토콜 기술 조사","TAM SAM SOM 추정","경쟁사 분석 도구","개발자 시장 정보","AI 에이전트 설정 튜토리얼","기술 의사 결정 지원"],"es":["market-research skill MCP","análisis competitivo AI agents","TAM SAM SOM estimación","due diligence inversores automatizado","atribución fuentes investigación mercado","claude-code market research","automated competitive analysis","MCP server setup research"],"fr":["market-research skill MCP","analyse concurrentielle outils IA","TAM SAM SOM estimation","due diligence investisseurs automatisé","attribution sources étude marché","claude-code recherche marché","veille technologique automatisée","configurer MCP server recherche"],"de":["market-research Skill MCP","Wettbewerbsanalyse KI-Agenten","TAM SAM SOM Schätzung","Investor Due Diligence automatisiert","Quellenangabe Marktforschung","claude-code Marktanalyse","automatisierte Competitive Analysis","MCP Server Setup Forschung"],"pt":["skill market research MCP","claude code análise competitiva","TAM SAM SOM estimativa automática","due diligence investidor automatizado","ai agents pesquisa de mercado","anthropic claude developer tools","integração llm business intelligence","configurar market research skill"],"ru":["навык market research MCP","claude code конкурентный анализ","TAM SAM SOM автоматический расчет","Due Diligence инвестора автоматизация","ИИ агенты исследование рынка","anthropic claude инструменты разработчика","интеграция LLM бизнес-аналитика","настроить навык market research"],"ar":["مهارة market research MCP","claude code تحليل تنافسي","TAM SAM SOM تقدير تلقائي","Due Diligence مستثمر آلي","عوامل الذكاء الاصطناعي أبحاث السوق","anthropic claude أدوات المطور","دمج LLM ذكاء الأعمال","إعداد مهارة market research"]}},"agentAnalysis":{"suitability":{"en":"Essential for Business Intelligence Agents conducting data-driven market analysis with source attribution.","zh":"对于使用数据驱动并附带来源归因的市场分析进行商业智能分析的AI代理而言，这是必不可少的技能。","ja":"ソースの帰属を伴うデータ駆動型の市場分析を実施するビジネスインテリジェンスエージェントにとって必須です。","ko":"소스 귀속이 포함된 데이터 기반 시장 분석을 수행하는 비즈니스 인텔리전스 에이전트에게 필수적인 기술입니다.","es":"Esencial para los agentes de inteligencia empresarial que realizan análisis de mercado basados en datos con atribución de fuente.","fr":"Essentiel pour les agents d''intelligence commerciale effectuant des analyses de marché axées sur les données avec attribution de source.","de":"Wesentlich für Business-Intelligence-Agents, die datengetriebene Marktanalyse mit Quellenangabe durchführen.","pt":"Essencial para Agentes de Business Intelligence que realizam análises de mercado orientadas por dados com atribuição de fonte.","ru":"Необходимо для агентов Business Intelligence, проводящих анализ рынка на основе данных с указанием источников.","ar":"ضروري لعملاء ذكاء الأعمال الذين يقومون بإجراء تحليل للسوق قائم على البيانات مع الإسناد إلى المصدر."},"recommendation":{"en":"Conducts comprehensive market research, competitive analysis, and investor due diligence with rigorous source attribution. Delivers decision-oriented summaries for TAM/SAM/SOM estimates, technology scans, and investor dossiers.","zh":"凭借严谨的来源归因，执行全面的市场研究、竞争分析和投资者尽职调查。为TAM/SAM/SOM估算、技术扫描和投资者档案提供决策导向的摘要。","ja":"厳格なソースの帰属に基づき、包括的な市場調査、競合分析、投資家のデューデリジェンスを実施します。TAM/SAM/SOMの推定、技術スキャン、投資家ダッシエのための意思決定指向の要約を提供します。","ko":"엄격한 소스 귀속을 통해 포괄적인 시장 조사, 경쟁 분석 및 투자자 실사 조사를 수행합니다. TAM/SAM/SOM 추정, 기술 스캔 및 투자자 서류를 위한 의사 결정 지향적 요약을 제공합니다.","es":"Realiza investigaciones de mercado integrales, análisis competitivos y debida diligencia para inversores con estricta atribución de fuente. Proporciona resúmenes orientados a la toma de decisiones para estimaciones de TAM/SAM/SOM, análisis tecnológicos y informes de inversores.","fr":"Effectue des recherches de marché complètes, des analyses compétitives et une diligence raisonnable pour les investisseurs avec une attribution de source rigoureuse. Fournit des résumés orientés vers la décision pour les estimations de TAM/SAM/SOM, les analyses technologiques et les dossiers d''investisseurs.","de":"Führt umfassende Marktforschung, Wettbewerbsanalyse und Due-Diligence-Prüfungen für Investoren mit strenger Quellenangabe durch. Liefern entscheidungsorientierte Zusammenfassungen für TAM/SAM/SOM-Schätzungen, Technologie-Scans und Investor-Dossiers.","pt":"Realiza pesquisas de mercado abrangentes, análises competitivas e due diligence de investidores com rigorosa atribuição de fonte. Entrega resumos orientados para decisão para estimativas TAM/SAM/SOM, scans de tecnologia e dossiês de investidores.","ru":"Проводит комплексное исследование рынка, конкурентный анализ и Due Diligence инвесторов с тщательным указанием источников. Предоставляет ориентированные на принятие решений сводки для оценок TAM/SAM/SOM, анализа технологий и досье инвесторов.","ar":"يجري أبحاثًا شاملة للسوق، وتحليلات تنافسية، وفحص العناية الواجبة للمستثمرين مع الإسناد الدقيق للمصدر. يقدم ملخصات موجهة نحو القرار لتقديرات TAM/SAM/SOM ومسح التقنيات وملفات المستثمرين."},"useCases":{"en":["Building market sizing estimates (TAM/SAM/SOM)","Performing competitive analysis with source attribution","Preparing investor due diligence reports","Pressure-testing business theses with recent data"],"zh":["构建市场规模估算（TAM/SAM/SOM）","执行附带来源归因的竞争分析","准备投资者尽职调查报告","使用最新数据对商业论点进行压力测试"],"ja":["市場規模の推定（TAM/SAM/SOM）の構築","ソース帰属を伴う競合分析の実行","投資家のためのデューデリジェンスレポートの作成","最新データを用いたビジネス仮説のプレッシャーテスト"],"ko":["시장 규모 추정치 (TAM/SAM/SOM) 구축","소스 귀속이 포함된 경쟁 분석 수행","투자자 실사 보고서 준비","최신 데이터를 사용한 비즈니스 가설 압력 테스트"],"es":["Creación de estimaciones de tamaño de mercado (TAM/SAM/SOM)","Realización de análisis competitivos con atribución de fuente","Preparación de informes de debida diligencia para inversores","Prueba de resistencia de las tesis empresariales con datos recientes"],"fr":["Établissement d''estimations de taille de marché (TAM/SAM/SOM)","Réalisations d''analyses compétitives avec attribution de source","Préparation de rapports de diligence raisonnable pour les investisseurs","Test de résistance des thèses commerciales avec des données récentes"],"de":["Erstellung von Marktgroßenschätzungen (TAM/SAM/SOM)","Durchführung von Wettbewerbsanalysen mit Quellenangabe","Vorbereitung von Due-Diligence-Berichten für Investoren","Belastbarkeitstest von Geschäftsthesen mit aktuellen Daten"],"pt":["Construindo estimativas de dimensionamento de mercado (TAM/SAM/SOM)","Realizando análise competitiva com atribuição de fonte","Preparando relatórios de due diligence para investidores","Testando teses de negócios sob pressão com dados recentes"],"ru":["Построение оценок размера рынка (TAM/SAM/SOM)","Проведение конкурентного анализа с указанием источников","Подготовка отчетов Due Diligence для инвесторов","Проверка бизнес-гипотез на прочность с использованием актуальных данных"],"ar":["بناء تقديرات لحجم السوق (TAM/SAM/SOM)","إجراء تحليل تنافسي مع الإسناد إلى المصدر","إعداد تقارير العناية الواجبة للمستثمرين","اختبار فرضيات العمل تحت الضغط باستخدام البيانات الحديثة"]},"limitations":{"en":["Requires access to current market data sources","Depends on availability of recent public data","Limited to publicly available information"],"zh":["需要访问当前的市场数据源","依赖于近期公开数据的可用性","仅限于公开可用信息"],"ja":["現在の市場データソースへのアクセスが必要","最近の公開データの可用性に依存","公開されている情報に限定される"],"ko":["현재 시장 데이터 소스에 대한 액세스 필요","최근 공개 데이터의 가용성에 의존","공개적으로 이용 가능한 정보로 제한됨"],"es":["Requiere acceso a fuentes de datos de mercado actuales","Depende de la disponibilidad de datos públicos recientes","Limitado a información pública disponible"],"fr":["Nécessite l''accès à des sources de données de marché actuelles","Dépend de la disponibilité de données publiques récentes","Limité à l''information publique disponible"],"de":["Erfordert Zugriff auf aktuelle Marktdatenquellen","Hängt von der Verfügbarkeit von aktuellen öffentlichen Daten ab","Begrenzt auf öffentlich verfügbare Informationen"],"pt":["Requer acesso a fontes de dados de mercado atuais","Depende da disponibilidade de dados públicos recentes","Limitado a informações publicamente disponíveis"],"ru":["Требует доступа к текущим источникам рыночных данных","Зависит от доступности недавних публичных данных","Ограничено общедоступной информацией"],"ar":["يتطلب الوصول إلى مصادر بيانات السوق الحالية","يعتمد على توافر بيانات عامة حديثة","مقتصر على المعلومات المتاحة للعموم"]},"version":4},"contentHash":"7ef3fa13d6272fd295eeb2aca9f6a2f09f6a8270cf33b0675fc5a0018cf6e406","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":76}');
