INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affaan-m/everything-claude-code/market-research', 'market-research', 'affaan-m', 'everything-claude-code', 'official', 'market-research affaan-m everything-claude-code official ai-agents anthropic claude claude-code developer-tools llm mcp productivity The market-research skill enables AI agents like Claude to perform rigorous market analysis, competitive intelligence, and investor due diligence. It provides developers and product teams with source-attributed research to inform critical business and technical decisions. market-research是一款基于Anthropic Claude的AI代理技能，专为技术决策提供市场研究支持。通过MCP协议集成到开发环境，能够执行技术扫描、竞争对手分析和市场规模估算，所有结论均附带来源标注。 market-researchはAnthropic ClaudeベースのAIエージェントスキルで、技術的意思決定のための市場調査をサポート。MCPプロトコルで開発環境に統合され、技術スキャン、競合分析、市場規模推定を実行。 market-research는 Anthropic Claude 기반 AI 에이전트 스킬로, 기술 의사 결정을 위한 시장 조사를 지원. MCP 프로토콜로 개발 환경에 통합되어 기술 스캔, 경쟁사 분석, 시장 규모 추정을 실행. La skill market-research para AI Agents como Claude automatiza la inteligencia de mercado técnica. Proporciona análisis competitivo, sizing de mercado y due diligence de inversores con atribución de fuentes y datos recientes para decisiones de negocio informadas. La skill market-research pour outils IA comme Claude automatise la veille technologique et marché. Fournit des analyses concurrentielles, sizing de marché et due diligence d''investisseurs avec attribution des sources et données récentes pour décisions business éclairées. Die market-research Skill für KI-Agenten wie Claude automatisiert die technische Markt- und Wettbewerbsanalyse. Liefert Wettbewerbsvergleiche, Marktgrößen-Schätzung und Investor Due Diligence mit Quellenangabe und aktuellen Daten für fundierte Geschäftsentscheidungen. Uma skill de MCP para desenvolvedores que integram o Claude Code em aplicações. Executa pesquisa de mercado decisória com fontes atribuídas, comparações de concorrentes e estimativas TAM/SAM/SOM, focando em dados para decisões de negócio. Навык MCP для разработчиков, интегрирующих Claude Code в приложения. Выполняет decisório исследование рынка с указанием источников, сравнением конкурентов и расчетами TAM/SAM/SOM, ориентируясь на данные для бизнес-решений. مهارة MCP للمطورين الذين يدمجون Claude Code في التطبيقات. تنفذ أبحاث سوق قائمة على القرار مع الإسناد إلى المصادر ومقارنات المنافسين وتقديرات TAM/SAM/SOM، مع التركيز على البيانات لاتخاذ القرارات التجارية. market-research MCP skill how to use market-research for TAM analysis market-research vs traditional research install market-research for Claude market-research competitive analysis what is market-research AI agent market-research setup guide investor due diligence AI skill Anthropic Claude market research market-research AI代理 Claude Code市场分析 MCP协议技术研究 TAM SAM SOM估算 竞争对手分析工具 开发者市场情报 AI代理设置教程 技术决策支持 Generates TAM/SAM/SOM market sizing estimates for business planning Performs competitive analysis and adjacent product comparisons Builds investor dossiers for outreach preparation Pressure-tests business theses before market entry Attributes every important claim to a verifiable source Flags stale data and prioritizes recent information in reports market-research is an AI Agent skill for MCP servers that conducts market sizing, competitor comparisons, and investor due diligence. It produces decision-oriented summaries with source attribution, adhering to standards that prioritize recent data and call out stale information.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('callstackincubator/agent-skills/github', 'official', 'callstackincubator', 'agent-skills', 'callstackincubator/agent-skills', 'github', 969, 57, 76, '2026-03-06T00:34:35Z', '2026-03-06T04:51:02.369Z', 'fdeaac730749855c597817941dcebe6c9811c667a364e70cbb211533374d3bad', '{"id":"callstackincubator/agent-skills/github","name":"github","description":{"en":"This skill provides GitHub patterns using gh CLI for pull requests, stacked PRs, and repository automation, benefiting developers and repository managers.","zh":"本文介绍如何使用 gh CLI 进行 GitHub 仓库管理，包括拉取请求、代码审查和分支策略","ja":"この記事では、gh CLI を使用した GitHub リポジトリ管理、プルリクエスト、コードレビュー、ブランチ戦略について説明します","ko":"본 문서에서는 gh CLI를 사용하여 GitHub 리포지토리를 관리하는 방법을 소개합니다","es":"Utilice gh CLI para operaciones de GitHub, como crear solicitudes de extracción y revisar código","fr":"Utilisez gh CLI pour les opérations GitHub, telles que la création de demandes d''extraction et la révision de code","de":"Verwenden Sie gh CLI für GitHub-Operationen, wie das Erstellen von Pull-Requests und die Überprüfung von Code","pt":"O GitHub com gh CLI oferece padrões para criar, mesclar e gerenciar pull requests de forma eficiente","ru":"ИИ Агенты и gh CLI помогают автоматизировать процессы GitHub, включая создание и слияние pull запросов","ar":"استخدم غه CLI وأدوات الذكاء الاصطناعي لتحسين إدارة المستودعات وطلبات السحب على GitHub"},"owner":"callstackincubator","repo":"agent-skills","repoPath":"callstackincubator/agent-skills","stars":969,"forks":57,"updatedAt":"2026-03-06T00:34:35Z","topics":[],"skillMd":{"name":"github","description":"GitHub patterns using gh CLI for pull requests, stacked PRs, code review, branching strategies, and repository automation. Use when working with GitHub PRs, merging strategies, or repository management tasks.","tags":"github, gh-cli, pull-request, stacked-pr, squash, rebase","bodyPreview":"# GitHub Patterns\n\n## Tools\n\nUse `gh` CLI for all GitHub operations. Prefer CLI over GitHub MCP servers for lower context usage.\n\n## Quick Commands\n\n```bash\n# Create a PR from the current branch\ngh pr create --title \"feat: add feature\" --body \"Description\"\n\n# Squash-merge a PR\ngh pr merge <PR_NUMBER> --squash --title \"feat: add feature (#<PR_NUMBER>)\"\n\n# View PR status and checks\ngh pr status\ngh pr checks <PR_NUMBER>\n```\n\n## Stacked PR Workflow Summary\n\nWhen merging a chain of stacked PRs (each","body":"# GitHub Patterns\n\n## Tools\n\nUse `gh` CLI for all GitHub operations. Prefer CLI over GitHub MCP servers for lower context usage.\n\n## Quick Commands\n\n```bash\n# Create a PR from the current branch\ngh pr create --title \"feat: add feature\" --body \"Description\"\n\n# Squash-merge a PR\ngh pr merge <PR_NUMBER> --squash --title \"feat: add feature (#<PR_NUMBER>)\"\n\n# View PR status and checks\ngh pr status\ngh pr checks <PR_NUMBER>\n```\n\n## Stacked PR Workflow Summary\n\nWhen merging a chain of stacked PRs (each targeting the previous branch):\n\n1. **Merge the first PR** into main via squash merge\n2. **For each subsequent PR**: rebase onto main, update base to main, then squash merge\n3. **On conflicts**: stop and ask the user to resolve manually\n\n```bash\n# Rebase next PR''s branch onto main, excluding already-merged commits\ngit rebase --onto origin/main <old-base-branch> <next-branch>\ngit push --force-with-lease origin <next-branch>\ngh pr edit <N> --base main\ngh pr merge <N> --squash --title \"<PR title> (#N)\"\n```\n\nSee [stacked-pr-workflow.md][stacked-pr-workflow] for full step-by-step details.\n\n## Quick Reference\n\n| File | Description |\n| --- | --- |\n| [stacked-pr-workflow.md][stacked-pr-workflow] | Merge stacked PRs into main as individual squash commits |\n\n## Problem -> Skill Mapping\n\n| Problem | Start With |\n| --- | --- |\n| Merge stacked PRs cleanly | [stacked-pr-workflow.md][stacked-pr-workflow] |\n\n[stacked-pr-workflow]: references/stacked-pr-workflow.md\n"},"category":"official","lastSynced":"2026-03-06T04:51:02.369Z","seo":{"title":{"en":"Github: Automation and Management Setup Guide | AI Agent ...","zh":"GitHub Setup Guide: 使用 gh CLI 进行仓库管理","ja":"GitHub ベストプラクティス: gh CLI を使用したリポジトリ管理","ko":"GitHub 자동화 가이드: gh CLI를 사용한 리포지토리 관리","es":"Guía de configuración de GitHub con gh CLI","fr":"Guide de configuration GitHub avec gh CLI","de":"GitHub-Setup-Leitfaden mit gh CLI","pt":"Guia de Configuração do GitHub com gh CLI","ru":"Настройка GitHub с помощью ИИ Агентов и gh CLI","ar":"دليل إعداد GitHub باستخدام غه CLI وأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient GitHub workflows with AI agent skills, learn to automate PRs, code reviews, and repository management with gh CLI commands","zh":"了解如何使用 gh CLI 进行 GitHub 仓库管理，包括拉取请求、代码审查和分支策略","ja":"GitHub リポジトリ管理を効率化するために、gh CLI を使用する方法を学びましょう","ko":"gh CLI를 사용하여 GitHub 리포지토리를 관리하는 방법에 대해 알아보세요","es":"Aprende a utilizar gh CLI para operaciones de GitHub, incluyendo solicitudes de extracción, revisión de código y automatización de repositorios","fr":"Découvrez comment utiliser gh CLI pour les opérations GitHub, y compris les demandes d''extraction, la révision de code et l''automatisation des référentiels","de":"Erfahren Sie, wie Sie gh CLI für GitHub-Operationen verwenden, einschließlich Pull-Requests, Code-Review und Repository-Automatisierung","pt":"Aprenda a usar o gh CLI para criar, mesclar e gerenciar pull requests no GitHub de forma eficiente","ru":"Используйте ИИ Агенты и gh CLI для автоматизации процессов GitHub, включая создание и слияние pull запросов","ar":"استخدم غه CLI وأدوات الذكاء الاصطناعي لتحسين إدارة المستودعات وطلبات السحب على GitHub"},"definition":{"en":"github is a version control system utilizing gh CLI for efficient repository management and automation","zh":"GitHub 仓库管理是使用 gh CLI 进行拉取请求、代码审查和分支策略的过程","ja":"GitHub リポジトリ管理は、gh CLI を使用してプルリクエスト、コードレビュー、ブランチ戦略を行うプロセスです","ko":"GitHub 리포지토리 관리는 gh CLI를 사용하여 プルリクエスト、コード 리뷰 및 브랜치 전략을 수행하는 과정입니다","es":"GitHub es una plataforma de desarrollo colaborativo que utiliza gh CLI para automatizar tareas","fr":"GitHub est une plateforme de développement collaboratif qui utilise gh CLI pour automatiser les tâches","de":"GitHub ist eine Plattform für kollaborative Entwicklung, die gh CLI zur Automatisierung von Aufgaben verwendet","pt":"O que é GitHub com gh CLI? É uma forma de automatizar tarefas no GitHub usando o CLI","ru":"Что такое ИИ Агенты и GitHub? Это инструменты для автоматизации процессов GitHub с помощью ИИ","ar":"ما هو GitHub مع غه CLI? هو وسيلة لتحسين إدارة المستودعات على GitHub باستخدام سطر الأوامر"},"features":{"en":["Creates pull requests using `gh pr create` command","Supports squash-merging PRs with `gh pr merge`","Enables PR status and checks with `gh pr status` and `gh pr checks`","Facilitates stacked PR workflow management","Utilizes gh CLI for lower context usage over GitHub MCP servers"],"zh":["使用 gh CLI 创建拉取请求","使用 gh CLI 进行代码审查","使用 gh CLI 实现分支策略","使用 gh CLI 进行仓库自动化","支持 stacked PR 工作流","支持 squash-merge 和 rebase 操作"],"ja":["gh CLI を使用してプルリクエストを作成","gh CLI を使用してコードレビューを行う","gh CLI を使用してブランチ戦略を実施","gh CLI を使用してリポジトリの自動化を行う","スタックされた PR ワークフローをサポート","スQUENCY マージとリベース操作をサポート"],"ko":["gh CLI를 사용하여 プルリクエスト를 생성","gh CLI를 사용하여 코드 리뷰를 수행","gh CLI를 사용하여 브랜치 전략을 구현","gh CLI를 사용하여 리포지토리 자동화를 수행","스택된 PR 워크플로우를 지원","스퀘시 머지와 리베이스 작업을 지원"],"es":["Crear solicitudes de extracción con gh pr create","Revisar código con gh pr checks","Automatizar repositorios con gh CLI","Utilizar estrategias de ramificación para gestionar cambios","Realizar merge de solicitudes de extracción con gh pr merge"],"fr":["Créer des demandes d''extraction avec gh pr create","Réviser le code avec gh pr checks","Automatiser les référentiels avec gh CLI","Utiliser des stratégies de branchement pour gérer les modifications","Réalisé le merge des demandes d''extraction avec gh pr merge"],"de":["Erstellen von Pull-Requests mit gh pr create","Überprüfen von Code mit gh pr checks","Automatisieren von Repositorys mit gh CLI","Verwenden von Branching-Strategien für Änderungsmanagement","Durchführen von Merge von Pull-Requests mit gh pr merge"],"pt":["Criação de pull requests com `gh pr create`","Mesclagem de pull requests com `gh pr merge`","Gerenciamento de branches com `gh branch`","Automatização de tarefas com `gh` CLI","Análise de status de pull requests com `gh pr status`"],"ru":["Создание pull запросов с помощью `gh pr create`","Слияние pull запросов с помощью `gh pr merge`","Управление ветками с помощью `gh branch`","Автоматизация задач с помощью `gh` CLI","Анализ статуса pull запросов с помощью `gh pr status`"],"ar":["إنشاء طلبات السحب باستخدام `gh pr create`","دمج طلبات السحب باستخدام `gh pr merge`","إدارة الفروع باستخدام `gh branch`","تحسين إدارة المستودعات باستخدام `gh` CLI","تحليل حالة طلبات السحب باستخدام `gh pr status`"]},"keywords":{"en":["github automation","gh cli commands","github pull request management","github vs gitlab","how to use github","github setup guide","github repository management","github alternative","github install"],"zh":["GitHub 仓库管理","gh CLI","拉取请求","代码审查","分支策略","仓库自动化","AIエージェント","GitHub Setup","GitHub Best Practices"],"ja":["GitHub リポジトリ管理","gh CLI","プルリクエスト","コードレビュー","ブランチ戦略","リポジトリ自動化","AIエージェント","GitHub Setup","GitHub ベストプラクティス"],"ko":["GitHub 리포지토리 관리","gh CLI","プルリクエスト","コード 리뷰","브랜치 전략","리포지토리 자동화","AI 에이전트","GitHub Setup","GitHub ベストプラクティス"],"es":["github","gh cli","solicitudes de extracción","revisión de código","automatización de repositorios","estrategias de ramificación","merge de solicitudes de extracción","herramientas de desarrollo","desarrollo colaborativo"],"fr":["github","gh cli","demandes d''extraction","révision de code","automatisation des référentiels","stratégies de branchement","merge des demandes d''extraction","outils de développement","développement collaboratif"],"de":["github","gh cli","pull-requests","code-review","repository-automatisierung","branching-strategien","merge von pull-requests","entwicklertools","kollaborative entwicklung"],"pt":["github cli","gh cli","pull requests github","automatizar tarefas github","gerenciar branches github","análise de status github","criar pull requests github","mesclar pull requests github"],"ru":["github cli","gh cli","pull запросы github","автоматизация задач github","управление ветками github","анализ статуса github","создать pull запросы github","слияние pull запросов github"],"ar":["github cli","غه cli","طلبات السحب على github","تحسين إدارة المستودعات على github","إدارة الفروع على github","تحليل حالة طلبات السحب على github","إنشاء طلبات السحب على github","دمج طلبات السحب على github"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Development Agents leveraging GitHub for version control and collaboration, particularly those utilizing gh CLI for streamlined repository management.","zh":"适用于使用 GitHub 进行版本控制和协作的开发代理，特别是那些使用 gh CLI 进行流线化仓库管理的代理。","ja":"GitHub をバージョン管理とコラボレーションに利用する開発エージェントに最適であり、特に gh CLI を使用してリポジトリ管理をストリームライン化するものに適しています。","ko":"버전 관리 및 협업을 위해 GitHub를 사용하는 개발 에이전트에게 적합하며, 특히 gh CLI를 사용하여 저장소 관리를 간소화하는 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que utilizan GitHub para el control de versiones y la colaboración, particularmente aquellos que utilizan gh CLI para la gestión de repositorios optimizada.","fr":"Idéal pour les agents de développement qui utilisent GitHub pour le contrôle de version et la collaboration, en particulier ceux qui utilisent gh CLI pour la gestion de référentiels optimisée.","de":"Ideal für Entwicklungsmittel, die GitHub für die Versionskontrolle und Zusammenarbeit nutzen, insbesondere solche, die gh CLI für die optimierte Repository-Verwaltung verwenden.","pt":"Ideal para Agentes de Desenvolvimento que utilizam o GitHub para controle de versão e colaboração, particularmente aqueles que utilizam o gh CLI para gestão de repositório simplificada.","ru":"Идеально для агентов разработки, использующих GitHub для контроля версий и сотрудничества, особенно тех, кто использует gh CLI для упрощенного управления репозиторием.","ar":"مثالي للوكلاء التطويريين الذين يستخدمون GitHub للسيطرة على الإصدار والتعاون، خاصة أولئك الذين يستخدمون gh CLI لإدارة المستودع المبسطة."},"recommendation":{"en":"Empowers agents to automate GitHub workflows, including creating and managing pull requests, implementing branching strategies, and performing code reviews using the gh CLI, facilitating efficient repository automation and streamlined development processes.","zh":"赋予代理自动化 GitHub 工作流的能力，包括创建和管理拉取请求、实施分支策略以及使用 gh CLI 进行代码审查，从而实现高效的仓库自动化和流线化的开发过程。","ja":"エージェントに GitHub ワークフローを自動化する能力を付与し、プルリクエストの作成と管理、ブランチ戦略の実施、gh CLI を使用したコードレビューなどを実行し、効率的なリポジトリ自動化とストリームライン化された開発プロセスを促進します。","ko":"에이전트가 GitHub 워크플로를 자동화할 수 있도록 해주며, 이는 gh CLI를 사용하여 풀 리퀘스트 생성 및 관리, 브랜치 전략 구현 및 코드 리뷰 수행 등을 포함하며, 이로써 효율적인 저장소 자동화 및 가속화된 개발 프로세스를 가능하게 합니다.","es":"Permite a los agentes automatizar flujos de trabajo de GitHub, incluyendo la creación y gestión de solicitudes de incorporación, la implementación de estrategias de ramificación y la realización de revisiones de código mediante gh CLI, lo que facilita la automatización eficiente del repositorio y los procesos de desarrollo optimizados.","fr":"Permet aux agents d''automatiser les flux de travail GitHub, y compris la création et la gestion des demandes d''intégration, la mise en œuvre de stratégies de branchement et la réalisation d''examen de code à l''aide de gh CLI, ce qui facilite l''automatisation efficace du référentiel et les processus de développement optimisés.","de":"Ermöglicht es Agenten, GitHub-Workflows zu automatisieren, einschließlich der Erstellung und Verwaltung von Pull-Anfragen, der Implementierung von Verzweigungsstrategien und der Durchführung von Code-Reviews mithilfe von gh CLI, wodurch eine effiziente Repository-Automatisierung und optimierte Entwicklungsprozesse erleichtert werden.","pt":"Habilita os agentes a automatizar fluxos de trabalho do GitHub, incluindo a criação e gerenciamento de solicitações de pull, implementação de estratégias de ramificação e realização de revisões de código usando o gh CLI, facilitando a automação eficiente do repositório e processos de desenvolvimento simplificados.","ru":"Позволяет агентам автоматизировать рабочие процессы GitHub, включая создание и управление запросами на слияние, реализацию стратегий ветвления и выполнение проверок кода с помощью gh CLI, что облегчает эффективную автоматизацию репозитория и упрощенные процессы разработки.","ar":"تمكّن الوكلاء من تلقيم عمليات سير عمل GitHub، بما في ذلك إنشاء وإدارة طلبات الدمج، وتنفيذ استراتيجيات الفروع والقيام بمراجعة الشفرة باستخدام gh CLI، مما يسهل تلقيم المستودع الفعال وعمليات التطوير المبسطة."},"useCases":{"en":["Automating pull request creation and merging using gh pr create and gh pr merge","Streamlining code review processes with gh pr checks and gh pr status","Implementing efficient branching strategies for collaborative development projects"],"zh":["使用 gh pr create 和 gh pr merge 自动化拉取请求创建和合并","使用 gh pr checks 和 gh pr status 流线化代码审查过程","实施高效的分支策略以进行协作开发项目"],"ja":["gh pr create と gh pr merge を使用してプルリクエストの作成とマージを自動化する","gh pr checks と gh pr status を使用してコードレビューのプロセスをストリームライン化する","コラボレーション開発プロジェクトのための効率的なブランチ戦略を実施する"],"ko":["gh pr create 및 gh pr merge를 사용하여 풀 리퀘스트 생성 및 병합 자동화","gh pr checks 및 gh pr status를 사용하여 코드 리뷰 프로세스 스트리밍","협업 개발 프로젝트를 위한 효율적인 브랜치 전략 구현"],"es":["Automatizar la creación y fusión de solicitudes de incorporación con gh pr create y gh pr merge","Optimizar los procesos de revisión de código con gh pr checks y gh pr status","Implementar estrategias de ramificación eficientes para proyectos de desarrollo colaborativo"],"fr":["Automatiser la création et la fusion des demandes d''intégration avec gh pr create et gh pr merge","Optimiser les processus d''examen de code avec gh pr checks et gh pr status","Mettre en œuvre des stratégies de branchement efficaces pour les projets de développement collaboratif"],"de":["Automatisieren der Erstellung und Zusammenführung von Pull-Anfragen mit gh pr create und gh pr merge","Optimieren der Code-Review-Prozesse mit gh pr checks und gh pr status","Implementieren effizienter Verzweigungsstrategien für kollaborative Entwicklungsvorhaben"],"pt":["Automatizar a criação e mesclagem de solicitações de pull usando gh pr create e gh pr merge","Simplificar processos de revisão de código com gh pr checks e gh pr status","Implementar estratégias de ramificação eficientes para projetos de desenvolvimento colaborativo"],"ru":["Автоматизировать создание и слияние запросов на слияние с помощью gh pr create и gh pr merge","Упростить процессы проверки кода с помощью gh pr checks и gh pr status","Реализовать эффективные стратегии ветвления для совместных проектов разработки"],"ar":["تلقيم إنشاء ودمج طلبات الدمج باستخدام gh pr create وgh pr merge","تبسيط عمليات مراجعة الشفرة باستخدام gh pr checks وgh pr status","تنفيذ استراتيجيات فرعية فعالة لمشاريع التطوير التعاوني"]},"limitations":{"en":["Requires gh CLI installation and configuration","Limited to GitHub repositories and ecosystems"],"zh":["需要 gh CLI 的安装和配置","仅限于 GitHub 仓库和生态系统"],"ja":["gh CLI のインストールと設定が必要","GitHub リポジトリとエコシステムのみに限定される"],"ko":["gh CLI 설치 및 구성이 필요","GitHub 저장소 및 생태계에만 제한"],"es":["Requiere la instalación y configuración de gh CLI","Limitado a los repositorios y ecosistemas de GitHub"],"fr":["Nécessite l''installation et la configuration de gh CLI","Limité aux référentiels et écosystèmes GitHub"],"de":["Benötigt die Installation und Konfiguration von gh CLI","Begrenzt auf GitHub-Repositorys und -Ökosysteme"],"pt":["Exige a instalação e configuração do gh CLI","Limitado a repositórios e ecossistemas do GitHub"],"ru":["Требует установки и настройки gh CLI","Ограничен репозиториями и экосистемами GitHub"],"ar":["يتطلب تثبيت وتكوين gh CLI","محدود بمستودعات وبيئات GitHub"]},"version":4},"contentHash":"fdeaac730749855c597817941dcebe6c9811c667a364e70cbb211533374d3bad","repoE