INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('callstackincubator/agent-skills/github', 'github', 'callstackincubator', 'agent-skills', 'official', 'github callstackincubator agent-skills official This skill provides GitHub patterns using gh CLI for pull requests, stacked PRs, and repository automation, benefiting developers and repository managers. 本文介绍如何使用 gh CLI 进行 GitHub 仓库管理，包括拉取请求、代码审查和分支策略 この記事では、gh CLI を使用した GitHub リポジトリ管理、プルリクエスト、コードレビュー、ブランチ戦略について説明します 본 문서에서는 gh CLI를 사용하여 GitHub 리포지토리를 관리하는 방법을 소개합니다 Utilice gh CLI para operaciones de GitHub, como crear solicitudes de extracción y revisar código Utilisez gh CLI pour les opérations GitHub, telles que la création de demandes d''extraction et la révision de code Verwenden Sie gh CLI für GitHub-Operationen, wie das Erstellen von Pull-Requests und die Überprüfung von Code O GitHub com gh CLI oferece padrões para criar, mesclar e gerenciar pull requests de forma eficiente ИИ Агенты и gh CLI помогают автоматизировать процессы GitHub, включая создание и слияние pull запросов استخدم غه CLI وأدوات الذكاء الاصطناعي لتحسين إدارة المستودعات وطلبات السحب على GitHub github automation gh cli commands github pull request management github vs gitlab how to use github github setup guide github repository management github alternative github install GitHub 仓库管理 gh CLI 拉取请求 代码审查 分支策略 仓库自动化 AIエージェント GitHub Setup GitHub Best Practices Creates pull requests using `gh pr create` command Supports squash-merging PRs with `gh pr merge` Enables PR status and checks with `gh pr status` and `gh pr checks` Facilitates stacked PR workflow management Utilizes gh CLI for lower context usage over GitHub MCP servers github is a version control system utilizing gh CLI for efficient repository management and automation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('callstackincubator/agent-skills/upgrading-react-native', 'official', 'callstackincubator', 'agent-skills', 'callstackincubator/agent-skills', 'upgrading-react-native', 969, 57, 76, '2026-03-06T00:34:35Z', '2026-03-06T04:54:11.093Z', '39e132e2d28423eb84216ffc10499ce7506453e19f4a375c5e484e312159004c', '{"id":"callstackincubator/agent-skills/upgrading-react-native","name":"upgrading-react-native","description":{"en":"The upgrading-react-native skill automates the upgrade workflow for React Native apps, handling template diffs, package updates, and native configuration migrations. It benefits developers upgrading to newer React Native versions.","zh":"升级 React Native 应用，实现 rn-diff-purge 模板差异、依赖更新和 Expo SDK 迁移","ja":"React Native アプリをアップグレードし、rn-diff-purge テンプレートの差異、依存関係の更新、Expo SDK の移行を行う","ko":"React Native 애플리케이션을 업그레이드하고 rn-diff-purge 템플릿의 차이, 종속성 업데이트, Expo SDK 마이그레이션을 수행합니다","es":"Actualiza tus aplicaciones React Native con confianza, siguiendo nuestra guía que cubre actualizaciones de dependencias y configuraciones nativas","fr":"Mettez à niveau vos applications React Native avec confiance, en suivant notre guide qui couvre les mises à jour des dépendances et des configurations natives","de":"Aktualisieren Sie Ihre React Native-Anwendungen mit unserem Leitfaden, der Updates von Abhängigkeiten und nativen Konfigurationen abdeckt","pt":"Atualize seus aplicativos React Native para versões mais recentes aplicando diferenças de modelo via Upgrade Helper e resolvendo problemas de dependência","ru":"Обновите свои приложения React Native до последних версий, применяя различия моделей через Upgrade Helper и решая проблемы зависимостей","ar":"رقي تطبيقات React Native إلى إصدارات أحدث путем تطبيق فروق النموذج عبر Upgrade Helper و حل مشاكل الاعتماد"},"owner":"callstackincubator","repo":"agent-skills","repoPath":"callstackincubator/agent-skills","stars":969,"forks":57,"updatedAt":"2026-03-06T00:34:35Z","topics":[],"skillMd":{"name":"upgrading-react-native","description":"Upgrades React Native apps to newer versions by applying rn-diff-purge template diffs, updating package.json dependencies, migrating native iOS and Android configuration, resolving CocoaPods and Gradle changes, and handling breaking API updates. Use when upgrading React Native, bumping RN version, updating from RN 0.x to 0.y, or migrating Expo SDK alongside a React Native upgrade.","tags":"react-native, upgrade, upgrade-helper, npm, changelog, cocoapods, ios, android","bodyPreview":"# Upgrading React Native\n\n## Overview\n\nCovers the full React Native upgrade workflow: template diffs via Upgrade Helper, dependency updates, Expo SDK steps, and common pitfalls.\n\n## Typical Upgrade Sequence\n\n1. **Route**: Choose the right upgrade path via [upgrading-react-native.md][upgrading-react-native]\n2. **Diff**: Fetch the canonical template diff using Upgrade Helper via [upgrade-helper-core.md][upgrade-helper-core]\n3. **Dependencies**: Assess and update third-party packages via [upgrading","body":"# Upgrading React Native\n\n## Overview\n\nCovers the full React Native upgrade workflow: template diffs via Upgrade Helper, dependency updates, Expo SDK steps, and common pitfalls.\n\n## Typical Upgrade Sequence\n\n1. **Route**: Choose the right upgrade path via [upgrading-react-native.md][upgrading-react-native]\n2. **Diff**: Fetch the canonical template diff using Upgrade Helper via [upgrade-helper-core.md][upgrade-helper-core]\n3. **Dependencies**: Assess and update third-party packages via [upgrading-dependencies.md][upgrading-dependencies]\n4. **React**: Align React version if upgraded via [react.md][react]\n5. **Expo** (if applicable): Apply Expo SDK layer via [expo-sdk-upgrade.md][expo-sdk-upgrade]\n6. **Verify**: Run post-upgrade checks via [upgrade-verification.md][upgrade-verification]\n\n```bash\n# Quick start: detect current version and fetch diff\nnpm pkg get dependencies.react-native --prefix \"$APP_DIR\"\nnpm view react-native dist-tags.latest\n\n# Example: upgrading from 0.76.9 to 0.78.2\n# 1. Fetch the template diff\ncurl -L -f -o /tmp/rn-diff.diff \\\n  \"https://raw.githubusercontent.com/react-native-community/rn-diff-purge/diffs/diffs/0.76.9..0.78.2.diff\" \\\n  && echo \"Diff downloaded OK\" || echo \"ERROR: diff not found, check versions\"\n# 2. Review changed files\ngrep -n \"^diff --git\" /tmp/rn-diff.diff\n# 3. Update package.json, apply native changes, then install + rebuild\nnpm install --prefix \"$APP_DIR\"\ncd \"$APP_DIR/ios\" && pod install\n# 4. Validate: both platforms must build successfully\nnpx react-native build-android --mode debug --no-packager\nxcodebuild -workspace \"$APP_DIR/ios/App.xcworkspace\" -scheme App -sdk iphonesimulator build\n```\n\n## When to Apply\n\nReference these guidelines when:\n- Moving a React Native app to a newer version\n- Reconciling native config changes from Upgrade Helper\n- Validating release notes for breaking changes\n\n## Quick Reference\n\n| File | Description |\n|------|-------------|\n| [upgrading-react-native.md][upgrading-react-native] | Router: choose the right upgrade path |\n| [upgrade-helper-core.md][upgrade-helper-core] | Core Upgrade Helper workflow and reliability gates |\n| [upgrading-dependencies.md][upgrading-dependencies] | Dependency compatibility checks and migration planning |\n| [react.md][react] | React and React 19 upgrade alignment rules |\n| [expo-sdk-upgrade.md][expo-sdk-upgrade] | Expo SDK-specific upgrade layer (conditional) |\n| [upgrade-verification.md][upgrade-verification] | Manual post-upgrade verification checklist |\n| [monorepo-singlerepo-targeting.md][monorepo-singlerepo-targeting] | Monorepo and single-repo app targeting and command scoping |\n\n## Problem → Skill Mapping\n\n| Problem | Start With |\n|---------|------------|\n| Need to upgrade React Native | [upgrade-helper-core.md][upgrade-helper-core] |\n| Need dependency risk triage and migration options | [upgrading-dependencies.md][upgrading-dependencies] |\n| Need React/React 19 package alignment | [react.md][react] |\n| Need workflow routing first | [upgrading-react-native.md][upgrading-react-native] |\n| Need Expo SDK-specific steps | [expo-sdk-upgrade.md][expo-sdk-upgrade] |\n| Need manual regression validation | [upgrade-verification.md][upgrade-verification] |\n| Need repo/app command scoping | [monorepo-singlerepo-targeting.md][monorepo-singlerepo-targeting] |\n\n[upgrading-react-native]: references/upgrading-react-native.md\n[upgrade-helper-core]: references/upgrade-helper-core.md\n[upgrading-dependencies]: references/upgrading-dependencies.md\n[react]: references/react.md\n[expo-sdk-upgrade]: references/expo-sdk-upgrade.md\n[upgrade-verification]: references/upgrade-verification.md\n[monorepo-singlerepo-targeting]: references/monorepo-singlerepo-targeting.md\n"},"category":"official","lastSynced":"2026-03-06T04:54:11.093Z","seo":{"title":{"en":"upgrading-react-native: Upgrade Workflow Setup Guide | AI...","zh":"React Native 升级设置指南 - AIエージェント","ja":"React Native アップグレードのベストプラクティス - AIエージェント","ko":"React Native 업그레이드 가이드 - AI 에이전트","es":"Guía de actualización de React Native","fr":"Mise à niveau de React Native - Guide étape par étape","de":"React Native Upgrade-Leitfaden","pt":"Guia de Configuração para Atualizar React Native","ru":"Руководство по обновлению React Native: ИИ Агенты","ar":"دليل ترقية React Native باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Streamline your React Native upgrade process with our AI agent skill, covering template diffs, dependency updates, and Expo SDK migrations - get started now!","zh":"使用 AI エージェント 升级 React Native 应用，实现 rn-diff-purge 模板差异、依赖更新和 Expo SDK 迁移","ja":"AI エージェントを使用して React Native アプリをアップグレードし、rn-diff-purge テンプレートの差異、依存関係の更新、Expo SDK の移行を行う","ko":"AI 에이전트를 사용하여 React Native 애플리케이션을 업그레이드하고 rn-diff-purge 템플릿의 차이, 종속성 업데이트, Expo SDK 마이그레이션을 수행합니다","es":"Aprende a actualizar tus aplicaciones React Native con nuestra guía paso a paso, que cubre actualizaciones de dependencias y configuraciones nativas","fr":"Découvrez comment mettre à niveau vos applications React Native avec notre guide détaillé, qui couvre les mises à jour des dépendances et des configurations ...","de":"Erfahren Sie, wie Sie Ihre React Native-Anwendungen mit unserem Schritt-für-Schritt-Leitfaden aktualisieren, der Updates von Abhängigkeiten und nativen Konfi...","pt":"Aprenda a atualizar seus aplicativos React Native para versões mais recentes com nosso guia passo a passo e evite problemas comuns","ru":"Обновите свои приложения React Native до последних версий с помощью нашего пошагового руководства и избегайте распространенных ошибок с помощью ИИ Агентов","ar":"تعلم كيفية ترقية تطبيقات React Native إلى الإصدارات الأحدث مع دليلنا خطوة بخطوة وتجنب المشاكل الشائعة باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"upgrading-react-native is a skill that automates the React Native upgrade process, applying rn-diff-purge template diffs and updating dependencies","zh":"React Native 升级是使用 AI エージェント 升级 React Native 应用的过程","ja":"React Native アップグレードは、AI エージェントを使用して React Native アプリをアップグレードするプロセスです","ko":"React Native 업그레이드는 AI 에이전트를 사용하여 React Native 애플리케이션을 업그레이드하는 과정입니다","es":"La actualización de React Native es el proceso de migrar una aplicación a una versión más reciente de la plataforma","fr":"La mise à niveau de React Native est le processus de migration d''une application vers une version plus récente de la plate-forme","de":"Die Aktualisierung von React Native ist der Prozess der Migration einer Anwendung auf eine neuere Version der Plattform","pt":"Atualização de React Native é o processo de atualizar aplicativos para versões mais recentes","ru":"Обновление React Native - это процесс обновления приложений до последних версий","ar":"ترقية React Native هي عملية ترقية التطبيقات إلى الإصدارات الأحدث"},"features":{"en":["Applies rn-diff-purge template diffs for seamless upgrades","Updates package.json dependencies for compatibility","Migrates native iOS and Android configurations","Resolves CocoaPods and Gradle changes","Handles breaking API updates for a smooth transition"],"zh":["rn-diff-purge 模板差异应用","依赖更新和 Expo SDK 迁移","Upgrade Helper 核心功能支持","第三方包依赖更新","CocoaPods 和 Gradle 变化解决","breaking API 更新处理"],"ja":["rn-diff-purge テンプレートの差異適用","依存関係の更新と Expo SDK の移行","Upgrade Helper コア機能のサポート","サードパーティパッケージの依存関係の更新","CocoaPods と Gradle の変化の解決","breaking API の更新処理"],"ko":["rn-diff-purge 템플릿의 차이 적용","종속성 업데이트 및 Expo SDK 마이그레이션","Upgrade Helper 핵심 기능 지원","제3자 패키지 종속성 업데이트","CocoaPods 및 Gradle 변경 사항 해결","breaking API 업데이트 처리"],"es":["Aplicación de plantillas de diferencia para actualizar la versión de React Native","Actualización de dependencias en el archivo package.json","Migración de configuraciones nativas para iOS y Android","Resolución de cambios en CocoaPods y Gradle","Manejo de actualizaciones de API que rompen la compatibilidad"],"fr":["Application de modèles de différence pour mettre à niveau la version de React Native","Mise à jour des dépendances dans le fichier package.json","Migration des configurations natives pour iOS et Android","Résolution des changements dans CocoaPods et Gradle","Gestion des mises à jour d''API qui cassent la compatibilité"],"de":["Anwendung von Differenzvorlagen, um die React Native-Version zu aktualisieren","Aktualisierung von Abhängigkeiten in der package.json-Datei","Migration von nativen Konfigurationen für iOS und Android","Auflösung von Änderungen in CocoaPods und Gradle","Handhabung von API-Updates, die die Kompatibilität brechen"],"pt":["Aplicação de diferenças de modelo via Upgrade Helper","Atualização de dependências via package.json","Migração de configuração nativa para iOS e Android","Resolução de problemas de CocoaPods e Gradle","Manipulação de atualizações de API quebradas"],"ru":["Применение различий моделей через Upgrade Helper","Обновление зависимостей через package.json","Миграция настроек для iOS и Android","Решение проблем с CocoaPods и Gradle","Обработка обновлений API, которые ломаются"],"ar":["تطبيق فروق النموذج عبر Upgrade Helper","تحديث الاعتماديات عبر package.json","هجرة إعدادات الأجهزة لiOS و Android","حل مشاكل CocoaPods و Gradle","تعامل مع تحديثات واجهة برمجة التطبيقات المحطمة"]},"keywords":{"en":["how to use upgrading-react-native","upgrading-react-native setup guide","react native upgrade workflow","rn-diff-purge template diffs","upgrading-react-native vs manual upgrades","upgrading-react-native install"],"zh":["React Native 升级","AI エージェント","rn-diff-purge","依赖更新","Expo SDK 迁移","Upgrade Helper","CocoaPods","Gradle"],"ja":["React Native アップグレード","AI エージェント","rn-diff-purge","依存関係の更新","Expo SDK の移行","Upgrade Helper","CocoaPods","Gradle"],"ko":["React Native 업그레이드","AI 에이전트","rn-diff-purge","종속성 업데이트","Expo SDK 마이그레이션","Upgrade Helper","CocoaPods","Gradle"],"es":["actualización de React Native","guía de actualización","migración de aplicaciones","Actualización de dependencias","Configuración nativa","CocoaPods","Gradle","API de React Native"],"fr":["mise à niveau de React Native","guide de mise à niveau","migration d''applications","Mise à jour des dépendances","Configuration native","CocoaPods","Gradle","API de React Native"],"de":["Aktualisierung von React Native","Leitfaden für die Aktualisierung","Migration von Anwendungen","Aktualisierung von Abhängigkeiten","Native Konfiguration","CocoaPods","Gradle","React Native-API"],"pt":["atualizar react native","upgrade helper","react native upgrade","atualizar dependências","migrar configuração nativa","resolver problemas de CocoaPods","guia de configuração react native"],"ru":["обновить react native","upgrade helper","react native обновление","обновить зависимости","мигрировать настройки","решить проблемы с CocoaPods","руководство по обновлению react native"],"ar":["ترقية رياكت نيتيف","أداة مساعدة الترقية","ترقية رياكت نيتيف","تحديث الاعتماديات","هجرة الإعدادات الأصلية","حل مشاكل كوكابودز","دليل ترقية رياكت نيتيف"]}},"agentAnalysis":{"suitability":{"en":"Essential for Mobile Development Agents automating complex React Native version migrations.","zh":"对于自动化复杂React Native版本迁移的移动开发代理而言至关重要。","ja":"複雑なReact Nativeバージョン移行を自動化するモバイル開発エージェントにとって必須です。","ko":"복잡한 React Native 버전 마이그레이션을 자동화하는 모바일 개발 에이전트에게 필수적입니다.","es":"Esencial para agentes de desarrollo móvil que automatizan migraciones de versiones complejas de React Native.","fr":"Essentiel pour les agents de développement mobile automatisant les migrations de versions complexes de React Native.","de":"Wesentlich für Mobile Development Agents, die komplexe React Native Version Migrations automatisieren.","pt":"Essencial para Agentes de Desenvolvimento Mobile que automatizam migrações complexas de versão do React Native.","ru":"Необходимо для агентов мобильной разработки, автоматизирующих сложные миграции версий React Native.","ar":"ضروري لوكلاء تطوير الجوال الذين يقومون بأتمتة ترحيل إصدارات React Native المعقدة."},"recommendation":{"en":"Executes comprehensive React Native upgrades by applying rn-diff-purge template diffs, managing CocoaPods and Gradle configurations, and resolving native iOS/Android breaking changes. Enables seamless dependency management through package.json updates and supports coordinated Expo SDK migrations alongside core React Native version bumps.","zh":"通过应用rn-diff-purge模板差异、管理CocoaPods和Gradle配置以及解决原生的iOS/Android破坏性变更，执行全面的React Native升级。通过package.json更新实现无缝依赖管理，并支持在核心React Native版本升级的同时协调Expo SDK迁移。","ja":"rn-diff-purgeテンプレートの差分を適用し、CocoaPodsとGradleの設定を管理し、ネイティブiOS/Androidの破壊的変更を解決することで、包括的なReact Nativeアップグレードを実行します。package.jsonの更新を通じてシームレスな依存関係管理を可能にし、コアのReact Nativeバージョンアップと並行したExpo SDKの移行を調整することをサポートします。","ko":"rn-diff-purge 템플릿 diff 적용, CocoaPods 및 Gradle 구성 관리, 네이티브 iOS/Android 호환 변경 사항 해결을 통해 포괄적인 React Native 업그레이드를 실행합니다. package.json 업데이트를 통한 원활한 종속성 관리를 가능하게 하며, 코어 React Native 버전 업그레이드와 함께 Expo SDK 마이그레이션을 조정하는 것을 지원합니다.","es":"Ejecuta actualizaciones integrales de React Native aplicando diferencias de plantilla rn-diff-purge, administrando configuraciones de CocoaPods y Gradle, y resolviendo cambios de ruptura de iOS/Android nativos. Permite una gestión de dependencias sin problemas a través de actualizaciones de package.json y admite migraciones coordinadas de Expo SDK junto con actualizaciones de versiones de React Native.","fr":"Exécute des mises à niveau React Native complètes en appliquant des différences de modèle rn-diff-purge, en gérant les configurations CocoaPods et Gradle, et en résolvant les changements de rupture natifs iOS/Android. Permet une gestion des dépendances sans problème via des mises à jour de package.json et prend en charge les migrations de SDK Expo coordonnées avec les mises à niveau de version de React Native.","de":"Führt umfassende React Native-Upgrades durch, indem es rn-diff-purge-Vorlagendifferenzen anwendet, CocoaPods- und Gradle-Konfigurationen verwaltet und native iOS/Android-Breaking-Changes löst. Ermöglicht eine nahtlose Abhängigkeitsverwaltung durch package.json-Aktualisierungen und unterstützt koordinierte Expo-SDK-Migrationen zusammen mit React-Native-Versionssprüngen.","pt":"Executa atualizações abrangentes do React Native aplicando diffs de template do rn-diff-purge, gerenciando configurações do CocoaPods e Gradle, e resolvendo breaking changes nativos do iOS/Android. Permite um gerenciamento de dependências contínuo através de atualizações do package.json e suporta migrações coordenadas do Expo SDK juntamente com atualizações da versão core do React Native.","ru":"Выполняет комплексные обновления React Native, применяя различия шаблонов rn-diff-purge, управляя конфигурациями CocoaPods и Gradle и разрешая критические изменения в нативных iOS/Android конфигурациях. Обеспечивает беспрерывное управление зависимостями через обновления package.json и поддерживает скоординированные миграции Expo SDK вместе с обновлениями основной версии React Native.","ar":"ينفذ ترقيات شاملة لـ React Native من خلال تطبيق فروق قوالب rn-diff-purge، وإدارة تكوينات CocoaPods وGradle، وحل التغييرات غير المتوافقة لأنظمة iOS/Android الأصلية. يتيح إدارة سلسة للتبعيات من خلال تحديثات package.json ويدعم ترحيلات Expo SDK المنسقة جنبًا إلى جنب مع ترقيات إصدار React Native الأساسي."},"useCases":{"en":["Automating version upgrades using Upgrade Helper diffs","Resolving CocoaPods and Gradle dependency conflicts","Migrating native iOS and Android configuration files","Bumping React Native versions from 0.x to 0.y","Coordinating Expo SDK updates with React Native upgrades"],"zh":["使用Upgrade Helper差异自动化版本升级","解决CocoaPods和Gradle依赖冲突","迁移原生iOS和Android配置文件","将React Native版本从0.x升级到0.y","协调Expo SDK更新与React Native升级"],"ja":["Upgrade Helperの差分を使用したバージョンアップグレードの自動化","CocoaPodsとGradleの依存関係競合の解決","ネイティブiOSおよびAndroid設定ファイルの移行","React Nativeのバージョンを0.xから0.yにバンプ","React Nativeアップグレードとの連携によるExpo SDKの更新調整"],"ko":["Upgrade Helper diff를 사용한 버전 업그레이드 자동화","CocoaPods 및 Gradle 종속성 충돌 해결","네이티브 iOS 및 Android 구성 파일 마이그레이션","React Native 버전을 0.x에서 0.y로 버밍","React Native 업그레이드와 함께 Expo SDK 업데이트 조정"],"es":["Automatizar actualizaciones de versiones usando diferencias de Upgrade Helper","Resolver conflictos de dependencias de CocoaPods y Gradle","Migrar archivos de configuración nativos de iOS y Android","Actualizar versiones de React Native de 0.x a 0.y","Coordinar actualizaciones de SDK de Expo con actualizaciones de React Native"],"fr":["Automatiser les mises à niveau de version à l''aide de différences d''Upgrade Helper","Résoudre les conflits de dépendances de CocoaPods et Gradle","Migrer les fichiers de configuration natifs iOS et Android","Mettre à niveau les versions de React Native de 0.x à 0.y","Coordiner les mises à jour du SDK Expo avec les mises à niveau de React Native"],"de":["Automatisieren von Versionen-Upgrades mit Upgrade Helper-Differenzen","Auflösen von CocoaPods- und Gradle-Abhängigkeitskonflikten","Migrieren von nativen iOS- und Android-Konfigurationsdateien","React Native-Versionen von 0.x auf 0.y aktualisieren","Koordinieren von Expo-SDK-Updates mit React Native-Upgrades"],"pt":["Automatizando upgrades de versão usando diffs do Upgrade Helper","Resolvendo conflitos de dependência do CocoaPods e Gradle","Migrando arquivos de configuração nativos do iOS e Android","Atualizando versões do React Native de 0.x para 0.y","Coordenando atualizações do Expo SDK com upgrades do React Native"],"ru":["Автоматизация обновлений версий с использованием различий Upgrade Helper","Разрешение конфликтов зависимостей CocoaPods и Gradle","Миграция нативных файлов конфигурации iOS и Android","Обновление версий React Native с 0.x до 0.y","Координация обновлений Expo SDK с обновлениями React Native"],"ar":["أتمتة ترقيات الإصدار باستخدام فروق Upgrade Helper","حل تعارضات تبعيات CocoaPods وGradle","ترحيل ملفات تكوين iOS وAndroid الأصلية","ترقية إصدارات React Native من 0.x إلى 0.y","تنسيق تحديثات Expo SDK مع ترقيات React Native"]},"limitations":{"en":["Requires existing React Native project structure","Dependent on rn-diff-purge template availability","Needs native development environment (Xcode/Android Studio)","Must handle third-party library compatibility separately"],"zh":["需要现有的React Native项目结构","依赖于rn-diff-purge模板的可用性","需要原生开发环境（Xcode/Android Studio）","必须单独处理第三方库的兼容性"],"ja":["既存のReact Nativeプロジェクト構造が必要","rn-diff-purgeテンプレートの可用性に依存","ネイティブ開発環境（Xcode/Android Studio）が必要","サードパーティライブラリの互換性は別途対応が必要"],"ko":["기존 React Native 프로젝트 구조 필요","rn-diff-purge 템플릿 가용성에 의존","네이티브 개발 환경(Xcode/Android Studio) 필요","타사 라이브러리 호환성을 별도로 처리해야 함"],"es":["Requiere estructura de proyecto React Native existente","Dependiente de la disponibilidad de plantillas rn-diff-purge","Necesita entorno de desarrollo nativo (Xcode/Android Studio)","Debe manejar la compatibilidad de bibliotecas de terceros por separado"],"fr":["Nécessite une structure de projet React Native existante","Dépend de la disponibilité des modèles rn-diff-purge","Nécessite un environnement de développement natif (Xcode/Android Studio)","Doit gérer la compatibilité des bibliothèques tierces séparément"],"de":["Benötigt vorhandene React Native-Projektstruktur","Abhängig von der Verfügbarkeit von rn-diff-purge-Vorlagen","Benötigt native Entwicklungsumgebung (Xcode/Android Studio)","Muss die Kompatibilität von Drittanbieterbibliotheken getrennt behandeln"],"pt":["Requer uma estrutura de projeto React Native existente","Dependente da disponibilidade de template do rn-diff-purge","Necessita de ambiente de desenvolvimento nativo (Xcode/Android Studio)","Deve lidar com a compatibilidade de bibliotecas de terceiros separadamente"],"ru":["Требует существующей структуры проекта React Native","Зависит от доступности шаблона rn-diff-purge","Требует наличия нативной среды разработки (Xcode/Android Studio)","Совместимость сторонних библиотек должна обрабатываться отдельно"],"ar":["يتطلب وجود هيكل مشروع React Native موجود","يعتمد على توفر قالب rn-diff-purge","يحتاج إلى بيئة تطوير أصلية (Xcode/Android Studio)","يجب التعامل مع توافق مكتبات الطرف الثالث بشكل منفصل"]},"version":4},"contentHash":"39e132e2d28423eb84216ffc10499ce7506453e19f4a375c5e484e312159004c","repoEtag":"W/\"cde3f79b6c913438993afe18fdb53c1f5dcf7c814f31b8ef5104f2d45f6ca3dc\"","qualityScore":76}');
