INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('callstackincubator/agent-skills/upgrading-react-native', 'upgrading-react-native', 'callstackincubator', 'agent-skills', 'official', 'upgrading-react-native callstackincubator agent-skills official The upgrading-react-native skill automates the upgrade workflow for React Native apps, handling template diffs, package updates, and native configuration migrations. It benefits developers upgrading to newer React Native versions. 升级 React Native 应用，实现 rn-diff-purge 模板差异、依赖更新和 Expo SDK 迁移 React Native アプリをアップグレードし、rn-diff-purge テンプレートの差異、依存関係の更新、Expo SDK の移行を行う React Native 애플리케이션을 업그레이드하고 rn-diff-purge 템플릿의 차이, 종속성 업데이트, Expo SDK 마이그레이션을 수행합니다 Actualiza tus aplicaciones React Native con confianza, siguiendo nuestra guía que cubre actualizaciones de dependencias y configuraciones nativas Mettez à niveau vos applications React Native avec confiance, en suivant notre guide qui couvre les mises à jour des dépendances et des configurations natives Aktualisieren Sie Ihre React Native-Anwendungen mit unserem Leitfaden, der Updates von Abhängigkeiten und nativen Konfigurationen abdeckt Atualize seus aplicativos React Native para versões mais recentes aplicando diferenças de modelo via Upgrade Helper e resolvendo problemas de dependência Обновите свои приложения React Native до последних версий, применяя различия моделей через Upgrade Helper и решая проблемы зависимостей رقي تطبيقات React Native إلى إصدارات أحدث путем تطبيق فروق النموذج عبر Upgrade Helper و حل مشاكل الاعتماد how to use upgrading-react-native upgrading-react-native setup guide react native upgrade workflow rn-diff-purge template diffs upgrading-react-native vs manual upgrades upgrading-react-native install React Native 升级 AI エージェント rn-diff-purge 依赖更新 Expo SDK 迁移 Upgrade Helper CocoaPods Gradle Applies rn-diff-purge template diffs for seamless upgrades Updates package.json dependencies for compatibility Migrates native iOS and Android configurations Resolves CocoaPods and Gradle changes Handles breaking API updates for a smooth transition upgrading-react-native is a skill that automates the React Native upgrade process, applying rn-diff-purge template diffs and updating dependencies');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('facebook/react/flags', 'official', 'facebook', 'react', 'facebook/react', 'flags', 243646, 50653, 76, '2026-03-06T05:37:42Z', '2026-03-06T06:13:00.189Z', '8dfb38a708aff4cc90f633d048d9f1c556c5d4a8f15107ad60f0d8cf252dc30e', '{"id":"facebook/react/flags","name":"flags","description":{"en":"The flags skill helps developers manage feature flag states, compare channels, and debug differences in feature behavior. It supports various channels, including www, canary, and React Native.","zh":"Flags 是一个用于检查功能标志状态、比较渠道和调试的工具","ja":"Flags は機能フラグの状態を確認し、チャネルを比較し、デバッグするためのツールです","ko":"Flags는 기능 플래그 상태를 확인하고 채널을 비교하며 디버깅하는 데 사용되는 툴입니다","es":"Los flags permiten verificar estados de características y comparar canales para depurar diferencias en el comportamiento de las características","fr":"Les flags permettent de vérifier les états des fonctionnalités et de comparer les canaux pour déboguer les différences dans le comportement des fonctionnalités","de":"Flags ermöglichen es, Zustände von Funktionen zu überprüfen und Kanäle zu vergleichen, um Unterschiede im Verhalten von Funktionen zu debuggen","pt":"Utilize flags para comparar canais, depurar comportamentos de recursos e otimizar a experiência do usuário. Suporta React, JavaScript e bibliotecas de frontend","ru":"Используйте флаги для сравнения каналов, отладки поведения функций и оптимизации пользовательского опыта. Поддерживает React, JavaScript и библиотеки frontend для ИИ Агентов","ar":"استخدم الأعلام لمقارنة القنوات وتصحيح أخطاء سلوك الميزات وتحسين تجربة المستخدم. يدعم React و JavaScript و مكتبات واجهة المستخدم"},"owner":"facebook","repo":"react","repoPath":"facebook/react","stars":243646,"forks":50653,"updatedAt":"2026-03-06T05:37:42Z","topics":["declarative","frontend","javascript","library","react","ui"],"skillMd":{"name":"flags","description":"Use when you need to check feature flag states, compare channels, or debug why a feature behaves differently across release channels.","bodyPreview":"# Feature Flags\n\nArguments:\n- $ARGUMENTS: Optional flags\n\n## Options\n\n| Option | Purpose |\n|--------|---------|\n| (none) | Show all flags across all channels |\n| `--diff <ch1> <ch2>` | Compare flags between channels |\n| `--cleanup` | Show flags grouped by cleanup status |\n| `--csv` | Output in CSV format |\n\n## Channels\n\n- `www`, `www-modern` - Meta internal\n- `canary`, `next`, `experimental` - OSS channels\n- `rn`, `rn-fb`, `rn-next` - React Native\n\n## Legend\n\n✅ enabled, ❌ disabled, 🧪 `__VARIANT","body":"# Feature Flags\n\nArguments:\n- $ARGUMENTS: Optional flags\n\n## Options\n\n| Option | Purpose |\n|--------|---------|\n| (none) | Show all flags across all channels |\n| `--diff <ch1> <ch2>` | Compare flags between channels |\n| `--cleanup` | Show flags grouped by cleanup status |\n| `--csv` | Output in CSV format |\n\n## Channels\n\n- `www`, `www-modern` - Meta internal\n- `canary`, `next`, `experimental` - OSS channels\n- `rn`, `rn-fb`, `rn-next` - React Native\n\n## Legend\n\n✅ enabled, ❌ disabled, 🧪 `__VARIANT__`, 📊 profiling-only\n\n## Instructions\n\n1. Run `yarn flags $ARGUMENTS`\n2. Explain the output to the user\n3. For --diff, highlight meaningful differences\n\n## Common Mistakes\n\n- **Forgetting `__VARIANT__` flags** - These are tested both ways in www; check both variants\n- **Comparing wrong channels** - Use `--diff` to see exact differences\n"},"category":"official","lastSynced":"2026-03-06T06:13:00.189Z","seo":{"title":{"en":"flags: Feature Flag Management Setup Guide | AI Agent Skill","zh":"Flags Setup Guide: React 和 JavaScript 应用","ja":"Flags セットアップガイド: React と JavaScript アプリケーション","ko":"Flags 설정 가이드: React 및 JavaScript 애플리케이션","es":"Guía de configuración de flags para desarrollo frontend","fr":"Guide de mise en place des flags pour le développement fr...","de":"Einrichtungsleitfaden für Flags in der Frontend-Entwicklung","pt":"Guia de Configuração de Flags para Desenvolvedores","ru":"Настройка Флагов: Руководство для Разработчиков ИИ Агентов","ar":"دليل إعداد الأعلام ل개발 البرمجيات"},"description":{"en":"Discover how to efficiently manage feature flags across channels with flags. Learn to compare, debug, and optimize your feature flag setup today!","zh":"了解 Flags 的功能和用法，包括比较渠道、调试和输出 CSV 格式","ja":"Flags の機能と使い方を学び、チャネル比較、デバッグ、CSV 出力を行う","ko":"Flags의 기능과 사용 방법을 알아보세요. 채널 비교, 디버깅 및 CSV 출력 등","es":"Aprende a utilizar flags para comparar canales y depurar comportamientos de características en diferentes canales de lanzamiento","fr":"Découvrez comment utiliser les flags pour comparer les canaux et déboguer les comportements des fonctionnalités sur différents canaux de publication","de":"Erfahren Sie, wie Sie Flags verwenden können, um Kanäle zu vergleichen und Verhaltensweisen von Funktionen in verschiedenen Release-Kanälen zu debuggen","pt":"Aprenda a utilizar flags para comparar canais, depurar comportamentos de recursos e otimizar a experiência do usuário com nossa ferramenta de flags","ru":"Используйте флаги для сравнения каналов, отладки поведения функций и оптимизации пользовательского опыта с нашей инструментом флагов для ИИ Агентов","ar":"تعلم كيفية استخدام الأعلام لمقارنة القنوات وتصحيح أخطاء سلوك الميزات وتحسين تجربة المستخدم مع أداة الأعلام الخاصة بنا"},"definition":{"en":"flags is a feature flag management system that enables developers to check flag states, compare channels, and debug feature behavior differences across release channels.","zh":"Flags 是一个用于管理和比较功能标志的工具，支持 React 和 JavaScript 应用","ja":"Flags は React と JavaScript アプリケーション向けの機能フラグを管理し比較するツールです","ko":"Flags는 React 및 JavaScript 애플리케이션을 위한 기능 플래그를 관리하고 비교하는 툴입니다","es":"Un flag es una herramienta de desarrollo que permite comparar y depurar estados de características en diferentes canales de lanzamiento","fr":"Un flag est un outil de développement qui permet de comparer et de déboguer les états des fonctionnalités sur différents canaux de publication","de":"Ein Flag ist ein Entwicklungstool, das es ermöglicht, Zustände von Funktionen in verschiedenen Release-Kanälen zu vergleichen und zu debuggen","pt":"Flags são utilitários que permitem verificar estados de recursos, comparar canais e depurar comportamentos de recursos em diferentes canais de lançamento","ru":"Флаги - это утилиты, которые позволяют проверять состояния функций, сравнивать каналы и отлаживать поведение функций в разных каналах выпуска для ИИ Агентов","ar":"الأعلام هي أدوات تتيح التحقق من حالات الميزات ومقارنة القنوات وتصحيح أخطاء سلوك الميزات في قنوات الإصدار المختلفة"},"features":{"en":["Show all flags across all channels using the `--diff` option","Compare flags between channels with `--diff <ch1> <ch2>`","Output flags in CSV format using the `--csv` option","Group flags by cleanup status with `--cleanup`","Supports multiple channels, including Meta internal and OSS channels","Integrates with React and React Native for seamless feature flag management"],"zh":["支持比较渠道，包括 www、www-modern、canary、next 和 experimental","提供 --diff 选项比较两个渠道之间的功能标志","支持输出 CSV 格式","提供 --cleanup 选项显示功能标志的清理状态","支持 React 和 JavaScript 应用"],"ja":["チャネル比較をサポートし、www、www-modern、canary、next、experimental を含む","--diff オプションを提供して 2 つのチャネルの機能フラグを比較する","CSV 出力をサポートする","--cleanup オプションを提供して機能フラグのクリーンアップ状態を表示する","React と JavaScript アプリケーションをサポートする"],"ko":["채널 비교를 지원하며, www, www-modern, canary, next 및 experimental을 포함","--diff 옵션을 제공하여 두 채널 간의 기능 플래그를 비교","CSV 출력을 지원","--cleanup 옵션을 제공하여 기능 플래그의 청소 상태를 표시","React 및 JavaScript 애플리케이션을 지원"],"es":["Opción para mostrar todos los flags en todos los canales","Comparación de flags entre canales con la opción --diff","Opción para mostrar flags agrupados por estado de limpieza con --cleanup","Salida en formato CSV con la opción --csv","Compatibilidad con canales como www, www-modern, canary, next y experimental","Soporte para React y React Native"],"fr":["Option pour afficher tous les flags sur tous les canaux","Comparaison de flags entre canaux avec l''option --diff","Option pour afficher les flags regroupés par état de nettoyage avec --cleanup","Sortie au format CSV avec l''option --csv","Compatibilité avec les canaux tels que www, www-modern, canary, next et experimental","Prise en charge de React et React Native"],"de":["Option, um alle Flags in allen Kanälen anzuzeigen","Vergleich von Flags zwischen Kanälen mit der Option --diff","Option, um Flags nach Bereinigungsstatus zu gruppieren mit --cleanup","Ausgabe im CSV-Format mit der Option --csv","Kompatibilität mit Kanälen wie www, www-modern, canary, next und experimental","Unterstützung für React und React Native"],"pt":["Comparação de canais com --diff","Depuração de comportamentos de recursos","Suporte a React e JavaScript","Saída em formato CSV com --csv","Agrupamento de flags por status de limpeza com --cleanup"],"ru":["Сравнение каналов с --diff","Отладка поведения функций","Поддержка React и JavaScript для ИИ Агентов","Выходные данные в формате CSV с --csv","Группировка флагов по статусу очистки с --cleanup"],"ar":["مقارنة القنوات مع --diff","تصحيح أخطاء سلوك الميزات","دعم React و JavaScript","إخراج في تنسيق CSV مع --csv","تجميع الأعلام حسب حالة التنظيف مع --cleanup"]},"keywords":{"en":["how to use flags","flags setup guide","feature flag management","flags alternative","flags vs feature toggles","flags install","what is flags","flags react integration","flags react native support"],"zh":["Flags 设置","React Flags","JavaScript Flags","功能标志状态","渠道比较","CSV 输出","AIエージェント","Flags 调试"],"ja":["Flags セットアップ","React Flags","JavaScript Flags","機能フラグの状態","チャネル比較","CSV 出力","AIエージェント","Flags デバッグ"],"ko":["Flags 설정","React Flags","JavaScript Flags","기능 플래그 상태","채널 비교","CSV 출력","AI 에이전트","Flags 디버깅"],"es":["flags de desarrollo","comparación de canales","depuración de características","React","React Native","desarrollo frontend","herramientas de desarrollo","flags para desarrollo","canal de lanzamiento"],"fr":["flags de développement","comparaison de canaux","débogage de fonctionnalités","React","React Native","développement frontend","outils de développement","flags pour développement","canal de publication"],"de":["Entwicklungsflags","Kanäle vergleichen","Funktionsdebugging","React","React Native","Frontend-Entwicklung","Entwicklungstools","Flags für Entwicklung","Release-Kanal"],"pt":["flags","comparação de canais","depuração de recursos","React","JavaScript","bibliotecas de frontend","otimização de experiência do usuário","desenvolvimento de software"],"ru":["флаги","сравнение каналов","отладка функций","React","JavaScript","библиотеки frontend","оптимизация пользовательского опыта","разработка программного обеспечения для ИИ Агентов"],"ar":["الأعلام","مقارنة القنوات","تصحيح أخطاء الميزات","React","JavaScript","مكتبات واجهة المستخدم","تحسين تجربة المستخدم","تطوير البرمجيات"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Debugging Agents requiring feature flag comparison and debugging across multiple release channels.","zh":"适用于需要在多个发布渠道之间进行功能标志比较和调试的调试代理的理想选择。","ja":"デバッグエージェントが複数のリリースチャネル間で機能フラグの比較とデバッグを必要とする場合に最適です。","ko":"여러 릴리즈 채널에서 기능 플래그 비교 및 디버깅이 필요한 디버깅 에이전트에 적합합니다.","es":"Ideal para agentes de depuración que requieren comparación de banderas de características y depuración en varios canales de lanzamiento.","fr":"Idéal pour les agents de débogage nécessitant une comparaison de drapeaux de fonctionnalités et un débogage sur plusieurs canaux de publication.","de":"Ideal für Debugging-Agents, die einen Vergleich von Feature-Flags und Debugging über mehrere Release-Kanäle erfordern.","pt":"Ideal para agentes de depuração que exigem comparação de flags de recursos e depuração em vários canais de lançamento.","ru":"Идеально для агентов отладки, требующих сравнения флагов функций и отладки в нескольких каналах выпуска.","ar":"مثالي لعمليات فحص العيوب التي تتطلب مقارنة أعلام الميزات وفحص الأخطاء عبر قنوات إصدار متعددة."},"recommendation":{"en":"Empowers agents to compare flags between channels using the `--diff` option, debug feature behavior discrepancies, and output results in CSV format for further analysis, leveraging flags like `--cleanup` for organized insights.","zh":"赋予代理比较渠道之间的标志的能力，使用 `--diff` 选项调试功能行为差异，并以 CSV 格式输出结果，以便进一步分析，利用诸如 `--cleanup` 的标志以获得有序的见解。","ja":"`--diff` オプションを使用してチャネル間のフラグを比較し、機能の動作の不一致をデバッグし、さらに分析するために CSV 形式で結果を出力し、`--cleanup` のようなフラグを使用して整理された洞察を取得するエージェントを可能にします。","ko":"`--diff` 옵션을 사용하여 채널 간의 플래그를 비교하고 기능 동작의 불일치를 디버깅하고 추가 분석을 위해 CSV 형식으로 결과를 출력하고 `--cleanup`과 같은 플래그를 사용하여 정리된 통찰력을 얻는 에이전트를 가능하게 합니다.","es":"Habilita a los agentes a comparar banderas entre canales usando la opción `--diff`, depurar discrepancias en el comportamiento de las características y salida de resultados en formato CSV para un análisis posterior, aprovechando banderas como `--cleanup` para insights organizados.","fr":"Permet aux agents de comparer des drapeaux entre les canaux en utilisant l''option `--diff`, de déboguer les disparités de comportement des fonctionnalités et de sortir les résultats au format CSV pour une analyse ultérieure, en exploitant des drapeaux comme `--cleanup` pour des insights organisés.","de":"Ermächtigt Agenten, Flags zwischen Kanälen mithilfe der Option `--diff` zu vergleichen, Abweichungen im Feature-Verhalten zu debuggen und Ergebnisse im CSV-Format für eine weitere Analyse auszugeben, indem Flags wie `--cleanup` für organisierte Einblicke genutzt werden.","pt":"Habilita os agentes a comparar flags entre canais usando a opção `--diff`, depurar discrepâncias de comportamento de recursos e produzir resultados no formato CSV para análise posterior, utilizando flags como `--cleanup` para insights organizados.","ru":"Наделяет агентов возможностью сравнивать флаги между каналами с помощью опции `--diff`, отлаживать несоответствия в поведении функций и выводить результаты в формате CSV для дальнейшего анализа, используя флаги như `--cleanup` для организованных сведений.","ar":"يمكّن العميل من مقارنة أعلام بين القنوات باستخدام خيار `--diff`، وفحص انسجام سلوك الميزات، وإخراج النتائج بترميز CSV للتحليل اللاحق، مستفيداً من أعلام مثل `--cleanup` للحصول على رؤى منظمة."},"useCases":{"en":["Comparing feature flags between OSS channels like `canary` and `next`","Debugging feature inconsistencies across Meta internal channels `www` and `www-modern`","Generating CSV reports for feature flag states using the `--csv` option"],"zh":["在 OSS 渠道（如 `canary` 和 `next`）之间比较功能标志","跨 Meta 内部渠道（如 `www` 和 `www-modern`）调试功能不一致","使用 `--csv` 选项生成功能标志状态的 CSV 报告"],"ja":["OSS チャネル（例： `canary` と `next`）間の機能フラグの比較","Meta 内部チャネル（例： `www` と `www-modern`）間の機能の不一致のデバッグ","`--csv` オプションを使用した機能フラグ状態の CSV レポートの生成"],"ko":["OSS 채널(`canary` 및 `next` 등) 간 기능 플래그 비교","Meta 내부 채널(`www` 및 `www-modern` 등) 간 기능 불일치 디버깅","`--csv` 옵션을 사용한 기능 플래그 상태 CSV 보고서 생성"],"es":["Comparar banderas de características entre canales OSS como `canary` y `next`","Depurar inconsistencias de características en canales internos de Meta `www` y `www-modern`","Generar informes CSV para estados de banderas de características usando la opción `--csv`"],"fr":["Comparer des drapeaux de fonctionnalités entre les canaux OSS tels que `canary` et `next`","Déboguer les incohérences de fonctionnalités sur les canaux internes Meta `www` et `www-modern`","Générer des rapports CSV pour les états des drapeaux de fonctionnalités en utilisant l''option `--csv`"],"de":["Vergleichen von Feature-Flags zwischen OSS-Kanälen wie `canary` und `next`","Debuggen von Feature-Inkonsistenzen über Meta-interne Kanäle `www` und `www-modern`","Erstellen von CSV-Berichten für Feature-Flag-Zustände unter Verwendung der Option `--csv`"],"pt":["Comparar flags de recursos entre canais OSS como `canary` e `next`","Depurar inconsistências de recursos em canais internos da Meta `www` e `www-modern`","Gerar relatórios CSV para estados de flags de recursos usando a opção `--csv`"],"ru":["Сравнивать флаги функций между каналами OSS, такими как `canary` и `next`","Отлаживать несоответствия функций в внутренних каналах Meta `www` и `www-modern`","Генерировать отчеты CSV для состояний флагов функций с помощью опции `--csv`"],"ar":["مقارنة أعلام الميزات بين قنوات OSS مثل `canary` و `next`","فحص انسجام الميزات عبر قنوات ميتا الداخلية `www` و `www-modern`","توليد تقارير بترميز CSV لحالات أعلام الميزات باستخدام خيار `--csv`"]},"limitations":{"en":["Requires knowledge of specific channel names like `rn`, `rn-fb`, and `rn-next`","Limited to comparing and debugging feature flags, not creating or modifying them"],"zh":["需要了解特定的渠道名称，如 `rn`、`rn-fb` 和 `rn-next`","仅限于比较和调试功能标志，不创建或修改它们"],"ja":["特定のチャネル名（例： `rn`、`rn-fb`、`rn-next`）の知識が必要","機能フラグの比較とデバッグのみに限定され、作成や変更は不可能"],"ko":["특정 채널 이름(`rn`, `rn-fb`, `rn-next` 등)에 대한 지식 필요","기능 플래그의 비교 및 디버깅만 가능하며, 생성 또는 수정은 불가능"],"es":["Requiere conocimiento de nombres de canales específicos como `rn`, `rn-fb` y `rn-next`","Limitado a la comparación y depuración de banderas de características, no a la creación o modificación de las mismas"],"fr":["Nécessite une connaissance de noms de canaux spécifiques tels que `rn`, `rn-fb` et `rn-next`","Limité à la comparaison et au débogage des drapeaux de fonctionnalités, et non à leur création ou modification"],"de":["Benötigt Kenntnisse von spezifischen Kanalnamen wie `rn`, `rn-fb` und `rn-next`","Begrenzt auf den Vergleich und das Debuggen von Feature-Flags, nicht auf deren Erstellung oder Modifizierung"],"pt":["Exige conhecimento de nomes de canais específicos como `rn`, `rn-fb` e `rn-next`","Limitado à comparação e depuração de flags de recursos, não à criação ou modificação deles"],"ru":["Требует знанияเฉพาะ названий каналов, таких как `rn`, `rn-fb` и `rn-next`","Ограничен сравнением и отладкой флагов функций, но не их созданием или изменением"],"ar":["يتطلب معرفة أسماء قنوات محددة مثل `rn` و `rn-fb` و `rn-next`","محدود بمقارنة وفحص أعلام الميزات، وليس إنشاءها أو تعديلها"]},"version":4},"contentHash":"8dfb38a708aff4cc90f633d048d9f1c556c5d4a8f15107ad60f0d8cf252dc30e","repoEtag":"W/\"7e366b67cb3bf6b132fa9e4b13c8e3f5f4a0c4e37519cb121164846325962090\"","qualityScore":76}');
