INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('facebook/react/flags', 'flags', 'facebook', 'react', 'official', 'flags facebook react official declarative frontend javascript library react ui The flags skill helps developers manage feature flag states, compare channels, and debug differences in feature behavior. It supports various channels, including www, canary, and React Native. Flags 是一个用于检查功能标志状态、比较渠道和调试的工具 Flags は機能フラグの状態を確認し、チャネルを比較し、デバッグするためのツールです Flags는 기능 플래그 상태를 확인하고 채널을 비교하며 디버깅하는 데 사용되는 툴입니다 Los flags permiten verificar estados de características y comparar canales para depurar diferencias en el comportamiento de las características Les flags permettent de vérifier les états des fonctionnalités et de comparer les canaux pour déboguer les différences dans le comportement des fonctionnalités Flags ermöglichen es, Zustände von Funktionen zu überprüfen und Kanäle zu vergleichen, um Unterschiede im Verhalten von Funktionen zu debuggen Utilize flags para comparar canais, depurar comportamentos de recursos e otimizar a experiência do usuário. Suporta React, JavaScript e bibliotecas de frontend Используйте флаги для сравнения каналов, отладки поведения функций и оптимизации пользовательского опыта. Поддерживает React, JavaScript и библиотеки frontend для ИИ Агентов استخدم الأعلام لمقارنة القنوات وتصحيح أخطاء سلوك الميزات وتحسين تجربة المستخدم. يدعم React و JavaScript و مكتبات واجهة المستخدم how to use flags flags setup guide feature flag management flags alternative flags vs feature toggles flags install what is flags flags react integration flags react native support Flags 设置 React Flags JavaScript Flags 功能标志状态 渠道比较 CSV 输出 AIエージェント Flags 调试 Show all flags across all channels using the `--diff` option Compare flags between channels with `--diff <ch1> <ch2>` Output flags in CSV format using the `--csv` option Group flags by cleanup status with `--cleanup` Supports multiple channels, including Meta internal and OSS channels Integrates with React and React Native for seamless feature flag management flags is a feature flag management system that enables developers to check flag states, compare channels, and debug feature behavior differences across release channels.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/ralphinho-rfc-pipeline', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'ralphinho-rfc-pipeline', 61988, 7678, 76, '2026-03-06T03:39:20Z', '2026-03-06T04:28:59.439Z', '3564f14e56b1af6019bbf59a7162136f4971f9884243fcb67d1229d039e3f19f', '{"id":"affaan-m/everything-claude-code/ralphinho-rfc-pipeline","name":"ralphinho-rfc-pipeline","description":{"en":"The ralphinho-rfc-pipeline skill decomposes large features into a Directed Acyclic Graph (DAG) of independently verifiable work units. It benefits developers and AI agents by managing multi-stage RFC-driven execution with quality gates and a merge queue for integration.","zh":"Ralphinho RFC Pipeline是一种RFC驱动的多智能体DAG执行模式，具有质量门、合并队列和工作单元编排功能","ja":"Ralphinho RFC Pipelineは、RFC駆動のマルチエージェントDAG実行パターンであり、品質ゲート、マージキュー、ワークユニットオーケストレーションを備えています","ko":"Ralphinho RFC Pipeline은 RFC 驱动의 멀티 에이전트 DAG 실행 패턴으로, 품질 게이트, 머지 큐, 워크 유닛 오케스트레이션 기능을 제공합니다","es":"Ralphinho-rfc-pipeline es un patrón de ejecución de DAG multiagente con puertas de calidad, colas de fusión y orquestación de unidades de trabajo","fr":"Ralphinho-rfc-pipeline est un modèle d''exécution de DAG multi-agent avec des portes de qualité, des files d''attente de fusion et une orchestration d''unités de travail","de":"Ralphinho-rfc-pipeline ist ein Muster für die Ausführung von DAG-Multiagenten mit Qualitäts gates, Merge-Warteschlangen und ArbeitsEinheiten-Orchestrierung","pt":"O ralphinho-rfc-pipeline é um padrão de execução de DAGs baseado em RFC com qualidade e orquestração de unidades de trabalho","ru":"ralphinho-rfc-pipeline - это шаблон выполнения DAG на основе RFC с качественными шлюзами и оркестровкой единиц работы","ar":"ralphinho-rfc-pipeline هو نمط تنفيذ DAG قائم على RFC مع بوابات جودة وتنسيق وحدات العمل"},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"ralphinho-rfc-pipeline","description":"RFC-driven multi-agent DAG execution pattern with quality gates, merge queues, and work unit orchestration.","bodyPreview":"# Ralphinho RFC Pipeline\n\nInspired by [humanplane](https://github.com/humanplane) style RFC decomposition patterns and multi-unit orchestration workflows.\n\nUse this skill when a feature is too large for a single agent pass and must be split into independently verifiable work units.\n\n## Pipeline Stages\n\n1. RFC intake\n2. DAG decomposition\n3. Unit assignment\n4. Unit implementation\n5. Unit validation\n6. Merge queue and integration\n7. Final system verification\n\n## Unit Spec Template\n\nEach work unit s","body":"# Ralphinho RFC Pipeline\n\nInspired by [humanplane](https://github.com/humanplane) style RFC decomposition patterns and multi-unit orchestration workflows.\n\nUse this skill when a feature is too large for a single agent pass and must be split into independently verifiable work units.\n\n## Pipeline Stages\n\n1. RFC intake\n2. DAG decomposition\n3. Unit assignment\n4. Unit implementation\n5. Unit validation\n6. Merge queue and integration\n7. Final system verification\n\n## Unit Spec Template\n\nEach work unit should include:\n- `id`\n- `depends_on`\n- `scope`\n- `acceptance_tests`\n- `risk_level`\n- `rollback_plan`\n\n## Complexity Tiers\n\n- Tier 1: isolated file edits, deterministic tests\n- Tier 2: multi-file behavior changes, moderate integration risk\n- Tier 3: schema/auth/perf/security changes\n\n## Quality Pipeline per Unit\n\n1. research\n2. implementation plan\n3. implementation\n4. tests\n5. review\n6. merge-ready report\n\n## Merge Queue Rules\n\n- Never merge a unit with unresolved dependency failures.\n- Always rebase unit branches on latest integration branch.\n- Re-run integration tests after each queued merge.\n\n## Recovery\n\nIf a unit stalls:\n- evict from active queue\n- snapshot findings\n- regenerate narrowed unit scope\n- retry with updated constraints\n\n## Outputs\n\n- RFC execution log\n- unit scorecards\n- dependency graph snapshot\n- integration risk summary\n"},"category":"official","lastSynced":"2026-03-06T04:28:59.439Z","seo":{"title":{"en":"ralphinho-rfc-pipeline: RFC-Driven Multi-Agent DAG Execut...","zh":"Ralphinho RFC Pipeline 介绍：AIエージェント工作流优化","ja":"Ralphinho RFC Pipeline Setup Guide: AIエージェントを活用した開発プロセス","ko":"Ralphinho RFC Pipeline 구축 가이드: AI 에이전트를 활용한 개발 워크플로우","es":"Guía de configuración de ralphinho-rfc-pipeline para Agen...","fr":"Mise en place de ralphinho-rfc-pipeline pour les outils d''IA","de":"Einrichtungsleitfaden für ralphinho-rfc-pipeline in KI-Ag...","pt":"Guia de Configuração do ralphinho-rfc-pipeline para Desen...","ru":"Настройка ralphinho-rfc-pipeline: ИИ Агенты для Разработч...","ar":"دليل إعداد ralphinho-rfc-pipeline لتنفيذ أنماط DAG المتعددة"},"description":{"en":"Implement complex features with AI agents using the ralphinho-rfc-pipeline. This skill orchestrates RFC-driven DAG workflows with quality gates & a merge que...","zh":"了解Ralphinho RFC Pipeline的技术细节，优化AIエージェント工作流，提高开发效率","ja":"Ralphinho RFC Pipelineを使用してAIエージェントを活用した開発プロセスを最適化する","ko":"Ralphinho RFC Pipeline을 사용하여 AI 에이전트를 활용한 개발 워크플로우를 최적화하는 방법","es":"Aprende a implementar ralphinho-rfc-pipeline para mejorar la productividad con patrones de descomposición de RFC y flujos de trabajo de orquestación de unidades","fr":"Découvrez comment mettre en place ralphinho-rfc-pipeline pour améliorer la productivité avec des modèles de décomposition de RFC et des flux de travail d''orc...","de":"Erfahren Sie, wie Sie ralphinho-rfc-pipeline einrichten, um die Produktivität mit RFC-Zerlegungsmustern und Arbeitsfluss-Orchestrierung zu verbessern","pt":"Aprenda a configurar o ralphinho-rfc-pipeline para execução de DAGs com qualidade e orquestração de unidades de trabalho","ru":"Узнайте, как настроить ralphinho-rfc-pipeline для выполнения DAG с качественными шлюзами и оркестровкой единиц работы","ar":"تعرف على كيفية إعداد ralphinho-rfc-pipeline لتنفيذ أنماط DAG المتعددة مع بوابات جودة وتنسيق وحدات العمل"},"definition":{"en":"ralphinho-rfc-pipeline is an AI agent skill that implements an RFC-driven multi-agent DAG execution pattern. It breaks down large features into smaller, managed work units, orchestrating them through stages including decomposition, unit assignment, implementation, validation, and integration via a merge queue.","zh":"Ralphinho RFC Pipeline是一种AIエージェント工作流优化工具，用于分解大型功能并提高开发效率","ja":"Ralphinho RFC Pipelineは、AIエージェントを活用した開発プロセスを最適化するためのツールであり、大規模な機能を分解して開発効率を向上させる","ko":"Ralphinho RFC Pipeline은 AI 에이전트를 활용한 개발 워크플로우를 최적화하는 도구로, 대형 기능을 분해하여 개발 효율을 향상시킵니다","es":"Ralphinho-rfc-pipeline es un patrón de ejecución de DAG que permite la descomposición de características en unidades de trabajo independientes","fr":"Ralphinho-rfc-pipeline est un modèle d''exécution de DAG qui permet la décomposition de fonctionnalités en unités de travail indépendantes","de":"Ralphinho-rfc-pipeline ist ein Muster für die Ausführung von DAG, das die Zerlegung von Funktionen in unabhängige ArbeitsEinheiten ermöglicht","pt":"O ralphinho-rfc-pipeline é um padrão de execução de DAGs que permite a decomposição de recursos em unidades de trabalho independentes","ru":"ralphinho-rfc-pipeline - это шаблон выполнения DAG, позволяющий декомпозировать ресурсы на независимые единицы работы","ar":"ralphinho-rfc-pipeline هو نمط تنفيذ DAG يسمح بتفكيك الموارد إلى وحدات عمل مستقلة"},"features":{"en":["RFC intake for initial feature specification and requirements gathering","DAG decomposition to break down features into a graph of dependent work units","Unit assignment for distributing work units to individual AI agents","Unit validation as a quality gate for each independently verifiable work unit","Merge queue and integration stage for combining validated units","Final system verification to ensure the complete integrated feature meets requirements"],"zh":["RFC驱动的多智能体DAG执行模式","质量门和合并队列功能","工作单元编排和分解","DAG分解和单元分配","单元实现和验证","最终系统验证"],"ja":["RFC駆動のマルチエージェントDAG実行パターン","品質ゲートとマージキュー機能","ワークユニットオーケストレーションと分解","DAG分解とユニット割り当て","ユニット実装と検証","最終システム検証"],"ko":["RFC 驱动의 멀티 에이전트 DAG 실행 패턴","품질 게이트와 머지 큐 기능","워크 유닛 오케스트레이션과 분해","DAG 분해와 유닛 할당","유닛 구현과 검증","최종 시스템 검증"],"es":["Patrón de ejecución de DAG multiagente","Descomposición de características en unidades de trabajo independientes","Puertas de calidad para garantizar la calidad del código","Colas de fusión para integrar unidades de trabajo","Orquestación de unidades de trabajo para mejorar la productividad","Integración con herramientas de desarrollo como CLI"],"fr":["Modèle d''exécution de DAG multi-agent","Décomposition de fonctionnalités en unités de travail indépendantes","Portes de qualité pour garantir la qualité du code","Files d''attente de fusion pour intégrer des unités de travail","Orchestration d''unités de travail pour améliorer la productivité","Intégration avec des outils de développement comme CLI"],"de":["Muster für die Ausführung von DAG-Multiagenten","Zerlegung von Funktionen in unabhängige ArbeitsEinheiten","Qualitäts gates für die Sicherstellung der Code-Qualität","Merge-Warteschlangen für die Integration von ArbeitsEinheiten","ArbeitsEinheiten-Orchestrierung für die Steigerung der Produktivität","Integration mit Entwicklungstools wie CLI"],"pt":["Execução de DAGs com qualidade e orquestração de unidades de trabalho","Decomposição de recursos em unidades de trabalho independentes","Integração de unidades de trabalho com merge queues e verificação final do sistema","Suporte a multi-agentes e padrões de decomposição de RFC","Orquestração de unidades de trabalho com qualidade e eficiência"],"ru":["Выполнение DAG с качественными шлюзами и оркестровкой единиц работы","Декомпозиция ресурсов на независимые единицы работы","Интеграция единиц работы с очередями слияния и окончательной проверкой системы","Поддержка 多 агентов и шаблонов декомпозиции RFC","Оркестровка единиц работы с качеством и эффективностью"],"ar":["تنفيذ أنماط DAG مع بوابات جودة وتنسيق وحدات العمل","تفكيك الموارد إلى وحدات عمل مستقلة","دمج وحدات العمل مع طوابير الدمج والتحقق النهائي من النظام","دعم_multi-وكلاء و أنماط تفكيك RFC","تنسيق وحدات العمل مع جودة و كفاءة"]},"keywords":{"en":["what is ralphinho-rfc-pipeline","how to use ralphinho-rfc-pipeline for DAG execution","ralphinho-rfc-pipeline vs humanplane","RFC multi-agent DAG pattern","ralphinho-rfc-pipeline install","ralphinho-rfc-pipeline setup guide","AI agent merge queue implementation","work unit orchestration with quality gates"],"zh":["Ralphinho RFC Pipeline","AIエージェント","开发工作流","RFC驱动","DAG执行","质量门","合并队列","工作单元编排"],"ja":["Ralphinho RFC Pipeline","AIエージェント","開発プロセス","RFC駆動","DAG実行","品質ゲート","マージキュー","ワークユニットオーケストレーション"],"ko":["Ralphinho RFC Pipeline","AI 에이전트","개발 워크플로우","RFC 驱动","DAG 실행","품질 게이트","머지 큐","워크 유닛 오케스트레이션"],"es":["ralphinho-rfc-pipeline","Agentes de IA","patrones de descomposición de RFC","flujos de trabajo de orquestación de unidades","puertas de calidad","colas de fusión","desarrollo de software","productividad","herramientas de desarrollo"],"fr":["ralphinho-rfc-pipeline","outils d''IA","modèles de décomposition de RFC","flux de travail d''orchestration d''unités","portes de qualité","files d''attente de fusion","développement de logiciels","productivité","outils de développement"],"de":["ralphinho-rfc-pipeline","KI-Agents","Muster für die Zerlegung von RFC","Arbeitsfluss-Orchestrierung","Qualitäts gates","Merge-Warteschlangen","Softwareentwicklung","Produktivität","Entwicklungstools"],"pt":["ralphinho-rfc-pipeline","execução de DAGs","orquestração de unidades de trabalho","qualidade e eficiência","desenvolvimento de software","ferramentas de desenvolvimento","AI agents","padrões de decomposição de RFC"],"ru":["ralphinho-rfc-pipeline","выполнение DAG","оркестровка единиц работы","качество и эффективность","разработка программного обеспечения","инструменты разработки","ИИ Агенты","шаблоны декомпозиции RFC"],"ar":["ralphinho-rfc-pipeline","تنفيذ أنماط DAG","تنسيق وحدات العمل","جودة و كفاءة","تطوير البرمجيات","أدوات التطوير","وكلاء الذكاء الاصطناعي","أنماط تفكيك RFC"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Complex Task Agents requiring multi-agent DAG execution and quality gate management","zh":"非常适合需要多智能体 DAG 执行和质量门管理的复杂任务智能体","ja":"マルチエージェント DAG 実行と品質ゲート管理を必要とする複雑なタスクエージェントに最適","ko":"다중 에이전트 DAG 실행 및 품질 게이트 관리가 필요한 복잡한 작업 에이전트에 이상적","es":"Ideal para Agentes de Tareas Complejas que requieren ejecución de DAG multiagente y gestión de puertas de calidad","fr":"Idéal pour les agents de tâches complexes nécessitant une exécution de DAG multiagent et une gestion de portes de qualité","de":"Ideal für komplexe Task-Agents, die eine Multiagent-DAG-Ausführung und QualitätsTor-Verwaltung erfordern","pt":"Ideal para Agentes de Tarefas Complexas que exigem execução DAG multiagente e gerenciamento de portões de qualidade","ru":"Идеально подходит для сложных агентов задач, требующих выполнения многоагентного DAG и управления контрольными точками качества","ar":"مثالي لوكلاء المهام المعقدة التي تتطلب تنفيذ DAG متعدد الوكلاء وإدارة بوابات الجودة"},"recommendation":{"en":"Empowers agents to execute RFC-driven workflows with merge queues, unit orchestration, and final system verification using DAG decomposition and unit assignment, enabling seamless integration of independently verifiable work units","zh":"使智能体能够通过 DAG 分解和单元分配，执行具有合并队列、单元编排和最终系统验证的 RFC 驱动工作流，从而实现可独立验证工作单元的无缝集成","ja":"DAG 分解とユニット割り当てを使用して、マージキュー、ユニットオーケストレーション、および最終的なシステム検証を備えた RFC 駆動ワークフローを実行する機能をエージェントに付与し、独立して検証可能な作業単位のシームレスな統合を可能にします","ko":"DAG 분해 및 유닛 할당을 사용하여 병합 큐, 유닛 오케스트레이션 및 최종 시스템 검증을 갖춘 RFC 기반 워크플로우를 실행할 수 있도록 에이전트에 권한을 부여하여 독립적으로 검증 가능한 작업 단위의 원활한 통합을 가능하게 합니다","es":"Habilita a los agentes a ejecutar flujos de trabajo impulsados por RFC con colas de combinación, orquestación de unidades y verificación final del sistema utilizando descomposición de DAG y asignación de unidades, lo que permite una integración fluida de unidades de trabajo verificables de forma independiente","fr":"Permet aux agents d''exécuter des flux de travail pilotés par RFC avec des files d''attente de fusion, une orchestration d''unités et une vérification finale du système en utilisant une décomposition de DAG et une affectation d''unités, ce qui permet une intégration fluide d''unités de travail vérifiables de manière indépendante","de":"Ermächtigt Agents, RFC-getriebene Workflows mit Merge-Warteschlangen, Einheits-Orchestrierung und abschließender Systemverifizierung unter Verwendung von DAG-Zerlegung und Einheitszuweisung auszuführen, wodurch eine nahtlose Integration von unabhängig überprüfbarer ArbeitsEinheiten ermöglicht wird","pt":"Capacita os agentes a executar fluxos de trabalho orientados por RFC com filas de merge, orquestração de unidades e verificação final do sistema usando decomposição DAG e atribuição de unidades, permitindo uma integração perfeita de unidades de trabalho independentemente verificáveis","ru":"Позволяет агентам выполнять рабочие процессы на основе RFC с очередями слияния, оркестровкой модулей и окончательной проверкой системы с использованием декомпозиции DAG и назначения модулей, обеспечивая беспрепятственную интеграцию независимо проверяемых рабочих единиц","ar":"يمكن الوكلاء من تنفيذ مهام سير العمل المعتمدة على RFC مع قوائم الانتظار للدمج، وتنسيق الوحدات، والتحقق النهائي من النظام باستخدام تحلل DAG وتعيين الوحدات، مما يتيح تكاملًا سلسًا لوحدات العمل القابلة للتحقق بشكل مستقل"},"useCases":{"en":["Decomposing large features into manageable work units","Orchestrating multi-unit workflows with quality gates and merge queues","Validating and integrating independently developed work units"],"zh":["将大型功能分解为可管理的工作单元","通过质量门和合并队列编排多单元工作流","验证和集成独立开发的工作单元"],"ja":["大規模な機能を管理可能な作業単位に分解","品質ゲートとマージキューを使用したマルチユニットワークフローのオーケストレーション","独立して開発された作業単位の検証と統合"],"ko":["대규모 기능을 관리 가능한 작업 단위로 분해","품질 게이트 및 병합 큐를 사용한 다중 유닛 워크플로우 오케스트레이션","독립적으로 개발된 작업 단위의 검증 및 통합"],"es":["Descomponer funciones grandes en unidades de trabajo manejables","Orquestar flujos de trabajo multiunidad con puertas de calidad y colas de combinación","Validar e integrar unidades de trabajo desarrolladas de forma independiente"],"fr":["Décomposer les grandes fonctionnalités en unités de travail gérables","Orchestrer des flux de travail multiunités avec des portes de qualité et des files d''attente de fusion","Valider et intégrer des unités de travail développées de manière indépendante"],"de":["Große Funktionen in handhabbare ArbeitsEinheiten zerlegen","Multi-Einheits-Workflows mit Qualitäts-Toren und Merge-Warteschlangen orchestrieren","Unabhängig entwickelte ArbeitsEinheiten validieren und integrieren"],"pt":["Decompor grandes funcionalidades em unidades de trabalho gerenciáveis","Orquestrar fluxos de trabalho multiunidade com portões de qualidade e filas de merge","Validar e integrar unidades de trabalho desenvolvidas independentemente"],"ru":["Декомпозиция крупных функций в управляемые рабочие единицы","Оркестрация многомодульных рабочих процессов с контрольными точками качества и очередями слияния","Проверка и интеграция независимо разработанных рабочих единиц"],"ar":["تحليل الميزات الكبيرة إلى وحدات عمل قابلة للإدارة","تنسيق مهام سير العمل متعددة الوحدات مع بوابات الجودة وقوائم الانتظار للدمج","التحقق من وحدات العمل المطورة بشكل مستقل ودمجها"]},"limitations":{"en":["Requires feature decomposition into independently verifiable work units","Dependent on RFC-driven workflow management"],"zh":["需要将功能分解为可独立验证的工作单元","依赖于 RFC 驱动的工作流管理"],"ja":["機能を独立して検証可能な作業単位に分解する必要がある","RFC 駆動のワークフロー管理に依存"],"ko":["기능을 독립적으로 검증 가능한 작업 단위로 분해해야 함","RFC 기반 워크플로우 관리에 의존"],"es":["Requiere descomposición de características en unidades de trabajo verificables de forma independiente","Depende de la gestión de flujos de trabajo impulsada por RFC"],"fr":["Nécessite une décomposition de fonctionnalités en unités de travail vérifiables de manière indépendante","Dépend de la gestion de flux de travail pilotée par RFC"],"de":["Benötigt Zerlegung von Funktionen in unabhängig überprüfbare ArbeitsEinheiten","Hängt von der RFC-getriebenen Workflow-Verwaltung ab"],"pt":["Requer a decomposição de funcionalidades em unidades de trabalho independentemente verificáveis","Dependente do gerenciamento de fluxo de trabalho orientado por RFC"],"ru":["Требует декомпозиции функций на независимо проверяемые рабочие единицы","Зависит от управления рабочими процессами на основе RFC"],"ar":["يتطلب تحليل الميزات إلى وحدات عمل قابلة للتحقق بشكل مستقل","يعتمد على إدارة سير العمل المعتمدة على RFC"]},"version":4},"contentHash":"3564f14e56b1af6019bbf59a7162136f4971f9884243fcb67d1229d039e3f19f","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":76}');
