INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pedrohcgs/claude-code-my-workflow/learn', 'learn', 'pedrohcgs', 'claude-code-my-workflow', 'community', 'learn pedrohcgs claude-code-my-workflow community The learn skill enables academics to extract non-obvious discoveries into reusable skills using LaTeX/Beamer + R. It benefits researchers and developers who need to document complex workflows. Learn 技能是一种可用于学术的 Claude Code 模板，支持 LaTeX/Beamer + R 多代理审查，质量门、对抗性 QA 和复制协议 Learn スキルは学術向けの Claude Code テンプレートで、LaTeX/Beamer + R マルチエージェントレビュー、品質ゲート、対抗的 QA、複製プロトコルをサポート Learn 스킬은 학술용 Claude Code 템플릿으로 LaTeX/Beamer + R 멀티 에이전트 리뷰, 품질 게이트, 대응 QA, 복제 프로토콜을 지원 El aprendizaje automático con Claude Code es una plantilla lista para usarse que combina LaTeX/Beamer + R para académicos. Ofrece revisiones multiagente, puertas de calidad, pruebas de adversarios y protocolos de replicación. L''apprentissage automatique avec Claude Code est un modèle prêt à l''emploi qui combine LaTeX/Beamer + R pour les universitaires. Il propose des examens multi-agents, des portes de qualité, des tests d''adversaires et des protocoles de réplication. Das maschinelle Lernen mit Claude Code ist eine bereit zur Verwendung stehende Vorlage, die LaTeX/Beamer + R für Akademiker kombiniert. Es bietet Multi-Agenten-Überprüfungen, Qualitäts-Tore, Adversarial-Tests und Replikationsprotokolle. O skill Learn é um modelo de código Claude pronto para ser usado por acadêmicos com LaTeX/Beamer + R, permitindo revisão multi-agente e protocolos de replicação Навык Learn — это готовый шаблон кода Claude для академиков с LaTeX/Beamer + R, обеспечивающий многоагентную проверку и протоколы репликации ИИ Агентов مهارة التعلم هي قوالب شفرة كلود مُعدة للاستخدام من قبل الأكاديميين مع LaTeX/Beamer + R ، مما يسمح بالاستعراض متعدد الوكلاء وبروتوكولات التكرار how to use learn skill what is learn ai agent learn alternative for researchers learn vs other skill extraction tools learn install guide for academics learn setup for LaTeX/Beamer + R learn skill for multi-agent review learn workflow for adversarial QA Learn 技能 LaTeX/Beamer + R 多代理审查 质量门 对抗性 QA 复制协议 非显而易见的发现 可重用的技能 Extracts non-obvious discoveries into reusable skills using LaTeX/Beamer + R Supports multi-agent review and quality gates for collaborative research Utilizes adversarial QA and replication protocols for rigorous testing Enables trial-and-error experimentation with undocumented API usage Facilitates workaround implementation for creative problem-solving learn is a Claude Code template for extracting non-obvious discoveries into reusable skills that persist across sessions');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Soju06/codex-lb/codex-review-loop', 'community', 'Soju06', 'codex-lb', 'Soju06/codex-lb', 'codex-review-loop', 121, 27, 75, '2026-03-01T00:14:23Z', '2026-03-06T06:30:47.996Z', 'f1017c1e026ac4526ee32af49b67e02bc445a02bcc99dc06ee0c1ab48a98e29d', '{"id":"Soju06/codex-lb/codex-review-loop","name":"codex-review-loop","description":{"en":"The codex-review-loop skill provides a load balancer and proxy for Codex/ChatGPT accounts, with usage tracking and a dashboard. It benefits developers by automating adversarial code review via Codex CLI.","zh":"Codex Review Loop 是一个 Codex/ChatGPT 账户负载均衡器和代理，具有使用追踪、仪表盘和 OpenCode 兼容端点","ja":"Codex Review Loop は、Codex/ChatGPT アカウントのロードバランサーとプロキシであり、使用状況の追跡、ダッシュボード、OpenCode 互換エンドポイントを備えています","ko":"Codex Review Loop는 Codex/ChatGPT 계정의 로드 밸런서 및 프록시로, 사용 추적, 대시보드 및 OpenCode 호환 엔드포인트를 제공합니다","es":"Codex Review Loop es una herramienta de revisión de código que utiliza Codex CLI y ofrece funcionalidades como balanceador de carga y seguimiento de uso","fr":"Codex Review Loop est un outil de revue de code qui utilise Codex CLI et offre des fonctionnalités comme équilibreur de charge et suivi d''utilisation","de":"Codex Review Loop ist ein Code-Review-Tool, das Codex CLI verwendet und Funktionen wie Lastenausgleich und Nutzungsverfolgung bietet","pt":"O Codex Review Loop é uma ferramenta de revisão de código que utiliza o Codex CLI e oferece recursos como proxy de API, balanceamento de carga e rastreamento de uso.","ru":"Codex Review Loop - это инструмент кодового обзора, использующий Codex CLI и предлагающий функции, такие как прокси API, балансировка нагрузки и отслеживание использования.","ar":"حلقة مراجعة Codex هي أداة مراجعة الكود التي تستخدم Codex CLI وتقدم ميزات مثل وكيل API وتنظيم الحمل ومراقبة الاستخدام."},"seo":{"title":{"en":"codex-review-loop: Adversarial Code Review Setup Guide | ...","zh":"Codex Review Loop 设置指南 - AI代理负载均衡与追踪","ja":"Codex Review Loop 導入ガイド - AIエージェントのロードバランサーとトラッキング","ko":"Codex Review Loop 설정 가이드 - AI 에이전트 로드 밸런서 및 추적","es":"Configuración de Codex Review Loop: Guía de Implementació...","fr":"Mise en Place de Codex Review Loop : Guide de Configurati...","de":"Einrichtung von Codex Review Loop: Anleitung für API-Prox...","pt":"Guia de Configuração do Codex Review Loop para Desenvolve...","ru":"Настройка Codex Review Loop: ИИ Агенты для Разработчиков","ar":"إعداد حلقة مراجعة Codex: أدوات ذكاء اصطناعي للطورين"},"description":{"en":"Streamline your code review process with codex-review-loop, featuring OAuth, rate-limiting, and OpenCode-compatible endpoints. Get started now!","zh":"了解 Codex Review Loop 的功能和特点，包括负载均衡、追踪和 OpenCode 兼容端点","ja":"Codex Review Loop の機能と特徴について紹介します。ロードバランサー、トラッキング、OpenCode 互換エンドポイントなど","ko":"Codex Review Loop의 기능과 특징에 대해 알아보세요. 로드 밸런서, 추적, OpenCode 호환 엔드포인트 등","es":"Descubre cómo configurar Codex Review Loop para una revisión de código adversarial eficiente con tecnologías como FastAPI y SQLAlchemy","fr":"Découvrez comment configurer Codex Review Loop pour une revue de code adverse efficace avec des technologies comme FastAPI et SQLAlchemy","de":"Erfahren Sie, wie Sie Codex Review Loop für eine effiziente adversarial Code-Review mit Technologien wie FastAPI und SQLAlchemy einrichten","pt":"Aprenda a configurar o Codex Review Loop com proxy de API, balanceamento de carga e rastreamento de uso para melhorar a eficiência do desenvolvimento","ru":"Узнайте, как настроить Codex Review Loop с прокси API, балансировкой нагрузки и отслеживанием использования для повышения эффективности разработки","ar":"تعرف على كيفية إعداد حلقة مراجعة Codex مع وكيل API وتنظيم الحمل ومراقبة الاستخدام لتحسين كفاءة التطوير"},"definition":{"en":"codex-review-loop is a Python-based API proxy and load balancer with usage tracking, dashboard, and OpenCode-compatible endpoints for Codex/ChatGPT accounts.","zh":"Codex Review Loop 是一种 AI 代理技术，用于负载均衡和追踪","ja":"Codex Review Loop は、AI エージェント技術の一種で、ロードバランサーとトラッキングに使用されます","ko":"Codex Review Loop는 로드 밸런서 및 추적에 사용되는 AI 에이전트 기술입니다","es":"Codex Review Loop es un agente de AI que actúa como proxy y balanceador de carga para la revisión de código","fr":"Codex Review Loop est un agent IA qui agit comme proxy et équilibreur de charge pour la revue de code","de":"Codex Review Loop ist ein KI-Agent, der als Proxy und Lastenausgleich für die Code-Review fungiert","pt":"O que é Codex Review Loop? É uma ferramenta de revisão de código que utiliza o Codex CLI para revisar e analisar o código.","ru":"Что такое Codex Review Loop? Это инструмент кодового обзора, использующий Codex CLI для обзора и анализа кода.","ar":"ما هي حلقة مراجعة Codex؟ هي أداة مراجعة الكود التي تستخدم Codex CLI لمراجعة وتحليل الكود."},"features":{"en":["Launches adversarial review via Codex CLI with optional re-verification","Supports rate-limiting and OAuth for secure authentication","Provides a dashboard for usage tracking and monitoring","Utilizes SQLAlchemy for database management","Compatible with OpenCode endpoints for seamless integration","Allows for review of uncommitted local changes with --uncommitted flag"],"zh":["负载均衡和追踪","OpenCode 兼容端点","使用 FastAPI 和 SQLAlchemy","支持 OAuth 和 rate-limit","仪表盘和使用情况追踪","Codex CLI 集成"],"ja":["ロードバランサーとトラッキング","OpenCode 互換エンドポイント","FastAPI と SQLAlchemy を使用","OAuth と rate-limit をサポート","ダッシュボードと使用状況の追跡","Codex CLI 統合"],"ko":["로드 밸런서 및 추적","OpenCode 호환 엔드포인트","FastAPI 및 SQLAlchemy 사용","OAuth 및 rate-limit 지원","대시보드 및 사용 상황 추적","Codex CLI 통합"],"es":["Balanceador de carga y proxy para la revisión de código","Seguimiento de uso y panel de control","Compatibilidad con OpenCode","Integración con FastAPI y SQLAlchemy","Revisión de código adversarial via Codex CLI","Soporte para autenticación OAuth"],"fr":["Équilibreur de charge et proxy pour la revue de code","Suivi d''utilisation et tableau de bord","Compatibilité avec OpenCode","Intégration avec FastAPI et SQLAlchemy","Revue de code adverse via Codex CLI","Support de l''authentification OAuth"],"de":["Lastenausgleich und Proxy für die Code-Review","Nutzungsverfolgung und Dashboard","Kompatibilität mit OpenCode","Integration mit FastAPI und SQLAlchemy","Adversarial Code-Review via Codex CLI","Unterstützung für OAuth-Authentifizierung"],"pt":["Proxy de API para gerenciar requisições","Balanceamento de carga para melhorar a eficiência","Rastreamento de uso para monitorar a atividade","Compatibilidade com OpenCode","Suporte a FastAPI e SQLAlchemy","Revisão de código via Codex CLI"],"ru":["Прокси API для управления запросами","Балансировка нагрузки для повышения эффективности","Отслеживание использования для мониторинга активности","Совместимость с OpenCode","Поддержка FastAPI и SQLAlchemy","Обзор кода через Codex CLI"],"ar":["وكيل API لإدارة الطلبات","تنظيم الحمل لتحسين الكفاءة","مراقبة الاستخدام لمراقبة النشاط","التوافق مع OpenCode","دعم FastAPI و SQLAlchemy","مراجعة الكود عبر Codex CLI"]},"keywords":{"en":["how to use codex-review-loop","codex-review-loop setup guide","codex-review-loop vs load balancer","codex-review-loop install","what is codex-review-loop","codex-review-loop alternative","codex-review-loop and OpenCode","codex-review-loop API proxy","codex-review-loop OAuth setup","codex-review-loop rate limiting"],"zh":["AI 代理","Codex Review Loop","负载均衡","追踪","OpenCode","FastAPI","SQLAlchemy","OAuth","rate-limit","Codex CLI"],"ja":["AI エージェント","Codex Review Loop","ロードバランサー","トラッキング","OpenCode","FastAPI","SQLAlchemy","OAuth","rate-limit","Codex CLI"],"ko":["AI 에이전트","Codex Review Loop","로드 밸런서","추적","OpenCode","FastAPI","SQLAlchemy","OAuth","rate-limit","Codex CLI"],"es":["agente de AI","herramienta de revisión de código","balanceador de carga","proxy","Codex CLI","FastAPI","SQLAlchemy","OpenCode","autenticación OAuth","seguimiento de uso"],"fr":["agent IA","outils de revue de code","équilibreur de charge","proxy","Codex CLI","FastAPI","SQLAlchemy","OpenCode","authentification OAuth","suivi d''utilisation"],"de":["KI-Agent","Code-Review-Tool","Lastenausgleich","Proxy","Codex CLI","FastAPI","SQLAlchemy","OpenCode","OAuth-Authentifizierung","Nutzungsverfolgung"],"pt":["Codex Review Loop","revisão de código","proxy de API","balanceamento de carga","rastreamento de uso","OpenCode","FastAPI","SQLAlchemy","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Codex Review Loop","обзор кода","прокси API","балансировка нагрузки","отслеживание использования","OpenCode","FastAPI","SQLAlchemy","разработка программного обеспечения","инструменты разработки"],"ar":["حلقة مراجعة Codex","مراجعة الكود","وكيل API","تنظيم الحمل","مراقبة الاستخدام","OpenCode","FastAPI","SQLAlchemy","تطوير البرمجيات","أدوات التطوير"]}},"owner":"Soju06","repo":"codex-lb","repoPath":"Soju06/codex-lb","stars":121,"forks":27,"updatedAt":"2026-03-01T00:14:23Z","topics":["api-proxy","chatgpt","codex","dashboard","fastapi","load-balancer","oauth","openai","opencode","python","rate-limit","sqlalchemy","usage-tracking"],"category":"community","skillMd":{"name":"codex-review-loop","description":"|","version":"2.0.0","bodyPreview":"# Codex Review Loop\n\nAdversarial code review via Codex CLI, structured finding analysis,\nHITL-gated fix loop, optional re-verification.\n\n## Arguments\n\n- `--pr <N>` — review PR number N (default: auto-detect most recent open PR)\n- `--base <branch>` — review changes against base branch\n- `--uncommitted` — review uncommitted local changes\n\n## Phases\n\n1. **Scope Resolution** — determine review target (PR/branch/uncommitted)\n2. **Codex Review** — launch adversarial review via Codex CLI (~20-50 min)\n3","body":"# Codex Review Loop\n\nAdversarial code review via Codex CLI, structured finding analysis,\nHITL-gated fix loop, optional re-verification.\n\n## Arguments\n\n- `--pr <N>` — review PR number N (default: auto-detect most recent open PR)\n- `--base <branch>` — review changes against base branch\n- `--uncommitted` — review uncommitted local changes\n\n## Phases\n\n1. **Scope Resolution** — determine review target (PR/branch/uncommitted)\n2. **Codex Review** — launch adversarial review via Codex CLI (~20-50 min)\n3. **Finding Analysis** — parse raw output into structured findings\n4. **Atomic Fix Loop** — fix, verify, commit each approved finding\n5. **Re-review Loop** — re-run review until 0 findings (max 3 iterations)\n6. **Final Report** — summary of all findings, fixes, and verification status\n\n---\n\n## Phase 1: Scope Resolution\n\nDetermine the review target and extract the base branch.\n\n- **PR mode** (default): Use `gh pr view` / `gh pr list` to resolve base branch\n  and display PR metadata (title, file count, additions/deletions).\n- **Branch mode** (`--base`): Use specified base branch directly.\n- **Uncommitted mode** (`--uncommitted`): Review working tree changes.\n\nIf no argument is given, auto-detect the user''s most recent open PR and confirm.\n\n---\n\n## Phase 2: Codex Review\n\nLaunch the adversarial review as a background process.\n\n1. Run the review script with `run_in_background=true`:\n   ```\n   bash <skill-dir>/scripts/codex-subagent.sh --base <branch>\n   ```\n   Note: Codex CLI v0.105.0+ does not support combining `--base`/`--commit`\n   with a custom prompt. The built-in review logic is used automatically.\n   For `--uncommitted` mode (no diff target), pipe stdin for custom instructions:\n   ```\n   cat <prompt-file> | bash <skill-dir>/scripts/codex-subagent.sh --uncommitted\n   ```\n2. Inform the user the review is running (~20-50 min).\n3. The script parses Codex output and returns the final review text.\n\n### Error handling\n\n| Exit code | Meaning | Action |\n|-----------|---------|--------|\n| 0 | Success | Proceed to Phase 3 |\n| 1 | Codex error | Show error, offer retry or abort |\n| 127 | codex not found | Guide: `npm i -g @openai/codex` |\n\n### Environment overrides\n\n| Variable | Purpose |\n|----------|---------|\n| `CODEX_REVIEW_MODEL` | Override Codex model |\n| `CODEX_REVIEW_REASONING` | Override reasoning effort |\n\n---\n\n## Phase 3: Finding Analysis\n\nParse the raw Codex output into structured findings.\n\n### References\n\n- **Schema**: `references/schemas/review-findings.md` — field definitions,\n  severity/category/effort enums, status lifecycle\n- **Convention rules**: `.agents/skills/project-conventions/conventions.md` —\n  project coding conventions to cross-reference\n\n### Severity escalation/downgrade guide\n\n- **Escalate to Critical**: Unvalidated external input, secret exposure,\n  injection vectors, data integrity compromise\n- **Escalate to High**: API contract change without test update, possible\n  NoneType error, blocking I/O in async context\n- **Downgrade to Medium**: Correct functionality but violates conventions,\n  duplicate logic, unnecessary complexity\n- **Downgrade to Low**: Pure style, unused import, missing docstring\n\n### Convention-to-category mapping\n\n- Typing violations (dict, Mapping, object, getattr) -> `typing`\n- Anti-patterns (speculative fallbacks, duplicate state) -> `convention`\n- Structure violations (core/modules boundary, DI bypass) -> `architecture`\n- Testing gaps (contract change without test update) -> `testing`\n\n### Process\n\n1. Parse each finding from the raw output\n2. Assign severity and category using the schema definitions and guide above\n3. Cross-reference with project conventions\n4. Estimate fix effort\n5. Deduplicate (keep the most severe instance)\n6. Sort: severity desc, file path asc\n\n---\n\n## HITL Gate 1: Finding Review\n\nPresent all findings to the user as a summary table\n(ID, severity, category, file:line, title, effort).\n\nAsk the user to choose a fix scope:\n- Fix all (recommended)\n- Fix Critical/High only\n- Report only (no fixes)\n\n---\n\n## Phase 4: Atomic Fix Loop\n\nFor each approved finding, execute an atomic fix-verify-commit cycle.\n\n### Per finding:\n\n1. **Fix**: Read target file(s), apply the fix.\n2. **HITL Gate 2** (conditional): For Critical/High findings that modify existing\n   logic (not just adding new code), show the current and proposed code to the\n   user for confirmation. Medium/Low findings are auto-fixed.\n3. **Verify** (all must pass):\n   - `uvx ruff check .`\n   - `uvx ruff format --check .` (auto-fix and re-check if needed)\n   - `uv run ty check`\n   - `uv run pytest` (mapped test files, or full suite if no mapping found)\n4. **Commit**: `fix(review): P{i} - {title}`\n5. **On failure**: Roll back changes, mark finding as `skipped`, continue to next.\n\n---\n\n## Phase 5: Re-review Loop\n\nAfter all fixes are committed, automatically re-run the Codex review\nto check for regressions or new issues introduced by the fixes.\n\n### Loop behaviour\n\n1. Re-run Codex review (`--base <branch>`) against the same base.\n2. Parse findings (Phase 3) and present to user (HITL Gate 1).\n3. If **0 findings** → loop terminates, proceed to Final Report.\n4. If findings exist → execute Phase 4 (fix-verify-commit), then repeat\n   from step 1.\n\n### Safety limits\n\n- **Max iterations**: 3 (initial review + 2 re-reviews).\n  After 3 iterations, terminate the loop regardless of remaining findings\n  and output the Final Report with unresolved items noted.\n- **Escalation**: If the same finding recurs across 2 consecutive iterations,\n  mark it as `wont_fix` and skip in subsequent iterations.\n\n### HITL override\n\nAt each re-review result, the user may choose:\n- **Continue** — proceed with fixes (default when findings > 0)\n- **Stop** — terminate the loop early and output Final Report\n\n---\n\n## Final Report\n\nOutput a summary including:\n- PR metadata (number, title, base/head)\n- Loop iteration count and termination reason (clean / max iterations / user stop)\n- Findings table (ID, severity, category, title, status, commit hash)\n- Commit stack\n- Verification status (ruff, ty, pytest)\n"},"lastSynced":"2026-03-06T06:30:47.996Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing automated adversarial code review via Codex CLI","zh":"适用于像 Cursor、Windsurf 和 Claude Code 这样的 AI Agent，需要通过 Codex CLI 进行自动化对抗性代码审查","ja":"Cursor、Windsurf、Claude Code などの AI エージェントに適しています。Codex CLI を使用した自動化されたアドバーサリアル コード レビューが必要です","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. Codex CLI를 통해 자동화된 적대적 코드 리뷰가 필요합니다","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan una revisión de código adversarial automatizada a través de Codex CLI","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant une revue de code adverse automatisée via Codex CLI","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die eine automatisierte adversarialen Code-Überprüfung über Codex CLI benötigen","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de revisão de código adversarial automatizada via Codex CLI","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих автоматизированного враждебного обзора кода через Codex CLI","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يحتاجون إلى مراجعة کد معادية آليّة عبر Codex CLI"},"recommendation":{"en":"Empowers agents to automate code review processes using Codex, providing structured finding analysis, HITL-gated fix loops, and optional re-verification, all while leveraging the Codex Review Loop''s load balancer and proxy capabilities for efficient usage tracking and dashboard management","zh":"赋予代理自动化代码审查流程的能力，使用 Codex 提供结构化的发现分析、HITL-gated 修复循环和可选的重新验证，同时利用 Codex Review Loop 的负载均衡器和代理功能实现高效的使用跟踪和仪表盘管理","ja":"エージェントにコード レビュー プロセスを自動化する能力を与え、Codex を使用して構造化された発見の分析、HITL-gated 修正ループ、およびオプションの再検証を提供し、同時に Codex Review Loop の負荷分散器およびプロキシ機能を使用して効率的な使用状況の追跡およびダッシュボード管理を行う","ko":"에이전트가 코드 리뷰 프로세스를 자동화할 수 있도록 해주며, Codex를 사용하여 구조화된 발견 분석, HITL-gated 수정 루프 및 선택적인 재검증을 제공하고, 동시에 Codex Review Loop의 부하 분산器 및 프록시 기능을 사용하여 효율적인 사용 추적 및 대시보드 관리를 수행합니다","es":"Habilita a los agentes a automatizar los procesos de revisión de código utilizando Codex, proporcionando un análisis de hallazgos estructurado, bucles de corrección con puerta HITL y re-verificación opcional, todo mientras aprovecha las capacidades de equilibrio de carga y proxy de la bucle de revisión de Codex para un seguimiento y administración de panel de instrumentos eficientes","fr":"Permet aux agents d''automatiser les processus de revue de code en utilisant Codex, en fournissant une analyse de résultats structurée, des boucles de correction à gate HITL et une ré-vérification optionnelle, le tout en exploitant les capacités d''équilibrage de charge et de proxy de la boucle de revue de Codex pour un suivi et une gestion de tableau de bord efficaces","de":"Ermächtigt die Agenten, Code-Überprüfungsprozesse mithilfe von Codex zu automatisieren, indem es eine strukturierte Analyse von Ergebnissen, HITL-gesteuerte Korrekturschleifen und optionale Überprüfung bietet, während es die Lastverteilungs- und Proxy-Funktionen der Codex-Überprüfungsschleife für effizientes Nutzungs- und Dashboard-Management nutzt","pt":"Habilita os agentes a automatizar os processos de revisão de código usando o Codex, fornecendo análise de descobertas estruturadas, loops de correção controlados por HITL, e re-verificação opcional, tudo isso aproveitando as capacidades de balanceador de carga e proxy do Loop de Revisão do Codex para um acompanhamento eficiente do uso e gerenciamento de dashboard","ru":"Наделяет агентов возможностью автоматизировать процессы обзора кода с помощью Codex, обеспечивая структурированный анализ находок, петли исправления, управляемые HITL, и опциональную повторную верификацию, все это при использовании возможностей балансировки нагрузки и прокси Loop обзора Codex для эффективного отслеживания использования и управления панелью управления","ar":"يمكّن الوكلاء من توفير عمليات مراجعة الكود باستخدام Codex، مع تقديم تحليل للنتائج المكتشفة بشكل منظم، ودوائر تصحيح بموجب HITL، والتحقق مرة أخرى اختياري، كل ذلك مع الاستفادة من قدرات موازنة الحمل ووكيل حلقة مراجعة Codex لمراقبة فعالة للاستخدام وإدارة لوحة التحكم"},"useCases":{"en":["Automating adversarial code reviews for GitHub pull requests","Analyzing code changes against base branches for quality assurance","Reviewing uncommitted local changes for instant feedback"],"zh":["自动化 GitHub 拉取请求的对抗性代码审查","分析代码更改以确保质量保证","审查未提交的本地更改以获得即时反馈"],"ja":["GitHub のプル リクエストのアドバーサリアル コード レビューを自動化する","コードの変更を分析して品質保証を行う","コミットされていないローカル変更をレビューして即時フィードバックを取得する"],"ko":["GitHub 풀 리퀘스트의 적대적 코드 리뷰를 자동화하는 것","코드 변경을 분석하여 품질 보증을 수행하는 것","커밋되지 않은 로컬 변경을 리뷰하여 즉시 피드백을 얻는 것"],"es":["Automatización de revisiones de código adversarial para solicitudes de extracción de GitHub","Análisis de cambios de código frente a ramas base para aseguramiento de la calidad","Revisión de cambios locales no comprometidos para comentarios instantáneos"],"fr":["Automatisation des revues de code adverse pour les demandes d''extraction de GitHub","Analyse des modifications de code par rapport aux branches de base pour l''assurance qualité","Révision des modifications locales non validées pour des commentaires instantanés"],"de":["Automatisierung von adversarialen Code-Überprüfungen für GitHub-Pull-Requests","Analyse von Code-Änderungen gegenüber Basiszweigen für Qualitätsicherung","Überprüfung von nicht committeten lokalen Änderungen für sofortiges Feedback"],"pt":["Automatizar revisões de código adversarial para solicitações de pull do GitHub","Analizar alterações de código em relação às branches base para garantia de qualidade","Revisar alterações locais não comprometidas para feedback instantâneo"],"ru":["Автоматизировать враждебные обзоры кода для запросов на включение изменений в GitHub","Анализировать изменения кода по отношению к базовым ветвям для обеспечения качества","Просматривать незафиксированные локальные изменения для мгновенной обратной связи"],"ar":["توفير مراجعات الكود المعادية الآلية لمشاركات السحب في GitHub","تحليل التغييرات في الكود مقابل الفروع الأساسية لتأمين جودة","مراجعة التغييرات المحلية غير الملتزمة للحصول على ملاحظات فورية"]},"limitations":{"en":["Requires Codex/ChatGPT account and CLI setup","Limited to reviewing code via Codex CLI, which may have usage limits and requirements","Needs specific arguments for PR number, base branch, or uncommitted changes for proper functionality"],"zh":["需要 Codex/ChatGPT 账户和 CLI 设置","仅限通过 Codex CLI 审查代码，这可能有使用限制和要求","需要特定的参数（例如 PR 编号、基准分支或未提交的更改）以实现正确的功能"],"ja":["Codex/ChatGPT アカウントおよび CLI の設定が必要","Codex CLI を使用してコードをレビューすることのみに限定され、使用制限や要件がある可能性がある","適切な機能を実現するには、特定の引数（PR 番号、ベース ブランチ、またはコミットされていない変更など）が必要"],"ko":["Codex/ChatGPT 계정 및 CLI 설정이 필요합니다","Codex CLI를 통해 코드를 리뷰하는 것만으로 제한되며, 사용 제한 및 요구 사항이 있을 수 있습니다","정상적인 기능을 수행하기 위해 특정 인수(PR 번호, 기본 분기 또는 커밋되지 않은 변경 사항 등)이 필요합니다"],"es":["Requiere una cuenta de Codex/ChatGPT y configuración de CLI","Limitado a la revisión de código a través de Codex CLI, que puede tener límites y requisitos de uso","Necesita argumentos específicos para el número de PR, rama base o cambios no comprometidos para una funcionalidad adecuada"],"fr":["Nécessite un compte Codex/ChatGPT et une configuration de CLI","Limité à la revue de code via Codex CLI, qui peut avoir des limites et des exigences d''utilisation","Nécessite des arguments spécifiques pour le numéro de PR, la branche de base ou les modifications non validées pour un fonctionnement correct"],"de":["Benötigt ein Codex/ChatGPT-Konto und CLI-Einrichtung","Begrenzt auf die Überprüfung von Code über Codex CLI, die möglicherweise Nutzungsbeschränkungen und -anforderungen hat","Benötigt spezifische Argumente für die PR-Nummer, den Basiszweig oder nicht committete Änderungen für eine ordnungsgemäße Funktionalität"],"pt":["Requer conta Codex/ChatGPT e configuração CLI","Limitado à revisão de código via Codex CLI, que pode ter limites e requisitos de uso","Necessita de argumentos específicos para número de PR, branch base ou alterações não comprometidas para funcionamento adequado"],"ru":["Требует учетной записи Codex/ChatGPT и настройки CLI","Ограничен обзором кода через Codex CLI, который может иметь ограничения и требования использования","Требует конкретных аргументов для номера PR, базовой ветви или незафиксированных изменений для правильного функционирования"],"ar":["يتطلب حساب Codex/ChatGPT وإعداد CLI","محدود لمراجعة الكود عبر Codex CLI، والذي قد يكون له حدود ومتطلبات استخدام","يحتاج إلى حُجج محددة لعدد PR، أو الفرع الأساسي، أو التغييرات غير الملتزمة من أجل الوظائف المناسبة"]},"version":4},"contentHash":"f1017c1e026ac4526ee32af49b67e02bc445a02bcc99dc06ee0c1ab48a98e29d","qualityScore":75}');
