INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yspreen/dotfiles/convex-component-authoring', 'convex-component-authoring', 'yspreen', 'dotfiles', 'community', 'convex-component-authoring yspreen dotfiles community Convex-component-authoring enables developers to create reusable Convex components with proper isolation, exports, and dependency management. This skill benefits developers working on projects that require sharing components across applications. Convex 组件是自包含的、可重用的组件，具有适当的隔离、导出和依赖管理 Convex コンポーネントは、自己完結した再利用可能なコンポーネントで、適切な分離、エクスポート、依存関係管理を備えています Convex 컴포넌트는 독립적이고 재사용 가능한 컴포넌트로 적절한 분리, 내보내기 및 종속성 관리를 갖추고 있습니다 Convex-component-authoring permite crear componentes reutilizables con exports y gestión de dependencias Convex-component-authoring permet de créer des composants réutilisables avec exports et gestion de dépendances Convex-component-authoring ermöglicht die Erstellung von wiederverwendbaren Komponenten mit Exports und Abhängigkeitsverwaltung Crie componentes Convex self-contidos e reutilizáveis com isolamento adequado, exportação e gerenciamento de dependências Создайте компоненты Convex с правильной изоляцией, экспортом и управлением зависимостями для ИИ Агентов إنشاء مكونات Convex قابلة لإعادة الاستخدام مع العزل والتصدير وإدارة التبعيات how to use convex-component-authoring what is convex-component-authoring convex-component-authoring alternative convex-component-authoring vs component-based architecture convex-component-authoring install convex-component-authoring setup guide convex-component-authoring documentation convex-component-authoring tutorial convex-component-authoring best practices Convex组件 Convex组件创建 Convex组件管理 可重用组件 依赖管理 Convex文档 组件作者指南 AI开发工具 Creates self-contained Convex components with proper isolation Supports exports and dependency management for sharing across projects Follows documentation guidelines from https://docs.convex.dev/components Utilizes component authoring guidelines from https://docs.convex.dev/components/authoring References broader context from https://docs.convex.dev/llms.txt Enables developers to fetch the latest documentation for implementation Convex-component-authoring is a skill that allows developers to create self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/octocode', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'octocode', 0, 0, 75, '2026-02-20T04:13:19.570Z', '2026-02-20T04:16:52.459Z', '8dbc402a13f2218a6e671f37b6fc5c7060d4ef71d5f25eafb21e97c830dd3660', '{"id":"majiayu000/claude-skill-registry/octocode","name":"octocode","description":{"zh":"OctoCode, GitHub","ja":"OctoCode, GitHub","ko":"OctoCode, GitHub ","es":"OctoCode es una herramienta de búsqueda de código en GitHub que permite encontrar implementaciones reales y realizar revisiones de seguridad","fr":"OctoCode est un outil de recherche de code sur GitHub qui permet de trouver des implémentations réelles et de réaliser des audits de sécurité","de":"OctoCode ist ein Code-Suchtool auf GitHub, das das Finden von realen Implementierungen und die Durchführung von Sicherheitsüberprüfungen ermöglicht","pt":"OctoCode é uma ferramenta de pesquisa de código que permite buscar implementações reais em repositórios GitHub. Ela ajuda a encontrar padrões e realizar revisões de segurança.","ru":"OctoCode — это инструмент поиска кода, который позволяет искать реальные реализации в репозиториях GitHub. Он помогает найти закономерности и провести обзоры безопасности.","ar":"OctoCode هو أداة بحث عن رمز يسمح بالبحث عن تنفيذات حقيقية في مستودعات GitHub. يساعد في العثور على الأنماط وتنفيذ مراجعات الأمان.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"OctoCode - GitHub ","ja":"OctoCode - GitHub","ko":"OctoCode - GitHub ","es":"OctoCode: Búsqueda de código en GitHub","fr":"OctoCode : Recherche de code sur GitHub","de":"OctoCode: Code-Suche auf GitHub","pt":"OctoCode: Pesquisa de Código em Repositórios GitHub","ru":"OctoCode: Поиск кода в репозиториях GitHub","ar":"OctoCode: البحث عن رمز في مستودعات GitHub","en":"octocode"},"description":{"zh":"OctoCode, GitHub","ja":"OctoCode, GitHub","ko":"OctoCode, GitHub ","es":"OctoCode es una herramienta de búsqueda de código en GitHub que permite encontrar implementaciones reales y realizar revisiones de seguridad","fr":"OctoCode est un outil de recherche de code sur GitHub qui permet de trouver des implémentations réelles et de réaliser des audits de sécurité","de":"OctoCode ist ein Code-Suchtool auf GitHub, das das Finden von realen Implementierungen und die Durchführung von Sicherheitsüberprüfungen ermöglicht","pt":"OctoCode é uma ferramenta de pesquisa de código que permite buscar implementações reais em repositórios GitHub. Ela ajuda a encontrar padrões e realizar revi...","ru":"OctoCode — это инструмент поиска кода, который позволяет искать реальные реализации в репозиториях GitHub. Он помогает найти закономерности и провести обзоры...","ar":"OctoCode هو أداة بحث عن رمز يسمح بالبحث عن تنفيذات حقيقية في مستودعات GitHub. يساعد في العثور على الأنماط وتنفيذ مراجعات الأمان.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["GitHub","OctoCode","GitHub","OctoCode","GitHub"],"ja":["GitHub","OctoCode","GitHub","OctoCode","GitHub"],"ko":["GitHub","OctoCode","GitHub","OctoCode","GitHub "],"es":["Búsqueda de código en repositorios de GitHub","Descubrimiento de repositorios por temas y palabras clave","Revisión de seguridad de código","Búsqueda de código por ruta y contenido","Análisis de estructura de repositorios"],"fr":["Recherche de code dans les référentiels GitHub","Découverte de référentiels par sujets et mots clés","Audit de sécurité de code","Recherche de code par chemin et contenu","Analyse de la structure des référentiels"],"de":["Code-Suche in GitHub-Repositorys","Entdeckung von Repositorys nach Themen und Schlüsselwörtern","Sicherheitsüberprüfung von Code","Code-Suche nach Pfad und Inhalt","Analyse der Repository-Struktur"],"pt":["Pesquisa de código em repositórios GitHub","Encontre implementações reais de código","Descubra padrões e realize revisões de segurança","Busca por conteúdo ou caminho","Suporte a múltiplos repositórios"],"ru":["Поиск кода в репозиториях GitHub","Найдите реальные реализации кода","Открывайте закономерности и проводите обзоры безопасности","Поиск по содержанию или пути","Поддержка множества репозиториев"],"ar":["بحث عن رمز في مستودعات GitHub","ابحث عن تنفيذات حقيقية للرمز","اكتشف الأنماط وتنفيذ مراجعات الأمان","البحث عن المحتوى أو المسار","دعم عدة مستودعات"]},"keywords":{"zh":["OctoCode","GitHub","GitHub","OctoCode","GitHub","OctoCode"],"ja":["OctoCode","GitHub","GitHub","OctoCode","GitHub","OctoCode"],"ko":["OctoCode","GitHub","GitHub","OctoCode","GitHub","OctoCode "],"es":["búsqueda de código","GitHub","revisión de seguridad","análisis de código","desarrollo de software","herramientas de desarrollo"],"fr":["recherche de code","GitHub","audit de sécurité","analyse de code","développement de logiciels","outils de développement"],"de":["Code-Suche","GitHub","Sicherheitsüberprüfung","Code-Analyse","Software-Entwicklung","Entwicklungstools"],"pt":["OctoCode","pesquisa de código","GitHub","repositórios","implementações reais","padrões","revisões de segurança","desenvolvimento de software"],"ru":["OctoCode","поиск кода","GitHub","репозитории","реальные реализации","закономерности","обзоры безопасности","разработка программного обеспечения"],"ar":["OctoCode","بحث عن رمز","GitHub","مستودعات","تنفيذات حقيقية","أنماط","مراجعات الأمان","تطوير البرمجيات"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.570Z","topics":[],"category":"community","skillMd":{"name":"octocode","description":"Semantic code research across GitHub repositories for finding implementations, patterns, and conducting PR/security reviews.","bodyPreview":"# OctoCode (Semantic Code Research)\n\nUse OctoCode to search across GitHub repositories for real implementations, patterns, and to conduct code/security reviews. Unlike Context7 (documentation lookup), OctoCode finds **actual production code**.\n\n## Tools\n\n| Tool | Purpose |\n|------|---------|\n| `octocode_githubSearchCode` | Search code across repositories by content or path |\n| `octocode_githubSearchRepositories` | Discover repositories by topics, keywords, stars |\n| `octocode_githubViewRepoStruc","body":"# OctoCode (Semantic Code Research)\n\nUse OctoCode to search across GitHub repositories for real implementations, patterns, and to conduct code/security reviews. Unlike Context7 (documentation lookup), OctoCode finds **actual production code**.\n\n## Tools\n\n| Tool | Purpose |\n|------|---------|\n| `octocode_githubSearchCode` | Search code across repositories by content or path |\n| `octocode_githubSearchRepositories` | Discover repositories by topics, keywords, stars |\n| `octocode_githubViewRepoStructure` | Explore repository directory structure |\n| `octocode_githubGetFileContent` | Read files with pattern matching and line ranges |\n| `octocode_githubSearchPullRequests` | Search PRs with discussions, diffs, and metadata |\n| `octocode_packageSearch` | Search npm and PyPI packages |\n\n## When to Use OctoCode vs Context7\n\n| Need | Tool | Why |\n|------|------|-----|\n| Library API documentation | **Context7** | Curated, version-specific docs |\n| Find real implementations | **OctoCode** | Searches actual codebases |\n| How does React do X? | **OctoCode** | Search React''s source code |\n| Axum middleware examples | **OctoCode** | Find production patterns |\n| PR review with evidence | **OctoCode** | `/review_pull_request` command |\n| Security vulnerability patterns | **OctoCode** | `/review_security` command |\n\n## Common Workflows\n\n### 1. Research Implementation Patterns\n\n```\n# Find OAuth implementations in Rust\noctocode_githubSearchCode({\n  query: \"oauth axum\",\n  language: \"rust\",\n  stars: \">100\"\n})\n\n# Then explore the top result\noctocode_githubViewRepoStructure({\n  owner: \"found-org\",\n  repo: \"found-repo\",\n  path: \"src/auth\"\n})\n\n# Read the specific implementation\noctocode_githubGetFileContent({\n  owner: \"found-org\",\n  repo: \"found-repo\",\n  path: \"src/auth/oauth.rs\"\n})\n```\n\n### 2. PR Review (Cleo)\n\nFor code quality reviews, use OctoCode to find canonical implementations for comparison:\n\n```\n# Find how top projects handle the same pattern\noctocode_githubSearchCode({\n  query: \"error handling middleware\",\n  language: \"typescript\",\n  stars: \">1000\"\n})\n```\n\n### 3. Security Analysis (Cipher)\n\nFor security reviews, search for vulnerability patterns and fixes:\n\n```\n# Find how security issues were fixed\noctocode_githubSearchPullRequests({\n  query: \"CVE fix authentication\",\n  state: \"merged\",\n  repo: \"relevant/repo\"\n})\n```\n\n### 4. Research for Task Generation (Morgan)\n\nBefore generating implementation tasks, research existing patterns:\n\n```\n# How do multi-agent platforms handle task decomposition?\noctocode_githubSearchCode({\n  query: \"task decomposition agent\",\n  language: \"rust OR python\",\n  stars: \">500\"\n})\n```\n\n## OctoCode Commands (Prompts)\n\nOctoCode provides specialized prompt commands for complex research:\n\n| Command | Purpose | Use Case |\n|---------|---------|----------|\n| `/research` | Deep code discovery and pattern analysis | Finding implementations before coding |\n| `/plan` | Research-backed implementation planning | Planning complex features |\n| `/review_pull_request` | Defects-first PR analysis | Quality reviews with evidence |\n| `/review_security` | Security audit with validation | Security analysis with citations |\n\n### Using `/research`\n\n```\n/research How does React''s useState hook work internally?\n/research Compare state management: Redux vs Zustand vs Jotai\n/research Find authentication patterns in axum Rust projects\n```\n\n### Using `/review_pull_request`\n\n```\n/review_pull_request prUrl: https://github.com/5dlabs/cto/pull/123\n```\n\nThis provides:\n- **Defects & Bugs**: Logic errors, edge cases, race conditions\n- **Security Issues**: Injection vulnerabilities, auth bypasses\n- **Performance**: N+1 queries, memory leaks\n- **Code Quality**: Complexity, maintainability\n\n### Using `/review_security`\n\n```\n/review_security repoUrl: https://github.com/5dlabs/cto\n```\n\nThis provides:\n- **Authentication & Authorization**: Auth flows, session management\n- **Input Validation**: Injection points, sanitization\n- **Secrets Management**: Hardcoded credentials, API keys\n- **Dependencies**: Known vulnerabilities, supply chain risks\n\n## Best Practices\n\n1. **Use both tools together** - Context7 for docs, OctoCode for implementations\n2. **Be specific with searches** - \"axum middleware error handling\" not \"error handling\"\n3. **Filter by stars** - `stars:>100` for quality code\n4. **Cite your sources** - Include GitHub links in research findings\n5. **Check recent PRs** - For understanding how issues were solved\n\n## Integration with Deep Research\n\nOctoCode complements Firecrawl for comprehensive research:\n\n| Research Type | Primary Tool | Secondary Tool |\n|---------------|--------------|----------------|\n| Competitive analysis | Firecrawl Agent | OctoCode (open source competitors) |\n| Implementation patterns | OctoCode | Context7 (docs for libraries used) |\n| Best practices | Firecrawl | OctoCode (real code examples) |\n| Bug investigation | OctoCode | GitHub MCP (internal PRs) |\n\n## Example: Research-Backed Task Generation\n\nWhen Morgan processes a PRD mentioning \"implement OAuth like Auth0\":\n\n```\n1. Use OctoCode to search for OAuth implementations:\n   octocode_githubSearchCode({ query: \"oauth2 refresh token rotation rust\" })\n\n2. Analyze how top projects structure auth:\n   octocode_githubViewRepoStructure({ owner: \"top-project\", repo: \"auth\" })\n\n3. Extract patterns from implementations:\n   octocode_githubGetFileContent({ \n     owner: \"top-project\", \n     repo: \"auth\", \n     path: \"src/oauth.rs\",\n     matchString: \"refresh_token\"\n   })\n\n4. Embed findings in task details for implementation agents\n```\n"},"lastSynced":"2026-02-20T04:16:52.459Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring in-depth GitHub repository analysis and semantic code research capabilities.","zh":"适合需要对 GitHub 仓库进行深入分析和语义代码研究能力的代码审查代理。","ja":"GitHub リポジトリの詳細な分析およびセマンティック コード 研究機能を必要とするコードレビュー エージェントに最適です。","ko":"깃허브 저장소에 대한 심층 분석 및 의미 코드 연구 기능을 필요로 하는 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para agentes de revisión de código que requieren un análisis en profundidad de los repositorios de GitHub y capacidades de investigación de código semántico.","fr":"Idéal pour les agents de révision de code nécessitant une analyse approfondie des référentiels GitHub et des capacités de recherche de code sémantique.","de":"Ideal für Code-Review-Agents, die eine umfassende Analyse von GitHub-Repositorys und semantische Code-Recherche-Funktionen erfordern.","pt":"Ideal para Agentes de Revisão de Código que exigem análise aprofundada de repositórios GitHub e capacidades de pesquisa de código semântico.","ru":"Идеально для агентов проверки кода, требующих глубокого анализа репозиториев GitHub и возможностей семантического исследования кода.","ar":"مثالي لعميل مراجعة الشفرة الذي يتطلب تحليلًا متعمقًا لمستودع GitHub وقدرات البحث الشبكي للشفرة."},"recommendation":{"en":"Empowers agents to conduct thorough code and security reviews by searching across GitHub repositories for real implementations and patterns, utilizing tools like octocode_githubSearchCode and octocode_githubSearchRepositories to discover topics, keywords, and starred repositories.","zh":"通过使用 octocode_githubSearchCode 和 octocode_githubSearchRepositories 等工具，在 GitHub 仓库中搜索真实实现和模式，赋予代理进行彻底代码和安全审查的能力。","ja":"octocode_githubSearchCode および octocode_githubSearchRepositories などのツールを使用して、GitHub リポジトリで実装とパターンを検索し、エージェントが包括的なコードおよびセキュリティのレビューを実行できるようにします。","ko":"octocode_githubSearchCode 및 octocode_githubSearchRepositories 등의 도구를 사용하여 깃허브 저장소에서 실제 구현 및 패턴을 검색하여 에이전트가 철저한 코드 및 보안 리뷰를 수행할 수 있도록 합니다.","es":"Habilita a los agentes a realizar revisiones exhaustivas de código y seguridad buscando en los repositorios de GitHub implementaciones reales y patrones, utilizando herramientas como octocode_githubSearchCode y octocode_githubSearchRepositories para descubrir temas, palabras clave y repositorios destacados.","fr":"Permet aux agents de réaliser des examens approfondis de code et de sécurité en recherchant des implementations réelles et des modèles à travers les référentiels GitHub, en utilisant des outils tels que octocode_githubSearchCode et octocode_githubSearchRepositories pour découvrir des sujets, des mots clés et des référentiels mis en évidence.","de":"Ermächtigt die Agenten, gründliche Code- und Sicherheitsprüfungen durchzuführen, indem sie in GitHub-Repositorys nach realen Implementierungen und Mustern suchen, unter Verwendung von Tools wie octocode_githubSearchCode und octocode_githubSearchRepositories, um Themen, Schlüsselwörter und favorisierte Repositorys zu entdecken.","pt":"Permite que os agentes realizem revisões de código e segurança abrangentes, pesquisando em repositórios GitHub por implementações reais e padrões, utilizando ferramentas como octocode_githubSearchCode e octocode_githubSearchRepositories para descobrir tópicos, palavras-chave e repositórios com estrelas.","ru":"Наделяет агентов возможностью проводить тщательные обзоры кода и безопасности, ища по реальным реализациям и шаблонам в репозиториях GitHub, используя инструменты, такие как octocode_githubSearchCode и octocode_githubSearchRepositories, для обнаружения тем, ключевых слов и репозиториев с звездами.","ar":"يسمح للعاملين بإجراء مراجعات شاملة للشفرة والأمان عن طريق البحث عبر مستودعات GitHub للحصول على تنفيذات حقيقية وأنماط، باستخدام أدوات مثل octocode_githubSearchCode و octocode_githubSearchRepositories لاكتشاف الموضوعات والكلمات الرئيسية والمستودعات التي تم تخصيص نجمات لها."},"useCases":{"en":["Searching code across repositories by content or path","Discovering repositories by topics, keywords, and stars","Conducting code and security reviews"],"zh":["根据内容或路径在存储库中搜索代码","通过主题、关键词和星级发现存储库","进行代码和安全审查"],"ja":["コンテンツまたはパスでリポジトリを検索","テーマ、キーワード、スターでリポジトリを発見","コードとセキュリティのレビューを実施"],"ko":["내용 또는 경로로 저장소를 검색하여 코드를 찾기","주제, 키워드, 별로 저장소를 발견하기","코드 및 보안 리뷰 수행"],"es":["Buscar código a través de repositorios por contenido o ruta","Descubrir repositorios por temas, palabras clave y estrellas","Realizar revisiones de código y seguridad"],"fr":["Rechercher du code à travers les référentiels par contenu ou chemin","Découvrir des référentiels par sujets, mots clés et étoiles","Réalisser des examens de code et de sécurité"],"de":["Code in Repositorys nach Inhalt oder Pfad suchen","Repositorys nach Themen, Schlüsselwörtern und Sternen entdecken","Code- und Sicherheitsprüfungen durchführen"],"pt":["Pesquisar código em repositórios por conteúdo ou caminho","Descobrir repositórios por tópicos, palavras-chave e estrelas","Realizar revisões de código e segurança"],"ru":["Поиск кода по репозиториям по содержанию или пути","Обнаружение репозиториев по темам, ключевым словам и звездам","Проведение обзоров кода и безопасности"],"ar":["البحث عن الشفرة عبر المستودعات حسب المحتوى أو المسار","اكتشاف المستودعات حسب المواضيع والكلمات الرئيسية والنجوم","إجراء مراجعات للشفرة والأمان"]},"limitations":{"en":["Requires GitHub access","Limited to GitHub repositories"],"zh":["需要 GitHub 访问权限","仅限 GitHub 仓库"],"ja":["GitHub アクセスが必要","GitHub リポジトリのみ"],"ko":["깃허브 액세스가 필요함","깃허브 저장소만 해당"],"es":["Requiere acceso a GitHub","Limitado a los repositorios de GitHub"],"fr":["Nécessite un accès à GitHub","Lim