INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/gh-search-repos', 'gh-search-repos', 'majiayu000', 'claude-skill-registry', 'community', 'gh-search-repos majiayu000 claude-skill-registry community gh search repos是GitHub CLI中用于搜索仓库的命令，支持按星数、语言、主题等过滤 gh search reposはGitHub CLIのリポジトリ検索コマンドで、スター数、言語、トピックなどでフィルタリングできます gh search repos는 GitHub CLI의 저장소 검색 명령으로 별 개수, 언어, 주제 등으로 필터링할 수 있습니다 La búsqueda de repositorios de GitHub permite encontrar proyectos por popularidad, lenguaje y temas. La recherche de dépôts GitHub permet de trouver des projets par popularité, langage et sujets. Die GitHub-Repository-Suche ermöglicht das Finden von Projekten nach Popularität, Sprache und Themen. O comando gh search repos permite buscar repositórios no GitHub com base em vários critérios. É útil para encontrar repositórios populares, por linguagem ou tópicos. Команда gh search repos позволяет искать репозитории на GitHub по разным критериям. Она полезна для нахождения популярных репозиториев, по языку или темам. يسمح أمر gh search repos بالبحث عن المستودعات على GitHub بناءً على معايير متعددة. وهو مفيد لfinding المستودعات الشهيرة، حسب اللغة أو المواضيع. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app GitHub仓库搜索 gh search repos GitHub CLI 仓库过滤 星数过滤 语言过滤 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
