INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/best-practices-researcher', 'best-practices-researcher', 'majiayu000', 'claude-skill-registry', 'community', 'best-practices-researcher majiayu000 claude-skill-registry community 最佳实践研究员是研究专家，专门从外部来源发现和总结最佳实践 ベストプラクティス研究者は、公式ドキュメント、コミュニティ標準、およびオープンソースプロジェクトからベストプラクティスを発見してまとめる研究専門家です 최적의 관행 연구자는 공식 문서, 커뮤니티 표준 및 오픈 소스 프로젝트에서 최적의 관행을 발견하고 요약하는 연구 전문가입니다 El investigador de mejores prácticas es un experto en investigación que encuentra y sintetiza las mejores prácticas de fuentes externas para desarrollar soluciones óptimas Le chercheur de bonnes pratiques est un expert en recherche qui trouve et synthétise les bonnes pratiques à partir de sources externes pour développer des solutions optimales Der Best-Practices-Forscher ist ein Forschungsexperte, der die besten Praktiken aus externen Quellen findet und synthetisiert, um optimale Lösungen zu entwickeln O pesquisador de melhores práticas é um especialista em encontrar e sintetizar as melhores práticas de desenvolvimento de software. Исследователь лучших практик - это специалист, который находит и синтезирует лучшие практики разработки программного обеспечения. باحث أفضل الممارسات هو خبير في العثور على وتحليل أفضل الممارسات لتنمية البرمجيات. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app 最佳实践 研究专家 外部来源 官方文档 社区标准 开源项目 综合信息 推荐上下文 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NeverSight/skills_feed/skill-from-github', 'community', 'NeverSight', 'skills_feed', 'NeverSight/skills_feed', 'skill-from-github', 0, 0, 75, '2026-02-20T04:13:19.570Z', '2026-02-20T04:20:05.361Z', '3a193a57719e34e75264311535a3f0b8672d2af893bd345d358666adae4efff8', '{"id":"NeverSight/skills_feed/skill-from-github","name":"skill-from-github","description":{"zh":"一个用于从GitHub获取技能数据的爬虫脚本，自动执行，提供技术解决方案","ja":"GitHubからスキルデータを取得するクローラースクリプト、自動実行、技術解決策を提供する","ko":"GitHub에서 스킬 데이터를 가져오는 크롤러 스크립트, 자동 실행, 기술적 해결책 제공","es":"La habilidad desde GitHub es un script de crawling que recopila datos de habilidades de la red, ejecutado diariamente a través de GitHub Actions.","fr":"La compétence depuis GitHub est un script de crawling qui collecte des données de compétences du réseau, exécuté quotidiennement via GitHub Actions.","de":"Die Fähigkeit von GitHub ist ein Crawler-Skript, das Fähigkeitsdaten aus dem Netz sammelt, täglich über GitHub Actions ausgeführt.","pt":"O script de habilidades do GitHub é uma ferramenta para extrair dados de projetos de qualidade e criar habilidades personalizadas para desenvolvedores","ru":"Скрипт навыков GitHub - это инструмент для извлечения данных из качественных проектов и создания индивидуальных навыков для разработчиков","ar":"سكريبت مهارات جيت هاب هو أداة لاستخراج البيانات من مشاريع ذات جودة عالية وإنشاء مهارات مخصصة للمطورين","en":"A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions."},"seo":{"title":{"zh":"GitHub技能爬虫脚本","ja":"GitHubスキルクローラースクリプト","ko":"GitHub 스킬 크롤러 스크립트","es":"Habilidad desde GitHub: Crawler de datos de habilidades","fr":"Compétence depuis GitHub : Crawling de données de compétence","de":"Fähigkeit von GitHub: Crawler für Fähigkeitsdaten","pt":"Habilidades do GitHub: Extraia Dados de Projetos","ru":"Навыки GitHub: Извлеките Данные из Проектов","ar":"مهارات جيت هاب: استخراج البيانات من المشاريع","en":"skill-from-github"},"description":{"zh":"一个用于从GitHub获取技能数据的爬虫脚本，自动执行，提供技术解决方案","ja":"GitHubからスキルデータを取得するクローラースクリプト、自動実行、技術解決策を提供する","ko":"GitHub에서 스킬 데이터를 가져오는 크롤러 스크립트, 자동 실행, 기술적 해결책 제공","es":"La habilidad desde GitHub es un script de crawling que recopila datos de habilidades de la red, ejecutado diariamente a través de GitHub Actions.","fr":"La compétence depuis GitHub est un script de crawling qui collecte des données de compétences du réseau, exécuté quotidiennement via GitHub Actions.","de":"Die Fähigkeit von GitHub ist ein Crawler-Skript, das Fähigkeitsdaten aus dem Netz sammelt, täglich über GitHub Actions ausgeführt.","pt":"O script de habilidades do GitHub é uma ferramenta para extrair dados de projetos de qualidade e criar habilidades personalizadas para desenvolvedores","ru":"Скрипт навыков GitHub - это инструмент для извлечения данных из качественных проектов и создания индивидуальных навыков для разработчиков","ar":"سكريبت مهارات جيت هاب هو أداة لاستخراج البيانات من مشاريع ذات جودة عالية وإنشاء مهارات مخصصة للمطورين","en":"A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions."},"definition":{"en":"A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions."},"features":{"zh":["自动从GitHub获取技能数据","了解用户意图","提供技术解决方案","支持daily自动执行","使用GitHub Actions"],"ja":["GitHubからスキルデータを自動取得","ユーザーの意図を理解","技術解決策を提供","daily自動実行をサポート","GitHub Actionsを使用"],"ko":["GitHub에서 스킬 데이터를 자동으로 가져옵니다","사용자의 의도를 이해합니다","기술적 해결책을 제공합니다","일일 자동 실행을 지원합니다","GitHub Actions를 사용합니다"],"es":["Crawling de datos de habilidades","Ejecución diaria a través de GitHub Actions","Análisis de proyectos de calidad en GitHub","Creación de habilidades personalizadas","Integración con herramientas de desarrollo","Automatización de tareas"],"fr":["Crawling de données de compétences","Exécution quotidienne via GitHub Actions","Analyse de projets de qualité sur GitHub","Création de compétences personnalisées","Intégration avec des outils de développement","Automatisation de tâches"],"de":["Crawling von Fähigkeitsdaten","Tägliche Ausführung über GitHub Actions","Analyse von Qualitätsprojekten auf GitHub","Erstellung von benutzerdefinierten Fähigkeiten","Integration mit Entwicklungstools","Automatisierung von Aufgaben"],"pt":["Extração de dados de projetos de qualidade","Criação de habilidades personalizadas para desenvolvedores","Execução automática diária via GitHub Actions","Suporte a busca de projetos no GitHub","Análise de sentimentos e geração de documentação de API"],"ru":["Извлечение данных из качественных проектов","Создание индивидуальных навыков для разработчиков","Автоматическое выполнение каждый день через GitHub Actions","Поддержка поиска проектов на GitHub","Анализ настроений и генерация документации API"],"ar":["استخراج البيانات من مشاريع ذات جودة عالية","إنشاء مهارات مخصصة للمطورين","تنفيذ تلقائي يومي عبر إجراءات جيت هاب","دعم البحث عن مشاريع على جيت هاب","تحليل المشاعر وتوليد توثيق واجهة برمجة التطبيقات"]},"keywords":{"zh":["GitHub技能爬虫脚本","自动获取技能数据","用户意图理解","技术解决方案","GitHub Actions","daily自动执行"],"ja":["GitHubスキルクローラースクリプト","スキルデータ自動取得","ユーザーの意図理解","技術解決策","GitHub Actions","daily自動実行"],"ko":["GitHub 스킬 크롤러 스크립트","스킬 데이터 자동 가져오기","사용자의 의도 이해","기술적 해결책","GitHub Actions","일일 자동 실행"],"es":["habilidad desde github","crawling de datos","github actions","desarrollo de habilidades","proyectos de calidad","automatización de tareas","integración con herramientas","análisis de proyectos","creación de habilidades"],"fr":["compétence depuis github","crawling de données","github actions","développement de compétences","projets de qualité","automatisation de tâches","intégration avec des outils","analyse de projets","création de compétences"],"de":["fähigkeit von github","crawling von daten","github actions","entwicklung von fähigkeiten","qualitätsprojekte","automatisierung von aufgaben","integration mit entwicklungs-tools","analyse von projekten","erstellung von fähigkeiten"],"pt":["habilidades do github","extração de dados","criação de habilidades","desenvolvedores","github actions","análise de sentimentos","geração de documentação de api"],"ru":["навыки github","извлечение данных","создание навыков","разработчики","github actions","анализ настроений","генерация документации api"],"ar":["مهارات جيت هاب","استخراج البيانات","إنشاء مهارات","مطورين","إجراءات جيت هاب","تحليل المشاعر","توليد توثيق واجهة برمجة التطبيقات"]}},"owner":"NeverSight","repo":"skills_feed","repoPath":"NeverSight/skills_feed","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.570Z","topics":[],"category":"community","skillMd":{"name":"skill-from-github","description":"Create skills by learning from high-quality GitHub projects","bodyPreview":"# Skill from GitHub\n\nWhen users want to accomplish something, search GitHub for quality projects that solve the problem, understand them deeply, then create a skill based on that knowledge.\n\n## When to Use\n\nWhen users describe a task and you want to find existing tools/projects to learn from:\n\n- \"I want to be able to convert markdown to PDF\"\n- \"Help me analyze sentiment in customer reviews\"\n- \"I need to generate API documentation from code\"\n\n## Workflow\n\n### Step 1: Understand User Intent\n\nClari","body":"# Skill from GitHub\n\nWhen users want to accomplish something, search GitHub for quality projects that solve the problem, understand them deeply, then create a skill based on that knowledge.\n\n## When to Use\n\nWhen users describe a task and you want to find existing tools/projects to learn from:\n\n- \"I want to be able to convert markdown to PDF\"\n- \"Help me analyze sentiment in customer reviews\"\n- \"I need to generate API documentation from code\"\n\n## Workflow\n\n### Step 1: Understand User Intent\n\nClarify what the user wants to achieve:\n- What is the input?\n- What is the expected output?\n- Any constraints (language, framework, etc.)?\n\n### Step 2: Search GitHub\n\nSearch for projects that solve this problem:\n\n```\n{task keywords} language:{preferred} stars:>100 sort:stars\n```\n\n**Search tips:**\n- Start broad, then narrow down\n- Try different keyword combinations\n- Include \"cli\", \"tool\", \"library\" if relevant\n\n**Quality filters (must meet ALL):**\n- Stars > 100 (community validated)\n- Updated within last 12 months (actively maintained)\n- Has README with clear documentation\n- Has actual code (not just awesome-list)\n\n### Step 3: Present Options to User\n\nShow top 3-5 candidates:\n\n```markdown\n## Found X projects that can help\n\n### Option 1: [project-name](github-url)\n- Stars: xxx | Last updated: xxx\n- What it does: one-line description\n- Why it''s good: specific strength\n\n### Option 2: ...\n\nWhich one should I dive into? Or should I search differently?\n```\n\n**Wait for user confirmation before proceeding.**\n\n### Step 4: Deep Dive into Selected Project\n\nOnce user selects a project, thoroughly understand it:\n\n1. **Read README** - Understand purpose, features, usage\n2. **Read core source files** - Understand how it works\n3. **Check examples** - See real usage patterns\n4. **Note dependencies** - What it relies on\n5. **Identify key concepts** - The mental model behind it\n\nExtract:\n- Core algorithm/approach\n- Input/output formats\n- Error handling patterns\n- Best practices encoded in the code\n\n### Step 5: Summarize Understanding\n\nPresent what you learned to user:\n\n```markdown\n## Understanding [project-name]\n\n### Core Approach\nHow it solves the problem...\n\n### Key Techniques\n1. ...\n2. ...\n\n### Limitations\n- ...\n\n### What I''ll encode in the skill\n- ...\n\nDoes this look right? Should I proceed to create the skill?\n```\n\n**Wait for user confirmation.**\n\n### Step 6: Create Skill via create-skill\n\nHand off to `/create-skill` with:\n\n1. **Clear purpose** - What the skill does\n2. **Methodology** - The approach learned from the project\n3. **Step-by-step process** - Concrete instructions\n4. **Quality criteria** - What good output looks like\n5. **Common pitfalls** - What to avoid (learned from project issues/docs)\n\n**Important:** The skill should encode the *knowledge* from the project, not just wrap the tool. The skill should work even without the original project installed.\n\n## Example\n\n**User:** \"I want to write better commit messages\"\n\n**Step 2 - Search:**\n```\ncommit message convention stars:>100 sort:stars\n```\n\n**Step 3 - Present:**\n```\n## Found 4 projects\n\n### Option 1: conventional-commits/conventionalcommits.org (4.2k ⭐)\n- Specification for human and machine readable commit messages\n- Why: Industry standard, used by Angular, Vue, etc.\n\n### Option 2: commitizen/cz-cli (15k ⭐)\n- CLI tool for creating conventional commits\n- Why: Battle-tested, lots of adapters\n\n### Option 3: carloscuesta/gitmoji (14k ⭐)\n- Emoji guide for commit messages\n- Why: Visual, fun approach\n\nWhich one interests you?\n```\n\n**User:** \"Let''s go with conventional commits\"\n\n**Step 4 - Deep dive:**\n- Read the specification\n- Understand types (feat, fix, docs, etc.)\n- Learn about scopes, breaking changes\n- Study real-world examples\n\n**Step 5 - Summarize:**\n```\n## Understanding Conventional Commits\n\n### Core Approach\nStructured format: <type>(<scope>): <description>\n\n### Key Types\n- feat: new feature\n- fix: bug fix\n- docs: documentation\n- ...\n\n### Benefits Learned\n- Automated changelog generation\n- Semantic versioning\n- Clear history\n\nReady to create a commit message skill based on this?\n```\n\n**Step 6 - Create skill with these principles encoded**\n\n## Important Notes\n\n1. **Always get user confirmation** - At step 3 (project selection) and step 5 (before creating)\n2. **Prefer learning over wrapping** - Encode the knowledge, not just \"run this tool\"\n3. **Check license** - Mention if project has restrictive license\n4. **Credit the source** - Include attribution in generated skill\n5. **Quality over speed** - Take time to truly understand the project\n\n## What This Skill is NOT\n\n- NOT a package installer\n- NOT a tool wrapper\n- It''s about **learning from the best projects** and encoding that knowledge into a reusable skill\n\n"},"lastSynced":"2026-02-20T04:20:05.361Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automated skill data fetching and GitHub project analysis capabilities.","zh":"适合需要自动化技能数据获取和 GitHub 项目分析能力的 AI 代理。","ja":"AI エージェントが自動化されたスキル データの取得と GitHub プロジェクト分析の機能を必要とする場合に適しています。","ko":"자동화된 기술 데이터 가져오기 및 GitHub 프로젝트 분석 기능이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan fetching de datos de habilidades automatizado y capacidades de análisis de proyectos de GitHub.","fr":"Parfait pour les agents IA nécessitant une récupération automatique de données de compétences et des capacités d''analyse de projet GitHub.","de":"Perfekt für KI-Agents, die automatisierte Fähigkeitsdatenabruf und GitHub-Projektanalysefunktionen benötigen.","pt":"Perfeito para agentes de IA que necessitam de dados de habilidades automatizados e capacidades de análise de projetos do GitHub.","ru":"Идеально для агентов ИИ, которым необходимы автоматические данные навыков и возможности анализа проектов GitHub.","ar":"مثالي لعمليات الوكلاء الذكية التي تحتاج إلى بيانات مهارات آلية وقدرات تحليل مشروع جيثب"},"recommendation":{"en":"Empowers agents to crawl and understand quality projects from GitHub, utilizing GitHub Actions for daily execution, and providing insights into projects that solve specific problems, such as converting markdown to PDF or analyzing sentiment in customer reviews.","zh":"赋予代理在 GitHub 上爬取和理解高质量项目的能力，利用 GitHub Actions 实现每日执行，并提供有关解决特定问题的项目的洞察，例如将 Markdown 转换为 PDF 或分析客户评论的情绪。","ja":"エージェントに GitHub からの高品質なプロジェクトをクロールして理解する能力を与え、GitHub Actions を使用して毎日の実行を実現し、特定の問題を解決するプロジェクト (たとえば、Markdown を PDF に変換したり、顧客のレビューの感情を分析したりするプロジェクト) に関する洞察を提供します。","ko":"에이전트가 GitHub에서 고품질 프로젝트를 크롤링하고 이해할 수 있는 능력을 부여하고 GitHub Actions를 사용하여 일일 실행을 구현하며 특정 문제를 해결하는 프로젝트(예: Markdown를 PDF로 변환하거나 고객 리뷰의 감정을 분석하는 프로젝트)에 대한 통찰력을 제공합니다.","es":"Habilita a los agentes a rastrear y comprender proyectos de alta calidad de GitHub, utilizando GitHub Actions para la ejecución diaria y proporcionando información sobre proyectos que resuelven problemas específicos, como convertir markdown a PDF o analizar sentimientos en reseñas de clientes.","fr":"Permet aux agents de parcourir et de comprendre des projets de haute qualité sur GitHub, en utilisant les GitHub Actions pour l''exécution quotidienne et en fournissant des informations sur les projets qui résolvent des problèmes spécifiques, tels que la conversion de markdown en PDF ou l''analyse des sentiments dans les avis clients.","de":"Ermächtigt die Agents, qualitativ hochwertige Projekte von GitHub zu durchsuchen und zu verstehen, wobei GitHub Actions für die tägliche Ausführung verwendet werden und Einblicke in Projekte gewährt werden, die spezifische Probleme lösen, wie z.B. die Umwandlung von Markdown in PDF oder die Analyse von Sentiments in Kundenbewertungen.","pt":"Habilita os agentes a rastejar e entender projetos de qualidade do GitHub, utilizando GitHub Actions para execução diária e fornecendo informações sobre projetos que resolvem problemas específicos, como converter markdown para PDF ou analisar sentimentos em avaliações de clientes.","ru":"Наделяет агентов возможностью ползать и понимать качественные проекты GitHub, используя GitHub Actions для ежедневного выполнения и предоставляя информацию о проектах, решающих конкретные проблемы, такие как преобразование markdown в PDF или анализ настроений в обзорах клиентов.","ar":"يمنح الوكلاء القدرة على التسلل وفهم مشاريع جيثب عالية الجودة، باستخدام إجراءات جيثب لتنفيذ يومي وتقديم معلومات حول المشاريع التي تحل مشاكل محددة، مثل تحويل markdown إلى PDF أو تحليل المشاعر في تقييمات العملاء"},"useCases":{"en":["Automating skill data updates from GitHub repositories","Generating insights from open-source projects for task automation","Discovering existing tools for sentiment analysis or API documentation generation"],"zh":["从 GitHub 存储库自动更新技能数据","从开源项目生成任务自动化的见解","发现现有的情绪分析或 API 文档生成工具"],"ja":["GitHub リポジトリからのスキル データを自動更新する","オープンソース プロジェクトからタスクの自動化に関する洞察を生成する","感情分析や API ドキュメント生成などの既存のツールを発見する"],"ko":["GitHub 리포지토리에서 기술 데이터를 자동으로 업데이트하는 것","오픈소스 프로젝트에서 작업 자동화에 대한 통찰력을 생성하는 것","감정 분석 또는 API 문서 생성과 같은 기존 도구를 발견하는 것"],"es":["Automatizar actualizaciones de datos de habilidades desde repositorios de GitHub","Generar información a partir de proyectos de código abierto para la automatización de tareas","Descubrir herramientas existentes para el análisis de sentimientos o la generación de documentación de API"],"fr":["Automatiser les mises à jour des données de compétences à partir de dépôts GitHub","Générer des informations à partir de projets open source pour l''automatisation des tâches","Découvrir des outils existants pour l''analyse des sentiments ou la génération de documentation d''API"],"de":["Automatisierung von Fähigkeitsdatenaktualisierungen aus GitHub-Repositorys","Generierung von Informationen aus Open-Source-Projekten für die Automatisierung von Aufgaben","Entdecken bestehender Tools für die Sentimentanalyse oder die Generierung von API-Dokumentation"],"pt":["Automatizar atualizações de dados de habilidades de repositórios do GitHub","Gerar informações de projetos de código aberto para automação de tarefas","Descobrir ferramentas existentes para análise de sentimentos ou geração de documentação de API"],"ru":["Автоматизировать обновления данных навыков из репозиториев GitHub","Генерировать информацию из открытых проектов для автоматизации задач","Обнаруживать существующие инструменты для анализа настроений или генерации документации API"],"ar":["توفير تحديثات آلية لبيانات المهارات من مستودعات جيثب","توليد معلومات من مشاريع مفتوحة المصدر للتحكم الآلي في المهام","اكتشاف أدوات موجودة لتحليل المشاعر أو توليد توثيق واجهة برمجة التطبيقات"]},"limitations":{"en":["Requires GitHub Actions setup","Dependent on network connectivity for crawling","Limited to publicly available GitHub projects"],"zh":["需要设置 GitHub Actions","依赖于网络连接以进行爬取","仅限于公开的 GitHub 项目"],"ja":["GitHub Actions の設定が必要","ネットワーク接続に依存してクロールする","公開された GitHub プロジェクトのみに限定される"],"ko":["GitHub Actions 설정이 필요합니다.","크롤링을 위해 네트워크 연결에 의존합니다.","공개된 GitHub 프로젝트에만 제한됩니다."],"es":["Requiere configuración de GitHub Actions","Dependiente de la conectividad de red para el rastreo","Limitado a proyectos de GitHub públicamente disponibles"],"fr":["Nécessite une configuration de GitHub Actions","Dépend de la connectivité réseau pour le parcours","Limité à des projets GitHub publiquement disponibles"],"de":["Benötigt GitHub Actions-Konfiguration","Abhängig von der Netzwerkverbindung für das Durchsuchen","Begrenzt auf öffentlich verfügbare GitHub-Projekte"],"pt":["Requer configuração do GitHub Actions","Dependente da conectividade de rede para crawling","Limitado a projetos públicos do GitHub"],"ru":["Требует настройки GitHub Actions","Зависит от сетевого подключения для crawling","Ограничен публичными проектами GitHub"],"ar":["يتطلب إعداد إجراءات جيثب","يعتمد على الاتصال الشبكي للتنقل","محدود بمشاريع جيثب العامة"]},"version":3},"contentHash":"3a193a57719e34e75264311535a3f0b8672d2af893bd345d358666adae4efff8","qualityScore":75}');
