INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NeverSight/skills_feed/skill-from-github', 'skill-from-github', 'NeverSight', 'skills_feed', 'community', 'skill-from-github NeverSight skills_feed community 一个用于从GitHub获取技能数据的爬虫脚本，自动执行，提供技术解决方案 GitHubからスキルデータを取得するクローラースクリプト、自動実行、技術解決策を提供する GitHub에서 스킬 데이터를 가져오는 크롤러 스크립트, 자동 실행, 기술적 해결책 제공 La habilidad desde GitHub es un script de crawling que recopila datos de habilidades de la red, ejecutado diariamente a través de GitHub Actions. La compétence depuis GitHub est un script de crawling qui collecte des données de compétences du réseau, exécuté quotidiennement via GitHub Actions. Die Fähigkeit von GitHub ist ein Crawler-Skript, das Fähigkeitsdaten aus dem Netz sammelt, täglich über GitHub Actions ausgeführt. O script de habilidades do GitHub é uma ferramenta para extrair dados de projetos de qualidade e criar habilidades personalizadas para desenvolvedores Скрипт навыков GitHub - это инструмент для извлечения данных из качественных проектов и создания индивидуальных навыков для разработчиков سكريبت مهارات جيت هاب هو أداة لاستخراج البيانات من مشاريع ذات جودة عالية وإنشاء مهارات مخصصة للمطورين A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions. GitHub技能爬虫脚本 自动获取技能数据 用户意图理解 技术解决方案 GitHub Actions daily自动执行 A crawler script to fetch skill data from network, automatically executed daily via GitHub Actions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/gh-search', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'gh-search', 0, 0, 75, '2026-02-20T04:13:19.570Z', '2026-02-20T04:20:33.951Z', '5263fa51a531db41b655db0ed69ca1a347c53d594e409b850d6083c343e32199', '{"id":"majiayu000/claude-skill-registry/gh-search","name":"gh-search","description":{"zh":"gh-search 是一个用于从命令行搜索 GitHub 的技能，支持复杂查询和排除","ja":"gh-search は、コマンドラインから GitHub を検索するためのスキルです。複雑なクエリと除外をサポート","ko":"gh-search는 명령줄에서 GitHub를 검색하는 데 사용되는 스킬로 복잡한 쿼리와 제외를 지원","es":"La búsqueda de GitHub desde la línea de comandos es posible gracias a gh search. Esta herramienta permite buscar issues, PRs, repos, código y commits de manera eficiente.","fr":"La recherche GitHub depuis la ligne de commande est possible grâce à gh search. Cet outil permet de rechercher des problèmes, des PR, des dépôts, du code et des commits de manière efficace.","de":"Die GitHub-Suche von der Kommandozeile ist dank gh search möglich. Dieses Tool ermöglicht die effiziente Suche nach Problemen, PRs, Repos, Code und Commits.","pt":"O comando gh search permite pesquisar o GitHub a partir da linha de comando. Use -- antes de consultas com exclusões.","ru":"Команда gh search позволяет искать GitHub из командной строки. Используйте -- перед запросами с исключениями.","ar":"أمر غه سيرش يسمح بالبحث في جيت هاب من سطر الأوامر. استخدم -- قبل الاستفسارات التي تحتوي على استثناءات.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"GitHub 命令行搜索","ja":"GitHub CLI 検索","ko":"GitHub 명령줄 검색","es":"Búsqueda de GitHub desde la línea de comandos","fr":"Recherche GitHub depuis la ligne de commande","de":"GitHub-Suche von der Kommandozeile","pt":"Pesquisa GitHub CLI: gh-search","ru":"Поиск GitHub CLI: gh-