INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/gh-search', 'gh-search', 'majiayu000', 'claude-skill-registry', 'community', 'gh-search majiayu000 claude-skill-registry community gh-search 是一个用于从命令行搜索 GitHub 的技能，支持复杂查询和排除 gh-search は、コマンドラインから GitHub を検索するためのスキルです。複雑なクエリと除外をサポート gh-search는 명령줄에서 GitHub를 검색하는 데 사용되는 스킬로 복잡한 쿼리와 제외를 지원 La búsqueda de GitHub desde la línea de comandos es posible gracias a gh search. Esta herramienta permite buscar issues, PRs, repos, código y commits de manera eficiente. La recherche GitHub depuis la ligne de commande est possible grâce à gh search. Cet outil permet de rechercher des problèmes, des PR, des dépôts, du code et des commits de manière efficace. Die GitHub-Suche von der Kommandozeile ist dank gh search möglich. Dieses Tool ermöglicht die effiziente Suche nach Problemen, PRs, Repos, Code und Commits. O comando gh search permite pesquisar o GitHub a partir da linha de comando. Use -- antes de consultas com exclusões. Команда gh search позволяет искать GitHub из командной строки. Используйте -- перед запросами с исключениями. أمر غه سيرش يسمح بالبحث في جيت هاب من سطر الأوامر. استخدم -- قبل الاستفسارات التي تحتوي على استثناءات. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app GitHub 命令行搜索 gh search 复杂查询 排除 开发工具 The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
