INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/patchright-skill', 'patchright-skill', 'aiskillstore', 'marketplace', 'community', 'patchright-skill aiskillstore marketplace community Patchright Skill提供浏览器自动化和安全审计功能，支持localhost、开发服务器和Web应用测试 Patchright Skillはブラウザ自動化とセキュリティ監査機能を提供し、localhost、開発サーバー、ウェブアプリケーションテストをサポート Patchright Skill은 브라우저 자동화 및 보안 감사 기능을 제공하며 localhost, 개발 서버 및 웹 애플리케이션 테스트를 지원 Patchright es una habilidad de automatización de navegador con detección de bots para pruebas de aplicaciones web y capturas de pantalla. Ideal para entornos de desarrollo y servidores locales. Patchright est une compétence d''automatisation de navigateur avec contournement de la détection de bots pour les tests d''applications web et les captures d''écran. Idéal pour les environnements de développement et les serveurs locaux. Patchright ist eine Browser-Automatisierungsfähigkeit mit Bot-Erkennungsumgehung für Web-Anwendungstests und Screenshot-Erfassung. Ideal für Entwicklungsumgebungen und lokale Server. A skill Patchright é uma ferramenta de automação de navegador com bypass de detecção de bot, ideal para testes de aplicativos web e capturas de tela. Skill Patchright - это инструмент для автоматизации браузера с обходом обнаружения ботов, подходящий для тестирования веб-приложений и захвата экрана. مهارة Patchright هي أداة آليّة لمتصفح مع تحايل على كشف البوت، مثالية لاختبار التطبيقات الوبية والتقاط الشاشة. Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. 浏览器自动化 安全审计 bot检测绕过 Web应用测试 localhost 开发服务器 Patchright Skill Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
