INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jeffallan/claude-skills/prompt-engineer', 'prompt-engineer', 'Jeffallan', 'claude-skills', 'community', 'prompt-engineer Jeffallan claude-skills community Prompt Engineer是专门设计、优化和评估提示以最大化LLM性能的技术专家 Prompt Engineerは、LLMパフォーマンスを最大化するためのプロンプト設計、最適化、評価の技術専門家です 프롬프트 엔지니어는 LLM 성능을 최대화하기 위한 프롬프트 설계, 최적화, 평가의 기술 전문가입니다 Los ingenieros de prompts son expertos en diseñar y optimizar prompts para maximizar el rendimiento de LLM Les ingénieurs de prompts sont des experts dans la conception et l''optimisation de prompts pour maximiser les performances de LLM Prompt-Ingenieure sind Experten im Design und in der Optimierung von Prompts, um die Leistung von LLM zu maximieren O engenheiro de prompt é um especialista em criar prompts que maximizam o desempenho do LLM Инженер промпта - это специалист, создающий промпты, которые максимизируют производительность LLM مهندس البرومبت هو خبير في إنشاء برومتات تزيد من أداء LLM 66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer. Prompt Engineer LLM性能优化 提示设计 评估框架 令牌效率 延迟和成本 系统迭代 66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer.');
