INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('feiskyer/codex-settings/nanobanana-skill', 'nanobanana-skill', 'feiskyer', 'codex-settings', 'community', 'nanobanana-skill feiskyer codex-settings community Nanobanana 技能允许开发者使用 Google Gemini API 生成和编辑图像。需要配置 GEMINI_API_KEY 和安装 Python 依赖包 Nanobanana スキルは、開発者が Google Gemini API を使用して画像を生成および編集できるようにします。GEMINI_API_KEY の設定と Python 依存パッケージのインストールが必要です 나노바나나 스킬은 개발자가 Google Gemini API를 사용하여 이미지 생성 및 편집을 가능하게 합니다. GEMINI_API_KEY 설정 및 Python 의존 패키지 설치가 필요합니다 Nanobanana es una herramienta de línea de comandos que permite generar y editar imágenes utilizando la API de Google Gemini Nanobanana est un outil en ligne de commande qui permet de générer et d''éditer des images en utilisant l''API Google Gemini Nanobanana ist ein Kommandozeilen-Tool, mit dem Sie Bilder erstellen und bearbeiten können, indem Sie die Google-Gemini-API verwenden A nanobanana skill é uma ferramenta para gerar ou editar imagens usando a API do Google Gemini. Requisitos incluem chave de API e pacotes Python. Нанобананский навык - это инструмент для генерации или редактирования изображений с помощью API Google Gemini. Требования включают ключ API и пакеты Python. مهارة النانوبانانا هي أداة لгенерация أو تحرير الصور باستخدام واجهة برمجة تطبيقات جوجل جيميني. المتطلبات تشمل مفتاح واجهة البرمجة و حزم بايثون. OpenAI Codex CLI settings, configurations, skills and prompts for vibe coding Nanobanana 技能 Google Gemini API 图像生成 图像编辑 vibe coding Python 依赖包 OpenAI Codex CLI settings, configurations, skills and prompts for vibe coding');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/aoc', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'aoc', 0, 0, 75, '2026-02-20T04:13:19.578Z', '2026-02-20T04:57:27.898Z', '0628c1558e9248160d7b77e6a50f1cf6a9f2d6822492d37a0c6555a0283f4cbf', '{"id":"majiayu000/claude-skill-registry/aoc","name":"aoc","description":{"zh":"Advent of Code Solver TDD","ja":"Advent of Code TDD","ko":"Advent of Code TDD","es":"El solver de Advent of Code utiliza TDD y un enfoque de corrección para resolver problemas de programación","fr":"Le solveur d''Advent of Code utilise TDD et une approche de correction pour résoudre des problèmes de programmation","de":"Der Advent-of-Code-Solver verwendet TDD und einen korrekturorientierten Ansatz zur Lösung von Programmierproblemen","pt":"aoc é uma ferramenta de resolução de desafios de programação que utiliza TDD e abordagem de correção primeiro. Estude problemas e exemplos, extraia estruturas de dados e escreva testes","ru":"aoc - это инструмент для решения задач программирования, который использует TDD и подход правильности сначала. Изучайте проблемы и примеры, извлекайте структуры данных и пишите тесты","ar":"aoc هو أداة لحل تحديات البرمجة التي تستخدم نهج TDD والأولوية للصواب. دراسة المشاكل والأمثلة، استخراج هياكل البياناتและการكتابة الاختبارات","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Advent of Code Solver","ja":"Advent of Code ","ko":"Advent of Code ","es":"Resolviendo Advent of Code con TDD","fr":"Résoudre Advent of Code avec TDD","de":"Advent of Code lösen mit TDD","pt":"Resolva Desafios de Programação com aoc","ru":"Решение задач программирования с aoc","ar":"حل تحديات البرمجة مع aoc","en":"aoc"},"description":{"zh":"Advent of Code Solver TDD","ja":"Advent of Code TDD","ko":"Advent of Code TDD","es":"El solver de Advent of Code utiliza TDD y un enfoque de corrección para resolver problemas de programación","fr":"Le solveur d''Advent of Code utilise TDD et une approche de correction pour résoudre des problèmes de programmation","de":"Der Advent-of-Code-Solver verwendet TDD und einen korrekturorientierten Ansatz zur Lösung von Programmierproblemen","pt":"aoc é uma ferramenta de resolução de desafios de programação que utiliza TDD e abordagem de correção primeiro. Estude problemas e exemplos, extraia estrutura...","ru":"aoc - это инструмент для решения задач программирования, который использует TDD и подход правильности сначала. Изучайте проблемы и примеры, извлекайте структ...","ar":"aoc هو أداة لحل تحديات البرمجة التي تستخدم نهج TDD والأولوية للصواب. دراسة المشاكل والأمثلة، استخراج هياكل البياناتและการكتابة الاختبارات","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["TDD"," ","6","Advent of Code "],"ja":["TDD"," ","6","Advent of Code "],"ko":["TDD"," ","6","Advent of Code "],"es":["Enfoque de pruebas y desarrollo dirigido por pruebas","Resolución de problemas de programación","Arquitectura de solución modular","Ejecución en entrada real","Refactorización para la parte 2","Extracción de estructuras de datos de la entrada"],"fr":["Approche de tests et de développement dirigé par les tests","Résolution de problèmes de programmation","Architecture de solution modulaire","Exécution sur une entrée réelle","Refactorisation pour la partie 2","Extraction de structures de données de l''entrée"],"de":["Test- und Test-Driven-Development-Ansatz","Lösung von Programmierproblemen","Modulare Lösungsarchitektur","Ausführung auf reale Eingabe","Refaktorisierung für Teil 2","Extraktion von Datenstrukturen aus der Eingabe"],"pt":["Abordagem de TDD e correção primeiro","Análise de problemas e exemplos","Extração de estruturas de dados","Escrita de testes","Implementação de soluções","Refatoração de código"],"ru":["Подход TDD и правильности сначала","Анализ проблем и примеров","Извлечение структур данных","Написание тестов","Реализация решений","Рефакторинг кода"],"ar":["نهج TDD والأولوية للصواب","دراسة المشاكل والأمثلة","استخراج هياكل البيانات","كتابة الاختبارات","تنفيذ الحلول","إعادة هيكلة الشفرة"]},"keywords":{"zh":["Advent of Code","TDD"," "," "," ","Advent of Code Solver"],"ja":["Advent of Code","TDD"," "," "," ","Advent of Code Solver"],"ko":["Advent of Code","TDD"," "," "," ","Advent of Code Solver"],"es":["Advent of Code","TDD","pruebas y desarrollo dirigido por pruebas","resolución de problemas de programación","arquitectura de solución","desarrollo de software","programación","ingeniería de software"],"fr":["Advent of Code","TDD","tests et développement dirigé par les tests","résolution de problèmes de programmation","architecture de solution","développement de logiciels","programmation","ingénierie de logiciels"],"de":["Advent of Code","TDD","Test- und Test-Driven-Development-Ansatz","Lösung von Programmierproblemen","Lösungsarchitektur","Software-Entwicklung","Programmierung","Software-Ingenieurwesen"],"pt":["desafios de programação","TDD","correção primeiro","análise de problemas","extração de estruturas de dados","escrita de testes","implementação de soluções","refatoração de código","aoc"],"ru":["задачи программирования","TDD","правильности сначала","анализ проблем","извлечение структур данных","написание тестов","реализация решений","рефакторинг кода","aoc"],"ar":["تحديات البرمجة","TDD","الأولوية للصواب","دراسة المشاكل","استخراج هياكل البيانات","كتابة الاختبارات","تنفيذ الحلول","إعادة هيكلة الشفرة","aoc"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.578Z","topics":[],"category":"community","skillMd":{"name":"aoc","description":"Solve Advent of Code puzzles, algorithm challenges, and competitive programming problems. Activate when user provides AoC problem context/input, mentions solving puzzles/challenges, asks about algorithm selection (BFS, DFS, DP, etc.), or needs help with parsing structured input.","bodyPreview":"# Advent of Code Solver\n\nLanguage-agnostic problem-solving with **TDD** and **correctness-first** approach.\n\n## Workflow\n\n```\n1. READ      → Study problem + examples (examples are your spec)\n2. PARSE     → Extract data structures from input\n3. TEST      → Write tests from example input/output\n4. IMPLEMENT → Minimal code to pass\n5. RUN       → Execute on real input\n6. ADAPT     → Refactor for Part 2\n```\n\n## Solution Architecture\n\n```\nparse(input) → data structure\npart1(data)  → answer\npart2(data)","body":"# Advent of Code Solver\n\nLanguage-agnostic problem-solving with **TDD** and **correctness-first** approach.\n\n## Workflow\n\n```\n1. READ      → Study problem + examples (examples are your spec)\n2. PARSE     → Extract data structures from input\n3. TEST      → Write tests from example input/output\n4. IMPLEMENT → Minimal code to pass\n5. RUN       → Execute on real input\n6. ADAPT     → Refactor for Part 2\n```\n\n## Solution Architecture\n\n```\nparse(input) → data structure\npart1(data)  → answer\npart2(data)  → answer\n```\n\nParse once. Solve both parts. Test each function independently.\n\n## Algorithm Selection\n\n| Scenario | Algorithm |\n|----------|-----------|\n| Unweighted shortest path | BFS |\n| Path existence / exhaustive | DFS |\n| Weighted shortest path | Dijkstra |\n| Weighted + good heuristic | A* |\n| \"After N iterations...\" (huge N) | Cycle detection |\n| \"Find minimum X such that...\" | Binary search |\n| \"Count ways...\" / \"Min/max...\" | Dynamic programming |\n| Connected regions | Flood fill |\n\n**Deep dive**: See [algorithms.md](cookbook/algorithms.md)\n\n## Input Patterns\n\n| Format | Approach |\n|--------|----------|\n| Numbers in text | Regex `-?\\d+` |\n| Grid of chars | 2D array or dict by coords |\n| Blank-line groups | Split on `\\n\\n` first |\n| Key-value pairs | Parse into map/dict |\n| Instructions/opcodes | Pattern match each line |\n\n**Grids**: Use `(row, col)` with row↓. Sparse dict for infinite/sparse grids.\n**Directions**: `UP=(-1,0), DOWN=(1,0), LEFT=(0,-1), RIGHT=(0,1)`\n\n**Deep dive**: See [parsing.md](cookbook/parsing.md)\n\n## Part 2 Patterns\n\n1. **Scale up** → Optimize algorithm\n2. **Add dimensions** → 2D → 3D/4D\n3. **Many iterations** → Find cycle, skip ahead\n4. **Reverse question** → \"Find X\" → \"Given X, find Y\"\n5. **Add constraints** → New rules or edge cases\n\n## Debugging\n\n- Print intermediate state at each step\n- Compare with example walkthrough\n- Add assertions for every assumption\n- Test parsing separately from logic\n- Binary search on input size to isolate failures\n\n## Complexity Targets\n\n| Input Size | Target |\n|------------|--------|\n| n ≤ 20 | O(2^n) OK |\n| n ≤ 500 | O(n³) OK |\n| n ≤ 10,000 | O(n²) OK |\n| n ≤ 1,000,000 | O(n log n) |\n| n > 1,000,000 | O(n) or O(log n) |\n\n## Research Tools\n\n```\n# gh search code for algorithm implementations\ngh search code \"heapq.heappush\" --language=python   # Dijkstra/priority queue\ngh search code \"collections.deque\" --language=python # BFS patterns\ngh search code \"fn dijkstra\" --language=rust\n```\n\n## References\n\n- [algorithms.md](cookbook/algorithms.md) - Graph traversal, DP, cycle detection, search\n- [parsing.md](cookbook/parsing.md) - Input formats, grids, coordinates, hex grids\n- [reference.md](reference.md) - Data structures, optimization, anti-patterns\n"},"lastSynced":"2026-02-20T04:57:27.898Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced problem-solving capabilities with Test-Driven Development (TDD) and correctness-first approach.","zh":"非常适合需要高级问题解决能力的代码分析代理，特别是那些使用测试驱动开发（TDD）和正确性优先方法的代理。","ja":"コード分析エージェントが高度な問題解決能力を必要とする場合、特にテスト駆動開発（TDD）と正しさ優先アプローチを使用する場合に適しています。","ko":"코드 분석 에이전트가 고급 문제 해결 능력을 필요로 할 때 적합하며, 특히 테스트 주도 개발(TDD) 및 올바름 우선 접근 방식을 사용하는 경우에 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan capacidades de resolución de problemas avanzadas con Desarrollo Dirigido por Pruebas (TDD) y enfoque de corrección primero.","fr":"Parfait pour les agents d''analyse de code nécessitant des capacités de résolution de problèmes avancées avec le Développement Dirigé par les Tests (TDD) et l''approche de correction première.","de":"Perfekt für Code-Analyse-Agents, die erweiterte Problemlösungsfähigkeiten mit Testgetriebenem Entwicklung (TDD) und korrektheitsorientiertem Ansatz benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de capacidades avançadas de resolução de problemas com Desenvolvimento Dirigido por Testes (TDD) e abordagem de correção em primeiro lugar.","ru":"Идеально для агентов анализа кода, которым необходимы продвинутые возможности решения проблем с помощью разработки, управляемой тестированием (TDD), и подхода «правильность прежде всего».","ar":"مثالي لعميل تحليل الشيفرة الذي يحتاج إلى قابليات متقدمة لحل المشكلات باستخدام التطوير الموجه بالاختبار (TDD) ومنهجية الصحة أولاً."},"recommendation":{"en":"Empowers agents to solve Advent of Code puzzles using a language-agnostic approach with TDD, parsing input into data structures, and implementing minimal code to pass tests, all while utilizing correctness-first principles and adapting solutions for Part 2 challenges.","zh":"赋予代理使用语言无关的方法解决冒险码（Advent of Code）谜题的能力，包括使用TDD、将输入解析为数据结构、实现最小代码以通过测试，同时利用正确性优先原则并适应第2部分挑战的解决方案。","ja":"エージェントが言語非依存のアプローチを使用してAdvent of Codeのパズルを解決する能力を与えます。TDD、入力をデータ構造に解析し、テストに合格するための最小限のコードを実装し、正しさ優先の原則を利用し、パート2の課題の解決策に適応します。","ko":"에이전트가 언어에 구애받지 않는 접근 방식을 사용하여 어드벤처 코드(Advent of Code) 퍼즐을 해결할 수 있도록 하는데, TDD를 사용하고 입력을 데이터 구조로 파싱하며 테스트를 통과하기 위한 최소한의 코드를 구현하고, 동시에 올바름 우선 원칙을 활용하며 2부 챌린지의 해결책에 적응할 수 있습니다.","es":"Habilita a los agentes a resolver rompecabezas de Advent of Code utilizando un enfoque agnóstico del lenguaje con TDD, analizando la entrada en estructuras de datos y implementando un código mínimo para aprobar las pruebas, todo mientras utiliza principios de corrección primero y adapta soluciones para los desafíos de la Parte 2.","fr":"Permet aux agents de résoudre les puzzles d''Advent of Code en utilisant une approche agnostique du langage avec le TDD, en analysant les entrées dans des structures de données et en implémentant un code minimal pour passer les tests, le tout en utilisant les principes de correction première et en adaptant les solutions pour les défis de la partie 2.","de":"Ermächtigt Agents, Advent of Code-Rätsel mit einer sprachagnostischen Herangehensweise mit TDD zu lösen, indem die Eingabe in Datenstrukturen analysiert und ein minimaler Code implementiert wird, um die Tests zu bestehen, während dabei korrektheitsorientierte Grundsätze verwendet und Lösungen für die Herausforderungen von Teil 2 angepasst werden.","pt":"Habilita os agentes a resolverem quebra-cabeças do Advent of Code usando uma abordagem independente de linguagem com TDD, analisando a entrada em estruturas de dados e implementando um código mínimo para passar nos testes, tudo isso utilizando princípios de correção em primeiro lugar e adaptando soluções para os desafios da Parte 2.","ru":"Наделяет агентов возможностью решать головоломки Advent of Code, используя языково-независимый подход с помощью TDD, парсинг ввода в структуры данных и реализация минимального кода для прохождения тестов, все это при использовании принципов «правильность прежде всего» и адаптации решений для задач части 2.","ar":"يسمح للعميل بحل ألعاب Advent of Code باستخدام منهجية غير معتمدة على اللغة مع TDD، و تحليل المدخلات إلى هياكل بيانات، وتنفيذ شفرة صغيرة لتجاوز الاختبارات، وكل ذلك باستخدام مبدأ الصحة أولاً وتكييف الحلول للتحديات الجزء الثاني."},"useCases":{"en":["Automating Advent of Code puzzle solutions with TDD","Generating data structures from puzzle input","Debugging puzzle solutions using a correctness-first approach"],"zh":["使用TDD自动化Advent of Code谜题解决","从谜题输入生成数据结构","使用正确性优先方法调试谜题解决"],"ja":["TDDを使用してAdvent of Codeのパズルを自動化する","パズルの入力からデータ構造を生成する","正しさ優先アプローチを使用してパズルの解決をデバッグする"],"ko":["TDD를 사용하여 어드벤처 코드 퍼즐을 자동화하는 것","퍼즐 입력에서 데이터 구조를 생성하는 것","올바름 우선 접근 방식을 사용하여 퍼즐 해결을 디버깅하는 것"],"es":["Automatizar soluciones de rompecabezas de Advent of Code con TDD","Generar estructuras de datos a partir de la entrada del rompecabezas","Depurar soluciones de rompecabezas utilizando un enfoque de corrección primero"],"fr":["Automatiser les solutions de puzzles d''Advent of Code avec le TDD","Générer des structures de données à partir de l''entrée du puzzle","Déboguer les solutions de puzzle en utilisant une approche de correction première"],"de":["Automatisieren von Advent of Code-Rätsellösungen mit TDD","Erzeugen von Datenstrukturen aus der Rätsel-Eingabe","Fehlerbehebung von Rätsellösungen unter Verwendung eines korrektheitsorientierten Ansatzes"],"pt":["Automatizar soluções de quebra-cabeças do Advent of Code com TDD","Gerar estruturas de dados a partir da entrada do quebra-cabeça","Depurar soluções de quebra-cabeças usando uma abordagem de correção em primeiro lugar"],"ru":["Автоматизация решений головоломок Advent of Code с помощью TDD","Генерация структур данных из ввода головоломки","Отладка решений головоломок с помощью подхода «правильность прежде всего»"],"ar":["توفير حلول لألعاب Advent of Code باستخدام TDD","إنشاء هياكل بيانات من مدخلات اللعبة","تصحيح أخطاء حلول اللعبة باستخدام منهجية الصحة أولاً"]},"limitations":{"en":["Requires understanding of TDD and correctness-first principles","Language-agnostic, but may require additional setup for certain languages","Limited to Advent of Code puzzle solving"],"zh":["需要理解TDD和正确性优先原则","语言无关，但可能需要为某些语言进行额外设置","仅限Advent of Code谜题解决"],"ja":["TDDと正しさ優先原則の理解が必要","言語非依存ですが、特定の言語には追加の設定が必要になる場合があります","Advent of Codeのパズル解決のみ"],"ko":["TDD 및 올바름 우선 원칙에 대한 이해가 필요","언어에 구애받지 않지만 특정 언어에는 추가 설정이 필요할 수 있음","어드벤처 코드 퍼즐 해결만 해당"],"es":["Requiere comprensión de TDD y principios de corrección primero","Agnóstico del lenguaje, pero puede requerir una configuración adicional para ciertos lenguajes","Limitado a la resolución de rompecabezas de Advent of Code"],"fr":["Nécessite une compréhension du TDD et des principes de correction première","Agnostique du langage, mais peut nécessiter une configuration supplémentaire pour certains langages","Limité à la résolution de puzzles d''Advent of Code"],"de":["Erfordert Verständnis von TDD und korrektheitsorientierten Grundsätzen","Sprachagnostisch, aber kann für bestimmte Sprachen eine zusätzliche Einrichtung erfordern","Begrenzt auf die Lösung von Advent of Code-Rätseln"],"pt":["Exige compreensão de TDD e princípios de correção em primeiro lugar","Independente de linguagem, mas pode exigir configuração adicional para certas linguagens","Limitado à resolução de quebra-cabeças do Advent of Code"],"ru":["Требует понимания TDD и принципов «правильность прежде всего»","Языково-независимый, но может требовать дополнительной настройки для определенных языков","Ограничен решением головоломок Advent of Code"],"ar":["يتطلب فهم TDD ومنهجية الصحة أولاً","غير معتمد على اللغة، ولكن قد يتطلب إعدادًا إضافيًا للغات معينة","محدود بحل ألعاب Advent of Code"]},"version":3},"contentHash":"0628c1558e9248160d7b77e6a50f1cf6a9f2d6822492d37a0c6555a0283f4cbf","qualityScore":75}');
