INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('majiayu000/claude-skill-registry/jira-issues', 'jira-issues', 'majiayu000', 'claude-skill-registry', 'community', 'jira-issues majiayu000 claude-skill-registry community Jira REST API MCP Jira REST API MCP Jira REST API MCP La gestión de problemas de Jira permite a los desarrolladores crear y gestionar problemas de Jira de manera eficiente. La gestion des problèmes Jira permet aux développeurs de créer et de gérer des problèmes Jira de manière efficace. Das Jira-Problemmgmt. ermöglicht es Entwicklern, Jira-Probleme effizient zu erstellen und zu verwalten. O skill jira-issues permite criar e gerenciar problemas Jira usando a API REST do Jira ou MCP. Навык jira-issues позволяет создавать и управлять проблемами Jira с помощью REST API Jira или MCP. المهارة jira-issues تمكن من إنشاء وإدارة مشاكل جيرا باستخدام واجهة برمجة التطبيقات REST لجيرا أو MCP. The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app Jira Jira REST API Jira MCP API MCP Jira Jira Jira The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app');
